fn s1_current_schema_catalog(conn: &Connection) -> Vec<(String, String, String, String)> {
    let mut statement = conn
        .prepare(
            "SELECT type,name,tbl_name,COALESCE(sql,'') FROM sqlite_master
             ORDER BY type,name,tbl_name,COALESCE(sql,'')",
        )
        .unwrap();
    statement
        .query_map([], |row| {
            Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?))
        })
        .unwrap()
        .collect::<rusqlite::Result<Vec<_>>>()
        .unwrap()
}

fn s1_registered_function_inventory(conn: &Connection) -> Vec<(String, i64)> {
    let mut statement = conn
        .prepare(
            "SELECT name,narg FROM pragma_function_list
             WHERE name LIKE 'rsi_%' ORDER BY name,narg",
        )
        .unwrap();
    statement
        .query_map([], |row| Ok((row.get(0)?, row.get(1)?)))
        .unwrap()
        .collect::<rusqlite::Result<Vec<_>>>()
        .unwrap()
}

fn s1_in_memory_pragmas(conn: &Connection) -> (i64, String, i64, i64) {
    (
        conn.query_row("PRAGMA foreign_keys", [], |row| row.get(0))
            .unwrap(),
        conn.query_row("PRAGMA journal_mode", [], |row| row.get(0))
            .unwrap(),
        conn.query_row("PRAGMA synchronous", [], |row| row.get(0))
            .unwrap(),
        conn.query_row("PRAGMA busy_timeout", [], |row| row.get(0))
            .unwrap(),
    )
}

fn s1_d04_seed_shape(conn: &Connection) -> (String, String) {
    let project_id = d04_test_project_id().to_string();
    let row = conn
        .query_row(
            "SELECT id,name,path,description,color,context_files,created_at,updated_at
             FROM projects WHERE id=?1",
            [&project_id],
            |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, Option<String>>(2)?,
                    row.get::<_, Option<String>>(3)?,
                    row.get::<_, Option<String>>(4)?,
                    row.get::<_, Option<String>>(5)?,
                    row.get::<_, String>(6)?,
                    row.get::<_, String>(7)?,
                ))
            },
        )
        .unwrap();
    assert_eq!(row.0, project_id);
    assert_eq!(row.1, "D04 test project");
    assert_eq!(row.2, None);
    assert_eq!(row.3, None);
    assert_eq!(row.4.as_deref(), Some("#89b4fa"));
    assert_eq!(row.5, None);
    assert!(is_canonical_rfc3339_nanos(&row.6));
    assert_eq!(row.6, row.7);
    (row.0, row.1)
}

fn s1_assert_template_error(result: Result<()>, code: CurrentSchemaTemplateErrorCode) {
    let error = result.expect_err("injected template operation must fail");
    assert!(
        matches!(error, DaemonError::Store(_)),
        "template failure is not a Store error: {error}"
    );
    assert!(
        error
            .to_string()
            .contains(&format!("test_current_schema_template:{}", code.as_str())),
        "wrong stable template error: {error}"
    );
}

#[test]
fn cached_current_schema_fixture_matches_migrated_current_schema() {
    let cached = Store::open_in_memory().unwrap();
    let migrated = Store::open_in_memory_via_migrations_for_test().unwrap();

    for store in [&cached, &migrated] {
        assert_eq!(
            store
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            LATEST_SCHEMA_VERSION
        );
        assert_eq!(
            store
                .conn
                .query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0))
                .unwrap(),
            "ok"
        );
        assert_eq!(
            store
                .conn
                .query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |row| {
                    row.get::<_, i64>(0)
                })
                .unwrap(),
            0
        );
        assert!(store.conn.is_autocommit());
        assert_eq!(
            s1_d04_seed_shape(&store.conn),
            (
                d04_test_project_id().to_string(),
                "D04 test project".to_owned()
            )
        );
    }
    assert_eq!(
        s1_current_schema_catalog(&cached.conn),
        s1_current_schema_catalog(&migrated.conn)
    );
    assert_eq!(
        s1_registered_function_inventory(&cached.conn),
        s1_registered_function_inventory(&migrated.conn)
    );
    assert!(!s1_registered_function_inventory(&cached.conn).is_empty());
    assert_eq!(
        s1_in_memory_pragmas(&cached.conn),
        s1_in_memory_pragmas(&migrated.conn)
    );
}

#[test]
fn cached_current_schema_fixtures_are_mutably_isolated() {
    let first = Store::open_in_memory().unwrap();
    let second = Store::open_in_memory().unwrap();
    first
        .conn
        .execute(
            "UPDATE projects SET name='first clone only' WHERE id=?1",
            [d04_test_project_id().to_string()],
        )
        .unwrap();
    first
        .conn
        .execute(
            "INSERT INTO projects (id,name,color,created_at,updated_at)
             VALUES (?1,'extra clone row','#ffffff',?2,?2)",
            rusqlite::params![Uuid::new_v4().to_string(), "2026-08-27T00:00:00.000000000Z"],
        )
        .unwrap();
    let second_name: String = second
        .conn
        .query_row(
            "SELECT name FROM projects WHERE id=?1",
            [d04_test_project_id().to_string()],
            |row| row.get(0),
        )
        .unwrap();
    assert_eq!(second_name, "D04 test project");
    assert_eq!(
        second
            .conn
            .query_row("SELECT count(*) FROM projects", [], |row| row
                .get::<_, i64>(0))
            .unwrap(),
        1
    );
    let third = Store::open_in_memory().unwrap();
    assert_eq!(s1_d04_seed_shape(&third.conn).1, "D04 test project");
    assert_eq!(
        third
            .conn
            .query_row("SELECT count(*) FROM projects", [], |row| row
                .get::<_, i64>(0))
            .unwrap(),
        1
    );
}

#[test]
fn cached_current_schema_template_ignores_thread_local_failpoints() {
    let _guard = S1IssueV97FaultGuard;
    issue_v97_test_fail_next_migration(IssueV97MigrationFault::AfterPreflight);
    Store::open_in_memory().expect("dedicated template thread must ignore caller TLS");
    let error = match Store::open_in_memory_via_migrations_for_test() {
        Ok(_) => panic!("uncached caller-thread migration did not consume the armed fault"),
        Err(error) => error,
    };
    assert!(
        error
            .to_string()
            .contains("injected V97 Issue migration fault: AfterPreflight")
    );
}

