#[test]
fn current_schema_template_spawn_and_join_failures_are_stable_store_errors() {
    let spawn = current_schema_template_init_failure_for_test(false);
    let join = current_schema_template_init_failure_for_test(true);
    assert!(spawn.contains("test_current_schema_template:init_spawn"));
    assert!(join.contains("test_current_schema_template:init_join"));
    assert!(!spawn.contains("CurrentSchemaTemplateSource"));
    assert!(!join.contains("injected current-schema template join failure"));
}

