#[test]
fn current_schema_template_disk_cache_reuses_a_valid_publication() {
    let directory = tempfile::tempdir().unwrap();
    let (first_path, first_pages) =
        current_schema_template_disk_cache_for_test(directory.path()).unwrap();
    let first_metadata = std::fs::metadata(&first_path).unwrap();
    let first_bytes = std::fs::read(&first_path).unwrap();
    let (second_path, second_pages) =
        current_schema_template_disk_cache_for_test(directory.path()).unwrap();
    let second_metadata = std::fs::metadata(&second_path).unwrap();

    assert_eq!(first_path, second_path);
    assert_eq!(first_pages, second_pages);
    assert_eq!(first_metadata.len(), second_metadata.len());
    assert_eq!(first_bytes, std::fs::read(&second_path).unwrap());
    assert!(first_metadata.permissions().readonly());
    assert!(
        first_path
            .file_name()
            .unwrap()
            .to_string_lossy()
            .starts_with(&format!(
                "v{CURRENT_SCHEMA_TEMPLATE_CACHE_PROTOCOL}-schema{LATEST_SCHEMA_VERSION}-"
            ))
    );
}

#[test]
fn current_schema_template_disk_cache_rebuilds_corrupt_content() {
    let directory = tempfile::tempdir().unwrap();
    let (path, expected_pages) =
        current_schema_template_disk_cache_for_test(directory.path()).unwrap();
    std::fs::remove_file(&path).unwrap();
    std::fs::write(&path, b"not a SQLite database").unwrap();

    let (rebuilt_path, rebuilt_pages) =
        current_schema_template_disk_cache_for_test(directory.path()).unwrap();
    assert_eq!(path, rebuilt_path);
    assert_eq!(expected_pages, rebuilt_pages);
    assert!(std::fs::metadata(&rebuilt_path).unwrap().len() > 1024);
    assert!(
        std::fs::metadata(&rebuilt_path)
            .unwrap()
            .permissions()
            .readonly()
    );
}

#[test]
fn current_schema_template_concurrent_publishers_share_one_atomic_file() {
    let directory = std::sync::Arc::new(tempfile::tempdir().unwrap());
    let mut threads = Vec::new();
    for _ in 0..8 {
        let directory = std::sync::Arc::clone(&directory);
        threads.push(std::thread::spawn(move || {
            current_schema_template_disk_cache_for_test(directory.path()).unwrap()
        }));
    }
    let results = threads
        .into_iter()
        .map(|thread| thread.join().unwrap())
        .collect::<Vec<_>>();
    assert!(results.windows(2).all(|pair| pair[0] == pair[1]));

    let key = current_schema_template_cache_key_for_test();
    let mut entries = std::fs::read_dir(directory.path())
        .unwrap()
        .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
        .collect::<Vec<_>>();
    entries.sort();
    assert_eq!(entries, vec![key.clone(), format!("{key}.lock")]);
}

