#[cfg(unix)]
#[derive(Debug, Clone, PartialEq, Eq)]
struct SchemaCacheHelperRecord {
    filename: String,
    page_count: i64,
    user_version: i64,
    d04_project_count: i64,
}

#[cfg(unix)]
impl SchemaCacheHelperRecord {
    fn parse(contents: &str, expected_key: &str) -> Self {
        assert!(
            contents.ends_with('\n'),
            "helper result must end with newline"
        );
        assert_eq!(
            contents.matches('\n').count(),
            1,
            "helper result line count"
        );
        let line = contents.strip_suffix('\n').unwrap();
        assert!(!line.contains('\r'), "helper result must use LF only");
        let fields = line.split('\t').collect::<Vec<_>>();
        assert_eq!(fields.len(), 5, "helper result field count");
        assert_eq!(fields[0], "OK", "helper result marker");
        assert_eq!(fields[1], expected_key, "helper result cache key");
        let parse_number = |field: &str, name: &str| {
            assert!(
                !field.is_empty() && field.bytes().all(|byte| byte.is_ascii_digit()),
                "helper result {name} is not an unsigned decimal: {field:?}"
            );
            field
                .parse::<i64>()
                .unwrap_or_else(|error| panic!("helper result {name} does not fit i64: {error}"))
        };
        let page_count = parse_number(fields[2], "page count");
        assert!(
            (1..=16_384).contains(&page_count),
            "helper page count out of bounds: {page_count}"
        );
        let user_version = parse_number(fields[3], "user version");
        assert_eq!(
            user_version, LATEST_SCHEMA_VERSION as i64,
            "helper schema version"
        );
        let d04_project_count = parse_number(fields[4], "D04 project count");
        assert_eq!(d04_project_count, 1, "helper D04 project count");
        Self {
            filename: fields[1].to_owned(),
            page_count,
            user_version,
            d04_project_count,
        }
    }
}

#[cfg(unix)]
struct SchemaCacheChildGuard {
    label: String,
    child: Option<Child>,
    stdout_path: PathBuf,
    stderr_path: PathBuf,
}

#[cfg(unix)]
impl SchemaCacheChildGuard {
    fn id(&self) -> u32 {
        self.child.as_ref().expect("child already reaped").id()
    }

    fn diagnostic(&self) -> String {
        let read_log = |path: &Path| {
            let mut contents = String::new();
            match std::fs::File::open(path).and_then(|mut file| file.read_to_string(&mut contents))
            {
                Ok(_) => contents,
                Err(error) => format!("<unavailable: {error}>"),
            }
        };
        format!(
            "{} stdout={} stderr={}",
            self.label,
            read_log(&self.stdout_path),
            read_log(&self.stderr_path)
        )
    }

    fn try_wait(&mut self) -> Option<ExitStatus> {
        self.child
            .as_mut()
            .expect("child already reaped")
            .try_wait()
            .unwrap_or_else(|error| panic!("{} try_wait failed: {error}", self.label))
    }

    fn check_early_exit(&mut self) {
        let status = self.try_wait();
        if let Some(status) = status {
            panic!(
                "{} exited early with {status}: {}",
                self.label,
                self.diagnostic()
            );
        }
    }

    fn finish(mut self) {
        let status = self
            .child
            .as_mut()
            .expect("child already reaped")
            .wait()
            .unwrap_or_else(|error| panic!("{} wait failed: {error}", self.label));
        self.child = None;
        assert!(
            status.success(),
            "{} exited with {status}: {}",
            self.label,
            self.diagnostic()
        );
    }
}

#[cfg(unix)]
impl Drop for SchemaCacheChildGuard {
    fn drop(&mut self) {
        let Some(mut child) = self.child.take() else {
            return;
        };
        if child.try_wait().ok().flatten().is_none() {
            let _ = child.kill();
        }
        let _ = child.wait();
    }
}

#[cfg(unix)]
fn create_schema_cache_marker(path: &Path) {
    OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(path)
        .unwrap_or_else(|error| panic!("create marker {}: {error}", path.display()));
}

#[cfg(unix)]
fn schema_cache_file_identity(path: &Path) -> (u64, u64, u64, bool) {
    let metadata = std::fs::symlink_metadata(path)
        .unwrap_or_else(|error| panic!("metadata {}: {error}", path.display()));
    assert!(metadata.is_file(), "not a regular file: {}", path.display());
    assert!(
        !metadata.file_type().is_symlink(),
        "unexpected symlink: {}",
        path.display()
    );
    (
        metadata.dev(),
        metadata.ino(),
        metadata.len(),
        metadata.permissions().readonly(),
    )
}

#[cfg(unix)]
fn assert_schema_cache_inventory(cache_dir: &Path, key: &str) {
    let mut entries = std::fs::read_dir(cache_dir)
        .unwrap_or_else(|error| panic!("read cache directory {}: {error}", cache_dir.display()))
        .map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned())
        .collect::<Vec<_>>();
    entries.sort();
    assert_eq!(entries, vec![key.to_owned(), format!("{key}.lock")]);
    let lock_path = cache_dir.join(format!("{key}.lock"));
    let lock_metadata = std::fs::symlink_metadata(&lock_path)
        .unwrap_or_else(|error| panic!("lock metadata {}: {error}", lock_path.display()));
    assert!(lock_metadata.is_file() && !lock_metadata.file_type().is_symlink());
}

#[cfg(unix)]
fn spawn_schema_cache_helper(
    phase: &str,
    index: usize,
    cache_dir: &Path,
    cwd: &Path,
    ready_path: &Path,
    go_path: &Path,
    result_path: &Path,
) -> SchemaCacheChildGuard {
    let log_prefix = ready_path.with_file_name(format!("{phase}-{index}"));
    let stdout_path = log_prefix.with_extension("stdout");
    let stderr_path = log_prefix.with_extension("stderr");
    let stdout = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&stdout_path)
        .unwrap_or_else(|error| panic!("create {}: {error}", stdout_path.display()));
    let stderr = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&stderr_path)
        .unwrap_or_else(|error| panic!("create {}: {error}", stderr_path.display()));
    let mut command = Command::new(std::env::current_exe().expect("current test executable"));
    for variable in [
        SCHEMA_CACHE_DIR_ENV,
        SCHEMA_CACHE_HELPER_TOKEN_ENV,
        SCHEMA_CACHE_READY_PATH_ENV,
        SCHEMA_CACHE_GO_PATH_ENV,
        SCHEMA_CACHE_RESULT_PATH_ENV,
    ] {
        command.env_remove(variable);
    }
    let child = command
        .args([
            "--ignored",
            "--exact",
            "store::tests::current_schema_template_multiprocess_helper",
            "--test-threads=1",
            "--nocapture",
        ])
        .current_dir(cwd)
        .env(SCHEMA_CACHE_DIR_ENV, cache_dir)
        .env(SCHEMA_CACHE_HELPER_TOKEN_ENV, SCHEMA_CACHE_HELPER_TOKEN)
        .env(SCHEMA_CACHE_READY_PATH_ENV, ready_path)
        .env(SCHEMA_CACHE_GO_PATH_ENV, go_path)
        .env(SCHEMA_CACHE_RESULT_PATH_ENV, result_path)
        .stdout(Stdio::from(stdout))
        .stderr(Stdio::from(stderr))
        .spawn()
        .unwrap_or_else(|error| panic!("spawn {phase}-{index}: {error}"));
    SchemaCacheChildGuard {
        label: format!("schema cache helper {phase}-{index}"),
        child: Some(child),
        stdout_path,
        stderr_path,
    }
}

#[cfg(unix)]
fn wait_for_schema_cache_helpers_ready(
    guards: &mut [SchemaCacheChildGuard],
    ready_paths: &[PathBuf],
) {
    let deadline = Instant::now() + SCHEMA_CACHE_READY_DEADLINE;
    loop {
        for guard in &mut *guards {
            guard.check_early_exit();
        }
        if ready_paths.iter().all(|path| {
            std::fs::symlink_metadata(path)
                .is_ok_and(|metadata| metadata.is_file() && !metadata.file_type().is_symlink())
        }) {
            return;
        }
        if Instant::now() >= deadline {
            let diagnostics = guards
                .iter()
                .map(SchemaCacheChildGuard::diagnostic)
                .collect::<Vec<_>>();
            panic!(
                "schema cache helpers did not become ready within {:?}: {diagnostics:?}",
                SCHEMA_CACHE_READY_DEADLINE
            );
        }
        std::thread::sleep(SCHEMA_CACHE_POLL_PAUSE);
    }
}

#[cfg(unix)]
fn wait_for_schema_cache_helpers_exit(guards: &mut [SchemaCacheChildGuard]) {
    let deadline = Instant::now() + SCHEMA_CACHE_EXIT_DEADLINE;
    loop {
        let mut any_running = false;
        for guard in &mut *guards {
            match guard.try_wait() {
                Some(status) => assert!(
                    status.success(),
                    "{} exited with {status}: {}",
                    guard.label,
                    guard.diagnostic()
                ),
                None => any_running = true,
            }
        }
        if !any_running {
            return;
        }
        if Instant::now() >= deadline {
            let diagnostics = guards
                .iter()
                .map(SchemaCacheChildGuard::diagnostic)
                .collect::<Vec<_>>();
            panic!(
                "schema cache helpers did not exit within {:?}: {diagnostics:?}",
                SCHEMA_CACHE_EXIT_DEADLINE
            );
        }
        std::thread::sleep(SCHEMA_CACHE_POLL_PAUSE);
    }
}

#[cfg(unix)]
fn run_schema_cache_helper_wave(
    phase: &str,
    child_count: usize,
    cache_dir: &Path,
    control_dir: &Path,
    cwd: &Path,
    expected_key: &str,
) -> Vec<SchemaCacheHelperRecord> {
    let go_path = control_dir.join(format!("{phase}.go"));
    let ready_paths = (0..child_count)
        .map(|index| control_dir.join(format!("{phase}-{index}.ready")))
        .collect::<Vec<_>>();
    let result_paths = (0..child_count)
        .map(|index| control_dir.join(format!("{phase}-{index}.result")))
        .collect::<Vec<_>>();
    let mut guards = Vec::with_capacity(child_count);
    for index in 0..child_count {
        guards.push(spawn_schema_cache_helper(
            phase,
            index,
            cache_dir,
            cwd,
            &ready_paths[index],
            &go_path,
            &result_paths[index],
        ));
    }
    assert_eq!(guards.len(), child_count);
    for (index, left) in guards.iter().enumerate() {
        for right in guards.iter().skip(index + 1) {
            assert_ne!(left.id(), right.id(), "helper PIDs must be distinct");
        }
    }
    wait_for_schema_cache_helpers_ready(&mut guards, &ready_paths);
    create_schema_cache_marker(&go_path);
    wait_for_schema_cache_helpers_exit(&mut guards);
    guards
        .into_iter()
        .zip(result_paths)
        .map(|(guard, result_path)| {
            guard.finish();
            let contents = std::fs::read_to_string(&result_path)
                .unwrap_or_else(|error| panic!("read {}: {error}", result_path.display()));
            SchemaCacheHelperRecord::parse(&contents, expected_key)
        })
        .collect()
}

#[cfg(unix)]
#[test]
#[ignore = "spawned only by the multi-process parent"]
fn current_schema_template_multiprocess_helper() {
    assert_eq!(
        std::env::var(SCHEMA_CACHE_HELPER_TOKEN_ENV).as_deref(),
        Ok(SCHEMA_CACHE_HELPER_TOKEN),
        "helper invocation token"
    );
    let path_from_env = |name: &str| {
        let path =
            PathBuf::from(std::env::var_os(name).unwrap_or_else(|| panic!("missing {name}")));
        assert!(
            path.is_absolute(),
            "{name} must be absolute: {}",
            path.display()
        );
        path
    };
    let cache_dir = path_from_env(SCHEMA_CACHE_DIR_ENV);
    let ready_path = path_from_env(SCHEMA_CACHE_READY_PATH_ENV);
    let go_path = path_from_env(SCHEMA_CACHE_GO_PATH_ENV);
    let result_path = path_from_env(SCHEMA_CACHE_RESULT_PATH_ENV);
    let cache_dir = std::fs::canonicalize(&cache_dir).unwrap_or_else(|error| {
        panic!(
            "canonicalize cache directory {}: {error}",
            cache_dir.display()
        )
    });
    let control_dir = std::fs::canonicalize(ready_path.parent().expect("ready parent"))
        .expect("canonicalize ready parent");
    for path in [&go_path, &result_path] {
        assert_eq!(
            std::fs::canonicalize(path.parent().expect("marker parent"))
                .expect("canonicalize marker parent"),
            control_dir,
            "all marker parents must match"
        );
    }
    assert_ne!(
        control_dir, cache_dir,
        "control and cache directories must differ"
    );
    assert_ne!(ready_path, go_path);
    assert_ne!(ready_path, result_path);
    assert_ne!(go_path, result_path);
    create_schema_cache_marker(&ready_path);
    let deadline = Instant::now() + SCHEMA_CACHE_GO_DEADLINE;
    loop {
        match std::fs::symlink_metadata(&go_path) {
            Ok(metadata) => {
                assert!(metadata.is_file() && !metadata.file_type().is_symlink());
                break;
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => panic!("go marker metadata {}: {error}", go_path.display()),
        }
        assert!(
            Instant::now() < deadline,
            "helper did not receive go marker within {:?}",
            SCHEMA_CACHE_GO_DEADLINE
        );
        std::thread::sleep(SCHEMA_CACHE_POLL_PAUSE);
    }
    let (cache_path, page_count) = current_schema_template_disk_cache_for_test(&cache_dir)
        .expect("no-fallback shared cache seam");
    let key = current_schema_template_cache_key_for_test();
    assert_eq!(cache_path, cache_dir.join(&key));
    let store = Store::open_in_memory().expect("ordinary cached Store");
    let user_version = store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get::<_, i64>(0))
        .expect("read schema version");
    let d04_project_count = store
        .conn
        .query_row(
            "SELECT COUNT(*) FROM projects WHERE id=?1",
            [d04_test_project_id().to_string()],
            |row| row.get::<_, i64>(0),
        )
        .expect("read D04 project count");
    assert_eq!(user_version, LATEST_SCHEMA_VERSION as i64);
    assert_eq!(d04_project_count, 1);
    let mut result = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&result_path)
        .unwrap_or_else(|error| panic!("create result {}: {error}", result_path.display()));
    writeln!(
        result,
        "OK\t{}\t{}\t{}\t{}",
        key, page_count, user_version, d04_project_count
    )
    .expect("write helper result");
}

#[cfg(unix)]
#[test]
fn current_schema_template_real_multiprocess_publication_is_atomic_reused_and_repairs_corruption() {
    let invocation = tempfile::tempdir().expect("invocation tempdir");
    let root = std::fs::canonicalize(invocation.path()).expect("canonical invocation root");
    let cache_dir = root.join("cache");
    let control_dir = root.join("control");
    let cwd = root.join("cwd");
    for directory in [&cache_dir, &control_dir, &cwd] {
        std::fs::create_dir(directory)
            .unwrap_or_else(|error| panic!("create {}: {error}", directory.display()));
    }
    let cache_dir = std::fs::canonicalize(cache_dir).expect("canonical cache directory");
    let control_dir = std::fs::canonicalize(control_dir).expect("canonical control directory");
    let cwd = std::fs::canonicalize(cwd).expect("canonical cwd directory");
    let key = current_schema_template_cache_key_for_test();
    let cache_path = cache_dir.join(&key);

    let publication =
        run_schema_cache_helper_wave("publication", 2, &cache_dir, &control_dir, &cwd, &key);
    assert_eq!(publication.len(), 2);
    assert_eq!(publication[0], publication[1]);
    open_shared_current_schema_template(&cache_path).expect("validate first publication");
    let valid_identity = schema_cache_file_identity(&cache_path);
    assert!(valid_identity.3, "canonical cache file must be read-only");
    assert_schema_cache_inventory(&cache_dir, &key);

    let valid_anchor = control_dir.join("valid-anchor.sqlite3");
    std::fs::hard_link(&cache_path, &valid_anchor).expect("hard-link valid cache file");
    assert_eq!(schema_cache_file_identity(&valid_anchor), valid_identity);
    let reuse = run_schema_cache_helper_wave("reuse", 1, &cache_dir, &control_dir, &cwd, &key);
    assert_eq!(reuse, vec![publication[0].clone()]);
    assert_eq!(schema_cache_file_identity(&cache_path), valid_identity);
    assert_eq!(schema_cache_file_identity(&valid_anchor), valid_identity);
    open_shared_current_schema_template(&cache_path).expect("validate reused publication");
    assert_schema_cache_inventory(&cache_dir, &key);

    std::fs::remove_file(&cache_path).expect("remove valid canonical path");
    std::fs::write(&cache_path, b"not a SQLite database").expect("write corrupt canonical payload");
    let corrupt_anchor = control_dir.join("corrupt-anchor.sqlite3");
    std::fs::hard_link(&cache_path, &corrupt_anchor).expect("hard-link corrupt cache file");
    let corrupt_identity = schema_cache_file_identity(&corrupt_anchor);
    let repair = run_schema_cache_helper_wave("repair", 2, &cache_dir, &control_dir, &cwd, &key);
    assert_eq!(repair.len(), 2);
    assert_eq!(repair[0], repair[1]);
    assert_eq!(repair[0], publication[0]);
    let repaired_identity = schema_cache_file_identity(&cache_path);
    assert_ne!(
        (repaired_identity.0, repaired_identity.1),
        (corrupt_identity.0, corrupt_identity.1),
        "repair must replace the pinned corrupt inode"
    );
    assert!(repaired_identity.3, "repaired cache file must be read-only");
    open_shared_current_schema_template(&cache_path).expect("validate repaired publication");
    assert_schema_cache_inventory(&cache_dir, &key);
}

