#[test]
fn current_schema_template_backup_budgets_are_enforced() {
    let (pages_per_step, page_limit, step_limit, no_progress_limit, busy_limit, deadline) =
        current_schema_template_backup_bounds_for_test();
    assert_eq!(pages_per_step, 64);
    assert_eq!(page_limit, 16_384);
    assert_eq!(step_limit, 272);
    assert_eq!(no_progress_limit, 8);
    assert_eq!(busy_limit, 8);
    assert_eq!(deadline, std::time::Duration::from_millis(500));

    let mutex = std::sync::Mutex::new(());
    current_schema_template_backup_seam_for_test(
        &mutex,
        128,
        &[
            CurrentSchemaTemplateBackupObservation::More(64),
            CurrentSchemaTemplateBackupObservation::Done(0),
        ],
        false,
    )
    .unwrap();
    s1_assert_template_error(
        current_schema_template_backup_seam_for_test(
            &mutex,
            page_limit + 1,
            &[CurrentSchemaTemplateBackupObservation::Done(0)],
            false,
        ),
        CurrentSchemaTemplateErrorCode::SourceTooLarge,
    );
    let descending = (0..=step_limit)
        .map(|index| {
            CurrentSchemaTemplateBackupObservation::More((page_limit as usize - index - 1) as i32)
        })
        .collect::<Vec<_>>();
    s1_assert_template_error(
        current_schema_template_backup_seam_for_test(&mutex, page_limit, &descending, false),
        CurrentSchemaTemplateErrorCode::BackupStepBudget,
    );
    s1_assert_template_error(
        current_schema_template_backup_seam_for_test(
            &mutex,
            1,
            &vec![CurrentSchemaTemplateBackupObservation::More(1); no_progress_limit + 1],
            false,
        ),
        CurrentSchemaTemplateErrorCode::BackupNoProgress,
    );
    let busy_locked = (0..=busy_limit)
        .map(|index| {
            if index % 2 == 0 {
                CurrentSchemaTemplateBackupObservation::Busy
            } else {
                CurrentSchemaTemplateBackupObservation::Locked
            }
        })
        .collect::<Vec<_>>();
    s1_assert_template_error(
        current_schema_template_backup_seam_for_test(&mutex, 1, &busy_locked, false),
        CurrentSchemaTemplateErrorCode::BackupBusyLocked,
    );
    s1_assert_template_error(
        current_schema_template_backup_seam_for_test(
            &mutex,
            1,
            &[CurrentSchemaTemplateBackupObservation::Error],
            false,
        ),
        CurrentSchemaTemplateErrorCode::BackupStep,
    );
    s1_assert_template_error(
        current_schema_template_backup_seam_for_test(&mutex, 1, &[], true),
        CurrentSchemaTemplateErrorCode::BackupDeadline,
    );
    s1_assert_template_error(
        current_schema_template_backup_seam_for_test(
            &mutex,
            1,
            &[CurrentSchemaTemplateBackupObservation::Unknown],
            false,
        ),
        CurrentSchemaTemplateErrorCode::BackupUnknownResult,
    );
}

#[test]
fn current_schema_template_backup_releases_mutex_on_every_exit() {
    let cases = [
        (vec![CurrentSchemaTemplateBackupObservation::Done(0)], false),
        (vec![CurrentSchemaTemplateBackupObservation::Error], false),
        (vec![CurrentSchemaTemplateBackupObservation::Unknown], false),
        (vec![], true),
    ];
    for (observations, deadline) in cases {
        let mutex = std::sync::Mutex::new(());
        let _ = current_schema_template_backup_seam_for_test(&mutex, 1, &observations, deadline);
        assert!(mutex.try_lock().is_ok());
    }
}

