#[test]
fn set_session_rotation_disabled_at_is_idempotent() {
    let store = Store::open_in_memory().unwrap();
    let mut session = make_test_session();
    let stamp = chrono::Utc::now();
    session.rotation_disabled_at = Some(stamp);
    store.insert_session(&session).unwrap();

    for _ in 0..3 {
        store
            .set_session_rotation_disabled_at(session.id, Some(stamp))
            .unwrap();
        assert_eq!(
            store
                .get_session(session.id)
                .unwrap()
                .unwrap()
                .rotation_disabled_at,
            Some(stamp)
        );
    }

    store
        .set_session_rotation_disabled_at(session.id, None)
        .unwrap();
    assert!(
        store
            .get_session(session.id)
            .unwrap()
            .unwrap()
            .rotation_disabled_at
            .is_none()
    );
    assert!(
        store
            .set_session_rotation_disabled_at(Uuid::new_v4(), Some(stamp))
            .is_err()
    );
}

#[test]
fn fill_session_title_if_absent_supplies_only_a_missing_title() {
    let store = Store::open_in_memory().unwrap();
    let session = make_test_session();
    store.insert_session(&session).unwrap();

    // Absent title: the generated fill is accepted.
    assert!(
        store
            .fill_session_title_if_absent(session.id, "Generated title")
            .unwrap()
    );
    assert_eq!(
        store.get_session(session.id).unwrap().unwrap().title,
        Some("Generated title".to_string())
    );

    // Present title: the next fill is refused and the title is unchanged.
    assert!(
        !store
            .fill_session_title_if_absent(session.id, "Generated overwrite")
            .unwrap()
    );
    assert_eq!(
        store.get_session(session.id).unwrap().unwrap().title,
        Some("Generated title".to_string())
    );

    // A missing session is an error, not a silent no-op.
    assert!(
        store
            .fill_session_title_if_absent(Uuid::new_v4(), "Orphan")
            .is_err()
    );
}

#[test]
fn explicit_title_survives_generated_fill_and_deliberate_rename_still_wins() {
    let store = Store::open_in_memory().unwrap();
    let mut session = make_test_session();
    session.title = Some("PARITYMODALSESSION".to_string());
    store.insert_session(&session).unwrap();

    // Asynchronous enrichment must not overwrite the explicit title.
    assert!(
        !store
            .fill_session_title_if_absent(session.id, "Demiurge: Generated")
            .unwrap()
    );
    assert_eq!(
        store.get_session(session.id).unwrap().unwrap().title,
        Some("PARITYMODALSESSION".to_string())
    );

    // Deliberate rename is a distinct path and must still overwrite.
    store
        .update_session_title(session.id, "Operator rename")
        .unwrap();
    assert_eq!(
        store.get_session(session.id).unwrap().unwrap().title,
        Some("Operator rename".to_string())
    );
}

#[test]
fn load_archived_sessions_returns_only_the_previous_seven_days() {
    let store = Store::open_in_memory().unwrap();
    let now = chrono::Utc::now();

    let mut recent = make_test_session();
    recent.status = SessionStatus::Archived;
    recent.updated_at = now - chrono::Duration::days(6);

    let mut expired = make_test_session();
    expired.status = SessionStatus::Archived;
    expired.updated_at = now - chrono::Duration::days(8);

    store.insert_session(&recent).unwrap();
    store.insert_session(&expired).unwrap();

    let archived = store.load_archived_sessions(None).unwrap();

    assert_eq!(archived.len(), 1);
    assert_eq!(archived[0].id, recent.id);

    let project_archived = store.load_archived_sessions(recent.project_id).unwrap();
    assert_eq!(project_archived.len(), 1);
    assert_eq!(project_archived[0].id, recent.id);
}

// D04 named regression filters. These small, deterministic probes pin the
// public project-ownership seams; fuller migration/link fault coverage lives
// alongside the production transaction tests above.
/// An issue created through the operator surface has no `created_by_session_id`,
/// so V77 cannot derive its owning project from a session. That absence is
/// legitimate provenance — V77 keeps the column nullable — so the migration must
/// neither drop the row nor invent a creator. It refuses until the operator
/// declares an owner, then attributes only the unowned rows to it.
#[test]
#[allow(clippy::unwrap_used)]
fn d04_v77_attributes_issues_with_no_creating_session_by_declaration() {
    let _env_guard = crate::store::TEST_V77_UNOWNED_PROJECT_LOCK.lock();
    let directory = tempfile::tempdir().unwrap();
    let pristine = directory.path().join("d04-v76-unowned.sqlite");

    // The declared owner is deliberately NOT the session-derived project, so a
    // migration that attributed every row by declaration would fail this test.
    let session_project = make_test_project("D04 session-derived owner");
    let declared_project = make_test_project("D04 declared owner");
    let mut session = make_test_session();
    session.project_id = Some(session_project.id);

    let (owned_id, unowned_id) = {
        let store = Store::open(&pristine).unwrap();
        store.insert_project(&session_project).unwrap();
        store.insert_project(&declared_project).unwrap();
        store.insert_session(&session).unwrap();

        let mut owned = make_new_issue("session-created issue");
        owned.project_id = session_project.id;
        owned.created_by_session_id = Some(session.id);
        let owned = store.create_issue(&owned).unwrap();

        let mut unowned = make_new_issue("operator-created issue");
        unowned.project_id = declared_project.id;
        unowned.created_by_session_id = None;
        let unowned = store.create_issue(&unowned).unwrap();

        // Remove the schema tail while its exact predecessor catalog is still
        // intact. Rebuilding the V76 issue pair first would correctly make the
        // V91/V90 catalog authenticator reject this raw fixture.
        d05_restore_v77_fixture(&store.conn);

        // Reconstruct the exact V76 issue shape, which carries no project_id
        // column at all. Deliberately raw fixture work, never a Store migration.
        store
            .conn
            .execute_batch(
                "PRAGMA foreign_keys = OFF;
             DROP INDEX idx_issue_dispatches_active_tracker_session;
             CREATE TABLE issues_v76 (
                 id TEXT PRIMARY KEY,
                 display_number INTEGER NOT NULL UNIQUE,
                 title TEXT NOT NULL,
                 body TEXT NOT NULL DEFAULT '',
                 status TEXT NOT NULL DEFAULT 'Open',
                 priority INTEGER,
                 labels TEXT NOT NULL DEFAULT '[]',
                 created_by_session_id TEXT,
                 assignee TEXT,
                 created_at TEXT NOT NULL,
                 updated_at TEXT NOT NULL,
                 closed_at TEXT
             );
             CREATE TABLE issue_deps_v76 (
                 issue_id TEXT NOT NULL REFERENCES issues_v76(id) ON DELETE CASCADE,
                 depends_on_id TEXT NOT NULL REFERENCES issues_v76(id) ON DELETE CASCADE,
                 created_at TEXT NOT NULL,
                 PRIMARY KEY (issue_id, depends_on_id),
                 CHECK (issue_id <> depends_on_id)
             );
             INSERT INTO issues_v76
                 SELECT id, display_number, title, body, status, priority, labels,
                        created_by_session_id, assignee, created_at, updated_at, closed_at
                 FROM issues;
             INSERT INTO issue_deps_v76
                 SELECT issue_id, depends_on_id, created_at FROM issue_deps;
             DROP TABLE issue_deps;
             DROP TABLE issues;
             ALTER TABLE issues_v76 RENAME TO issues;
             ALTER TABLE issue_deps_v76 RENAME TO issue_deps;
             CREATE INDEX idx_issues_status ON issues(status);
             CREATE INDEX idx_issues_created_by ON issues(created_by_session_id);
             CREATE INDEX idx_issue_deps_depends_on ON issue_deps(depends_on_id);
             PRAGMA foreign_keys = ON;",
            )
            .unwrap();
        store.conn.pragma_update(None, "user_version", 76).unwrap();
        (owned.id, unowned.id)
    };

    // Undeclared: refuse, name the blocking row, and leave V76 intact so the
    // operator can retry after declaring an owner.
    unsafe { std::env::remove_var("RSI_V77_UNOWNED_ISSUE_PROJECT") };
    let refusal = match Store::open(&pristine) {
        Ok(_) => panic!("V77 must refuse an undeclared unowned issue"),
        Err(error) => error.to_string(),
    };
    assert!(
        refusal.contains("RSI_V77_UNOWNED_ISSUE_PROJECT"),
        "refusal must name the declaration it needs: {refusal}"
    );
    assert!(
        refusal.contains(&unowned_id.to_string()),
        "refusal must name the blocking issue: {refusal}"
    );
    {
        let v76 = Connection::open(&pristine).unwrap();
        assert_eq!(
            v76.query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            76,
            "a refused V77 leaves the database on V76"
        );
    }

    // A declaration naming no real project is itself a mistake, not an owner.
    unsafe {
        std::env::set_var("RSI_V77_UNOWNED_ISSUE_PROJECT", Uuid::new_v4().to_string());
    }
    let bad_owner = match Store::open(&pristine) {
        Ok(_) => panic!("V77 must reject a declaration naming no real project"),
        Err(error) => error.to_string(),
    };
    assert!(
        bad_owner.contains("is not an existing project"),
        "unknown declared owner must be rejected: {bad_owner}"
    );

    // Declared: the unowned row is attributed to the declaration; the
    // session-created row keeps its session-derived project.
    unsafe {
        std::env::set_var(
            "RSI_V77_UNOWNED_ISSUE_PROJECT",
            declared_project.id.to_string(),
        );
    }
    let store = Store::open(&pristine).unwrap();
    unsafe { std::env::remove_var("RSI_V77_UNOWNED_ISSUE_PROJECT") };

    assert!(
        store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap()
            >= 77
    );

    let (unowned_project, unowned_creator) = store
        .conn
        .query_row(
            "SELECT project_id, created_by_session_id FROM issues WHERE id = ?1",
            [unowned_id.to_string()],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, Option<String>>(1)?)),
        )
        .unwrap();
    assert_eq!(
        unowned_project,
        declared_project.id.to_string(),
        "the unowned issue takes the declared owner"
    );
    assert_eq!(
        unowned_creator, None,
        "migration must not invent a creating session"
    );

    let (owned_project, owned_creator) = store
        .conn
        .query_row(
            "SELECT project_id, created_by_session_id FROM issues WHERE id = ?1",
            [owned_id.to_string()],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, Option<String>>(1)?)),
        )
        .unwrap();
    assert_eq!(
        owned_project,
        session_project.id.to_string(),
        "a session-created issue keeps its session-derived project"
    );
    assert_eq!(owned_creator, Some(session.id.to_string()));
}

#[test]
#[allow(clippy::unwrap_used)]
fn d04_issue_linkage_copied_v76_upgrade_reopen_fault_rollback_and_fingerprint() {
    let directory = tempfile::tempdir().unwrap();
    let pristine = directory.path().join("d04-v76.sqlite");
    let project = make_test_project("D04 copied V76");
    let mut session = make_test_session();
    session.project_id = Some(project.id);
    let alternate_project = make_test_project("D04 misleading alternate project");
    let mut alternate_session = make_test_session();
    alternate_session.project_id = Some(alternate_project.id);
    let (first_id, alternate_issue_id) = {
        let store = Store::open(&pristine).unwrap();
        store.insert_project(&project).unwrap();
        store.insert_project(&alternate_project).unwrap();
        store.insert_session(&session).unwrap();
        store.insert_session(&alternate_session).unwrap();
        let mut first = make_new_issue("migrated first");
        first.project_id = project.id;
        first.created_by_session_id = Some(session.id);
        let first = store.create_issue(&first).unwrap();
        let mut second = make_new_issue("migrated second");
        second.project_id = project.id;
        second.created_by_session_id = Some(session.id);
        let second = store.create_issue(&second).unwrap();
        store.add_issue_dep(second.id, first.id).unwrap();
        let mut alternate = make_new_issue("alternate project context");
        alternate.project_id = alternate_project.id;
        alternate.created_by_session_id = Some(alternate_session.id);
        let alternate = store.create_issue(&alternate).unwrap();

        // Authenticate and remove the post-V77 schema before deliberately
        // changing the issue catalog into the historical V76 shape.
        d05_restore_v77_fixture(&store.conn);

        // Reconstruct the exact V76 issue pair from a current isolated store.
        // This is deliberately raw fixture work, never a Store migration.
        store
            .conn
            .execute_batch(
                "PRAGMA foreign_keys = OFF;
             DROP INDEX idx_issue_dispatches_active_tracker_session;
             CREATE TABLE issues_v76 (
                 id TEXT PRIMARY KEY,
                 display_number INTEGER NOT NULL UNIQUE,
                 title TEXT NOT NULL,
                 body TEXT NOT NULL DEFAULT '',
                 status TEXT NOT NULL DEFAULT 'Open',
                 priority INTEGER,
                 labels TEXT NOT NULL DEFAULT '[]',
                 created_by_session_id TEXT,
                 assignee TEXT,
                 created_at TEXT NOT NULL,
                 updated_at TEXT NOT NULL,
                 closed_at TEXT
             );
             CREATE TABLE issue_deps_v76 (
                 issue_id TEXT NOT NULL REFERENCES issues_v76(id) ON DELETE CASCADE,
                 depends_on_id TEXT NOT NULL REFERENCES issues_v76(id) ON DELETE CASCADE,
                 created_at TEXT NOT NULL,
                 PRIMARY KEY (issue_id, depends_on_id),
                 CHECK (issue_id <> depends_on_id)
             );
             INSERT INTO issues_v76
                 SELECT id, display_number, title, body, status, priority, labels,
                        created_by_session_id, assignee, created_at, updated_at, closed_at
                 FROM issues;
             INSERT INTO issue_deps_v76
                 SELECT issue_id, depends_on_id, created_at FROM issue_deps;
             DROP TABLE issue_deps;
             DROP TABLE issues;
             ALTER TABLE issues_v76 RENAME TO issues;
             ALTER TABLE issue_deps_v76 RENAME TO issue_deps;
             CREATE INDEX idx_issues_status ON issues(status);
             CREATE INDEX idx_issues_created_by ON issues(created_by_session_id);
             CREATE INDEX idx_issue_deps_depends_on ON issue_deps(depends_on_id);
             PRAGMA foreign_keys = ON;",
            )
            .unwrap();
        // Future additive schemas must not leak into this exact V76 copied
        // fixture merely because it was constructed from the current Store.
        store.conn.pragma_update(None, "user_version", 76).unwrap();
        (first.id, alternate.id)
    };
    let v76 = Connection::open(&pristine).unwrap();
    let v76_snapshot = d04_database_snapshot(&v76).unwrap();
    assert_eq!(
        v76.query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        76
    );
    drop(v76);

    // A count-only assertion cannot falsify a changed legacy value. This
    // mutation preserves cardinality but must alter the canonical all-column
    // snapshot used by each fault rollback assertion below.
    let falsifier_path = directory.path().join("v76-fingerprint-falsifier.sqlite");
    std::fs::copy(&pristine, &falsifier_path).unwrap();
    let falsifier = Connection::open(&falsifier_path).unwrap();
    let original_issue_count: i64 = falsifier
        .query_row("SELECT count(*) FROM issues", [], |row| row.get(0))
        .unwrap();
    falsifier
        .execute(
            "UPDATE issues SET title = title || ' (mutated)' WHERE id = ?1",
            [first_id.to_string()],
        )
        .unwrap();
    assert_eq!(
        falsifier
            .query_row("SELECT count(*) FROM issues", [], |row| row
                .get::<_, i64>(0))
            .unwrap(),
        original_issue_count,
        "the D04 fingerprint falsifier deliberately preserves row count"
    );
    assert_ne!(
        d04_database_snapshot(&falsifier).unwrap().issues,
        v76_snapshot.issues,
        "a same-count legacy field mutation must change the all-column fingerprint"
    );
    drop(falsifier);

    // The preflight is an exact V76 catalog contract, not a column-only
    // convenience check. Each named legacy index and a semantically altered
    // table constraint must fail before V77 DDL can begin.
    for (label, mutation) in [
        ("status-index", "DROP INDEX idx_issues_status;".to_string()),
        (
            "creator-index",
            "DROP INDEX idx_issues_created_by;".to_string(),
        ),
        (
            "dependency-index",
            "DROP INDEX idx_issue_deps_depends_on;".to_string(),
        ),
        (
            "dependency-constraint",
            "PRAGMA writable_schema = ON;
             UPDATE sqlite_master
             SET sql = replace(sql, 'CHECK (issue_id <> depends_on_id)', 'CHECK (issue_id != depends_on_id)')
             WHERE type = 'table' AND name = 'issue_deps';
             PRAGMA writable_schema = OFF;
             PRAGMA schema_version = 900;"
                .to_string(),
        ),
    ] {
        let path = directory.path().join(format!("catalog-{label}.sqlite"));
        std::fs::copy(&pristine, &path).unwrap();
        Connection::open(&path).unwrap().execute_batch(&mutation).unwrap();
        assert!(Store::open(&path).is_err(), "{label} must fail V76 preflight");
        let raw = Connection::open(&path).unwrap();
        assert_eq!(
            raw.query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            76,
            "{label} must fail before V77 versioning"
        );
        assert_eq!(
            raw.query_row(
                "SELECT count(*) FROM sqlite_master WHERE name IN ('issues_v77', 'issue_deps_v77')",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
            0,
            "{label} must fail before V77 DDL"
        );
    }

    let resolver_failures = [
        (
            "creator-null",
            format!("UPDATE issues SET created_by_session_id = NULL WHERE id = '{first_id}';"),
        ),
        (
            "creator-missing",
            format!(
                "UPDATE issues SET created_by_session_id = '{}' WHERE id = '{first_id}';",
                Uuid::new_v4()
            ),
        ),
        (
            "creator-project-null",
            format!(
                "UPDATE sessions SET project_id = NULL WHERE id = '{}';",
                session.id
            ),
        ),
        (
            "creator-project-missing",
            format!(
                "PRAGMA foreign_keys = OFF; DELETE FROM projects WHERE id = '{}'; PRAGMA foreign_keys = ON;",
                project.id
            ),
        ),
        (
            "cross-project-dependency",
            format!(
                "INSERT INTO issue_deps(issue_id, depends_on_id, created_at)
                 VALUES ('{first_id}', '{alternate_issue_id}', '2026-07-31T00:00:00.000000000Z');"
            ),
        ),
    ];
    for (label, mutation) in resolver_failures {
        let path = directory.path().join(format!("resolver-{label}.sqlite"));
        std::fs::copy(&pristine, &path).unwrap();
        Connection::open(&path)
            .unwrap()
            .execute_batch(&mutation)
            .unwrap();
        assert!(Store::open(&path).is_err(), "{label} must fail closed");
        let raw = Connection::open(&path).unwrap();
        assert_eq!(
            d01_schema_fingerprint(&raw).unwrap(),
            v76_snapshot.catalog,
            "{label} must leave the exact V76 catalog intact"
        );
        assert_eq!(
            raw.query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            76
        );
    }

    // An alternate project/session is deliberately present in the copied V76
    // database; the creator Session remains the only resolver source.
    let misleading_path = directory.path().join("resolver-misleading-context.sqlite");
    std::fs::copy(&pristine, &misleading_path).unwrap();
    let misleading = Store::open(&misleading_path).unwrap();
    assert_eq!(
        misleading.get_issue(first_id).unwrap().unwrap().project_id,
        project.id,
        "the creator project wins over unrelated alternate project context"
    );
    drop(misleading);

    let repaired_path = directory.path().join("resolver-repaired.sqlite");
    std::fs::copy(&pristine, &repaired_path).unwrap();
    let raw = Connection::open(&repaired_path).unwrap();
    raw.execute(
        "UPDATE issues SET created_by_session_id = NULL WHERE id = ?1",
        [first_id.to_string()],
    )
    .unwrap();
    assert!(Store::open(&repaired_path).is_err());
    raw.execute(
        "UPDATE issues SET created_by_session_id = ?1 WHERE id = ?2",
        [session.id.to_string(), first_id.to_string()],
    )
    .unwrap();
    drop(raw);
    assert_eq!(
        Store::open(&repaired_path)
            .unwrap()
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        LATEST_SCHEMA_VERSION,
        "a repaired copied V76 fixture upgrades through the current schema exactly once on reopen"
    );

    // This separate successful upgrade provides the exact V77 row/catalog
    // reference for every repaired fault copy.
    let reference_path = directory.path().join("v77-reference.sqlite");
    std::fs::copy(&pristine, &reference_path).unwrap();
    let reference = Store::open(&reference_path).unwrap();
    let v77_snapshot = d04_database_snapshot(&reference.conn).unwrap();
    assert_eq!(v77_snapshot.version, LATEST_SCHEMA_VERSION);
    drop(reference);

    assert_eq!(D04MigrationFault::ALL.len(), 23);
    for fault in D04MigrationFault::ALL {
        let fault_path = directory.path().join(format!("fault-{fault:?}.sqlite"));
        std::fs::copy(&pristine, &fault_path).unwrap();
        d04_test_fail_next_migration(fault);
        let failed_store = Store::open(&fault_path);
        assert!(
            failed_store.is_err(),
            "{fault:?} must fail the V77 transaction"
        );
        drop(failed_store);
        let raw = Connection::open(&fault_path).unwrap();
        assert_eq!(
            d04_database_snapshot(&raw).unwrap(),
            v76_snapshot,
            "{fault:?} must leave exact V76 catalog, data, FK, and integrity state intact"
        );
        drop(raw);

        // Re-enter the documented Store-open repair path for this exact failed
        // copy, then prove its stable V77 state through a second reopen.
        let repaired = Store::open(&fault_path).unwrap();
        assert_eq!(
            d04_database_snapshot(&repaired.conn).unwrap(),
            v77_snapshot,
            "{fault:?} repair must preserve exact migrated Issue/dependency semantics"
        );
        drop(repaired);
        let reopened = Store::open(&fault_path).unwrap();
        assert_eq!(
            d04_database_snapshot(&reopened.conn).unwrap(),
            v77_snapshot,
            "{fault:?} repaired copy must survive close/reopen unchanged"
        );
        drop(reopened);
    }

    let upgraded = Store::open(&pristine).unwrap();
    assert_eq!(
        upgraded
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        LATEST_SCHEMA_VERSION
    );
    assert_eq!(d04_database_snapshot(&upgraded.conn).unwrap(), v77_snapshot);
    let table_sql: String = upgraded
        .conn
        .query_row(
            "SELECT sql FROM sqlite_master WHERE type = 'table' AND name = 'issues'",
            [],
            |row| row.get(0),
        )
        .unwrap();
    assert!(table_sql.contains("project_id TEXT NOT NULL"));
    assert!(table_sql.contains("source_finding_ref"));
    drop(upgraded);
    let reopened = Store::open(&pristine).unwrap();
    assert_eq!(d04_database_snapshot(&reopened.conn).unwrap(), v77_snapshot);
}

#[test]
#[allow(clippy::unwrap_used)]
