#[test]
#[allow(clippy::unwrap_used)]
fn d04_composite_foreign_keys_reject_cross_project_idea_event_and_deps() -> anyhow::Result<()> {
    let fixture = d01_kernel_fixture()?;
    let issue_a = fixture.store.create_issue(&NewIssue {
        project_id: fixture.project_a.id,
        title: "project A issue".into(),
        body: String::new(),
        priority: None,
        labels: vec![],
        created_by_session_id: None,
        assignee: None,
        idea_id: None,
        source_event_id: None,
        source_finding_ref: None,
    })?;
    let issue_b = fixture.store.create_issue(&NewIssue {
        project_id: fixture.project_b.id,
        title: "project B issue".into(),
        body: String::new(),
        priority: None,
        labels: vec![],
        created_by_session_id: None,
        assignee: None,
        idea_id: None,
        source_event_id: None,
        source_finding_ref: None,
    })?;

    assert!(fixture.store.add_issue_dep(issue_a.id, issue_b.id).is_err());
    assert!(
        fixture
            .store
            .conn
            .execute(
                "UPDATE issues SET idea_id = ?1 WHERE id = ?2",
                [fixture.idea_b.id.to_string(), issue_a.id.to_string()],
            )
            .is_err(),
        "Issue->Idea composite project FK must reject a cross-project link"
    );

    let mut event_b = d01_event(&fixture, 1)?;
    event_b.id = Uuid::new_v4();
    event_b.project_id = fixture.project_b.id;
    event_b.idea_id = fixture.idea_b.id;
    event_b.idempotency_key = "project-b:event:1".to_string();
    fixture.store.insert_d01_event_fixture(&event_b)?;
    assert!(
        fixture
            .store
            .conn
            .execute(
                "UPDATE issues SET idea_id = ?1, source_event_id = ?2 WHERE id = ?3",
                [
                    fixture.idea_a1.id.to_string(),
                    event_b.id.to_string(),
                    issue_a.id.to_string(),
                ],
            )
            .is_err(),
        "Issue->IdeaEvent composite project/Idea FK must reject a foreign event"
    );
    assert!(
        fixture
            .store
            .get_issue(issue_a.id)?
            .unwrap()
            .idea_id
            .is_none()
    );
    assert!(
        fixture
            .store
            .get_issue(issue_a.id)?
            .unwrap()
            .source_event_id
            .is_none()
    );
    Ok(())
}

#[test]
#[allow(clippy::unwrap_used)]
fn d04_link_constraint_classes_are_typed_and_rpc_data_is_redacted() {
    use crate::store::ideas::{SqliteFailureClass, classify_sqlite_error, map_sql_error};

    fn sqlite_failure(code: i32) -> rusqlite::Error {
        rusqlite::Error::SqliteFailure(
            rusqlite::ffi::Error::new(code),
            Some("raw SQL must stay private".into()),
        )
    }

    for (sqlite_code, failure_class, constraint_class) in [
        (
            rusqlite::ffi::SQLITE_CONSTRAINT_FOREIGNKEY,
            SqliteFailureClass::ForeignKey,
            IssueLinkConstraintClass::ForeignKey,
        ),
        (
            rusqlite::ffi::SQLITE_CONSTRAINT_CHECK,
            SqliteFailureClass::Check,
            IssueLinkConstraintClass::Check,
        ),
        (
            rusqlite::ffi::SQLITE_CONSTRAINT_NOTNULL,
            SqliteFailureClass::NotNull,
            IssueLinkConstraintClass::NotNull,
        ),
        (
            rusqlite::ffi::SQLITE_CONSTRAINT_UNIQUE,
            SqliteFailureClass::UniqueOrPrimary,
            IssueLinkConstraintClass::UniquePrimary,
        ),
        (
            rusqlite::ffi::SQLITE_CONSTRAINT_PRIMARYKEY,
            SqliteFailureClass::UniqueOrPrimary,
            IssueLinkConstraintClass::UniquePrimary,
        ),
    ] {
        assert_eq!(
            classify_sqlite_error(&sqlite_failure(sqlite_code)),
            failure_class
        );
        let error = map_sql_error(sqlite_failure(sqlite_code));
        assert_eq!(
            error,
            IdeaControlError::ConstraintViolation {
                class: constraint_class
            }
        );
        let rpc = crate::rpc::link_issue_rpc_error(&error);
        let crate::error::DaemonError::StructuredRpc {
            rpc_code,
            message,
            data,
        } = rpc
        else {
            panic!("constraint error must remain a structured RPC failure");
        };
        assert_eq!(rpc_code, rsi_common::rpc::INTERNAL_ERROR);
        assert_eq!(message, "Issue link integrity constraint failed");
        assert_eq!(data["code"], "ISSUE_LINK_CONSTRAINT_FAILURE");
        assert_eq!(data["details"]["class"], constraint_class.as_str());
        assert!(!data.to_string().contains("raw SQL must stay private"));
    }
}

fn assert_issue_event_semantics_are_complete(event: &rsi_common::types::IssueEventV1) {
    use rsi_common::types::IssueSemanticOperationV1;

    event.request.validate().unwrap();
    assert_eq!(
        event.request.fingerprint().unwrap(),
        event.request_fingerprint
    );
    assert_eq!(event.operation, event.request.operation.event_operation());
    assert_eq!(event.issue.id, event.issue_id);
    assert_eq!(event.issue.project_id, event.project_id);
    assert_eq!(event.issue.row_version, event.resulting_row_version);
    assert_eq!(event.sequence, event.resulting_row_version);
    assert_eq!(
        event
            .occurred_at
            .to_rfc3339_opts(chrono::SecondsFormat::Nanos, true)
            .len(),
        30
    );
    match &event.request.operation {
        IssueSemanticOperationV1::BaselineImported {
            issue_id,
            project_id,
        } => {
            assert_eq!(*issue_id, event.issue_id);
            assert_eq!(*project_id, event.project_id);
        }
        IssueSemanticOperationV1::Created { create } => {
            assert_eq!(create.issue_id, event.issue.id);
            assert_eq!(create.project_id, event.issue.project_id);
            assert_eq!(create.title, event.issue.title);
            assert_eq!(create.body, event.issue.body);
            assert_eq!(create.priority, event.issue.priority);
            assert_eq!(create.labels, event.issue.labels);
            assert_eq!(
                create.created_by_session_id,
                event.issue.created_by_session_id
            );
            assert_eq!(create.assignee, event.issue.assignee);
        }
        IssueSemanticOperationV1::ContentUpdated {
            issue_id,
            expected_row_version,
            patch,
        } => {
            assert_eq!(*issue_id, event.issue_id);
            assert_eq!(*expected_row_version, event.expected_row_version);
            if let Some(title) = &patch.title {
                assert_eq!(title, &event.issue.title);
            }
            if let Some(body) = &patch.body {
                assert_eq!(body, &event.issue.body);
            }
            if let Some(labels) = &patch.labels {
                assert_eq!(labels, &event.issue.labels);
            }
            if let Some(priority) = patch.priority {
                assert_eq!(Some(priority), event.issue.priority);
            }
            if patch.clear_priority {
                assert_eq!(event.issue.priority, None);
            }
            if let Some(assignee) = &patch.assignee {
                assert_eq!(Some(assignee), event.issue.assignee.as_ref());
            }
            if patch.clear_assignee {
                assert_eq!(event.issue.assignee, None);
            }
        }
        IssueSemanticOperationV1::StatusUpdated {
            issue_id,
            expected_row_version,
            status,
        } => {
            assert_eq!(*issue_id, event.issue_id);
            assert_eq!(*expected_row_version, event.expected_row_version);
            assert_eq!(*status, event.issue.status);
        }
        IssueSemanticOperationV1::Archived {
            issue_id,
            expected_row_version,
        } => {
            assert_eq!(*issue_id, event.issue_id);
            assert_eq!(*expected_row_version, event.expected_row_version);
            assert!(event.issue.archived_at.is_some());
        }
        IssueSemanticOperationV1::Restored {
            issue_id,
            expected_row_version,
        } => {
            assert_eq!(*issue_id, event.issue_id);
            assert_eq!(*expected_row_version, event.expected_row_version);
            assert!(event.issue.archived_at.is_none());
        }
        IssueSemanticOperationV1::IdeaLinked {
            issue_id,
            expected_row_version,
            idea_id,
            source_event_id,
            source_finding_ref,
        } => {
            assert_eq!(*issue_id, event.issue_id);
            assert_eq!(*expected_row_version, event.expected_row_version);
            assert_eq!(Some(*idea_id), event.issue.idea_id);
            assert_eq!(*source_event_id, event.issue.source_event_id);
            assert_eq!(*source_finding_ref, event.issue.source_finding_ref);
        }
    }
}

#[tokio::test]
#[allow(clippy::unwrap_used)]
async fn issue_writer_d04_link_issue_operator_cas_replay_changed_conflict_and_atomic_event() {
    use rsi_common::rpc::LinkIssueToIdeaParams;
    use rsi_common::types::IssueSourceFindingRef;

    let project_id = d04_test_project_id();
    let store = std::sync::Arc::new(tokio::sync::Mutex::new(Store::open_in_memory().unwrap()));
    let handle =
        IdeaControlHandle::for_operator(std::sync::Arc::clone(&store), project_id, "d04-operator")
            .unwrap();
    let digest = Sha256Digest::parse(format!("sha256:{}", "d".repeat(64))).unwrap();
    let capture = Capture {
        id: Uuid::new_v4(),
        project_id,
        creator_kind: IdeaActorKind::Operator,
        creator_id: "d04-operator".to_string(),
        captured_at: chrono::Utc::now(),
        source_kind: CaptureSourceKind::OperatorInput,
        raw_content_digest: digest.clone(),
        storage_policy_id: "cas-v1".to_string(),
        content_ref: ContentAddressedRef::for_digest(&digest),
    };
    store
        .lock()
        .await
        .insert_d02_capture_fixture(&capture)
        .unwrap();
    let create = CreateIdeaRequestV1 {
        idempotency_key: "d04-link-idea".to_string(),
        genesis_capture_id: capture.id,
        genesis_span: None,
        slug: "d04-link-idea".to_string(),
        sigil: Some("D4".to_string()),
        title: "D04 link target".to_string(),
        description: "link test".to_string(),
        portfolio_summary: "link test".to_string(),
        priority: 1,
        autonomy_policy: AutonomyPolicy::CaptureOnly,
        integration_target_ref: "refs/heads/main".to_string(),
        program_template_policy_id: Some("default-v1".to_string()),
        derived_from_idea_id: None,
        artifact_digests: vec![digest.clone()],
        evidence_digests: vec![digest.clone()],
    };
    let created = handle.create_idea(&create).await.unwrap();
    for (index, (fault, class)) in [
        (
            super::ideas::IssueLinkWriteFault::ConstraintForeignKey,
            IssueLinkConstraintClass::ForeignKey,
        ),
        (
            super::ideas::IssueLinkWriteFault::ConstraintCheck,
            IssueLinkConstraintClass::Check,
        ),
        (
            super::ideas::IssueLinkWriteFault::ConstraintNotNull,
            IssueLinkConstraintClass::NotNull,
        ),
        (
            super::ideas::IssueLinkWriteFault::ConstraintUniquePrimary,
            IssueLinkConstraintClass::UniquePrimary,
        ),
    ]
    .into_iter()
    .enumerate()
    {
        let issue = store
            .lock()
            .await
            .create_issue(&make_new_issue(&format!("constraint link {index}")))
            .unwrap();
        super::ideas::inject_d04_issue_link_write_fault(fault);
        let err = handle
            .link_issue_to_idea(&LinkIssueToIdeaParams {
                idea_id: created.idea.id,
                expected_idea_row_version: created.idea.row_version,
                idempotency_key: format!("d04-link-constraint-{index}"),
                issue_id: issue.id,
                source_event_id: None,
                source_finding_ref: None,
            })
            .await
            .unwrap_err();
        assert_eq!(err, IdeaControlError::ConstraintViolation { class });
        let persisted = store.lock().await.get_issue(issue.id).unwrap().unwrap();
        assert!(persisted.idea_id.is_none() && persisted.source_event_id.is_none());
    }
    for (index, fault) in [
        super::ideas::IssueLinkWriteFault::AfterIdeaCas,
        super::ideas::IssueLinkWriteFault::AfterIssueUpdate,
        super::ideas::IssueLinkWriteFault::AfterEventInsert,
        super::ideas::IssueLinkWriteFault::BeforeCommit,
    ]
    .into_iter()
    .enumerate()
    {
        let fault_issue = store
            .lock()
            .await
            .create_issue(&make_new_issue(&format!("link fault {index}")))
            .unwrap();
        super::ideas::inject_d04_issue_link_write_fault(fault);
        let fault_request = LinkIssueToIdeaParams {
            idea_id: created.idea.id,
            expected_idea_row_version: created.idea.row_version,
            idempotency_key: format!("d04-link-fault-{index}"),
            issue_id: fault_issue.id,
            source_event_id: Some(created.event.id),
            source_finding_ref: None,
        };
        assert!(matches!(
            handle.link_issue_to_idea(&fault_request).await,
            Err(IdeaControlError::StorageFailure(_))
        ));
        assert!(
            store
                .lock()
                .await
                .get_issue(fault_issue.id)
                .unwrap()
                .unwrap()
                .idea_id
                .is_none()
        );
        let history = store
            .lock()
            .await
            .list_issue_events_v1(&rsi_common::types::IssueEventPageRequestV1 {
                issue_id: fault_issue.id,
                after_sequence: 0,
                limit: None,
            })
            .unwrap();
        assert_eq!(history.events.len(), 1, "Issue event survived {fault:?}");
    }
    let issue = store
        .lock()
        .await
        .create_issue(&make_new_issue("link candidate"))
        .unwrap();
    let finding =
        IssueSourceFindingRef::parse(format!("finding:v1:sha256:{}:F-D04-001", "d".repeat(64)))
            .unwrap();
    let request = LinkIssueToIdeaParams {
        idea_id: created.idea.id,
        expected_idea_row_version: created.idea.row_version,
        idempotency_key: "d04-link-issue".to_string(),
        issue_id: issue.id,
        source_event_id: Some(created.event.id),
        source_finding_ref: Some(finding.clone()),
    };
    let linked = handle.link_issue_to_idea(&request).await.unwrap();
    assert!(!linked.deduplicated);
    assert_eq!(linked.issue.idea_id, Some(created.idea.id));
    assert_eq!(linked.issue.source_event_id, Some(created.event.id));
    assert_eq!(linked.issue.source_finding_ref, Some(finding.clone()));
    assert_eq!(linked.issue.row_version, issue.row_version + 1);
    assert_eq!(linked.idea.row_version, created.idea.row_version + 1);
    assert_eq!(linked.event.event_type, IdeaEventType::IssueLinked);
    let issue_history = store
        .lock()
        .await
        .list_issue_events_v1(&rsi_common::types::IssueEventPageRequestV1 {
            issue_id: issue.id,
            after_sequence: 0,
            limit: None,
        })
        .unwrap();
    assert_eq!(issue_history.events.len(), 2);
    let issue_event = issue_history.events.last().unwrap();
    assert_eq!(
        issue_event.actor_kind,
        rsi_common::types::IssueActorKindV1::Operator
    );
    assert_eq!(
        issue_event.actor_label.as_deref(),
        Some("rsi-rpc:LinkIssueToIdea")
    );
    assert_eq!(issue_event.issue, linked.issue);
    assert_issue_event_semantics_are_complete(issue_event);
    assert!(matches!(
        &issue_event.request.operation,
        rsi_common::types::IssueSemanticOperationV1::IdeaLinked {
            issue_id,
            expected_row_version,
            idea_id,
            source_event_id,
            source_finding_ref,
        } if *issue_id == issue.id
            && *expected_row_version == issue.row_version
            && *idea_id == created.idea.id
            && *source_event_id == Some(created.event.id)
            && source_finding_ref.as_ref() == Some(&finding)
    ));

    let replay = handle.link_issue_to_idea(&request).await.unwrap();
    assert!(replay.deduplicated);
    assert_eq!(replay.event.id, linked.event.id);
    assert_eq!(
        store
            .lock()
            .await
            .list_issue_events_v1(&rsi_common::types::IssueEventPageRequestV1 {
                issue_id: issue.id,
                after_sequence: 0,
                limit: None,
            })
            .unwrap()
            .events
            .len(),
        2,
        "Idea replay duplicated the Issue event"
    );

    let mut changed = request.clone();
    changed.source_finding_ref = Some(
        IssueSourceFindingRef::parse(format!("finding:v1:sha256:{}:F-D04-002", "e".repeat(64)))
            .unwrap(),
    );
    assert!(matches!(
        handle.link_issue_to_idea(&changed).await,
        Err(IdeaControlError::IdempotencyConflict)
    ));
    let persisted = store.lock().await.get_issue(issue.id).unwrap().unwrap();
    assert_eq!(persisted.idea_id, Some(created.idea.id));
}

