#[test]
#[allow(clippy::unwrap_used)]
fn d04_active_dispatch_restore_query_is_project_scoped_and_keyed() {
    let store = Store::open_in_memory().unwrap();
    let issue = store.create_issue(&make_new_issue("local")).unwrap();
    assert!(
        store
            .get_issue_in_project(issue.project_id, issue.id)
            .unwrap()
            .is_some()
    );
    assert!(
        store
            .get_issue_in_project(Uuid::new_v4(), issue.id)
            .unwrap()
            .is_none()
    );
    let mut session = make_test_session();
    session.project_id = Some(issue.project_id);
    store.insert_session(&session).unwrap();
    store
        .insert_issue_dispatch(&crate::issue_tracker::types::DispatchRecord {
            issue_id: issue.id.to_string(),
            issue_identifier: "LOCAL-plan".to_string(),
            tracker: "local".to_string(),
            session_id: session.id,
            dispatched_at: chrono::Utc::now(),
            last_reconciled_at: None,
            terminal_state: None,
        })
        .unwrap();
    let mut statement = store
        .conn
        .prepare(
            "EXPLAIN QUERY PLAN
             SELECT d.issue_id, d.issue_identifier, d.tracker, d.session_id,
                    d.dispatched_at, d.last_reconciled_at, d.terminal_state
             FROM issue_tracker_dispatches d
             JOIN sessions s ON s.id = d.session_id
             JOIN issues i ON i.id = d.issue_id AND i.project_id = s.project_id
             WHERE d.terminal_state IS NULL
               AND d.tracker = ?1
               AND s.project_id = ?2
               AND i.project_id = ?2
             ORDER BY d.issue_id",
        )
        .unwrap();
    let plan = statement
        .query_map(
            rusqlite::params!["local", issue.project_id.to_string()],
            |row| row.get::<_, String>(3),
        )
        .unwrap()
        .collect::<rusqlite::Result<Vec<_>>>()
        .unwrap()
        .join("\n");
    assert!(
        plan.contains("idx_issue_dispatches_active_tracker_session"),
        "{plan}"
    );
    assert!(plan.contains("sqlite_autoindex_sessions_1"), "{plan}");
    assert!(
        plan.contains("SEARCH i USING") && plan.contains("(id=? AND project_id=?)"),
        "{plan}"
    );
    assert!(
        !plan.contains("SCAN"),
        "restore plan must remain keyed: {plan}"
    );
    assert!(
        !plan.contains("TEMP B-TREE"),
        "restore plan must not materialize an order sort: {plan}"
    );
}

#[tokio::test]
#[allow(clippy::unwrap_used)]
async fn d04_uuidv5_domains_and_display_numbers_are_unchanged() {
    let store = std::sync::Arc::new(tokio::sync::Mutex::new(Store::open_in_memory().unwrap()));
    let active = std::sync::Arc::new(tokio::sync::RwLock::new(std::collections::HashMap::new()));
    let completed = std::sync::Arc::new(tokio::sync::RwLock::new(std::collections::HashMap::new()));
    let (sender, _receiver) = tokio::sync::mpsc::channel(1);
    let control = crate::session::agent_verbs::AgentControlHandle::new(
        active,
        completed,
        std::sync::Arc::clone(&store),
        std::sync::Arc::new(crate::bus::EventBus::new(4)),
        std::sync::Arc::new(crate::session::spawn_coordinator::SpawnCoordinator::new(
            sender,
        )),
    );
    let caller = Uuid::new_v4();
    store
        .lock()
        .await
        .insert_session(&{
            let mut session = make_test_session();
            session.id = caller;
            session
        })
        .unwrap();
    let params = rsi_common::rpc::AgentCreateIssueParams {
        title: "attributed".into(),
        body: String::new(),
        priority: None,
        labels: vec![],
        assignee: None,
        idempotency_key: "d04-pinned-domain".into(),
    };
    let attributed = control
        .agent_create_issue(caller, params.clone())
        .await
        .unwrap();
    let mut name = b"agent-create\0".to_vec();
    name.extend_from_slice(caller.to_string().as_bytes());
    name.push(0);
    name.extend_from_slice(params.idempotency_key.as_bytes());
    assert_eq!(
        attributed.issue.id,
        Uuid::new_v5(
            &Uuid::from_u128(0x5da3_4881_ecc9_54fb_a7da_3913_bc97_8130),
            &name
        )
    );
    let operator = store
        .lock()
        .await
        .create_issue(&make_new_issue("operator"))
        .unwrap();
    assert_eq!(
        (attributed.issue.display_number, operator.display_number),
        (1, 2),
        "UUIDv5 attributed creation must not fork global display allocation"
    );
}

