#[test]
fn test_store_open_creates_schema() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    // Verify tables exist by querying sqlite_master
    let mut stmt = store
        .conn
        .prepare("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
        .unwrap();
    let tables: Vec<String> = stmt
        .query_map([], |row| row.get(0))
        .unwrap()
        .filter_map(|r| r.ok())
        .collect();

    assert!(tables.contains(&"sessions".to_string()));
    assert!(tables.contains(&"conversation_events".to_string()));
    assert!(tables.contains(&"approvals".to_string()));
    assert!(tables.contains(&"sandbox_reclaim_runs".to_string()));
    assert!(tables.contains(&"sandbox_reclaim_items".to_string()));
    assert!(tables.contains(&"sandbox_reclaim_recreations".to_string()));

    let version: i32 = store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .unwrap();
    assert_eq!(version, LATEST_SCHEMA_VERSION);

    let has_pending_question_json: i64 = store
        .conn
        .query_row(
            "SELECT COUNT(*) FROM pragma_table_info('sessions') WHERE name = 'pending_question_json'",
            [],
            |row| row.get(0),
        )
        .unwrap();
    assert_eq!(has_pending_question_json, 1);
}

#[test]
#[allow(clippy::unwrap_used)]
fn sandbox_reclaim_one_effectful_item_per_custody_generation_across_runs() {
    let store = Store::open_in_memory().unwrap();
    store.conn.execute_batch("PRAGMA foreign_keys=OFF").unwrap();
    let custody_id = Uuid::new_v4().to_string();
    let stamp = "2026-09-23T12:00:00.000000000Z";
    let insert_item = |run_id: Uuid, effectful: bool| {
        let (class, phase) = if effectful {
            ("absent_adopted", "settled")
        } else {
            ("retained", "retained")
        };
        store.conn.execute(
            "INSERT INTO sandbox_reclaim_items(
                run_id,custody_id,generation,class,effectful,sandbox_root,
                sandbox_branch,phase,updated_at
             ) VALUES(?1,?2,1,?3,?4,'/tmp/reclaim-index-test',
                'rsi/reclaim-index-test',?5,?6)",
            rusqlite::params![
                run_id.to_string(),
                custody_id,
                class,
                i64::from(effectful),
                phase,
                stamp,
            ],
        )
    };

    let retained_run = Uuid::new_v4();
    let first_effectful_run = Uuid::new_v4();
    let second_effectful_run = Uuid::new_v4();
    insert_item(retained_run, false).unwrap();
    insert_item(first_effectful_run, true).unwrap();
    let duplicate = insert_item(second_effectful_run, true).unwrap_err();
    assert!(duplicate.to_string().contains("UNIQUE constraint failed"));

    let (rows, effectful_rows): (i64, i64) = store
        .conn
        .query_row(
            "SELECT count(*),sum(effectful) FROM sandbox_reclaim_items
             WHERE custody_id=?1 AND generation=1",
            [&custody_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .unwrap();
    assert_eq!((rows, effectful_rows), (2, 1));
}

#[test]
#[allow(clippy::unwrap_used)]
fn sandbox_reclaim_manager_operation_reuses_run_and_unique_index_rejects_duplicate() {
    let store = Store::open_in_memory().unwrap();
    let operation_id = Uuid::new_v4();
    let (first_run, inserted) = store
        .begin_absent_adoption_run("manager", false, 16, Some(operation_id))
        .unwrap();
    assert!(inserted);
    let (reused_run, inserted) = store
        .begin_absent_adoption_run("manager", false, 16, Some(operation_id))
        .unwrap();
    assert_eq!(reused_run, first_run);
    assert!(!inserted);

    let duplicate = store.conn.execute(
        "INSERT INTO sandbox_reclaim_runs(
            run_id,trigger,dry_run,requested_max,manager_operation_id,started_at
         ) VALUES(?1,'manager',0,16,?2,'2026-09-23T12:00:00.000000000Z')",
        rusqlite::params![Uuid::new_v4().to_string(), operation_id.to_string()],
    );
    assert!(
        duplicate
            .unwrap_err()
            .to_string()
            .contains("UNIQUE constraint failed")
    );

    let (first_null_run, first_inserted) = store
        .begin_absent_adoption_run("startup", false, 16, None)
        .unwrap();
    let (second_null_run, second_inserted) = store
        .begin_absent_adoption_run("startup", false, 16, None)
        .unwrap();
    assert!(first_inserted && second_inserted);
    assert_ne!(first_null_run, second_null_run);
    let null_rows: i64 = store
        .conn
        .query_row(
            "SELECT count(*) FROM sandbox_reclaim_runs WHERE manager_operation_id IS NULL",
            [],
            |row| row.get(0),
        )
        .unwrap();
    assert_eq!(null_rows, 2);
}

