// ---- Issue #16: `PRAGMA user_version` read failures must propagate ----

thread_local! {
    /// Counts `PRAGMA user_version` *read* attempts denied on this thread since
    /// `UserVersionReadDenial::install`. Reset on install so a reused harness
    /// thread cannot leak an earlier count into the next fixture.
    static USER_VERSION_READ_ATTEMPTS: std::cell::Cell<u32> = const { std::cell::Cell::new(0) };
}

/// Deny only the *read* form of `PRAGMA user_version`.
///
/// SQLite passes a null `arg2` for the read form and a non-null argument for the
/// `= N` write form, so this predicate induces a genuine failing read without
/// blocking the migrations' own version writes, which the failure path must never
/// reach. Every other statement is authorized normally, which is what makes this
/// a targeted fault rather than a broken fixture. Verified against
/// `sqlite3AuthCheck`'s single `SQLITE_PRAGMA` call site in the
/// SQLite amalgamation: the pragma name is `arg1`.
unsafe extern "C" fn deny_user_version_read(
    _user_data: *mut std::os::raw::c_void,
    action: std::os::raw::c_int,
    arg1: *const std::os::raw::c_char,
    arg2: *const std::os::raw::c_char,
    _arg3: *const std::os::raw::c_char,
    _arg4: *const std::os::raw::c_char,
) -> std::os::raw::c_int {
    if action != rusqlite::ffi::SQLITE_PRAGMA || arg1.is_null() || !arg2.is_null() {
        return rusqlite::ffi::SQLITE_OK;
    }
    // SAFETY: `arg1` is non-null (checked above) and SQLite guarantees a
    // NUL-terminated pragma name for the duration of the callback.
    let pragma = unsafe { std::ffi::CStr::from_ptr(arg1) };
    if pragma.to_string_lossy() != "user_version" {
        return rusqlite::ffi::SQLITE_OK;
    }
    USER_VERSION_READ_ATTEMPTS.with(|attempts| attempts.set(attempts.get() + 1));
    rusqlite::ffi::SQLITE_DENY
}

/// RAII fault injection for a failing `PRAGMA user_version` read. Install it
/// only around an `init_schema` call under test; `Drop` clears the authorizer.
struct UserVersionReadDenial {
    handle: *mut rusqlite::ffi::sqlite3,
}

impl UserVersionReadDenial {
    fn install(connection: &Connection) -> Self {
        USER_VERSION_READ_ATTEMPTS.with(|attempts| attempts.set(0));
        // SAFETY: `handle` is the live connection this guard borrows from by
        // reference; the guard clears the authorizer before that borrow ends.
        let handle = unsafe { connection.handle() };
        let rc = unsafe {
            rusqlite::ffi::sqlite3_set_authorizer(
                handle,
                Some(deny_user_version_read),
                std::ptr::null_mut(),
            )
        };
        assert_eq!(
            rc,
            rusqlite::ffi::SQLITE_OK,
            "install user_version read denial"
        );
        Self { handle }
    }

    /// Denied `user_version` reads observed since `install`.
    fn denied_reads(&self) -> u32 {
        USER_VERSION_READ_ATTEMPTS.with(|attempts| attempts.get())
    }
}

impl Drop for UserVersionReadDenial {
    fn drop(&mut self) {
        // SAFETY: the authorizer is cleared on the same live connection.
        unsafe {
            rusqlite::ffi::sqlite3_set_authorizer(self.handle, None, std::ptr::null_mut());
        }
    }
}

/// Order-independent `sqlite_master` snapshot used to prove a refused migration
/// did not create or rewrite schema objects.
fn schema_catalog_snapshot(connection: &Connection) -> Vec<(String, String, String)> {
    let mut statement = connection
        .prepare(
            "SELECT type, name, COALESCE(sql, '') FROM sqlite_master
             WHERE name NOT LIKE 'sqlite_%' ORDER BY type, name",
        )
        .expect("prepare catalog snapshot");
    statement
        .query_map([], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)))
        .expect("query catalog snapshot")
        .map(|row| row.expect("read catalog row"))
        .collect()
}

fn assert_user_version_read_was_denied(error: DaemonError) {
    match error {
        DaemonError::Database(rusqlite::Error::SqliteFailure(failure, _)) => assert_eq!(
            failure.extended_code,
            rusqlite::ffi::SQLITE_AUTH,
            "a denied user_version read must surface as SQLITE_AUTH, got {failure:?}"
        ),
        other => panic!("expected a typed Database(SqliteFailure) error, got {other:?}"),
    }
}

#[test]
#[allow(clippy::unwrap_used)]
fn init_schema_propagates_a_failed_user_version_read_without_migrating() {
    let store = raw_in_memory_store_for_test().unwrap();
    let version: i32 = store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .unwrap();
    assert_eq!(version, 0, "fixture must start genuinely unversioned");

    let denial = UserVersionReadDenial::install(&store.conn);
    let error = store
        .init_schema()
        .expect_err("a failing user_version read must not be coerced to version 0");
    assert_user_version_read_was_denied(error);
    assert!(
        denial.denied_reads() >= 1,
        "the fixture must have genuinely attempted the denied read"
    );
    drop(denial);

    // Before the fix, the failed read was coerced to 0 and every
    // `if version < N` block re-ran, starting with V0's non-idempotent DDL.
    // Assert the positive end state: nothing ran and the database is still
    // unversioned and empty.
    let version_after: i32 = store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .unwrap();
    assert_eq!(
        version_after, 0,
        "a failed version read must not advance the schema version"
    );
    assert!(
        !table_exists(&store.conn, "sessions"),
        "V0 DDL must not run after a failed version read"
    );
    assert!(
        schema_catalog_snapshot(&store.conn).is_empty(),
        "a failed version read must not create schema objects"
    );
}

#[test]
#[allow(clippy::unwrap_used)]
fn init_schema_runs_the_full_chain_for_a_new_database_reading_version_zero() {
    let store = raw_in_memory_store_for_test().unwrap();
    // The preserved behavior: a genuine, *successful* 0 read still migrates.
    let version: i32 = store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .unwrap();
    assert_eq!(version, 0);

    store
        .init_schema()
        .expect("a genuine user_version=0 must run the whole migration chain");

    let version: i32 = store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .unwrap();
    assert_eq!(version, LATEST_SCHEMA_VERSION);
    assert!(
        table_exists(&store.conn, "sessions"),
        "V0 must create the base tables for a new database"
    );
}

#[test]
#[allow(clippy::unwrap_used)]
fn init_schema_failed_version_read_leaves_a_migrated_database_untouched() {
    let store = Store::open_in_memory().unwrap();
    let baseline_version: i32 = store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .unwrap();
    assert_eq!(baseline_version, LATEST_SCHEMA_VERSION);

    let session = make_test_session();
    store.insert_session(&session).unwrap();
    let baseline_catalog = schema_catalog_snapshot(&store.conn);

    let denial = UserVersionReadDenial::install(&store.conn);
    let error = store
        .init_schema()
        .expect_err("a failing user_version read on a migrated database must refuse");
    assert_user_version_read_was_denied(error);
    assert!(denial.denied_reads() >= 1);
    drop(denial);

    let version_after: i32 = store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .unwrap();
    assert_eq!(version_after, LATEST_SCHEMA_VERSION);
    assert!(
        store.get_session(session.id).unwrap().is_some(),
        "the seeded row must survive a failed version read"
    );
    assert_eq!(
        schema_catalog_snapshot(&store.conn),
        baseline_catalog,
        "a failed version read must not re-run migration DDL over a migrated database"
    );
}

#[test]
fn closure_v84_copied_v83_upgrades_twice_with_catalog_guards_intact() {
    let directory = tempfile::tempdir().unwrap();
    let database = directory.path().join("copied-v83.sqlite");
    {
        let store = Store::open(&database).unwrap();
        rewind_store_to_schema_version(&store.conn, 83);
        assert_eq!(
            store
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            83
        );
    }

    let first_program = Uuid::new_v4().to_string();
    let second_program = Uuid::new_v4().to_string();
    let destination = "refs/heads/rolling";
    let digest = format!("sha256:{}", "1".repeat(64));
    let head = "a".repeat(40);
    let now = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Nanos, true);
    {
        let store =
            Store::open_test_predecessor_v84(&database).expect("copied V83 upgrades to V84");
        assert_eq!(
            store
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            84
        );
        let insert_program = |id: &str, key: Uuid| {
            store.conn.execute(
                "INSERT INTO closure_programs
                 (id,version,repository_root,repository_identity,base_ref,base_sha,
                  destination_ref,destination_pre_head,state,destination_claim_state,
                  review_policy_json,review_policy_digest,verification_policy_json,
                  verification_policy_digest,verifier_policy_json,verifier_policy_digest,
                  checkout_remediation_policy,creation_idempotency_key,
                  creation_request_fingerprint,created_at,updated_at)
                 VALUES (?1,1,'/tmp/repo','repo:test','refs/heads/base',?2,?3,?2,
                         'configured','held','{}',?4,'{}',?4,'{}',?4,'refuse',?5,
                         ?4,?6,?6)",
                rusqlite::params![id, head, destination, digest, key.to_string(), now],
            )
        };
        insert_program(&first_program, Uuid::new_v4()).unwrap();
        let collision = insert_program(&second_program, Uuid::new_v4()).unwrap_err();
        assert!(collision.to_string().contains("UNIQUE constraint failed"));

        let invalid_release = store
            .conn
            .execute(
                "UPDATE closure_programs
                 SET state='closed',destination_claim_state='released',updated_at=?2
                 WHERE id=?1",
                rusqlite::params![first_program, now],
            )
            .unwrap_err();
        assert!(
            invalid_release
                .to_string()
                .contains("Closure destination release requires cleanup or quarantine settlement")
        );
        store
            .conn
            .execute(
                "UPDATE closure_programs SET destination_ref='refs/heads/retired',updated_at=?2 WHERE id=?1",
                rusqlite::params![first_program, now],
            )
            .unwrap();
        insert_program(&second_program, Uuid::new_v4()).unwrap();

        let request_id = Uuid::new_v4().to_string();
        let replay_key = Uuid::new_v4().to_string();
        store
            .conn
            .execute(
                "INSERT INTO closure_operator_requests
                 (id,method,idempotency_key,request_fingerprint,request_json,result_json,created_at)
                 VALUES (?1,'CreateClosureProgram',?2,?3,'{}','{}',?4)",
                rusqlite::params![request_id, replay_key, digest, now],
            )
            .unwrap();
        assert!(
            store
                .conn
                .execute(
                    "UPDATE closure_operator_requests SET result_json='[]' WHERE id=?1",
                    [request_id.as_str()],
                )
                .is_err(),
            "operator replay receipts must remain immutable"
        );
    }

    let mut reopened = Store::open(&database).expect("copied V84 upgrades through the live head");
    assert_eq!(
        reopened
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        LATEST_SCHEMA_VERSION
    );
    assert_eq!(
        reopened
            .conn
            .query_row("SELECT count(*) FROM closure_programs", [], |row| {
                row.get::<_, i64>(0)
            })
            .unwrap(),
        2
    );
    assert_eq!(
        reopened
            .conn
            .query_row(
                "SELECT count(*) FROM closure_operator_requests",
                [],
                |row| { row.get::<_, i64>(0) }
            )
            .unwrap(),
        1
    );
    for required_index in [
        "idx_closure_programs_held_destination",
        "idx_closure_programs_state_updated",
        "idx_closure_sources_recovery",
        "idx_closure_sources_state",
        "idx_conversation_event_provenance_invocation",
        "idx_closure_output_validations_source",
        "idx_closure_target_leases_held",
    ] {
        assert_eq!(
            reopened
                .conn
                .query_row(
                    "SELECT count(*) FROM sqlite_master WHERE type='index' AND name=?1",
                    [required_index],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            1,
            "copied V83 migration must create {required_index}"
        );
    }

    use super::sandbox_custody::{CustodyCause, NewCustodyRoot, SessionCustodyBinding};
    use rsi_common::types::{SandboxCleanupState, SandboxKind, SessionStatus};
    let mut session = make_test_session();
    session.status = SessionStatus::Starting;
    session.working_dir = PathBuf::from("/tmp/copied-v83-repo");
    session.sandbox_kind = Some(SandboxKind::GitWorktree);
    session.sandbox_root = Some(PathBuf::from("/tmp/copied-v83-source"));
    session.sandbox_branch = Some("rsi/copied-v83-source".into());
    session.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
    let custody_id = Uuid::new_v4();
    reopened
        .insert_session_with_custody(
            &session,
            SessionCustodyBinding::New(NewCustodyRoot {
                custody_id,
                canonical_repo_dir: "/tmp/copied-v83-repo".into(),
                sandbox_root: "/tmp/copied-v83-source".into(),
                sandbox_branch: "rsi/copied-v83-source".into(),
                repository_identity: "repo:test".into(),
                source_commit: head.clone(),
                cause: CustodyCause::FreshLaunch,
            }),
        )
        .unwrap();
    let source_id = Uuid::new_v4();
    reopened
        .conn
        .execute(
            "INSERT INTO closure_sources
             (id,program_id,custody_id,custody_generation,root_session_id,source_ref,
              source_base_sha,destination_ref,destination_pre_head,staging_ref,state,
              launch_idempotency_key,launch_request_fingerprint,created_at,updated_at)
             VALUES (?1,?2,?3,1,?4,'refs/heads/rsi/copied-v83-source',?5,
                     'refs/heads/retired',?5,?6,'working',?7,?8,?9,?9)",
            rusqlite::params![
                source_id.to_string(),
                &first_program,
                custody_id.to_string(),
                session.id.to_string(),
                &head,
                format!("refs/heads/rsi/closure-stage/{first_program}/{source_id}"),
                Uuid::new_v4().to_string(),
                &digest,
                &now
            ],
        )
        .unwrap();
    reopened
        .conn
        .execute(
            "INSERT INTO closure_source_sessions
             (source_id,session_id,rotation_depth,custody_id,custody_generation,
              continued_from_session_id,bound_at)
             VALUES (?1,?2,0,?3,1,NULL,?4)",
            rusqlite::params![
                source_id.to_string(),
                session.id.to_string(),
                custody_id.to_string(),
                &now
            ],
        )
        .unwrap();
    let immutable_event_id = Uuid::new_v4();
    reopened
        .conn
        .execute(
            "INSERT INTO closure_events
             (id,program_id,source_id,sequence,event_kind,next_program_state,next_source_state,
              correlation_key,payload_json,occurred_at)
             VALUES (?1,?2,?3,1,'migration_constraint_probe','working','working',?4,'{}',?5)",
            rusqlite::params![
                immutable_event_id.to_string(),
                &first_program,
                source_id.to_string(),
                Uuid::new_v4().to_string(),
                &now
            ],
        )
        .unwrap();
    let store = &reopened;
    let invocation_id = Uuid::new_v4();
    let now = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Nanos, true);
    store
        .conn
        .execute(
            "INSERT INTO model_invocations
             (id,purpose,invocation_kind,foreground,paid_risk,admission_status,status,
              provider,model,trigger_source,session_id,policy_snapshot_json,
              usage_confidence,created_at)
             VALUES (?1,'session_launch_fresh','session_lifecycle','foreground',
                     'paid_capable','admitted','completed','Claude','closure-test',
                     'closure_replay_test',?2,'{}','unavailable',?3)",
            rusqlite::params![invocation_id.to_string(), session.id.to_string(), &now],
        )
        .unwrap();
    let validation_id = Uuid::new_v4();
    let insert_validation = |id: Uuid, source: Option<String>| {
        store.conn.execute(
            "INSERT INTO closure_output_validations
             (id,source_id,tip_session_id,model_invocation_id,conversation_event_id,
              conversation_sequence,producer_kind,provider_event_type,parser_source,raw_handoff,
              raw_handoff_digest,normalized_envelope_json,normalized_envelope_digest,disposition,
              validation_issues_json,source_state,created_at)
             VALUES (?1,?2,?3,?4,NULL,NULL,NULL,NULL,'missing_provider_output',NULL,NULL,NULL,NULL,
                     'missing_provider_output','[]','outcome_blocked',?5)",
            rusqlite::params![
                id.to_string(),
                source,
                session.id.to_string(),
                invocation_id.to_string(),
                &now
            ],
        )
    };
    insert_validation(validation_id, Some(source_id.to_string())).unwrap();
    assert!(
        insert_validation(Uuid::new_v4(), Some(source_id.to_string())).is_err(),
        "the non-null ingestion key must be unique"
    );
    assert!(
        insert_validation(Uuid::new_v4(), None).is_err(),
        "the ingestion key cannot silently weaken through NULL"
    );

    let event_id: String = store
        .conn
        .query_row(
            "SELECT id FROM closure_events WHERE program_id=?1 ORDER BY sequence LIMIT 1",
            [&first_program],
            |row| row.get(0),
        )
        .unwrap();
    assert!(
        store
            .conn
            .execute(
                "UPDATE closure_events SET payload_json='[]' WHERE id=?1",
                [&event_id]
            )
            .is_err()
    );
    assert!(
        store
            .conn
            .execute("DELETE FROM closure_events WHERE id=?1", [&event_id])
            .is_err()
    );

    let (review_digest, verification_digest, verifier_digest): (String, String, String) = store
        .conn
        .query_row(
            "SELECT review_policy_digest,verification_policy_digest,verifier_policy_digest
             FROM closure_programs WHERE id=?1",
            [&first_program],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .unwrap();
    let receipt_id = Uuid::new_v4();
    store
        .conn
        .execute(
            "INSERT INTO integration_receipts
             (id,program_id,source_id,receipt_kind,method,source_base_sha,source_head,
              review_policy_digest,verification_policy_digest,verifier_policy_digest,
              disposition,actor,created_at)
             VALUES (?1,?2,?3,'accepted_no_change','fast_forward',?4,?4,?5,?6,?7,
                     'accepted_no_change','test',?8)",
            rusqlite::params![
                receipt_id.to_string(),
                &first_program,
                source_id.to_string(),
                &head,
                review_digest,
                verification_digest,
                verifier_digest,
                &now
            ],
        )
        .unwrap();
    assert!(
        store
            .conn
            .execute(
                "UPDATE integration_receipts SET actor='changed' WHERE id=?1",
                [receipt_id.to_string()]
            )
            .is_err()
    );
    assert!(
        store
            .conn
            .execute(
                "DELETE FROM integration_receipts WHERE id=?1",
                [receipt_id.to_string()]
            )
            .is_err()
    );
    let attempt_id = Uuid::new_v4();
    store
        .conn
        .execute(
            "INSERT INTO closure_integration_attempts (id,source_id,phase,created_at,updated_at)
             VALUES (?1,?2,'reserved',?3,?3)",
            rusqlite::params![attempt_id.to_string(), source_id.to_string(), &now],
        )
        .unwrap();
    let consumption_id = Uuid::new_v4();
    store
        .conn
        .execute(
            "INSERT INTO closure_receipt_consumptions
             (id,candidate_receipt_id,integration_attempt_id,consumed_at)
             VALUES (?1,?2,?3,?4)",
            rusqlite::params![
                consumption_id.to_string(),
                receipt_id.to_string(),
                attempt_id.to_string(),
                &now
            ],
        )
        .unwrap();
    assert!(
        store
            .conn
            .execute(
                "UPDATE closure_receipt_consumptions SET consumed_at=?2 WHERE id=?1",
                rusqlite::params![consumption_id.to_string(), &now]
            )
            .is_err()
    );
    assert!(
        store
            .conn
            .execute(
                "DELETE FROM closure_receipt_consumptions WHERE id=?1",
                [consumption_id.to_string()]
            )
            .is_err()
    );
    assert!(
        store
            .conn
            .execute(
                "INSERT INTO closure_receipt_consumptions
                 (id,candidate_receipt_id,integration_attempt_id,consumed_at)
                 VALUES (?1,?2,?3,?4)",
                rusqlite::params![
                    Uuid::new_v4().to_string(),
                    receipt_id.to_string(),
                    attempt_id.to_string(),
                    &now
                ]
            )
            .is_err(),
        "one candidate receipt cannot be consumed twice"
    );

    let valid_lease_id = Uuid::new_v4();
    store
        .conn
        .execute(
            "INSERT INTO closure_target_leases
             (id,repository_identity,target_ref,program_id,generation,state,holder_boot_id,
              expires_at,created_at,updated_at)
             VALUES (?1,'repo:test','refs/heads/retired',?2,1,'held',?3,?4,?4,?4)",
            rusqlite::params![
                valid_lease_id.to_string(),
                &first_program,
                Uuid::new_v4().to_string(),
                &now
            ],
        )
        .unwrap();
    assert!(
        store
            .conn
            .execute(
                "INSERT INTO closure_target_leases
                 (id,repository_identity,target_ref,program_id,generation,state,holder_boot_id,
                  expires_at,created_at,updated_at)
                 VALUES (?1,'repo:other','rolling',?2,1,'released',?3,?4,?4,?4)",
                rusqlite::params![
                    Uuid::new_v4().to_string(),
                    &first_program,
                    Uuid::new_v4().to_string(),
                    &now
                ]
            )
            .is_err(),
        "V84 target refs must be fully qualified local branches"
    );
    assert!(
        store
            .conn
            .execute(
                "INSERT INTO closure_target_leases
                 (id,repository_identity,target_ref,program_id,generation,state,holder_boot_id,
                  expires_at,created_at,updated_at)
                 VALUES (?1,'repo:uppercase','refs/heads/other',?2,1,'released',?3,?4,?4,?4)",
                rusqlite::params![
                    Uuid::new_v4().to_string().to_uppercase(),
                    &first_program,
                    Uuid::new_v4().to_string(),
                    &now
                ]
            )
            .is_err(),
        "V84 catalog identities must be lowercase canonical UUIDs"
    );
    assert!(
        store
            .conn
            .execute(
                "INSERT INTO closure_integration_attempts
                 (id,source_id,phase,staging_old_head,created_at,updated_at)
                 VALUES (?1,?2,'reserved',?3,?4,?4)",
                rusqlite::params![
                    Uuid::new_v4().to_string(),
                    source_id.to_string(),
                    "a".repeat(39),
                    &now
                ]
            )
            .is_err(),
        "V84 attempt heads must use a supported exact lowercase Git width"
    );
    assert!(
        store
            .conn
            .execute(
                "INSERT INTO integration_receipts
                 (id,program_id,source_id,receipt_kind,method,source_base_sha,source_head,
                  review_policy_digest,verification_policy_digest,verifier_policy_digest,
                  disposition,actor,created_at)
                 VALUES (?1,?2,?3,'accepted_no_change','fast_forward',?4,?4,?5,?6,?7,
                         'invalid','test',?8)",
                rusqlite::params![
                    Uuid::new_v4().to_string(),
                    &first_program,
                    source_id.to_string(),
                    "A".repeat(40),
                    &digest,
                    &digest,
                    &digest,
                    &now
                ]
            )
            .is_err(),
        "V84 receipt heads must reject uppercase hexadecimal"
    );
    assert!(
        store
            .conn
            .execute(
                "INSERT INTO closure_final_gate_attempt_receipts
                 (id,integration_attempt_id,ordinal,receipt_phase,gated_head,
                  verifier_policy_digest,reason,actor,created_at)
                 VALUES (?1,?2,1,'started',?3,?4,'initial','test',?5)",
                rusqlite::params![
                    Uuid::new_v4().to_string(),
                    attempt_id.to_string(),
                    &head,
                    "1".repeat(64),
                    &now
                ]
            )
            .is_err(),
        "V84 policy digests must retain the canonical sha256: prefix"
    );

    let gate_attempt_id = Uuid::new_v4();
    store
        .conn
        .execute(
            "INSERT INTO closure_final_gate_attempt_receipts
             (id,integration_attempt_id,ordinal,receipt_phase,gated_head,
              verifier_policy_digest,reason,actor,created_at)
             VALUES (?1,?2,1,'started',?3,?4,'initial','test',?5)",
            rusqlite::params![
                gate_attempt_id.to_string(),
                attempt_id.to_string(),
                &head,
                &digest,
                &now
            ],
        )
        .unwrap();
    assert!(
        store
            .conn
            .execute(
                "INSERT INTO closure_gate_failure_settlements
                 (id,source_id,failed_destination_receipt_id,
                  expected_current_destination_head,quarantine_ref,quarantine_head,
                  reason,rationale,confirmation,journal_phase,created_at,updated_at)
                 VALUES (?1,?2,?3,?4,'refs/heads/not-quarantine',?4,'candidate_bad',
                         'test','HUMAN-QUARANTINE','reserved',?5,?5)",
                rusqlite::params![
                    Uuid::new_v4().to_string(),
                    source_id.to_string(),
                    receipt_id.to_string(),
                    &head,
                    &now
                ]
            )
            .is_err(),
        "V84 quarantine journals must reject non-quarantine refs"
    );
    store
        .conn
        .execute(
            "INSERT INTO closure_gate_failure_settlements
             (id,source_id,failed_destination_receipt_id,
              expected_current_destination_head,quarantine_ref,quarantine_head,
              reason,rationale,confirmation,journal_phase,created_at,updated_at)
             VALUES (?1,?2,?3,?4,?5,?4,'candidate_bad','test','HUMAN-QUARANTINE',
                     'reserved',?6,?6)",
            rusqlite::params![
                Uuid::new_v4().to_string(),
                source_id.to_string(),
                receipt_id.to_string(),
                &head,
                format!("refs/rsi/closure-quarantine/{source_id}"),
                &now
            ],
        )
        .unwrap();
    let proof_id = Uuid::new_v4();
    let preview_id = Uuid::new_v4();
    store
        .conn
        .execute(
            "INSERT INTO closure_cleanup_proofs
             (id,source_id,proof_kind,receipt_id,destination_reachable,
              observed_source_head,observed_staging_head,preview_id,inventory_json,
              inventory_digest,expires_at,created_at)
             VALUES (?1,?2,'accepted_receipt',?3,1,?4,?4,?5,'{}',?6,?7,?7)",
            rusqlite::params![
                proof_id.to_string(),
                source_id.to_string(),
                receipt_id.to_string(),
                &head,
                preview_id.to_string(),
                &digest,
                &now
            ],
        )
        .unwrap();
    store
        .conn
        .execute(
            "INSERT INTO closure_cleanup_actions
             (id,source_id,proof_id,preview_id,preview_digest,confirmation,
              expected_custody_generation,worktree_root,source_ref,source_expected_sha,
              staging_ref,staging_expected_sha,session_ids_json,phase,created_at,updated_at)
             VALUES (?1,?2,?3,?4,?5,'HUMAN-CLEANUP',1,'/tmp/copied-v83-source',
                     'refs/heads/rsi/copied-v83-source',?6,?7,?6,'[]',
                     'worktree_remove_pending',?8,?8)",
            rusqlite::params![
                Uuid::new_v4().to_string(),
                source_id.to_string(),
                proof_id.to_string(),
                preview_id.to_string(),
                &digest,
                &head,
                format!("refs/heads/rsi/closure-stage/{first_program}/{source_id}"),
                &now
            ],
        )
        .unwrap();
    assert!(
        store
            .conn
            .execute(
                "INSERT INTO closure_operator_requests
                 (id,method,idempotency_key,request_fingerprint,request_json,result_json,created_at)
                 VALUES (?1,'UpdateClosureProgram',?2,?3,'{}','{}',?4)",
                rusqlite::params![
                    Uuid::new_v4().to_string().replace('-', ""),
                    Uuid::new_v4().to_string(),
                    &digest,
                    &now
                ]
            )
            .is_err(),
        "simple UUID spellings must be rejected by the durable replay ledger"
    );
    drop(reopened);
    let idempotent = Store::open(&database).expect("live-head reopen is idempotent");
    assert_eq!(
        idempotent
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        LATEST_SCHEMA_VERSION
    );
    assert_eq!(
        idempotent
            .conn
            .query_row("SELECT count(*) FROM closure_programs", [], |row| {
                row.get::<_, i64>(0)
            })
            .unwrap(),
        2
    );
    assert_eq!(
        idempotent
            .conn
            .query_row(
                "SELECT count(*) FROM closure_operator_requests",
                [],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
        1
    );
}

#[test]
fn closure_operator_same_key_replays_and_different_payload_refuses_without_effect() {
    use super::sandbox_custody::{CustodyCause, NewCustodyRoot, SessionCustodyBinding};
    use rsi_common::closure_kernel::*;
    use rsi_common::types::{SandboxCleanupState, SandboxKind, SessionProvider, SessionStatus};

    let directory = tempfile::tempdir().unwrap();
    let database = directory.path().join("closure-launch-replay.sqlite");
    let mut store = Store::open(&database).unwrap();
    let idempotency_key = Uuid::new_v4();
    let request = CreateClosureProgramRequestV1 {
        config: ClosureProgramConfigV1 {
            repository_root: PathBuf::from("/tmp/closure-replay"),
            base_ref: ClosureLocalBranchRefV1::parse("refs/heads/base").unwrap(),
            destination_ref: ClosureLocalBranchRefV1::parse("refs/heads/rolling").unwrap(),
            review_policy: ClosureReviewPolicyV1::NotRequired {
                basis: ClosureReviewNotRequiredBasisV1::Tier0Deterministic,
                rationale: "deterministic".into(),
            },
            verification_policy: ClosureVerificationPolicyV1 {
                required_buckets: vec!["Automated".into()],
                require_all_items_pass: true,
            },
            verifier_policy: ClosureVerifierPolicyV1 {
                commands: Vec::new(),
            },
            checkout_remediation_policy: ClosureCheckoutRemediationPolicyV1::Refuse,
        },
        idempotency_key,
    };
    let resolved = super::closure_kernel::ResolvedClosureProgramV1 {
        repository_root: "/tmp/closure-replay".into(),
        repository_identity: ClosureRepositoryIdentityV1::parse("repo:closure-replay").unwrap(),
        base_sha: ClosureGitShaV1::parse("a".repeat(40)).unwrap(),
        destination_pre_head: ClosureGitShaV1::parse("b".repeat(40)).unwrap(),
    };
    let first = store.create_closure_program(&request, &resolved).unwrap();
    let replay = store.create_closure_program(&request, &resolved).unwrap();
    assert!(replay.replayed);
    assert_eq!(replay.program_id, first.program_id);
    assert_eq!(replay.refusal, None);
    assert_eq!(
        store
            .replay_create_closure_program(&request)
            .unwrap()
            .expect("operator-boundary create replay")
            .program_id,
        first.program_id
    );

    let mut different = request;
    different.config.review_policy = ClosureReviewPolicyV1::RequiredIndependent;
    assert_eq!(
        store
            .replay_create_closure_program(&different)
            .unwrap()
            .expect("operator-boundary create mismatch")
            .refusal,
        Some(ClosureRefusalCodeV1::IdempotencyMismatch)
    );
    let refused = store.create_closure_program(&different, &resolved).unwrap();
    assert!(refused.replayed);
    assert_eq!(
        refused.refusal,
        Some(ClosureRefusalCodeV1::IdempotencyMismatch)
    );
    assert_eq!(
        store
            .conn
            .query_row("SELECT count(*) FROM closure_programs", [], |row| {
                row.get::<_, i64>(0)
            })
            .unwrap(),
        1
    );
    assert_eq!(
        store
            .conn
            .query_row(
                "SELECT count(*) FROM closure_operator_requests",
                [],
                |row| { row.get::<_, i64>(0) }
            )
            .unwrap(),
        1
    );

    let update = UpdateClosureProgramRequestV1 {
        program_id: first.program_id,
        expected_program_version: 1,
        config: ClosureProgramConfigV1 {
            verification_policy: ClosureVerificationPolicyV1 {
                required_buckets: vec!["Automated".into(), "Daemon-level".into()],
                require_all_items_pass: true,
            },
            ..different.config.clone()
        },
        idempotency_key: Uuid::new_v4(),
    };
    let updated = store.update_closure_program(&update, &resolved).unwrap();
    assert_eq!(updated.version, 2);
    assert!(!updated.replayed);
    let update_replay = store.update_closure_program(&update, &resolved).unwrap();
    assert!(update_replay.replayed);
    assert_eq!(update_replay.refusal, None);
    assert_eq!(
        store
            .replay_update_closure_program(&update)
            .unwrap()
            .expect("operator-boundary update replay")
            .version,
        updated.version
    );
    let mut different_update = update.clone();
    different_update.config.verifier_policy.commands = vec![ClosureVerifierCommandV1 {
        argv: vec!["cargo".into(), "test".into()],
        timeout_ms: 1_000,
    }];
    assert_eq!(
        store
            .replay_update_closure_program(&different_update)
            .unwrap()
            .expect("operator-boundary update mismatch")
            .refusal,
        Some(ClosureRefusalCodeV1::IdempotencyMismatch)
    );
    let update_refusal = store
        .update_closure_program(&different_update, &resolved)
        .unwrap();
    assert!(update_refusal.replayed);
    assert_eq!(
        update_refusal.refusal,
        Some(ClosureRefusalCodeV1::IdempotencyMismatch)
    );

    let launch_request = LaunchClosureSourceRequestV1 {
        program_id: first.program_id,
        title: "Closure replay".into(),
        query: "prove launch replay".into(),
        provider: SessionProvider::Claude,
        model: Some("test-model".into()),
        effort: Some("high".into()),
        idempotency_key: Uuid::new_v4(),
    };
    drop(store);
    // Open both SQLite handles before the start barrier. `Store::open` runs
    // schema initialization and WAL negotiation, which is intentionally not
    // part of the reservation race and can itself serialize across handles.
    let contender_stores = (0..2)
        .map(|_| Store::open(&database).expect("concurrent launch store"))
        .collect::<Vec<_>>();
    let barrier = std::sync::Arc::new(std::sync::Barrier::new(3));
    let contenders = contender_stores
        .into_iter()
        .map(|contender| {
            let barrier = std::sync::Arc::clone(&barrier);
            let request = launch_request.clone();
            std::thread::spawn(move || {
                barrier.wait();
                contender
                    .reserve_closure_source_launch(&request)
                    .expect("concurrent launch claim")
            })
        })
        .collect::<Vec<_>>();
    barrier.wait();
    let reservations = contenders
        .into_iter()
        .map(
            |contender| match contender.join().expect("launch contender") {
                super::closure_kernel::ClosureSourceLaunchClaimV1::Reserved(value) => value,
                super::closure_kernel::ClosureSourceLaunchClaimV1::Result(_) => {
                    panic!("same-key launch contenders must converge on the reservation")
                }
            },
        )
        .collect::<Vec<_>>();
    assert_eq!(reservations[0].source, reservations[1].source);
    assert_eq!(
        reservations[0].root_session_id,
        reservations[1].root_session_id
    );
    let reservation = reservations[0].clone();
    let mut store = Store::open(&database).expect("restart after durable launch reservation");
    let exact_reservation = match store
        .resume_closure_source_launch(&launch_request)
        .unwrap()
        .expect("durable reservation replay")
    {
        super::closure_kernel::ClosureSourceLaunchClaimV1::Reserved(value) => value,
        super::closure_kernel::ClosureSourceLaunchClaimV1::Result(_) => {
            panic!("pre-effect replay must resume reservation")
        }
    };
    assert_eq!(exact_reservation.source, reservation.source);
    assert_eq!(
        exact_reservation.root_session_id,
        reservation.root_session_id
    );

    let mut reserved_mismatch = launch_request.clone();
    reserved_mismatch.title.clear();
    let mismatch = match store
        .resume_closure_source_launch(&reserved_mismatch)
        .unwrap()
        .expect("changed-key reservation replay")
    {
        super::closure_kernel::ClosureSourceLaunchClaimV1::Result(value) => value,
        super::closure_kernel::ClosureSourceLaunchClaimV1::Reserved(_) => {
            panic!("changed payload must not own a second reservation")
        }
    };
    assert_eq!(
        mismatch.refusal,
        Some(ClosureRefusalCodeV1::IdempotencyMismatch)
    );

    let mut session = make_test_session();
    session.id = reservation.root_session_id;
    session.status = SessionStatus::Starting;
    session.working_dir = PathBuf::from("/tmp/closure-replay");
    session.sandbox_kind = Some(SandboxKind::GitWorktree);
    session.sandbox_root = Some(PathBuf::from("/tmp/closure-replay-source"));
    session.sandbox_branch = Some(reservation.branch_name.clone());
    session.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
    store
        .insert_session_with_custody(
            &session,
            SessionCustodyBinding::New(NewCustodyRoot {
                custody_id: reservation.source.custody_id,
                canonical_repo_dir: "/tmp/closure-replay".into(),
                sandbox_root: "/tmp/closure-replay-source".into(),
                sandbox_branch: reservation.branch_name.clone(),
                repository_identity: resolved.repository_identity.as_str().into(),
                source_commit: resolved.base_sha.as_str().into(),
                cause: CustodyCause::FreshLaunch,
            }),
        )
        .unwrap();
    let prepared = super::closure_kernel::PreparedClosureSourceV1 {
        source: reservation.source,
        root_session_id: reservation.root_session_id,
        idempotency_key: reservation.idempotency_key,
        request_fingerprint: reservation.request_fingerprint,
    };
    let launched = store.record_closure_source_launch(&prepared).unwrap();
    assert!(!launched.replayed);
    let launch_replay = store.record_closure_source_launch(&prepared).unwrap();
    assert!(launch_replay.replayed);
    assert_eq!(launch_replay.refusal, None);
    let mut different_launch = launch_request;
    different_launch.title = "different payload".into();
    let launch_refusal = store
        .replay_launch_closure_source(&different_launch)
        .unwrap()
        .expect("stored launch replay");
    assert!(launch_refusal.replayed);
    assert_eq!(
        launch_refusal.refusal,
        Some(ClosureRefusalCodeV1::IdempotencyMismatch)
    );
    assert_eq!(
        store
            .conn
            .query_row("SELECT count(*) FROM closure_sources", [], |row| row
                .get::<_, i64>(0))
            .unwrap(),
        1
    );
}

#[test]
fn closure_event_and_typed_provenance_commit_atomically() {
    use rsi_common::closure_kernel::{
        ConversationEventProducerKindV1, ConversationEventProvenanceV1,
    };

    let store = Store::open_in_memory().unwrap();
    let session = make_test_session();
    store.insert_session(&session).unwrap();
    let invocation_id = Uuid::new_v4();
    store
        .conn
        .execute(
            "INSERT INTO model_invocations
             (id,purpose,invocation_kind,foreground,paid_risk,admission_status,status,
              provider,model,trigger_source,session_id,policy_snapshot_json,
              usage_confidence,created_at)
             VALUES (?1,'session_launch_fresh','session_lifecycle','foreground',
                     'paid_capable','admitted','completed','Claude','closure-test',
                     'closure_test',?2,'{}','unavailable',?3)",
            rusqlite::params![
                invocation_id.to_string(),
                session.id.to_string(),
                chrono::Utc::now().to_rfc3339()
            ],
        )
        .unwrap();
    let event = ConversationEvent {
        id: 0,
        session_id: session.id,
        sequence: 1,
        event_type: EventType::Message,
        role: Some(Role::Assistant),
        created_at: chrono::Utc::now(),
        content: "provider output".into(),
        tool_name: None,
        tool_input: None,
        offload_id: None,
        tool_use_id: None,
        metadata: None,
    };
    let event_id = store
        .insert_event_with_provenance(
            &event,
            &ConversationEventProvenanceV1 {
                producer_kind: ConversationEventProducerKindV1::ProviderAssistantOutput,
                model_invocation_id: invocation_id,
                provider_event_type: "assistant".into(),
            },
        )
        .unwrap();
    let stored: (String, String) = store
        .conn
        .query_row(
            "SELECT producer_kind,model_invocation_id FROM conversation_event_provenance
             WHERE conversation_event_id=?1",
            [event_id],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .unwrap();
    assert_eq!(stored.0, "provider_assistant_output");
    assert_eq!(stored.1, invocation_id.to_string());

    let other_session = make_test_session();
    store.insert_session(&other_session).unwrap();
    let other_invocation_id = Uuid::new_v4();
    store
        .conn
        .execute(
            "INSERT INTO model_invocations
             (id,purpose,invocation_kind,foreground,paid_risk,admission_status,status,
              provider,model,trigger_source,session_id,policy_snapshot_json,
              usage_confidence,created_at)
             VALUES (?1,'session_launch_fresh','session_lifecycle','foreground',
                     'paid_capable','admitted','completed','Claude','closure-test',
                     'closure_test',?2,'{}','unavailable',?3)",
            rusqlite::params![
                other_invocation_id.to_string(),
                other_session.id.to_string(),
                chrono::Utc::now().to_rfc3339()
            ],
        )
        .unwrap();
    let mut cross_session = event.clone();
    cross_session.sequence = 2;
    cross_session.content = "wrong invocation owner".into();
    assert!(
        store
            .insert_event_with_provenance(
                &cross_session,
                &ConversationEventProvenanceV1 {
                    producer_kind: ConversationEventProducerKindV1::ProviderAssistantOutput,
                    model_invocation_id: other_invocation_id,
                    provider_event_type: "assistant".into(),
                },
            )
            .is_err(),
        "an existing invocation owned by another session must not authenticate event provenance"
    );

    let mut rejected = event;
    rejected.sequence = 3;
    rejected.content = "must not persist".into();
    assert!(
        store
            .insert_event_with_provenance(
                &rejected,
                &ConversationEventProvenanceV1 {
                    producer_kind: ConversationEventProducerKindV1::DaemonProviderDiagnostic,
                    model_invocation_id: Uuid::new_v4(),
                    provider_event_type: "process_error".into(),
                },
            )
            .is_err()
    );
    assert_eq!(
        store
            .conn
            .query_row("SELECT count(*) FROM conversation_events", [], |row| {
                row.get::<_, i64>(0)
            })
            .unwrap(),
        1
    );
    assert_eq!(
        store
            .conn
            .query_row(
                "SELECT count(*) FROM conversation_event_provenance",
                [],
                |row| { row.get::<_, i64>(0) }
            )
            .unwrap(),
        1
    );
}

#[test]
fn h1_v83_migration_backfills_and_triggers_unverified_projections() {
    let mut store = Store::open_in_memory().unwrap();
    let version: i32 = store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .unwrap();
    assert_eq!(version, LATEST_SCHEMA_VERSION);
    for table in [
        "sandbox_custody_roots",
        "sandbox_custody_events",
        "session_execution_projections",
    ] {
        assert!(
            table_exists(&store.conn, table),
            "missing V83 table {table}"
        );
    }

    let session = make_test_session();
    store.insert_session(&session).unwrap();
    let projection: (String, String, Option<String>) = store
        .conn
        .query_row(
            "SELECT execution_state,freshness,effective_cwd FROM session_execution_projections WHERE session_id=?1",
            [session.id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .unwrap();
    assert_eq!(projection.0, "ordinary_unsandboxed");
    assert_eq!(projection.1, "unverified");
    assert_eq!(projection.2, None);
}

#[test]
fn h1_v83_startup_participant_keysets_use_custody_indexes() {
    let store = Store::open_in_memory().unwrap();
    let custody_id = Uuid::new_v4();
    let root = "/tmp/h1-v83-query-plan-root";
    let plan = store
        .conn
        .prepare(
            "EXPLAIN QUERY PLAN SELECT id FROM (
                 SELECT id FROM sessions WHERE sandbox_custody_id=?1 AND id>?3
                 UNION
                 SELECT id FROM sessions WHERE sandbox_root=?2 AND id>?3
                 UNION
                 SELECT to_owner_session_id AS id FROM sandbox_custody_events
                  WHERE custody_id=?1 AND to_owner_session_id IS NOT NULL AND to_owner_session_id>?3
             ) ORDER BY id LIMIT ?4",
        )
        .unwrap()
        .query_map(
            rusqlite::params![custody_id.to_string(), root, "", 64_i64],
            |row| row.get::<_, String>(3),
        )
        .unwrap()
        .collect::<rusqlite::Result<Vec<_>>>()
        .unwrap()
        .join("\n");
    for index in [
        "idx_sessions_sandbox_custody_id_id",
        "idx_sessions_sandbox_root_id",
        "idx_sandbox_custody_events_to_owner",
    ] {
        assert!(
            plan.contains(index),
            "participant keyset must use {index}, plan was:\n{plan}"
        );
    }
}

#[test]
fn h1_v83_startup_group_pages_use_production_phase_indexes_without_global_sort() {
    let store = Store::open_in_memory().unwrap();
    for (phase, required_index) in [
        ("aggregate", "sqlite_autoindex_sandbox_custody_roots"),
        ("root", "idx_sessions_startup_unlinked_root"),
        ("session", "idx_sessions_startup_unlinked_rootless"),
    ] {
        let plan = store
            .startup_custody_group_page_query_plan(phase)
            .unwrap()
            .join("\n");
        assert!(
            plan.contains(required_index),
            "production startup {phase} page must use {required_index}, plan was:\n{plan}"
        );
        assert!(
            !plan.contains("SCAN sessions")
                && !plan.contains("SCAN sandbox_custody_roots")
                && !plan.contains("TEMP B-TREE"),
            "production startup {phase} page must not scan or globally sort, plan was:\n{plan}"
        );
    }
}

#[test]
fn h1_v83_startup_group_cursor_crosses_all_production_phases_without_loss() {
    use super::sandbox_custody::{CustodyCause, NewCustodyRoot, SessionCustodyBinding};
    use rsi_common::types::{SandboxCleanupState, SandboxKind};

    let mut store = Store::open_in_memory().unwrap();
    let mut expected = std::collections::BTreeSet::new();
    for index in 0..65 {
        let mut session = make_test_session();
        session.sandbox_kind = Some(SandboxKind::GitWorktree);
        session.sandbox_root = Some(PathBuf::from(format!("/tmp/h1-v83-page-aggregate-{index}")));
        session.sandbox_branch = Some(format!("rsi/h1-v83-page-aggregate-{index}"));
        session.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
        let custody_id = Uuid::new_v4();
        store
            .insert_session_with_custody(
                &session,
                SessionCustodyBinding::New(NewCustodyRoot {
                    custody_id,
                    canonical_repo_dir: session.working_dir.display().to_string(),
                    sandbox_root: session.sandbox_root.as_ref().unwrap().display().to_string(),
                    sandbox_branch: session.sandbox_branch.clone().unwrap(),
                    repository_identity: format!("aggregate-repository-{index}"),
                    source_commit: format!("{index:040x}"),
                    cause: CustodyCause::FreshLaunch,
                }),
            )
            .unwrap();
        expected.insert(format!("aggregate:{custody_id}"));
    }
    for index in 0..65 {
        let mut session = make_test_session();
        session.status = if index % 2 == 0 {
            SessionStatus::Archived
        } else {
            SessionStatus::Deleted
        };
        session.sandbox_kind = Some(SandboxKind::GitWorktree);
        session.sandbox_root = Some(PathBuf::from(format!("/tmp/h1-v83-page-root-{index}")));
        session.sandbox_branch = Some(format!("rsi/h1-v83-page-root-{index}"));
        session.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
        expected.insert(format!(
            "root:{}",
            session.sandbox_root.as_ref().unwrap().display()
        ));
        store.insert_session(&session).unwrap();
    }
    for index in 0..65 {
        let mut session = make_test_session();
        session.status = if index % 2 == 0 {
            SessionStatus::Archived
        } else {
            SessionStatus::Deleted
        };
        expected.insert(format!("session:{}", session.id));
        store.insert_session(&session).unwrap();
    }

    let mut cursor = None;
    let mut actual = Vec::new();
    let mut phases = Vec::new();
    loop {
        let page = store
            .startup_custody_group_page(cursor.as_deref(), 64)
            .unwrap();
        if page.is_empty() {
            break;
        }
        assert!(page.len() <= 64);
        phases.extend(
            page.iter()
                .map(|group| group.key.split(':').next().unwrap().to_owned()),
        );
        cursor = page.last().map(|group| group.key.clone());
        actual.extend(page.into_iter().map(|group| group.key));
    }
    let actual_set = actual
        .iter()
        .cloned()
        .collect::<std::collections::BTreeSet<_>>();
    assert_eq!(
        actual.len(),
        195,
        "every phase must cross a 64-row boundary"
    );
    assert_eq!(
        actual_set, expected,
        "cursor must neither drop nor duplicate groups"
    );
    assert!(
        phases.windows(2).all(|pair| pair[0] <= pair[1]),
        "production cursor phases must remain aggregate, root, session"
    );
}

#[test]
fn h1_v83_direct_bind_transfer_and_generation_cas_are_atomic() {
    use super::sandbox_custody::{CustodyCause, NewCustodyRoot, SessionCustodyBinding};
    use rsi_common::types::{SandboxCleanupState, SandboxKind};

    let mut store = Store::open_in_memory().unwrap();
    let canonical = "/tmp/h1-v83-transfer-canonical";
    let root = "/tmp/h1-v83-transfer-root";
    let branch = "rsi/h1-v83-transfer";
    let mut parent = make_test_session();
    parent.working_dir = PathBuf::from(canonical);
    parent.sandbox_kind = Some(SandboxKind::GitWorktree);
    parent.sandbox_root = Some(PathBuf::from(root));
    parent.sandbox_branch = Some(branch.into());
    parent.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
    let custody_id = Uuid::new_v4();
    store
        .insert_session_with_custody(
            &parent,
            SessionCustodyBinding::New(NewCustodyRoot {
                custody_id,
                canonical_repo_dir: canonical.into(),
                sandbox_root: root.into(),
                sandbox_branch: branch.into(),
                repository_identity: "test-repository".into(),
                source_commit: "0123456789012345678901234567890123456789".into(),
                cause: CustodyCause::FreshLaunch,
            }),
        )
        .unwrap();
    let mut successor = make_test_session();
    successor.id = Uuid::new_v4();
    successor.working_dir = PathBuf::from(canonical);
    successor.sandbox_kind = Some(SandboxKind::GitWorktree);
    successor.sandbox_root = Some(PathBuf::from(root));
    successor.sandbox_branch = Some(branch.into());
    successor.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
    store.insert_session(&successor).unwrap();
    store
        .bind_reserved_session_custody(
            successor.id,
            SessionCustodyBinding::Transfer {
                custody_id,
                from_session_id: parent.id,
                generation: 1,
                cause: CustodyCause::Rotation,
                origin_session_id: Some(parent.id),
                scheduled_job_id: None,
            },
        )
        .unwrap();
    let ownership: (String, i64, i64) = store
        .conn
        .query_row(
            "SELECT owner_session_id,generation,event_sequence FROM sandbox_custody_roots WHERE custody_id=?1",
            [custody_id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .unwrap();
    assert_eq!(ownership.0, successor.id.to_string());
    assert_eq!((ownership.1, ownership.2), (2, 2));
    assert!(
        store
            .bind_reserved_session_custody(
                successor.id,
                SessionCustodyBinding::Transfer {
                    custody_id,
                    from_session_id: parent.id,
                    generation: 1,
                    cause: CustodyCause::Rotation,
                    origin_session_id: Some(parent.id),
                    scheduled_job_id: None,
                },
            )
            .is_err()
    );
}

#[test]
fn h1_v83_direct_insert_rejects_nonstarting_and_nonnew_bindings_without_mutation() {
    use super::sandbox_custody::{CustodyCause, SessionCustodyBinding};

    let mut store = Store::open_in_memory().unwrap();
    let mut nonstarting = make_test_session();
    nonstarting.status = SessionStatus::Running;
    let error = store
        .insert_direct_session_with_custody_and_invocation(
            &nonstarting,
            SessionCustodyBinding::Ordinary,
            Uuid::new_v4(),
        )
        .expect_err("direct insert must refuse a non-Starting Session before a transaction");
    assert!(error.to_string().contains("requires a Starting Session"));

    let mut reuse = make_test_session();
    reuse.status = SessionStatus::Starting;
    let error = store
        .insert_direct_session_with_custody_and_invocation(
            &reuse,
            SessionCustodyBinding::Reuse {
                custody_id: Uuid::new_v4(),
                generation: 1,
                cause: CustodyCause::Rotation,
            },
            Uuid::new_v4(),
        )
        .expect_err("direct insert must refuse Reuse before a transaction");
    assert!(
        error
            .to_string()
            .contains("accepts only Ordinary or New bindings")
    );

    let mut transfer = make_test_session();
    transfer.status = SessionStatus::Starting;
    let error = store
        .insert_direct_session_with_custody_and_invocation(
            &transfer,
            SessionCustodyBinding::Transfer {
                custody_id: Uuid::new_v4(),
                from_session_id: Uuid::new_v4(),
                generation: 1,
                cause: CustodyCause::Rotation,
                origin_session_id: None,
                scheduled_job_id: None,
            },
            Uuid::new_v4(),
        )
        .expect_err("direct insert must refuse Transfer before a transaction");
    assert!(
        error
            .to_string()
            .contains("accepts only Ordinary or New bindings")
    );

    let durable_rows: (i64, i64, i64, i64) = store
        .conn
        .query_row(
            "SELECT (SELECT COUNT(*) FROM sessions),
                    (SELECT COUNT(*) FROM sandbox_custody_roots),
                    (SELECT COUNT(*) FROM sandbox_custody_events),
                    (SELECT COUNT(*) FROM session_execution_projections)",
            [],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .unwrap();
    assert_eq!(durable_rows, (0, 0, 0, 0));
}

#[test]
fn h1_v83_effect_permits_balance_and_clear_boot_identity() {
    use super::sandbox_custody::{CustodyCause, NewCustodyRoot, SessionCustodyBinding};

    let mut store = Store::open_in_memory().unwrap();
    let mut session = make_test_session();
    let custody_id = Uuid::new_v4();
    session.sandbox_kind = Some(rsi_common::types::SandboxKind::GitWorktree);
    session.sandbox_root = Some(PathBuf::from("/tmp/h1-v83-permit-root"));
    session.sandbox_branch = Some("rsi/h1-v83-permit".into());
    session.sandbox_cleanup_state = Some(rsi_common::types::SandboxCleanupState::Live);
    store
        .insert_session_with_custody(
            &session,
            SessionCustodyBinding::New(NewCustodyRoot {
                custody_id,
                canonical_repo_dir: session.working_dir.display().to_string(),
                sandbox_root: "/tmp/h1-v83-permit-root".into(),
                sandbox_branch: "rsi/h1-v83-permit".into(),
                repository_identity: "test-repository".into(),
                source_commit: "0123456789012345678901234567890123456789".into(),
                cause: CustodyCause::FreshLaunch,
            }),
        )
        .unwrap();
    let boot = Uuid::new_v4();
    let reservation = store.reserve_effect(custody_id, 1, boot).unwrap();
    store.settle_effect(reservation, true).unwrap();
    let active: (i64, i64, Option<String>) = store
        .conn
        .query_row(
            "SELECT reserved_effects,active_effects,effect_boot_id FROM sandbox_custody_roots WHERE custody_id=?1",
            [custody_id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .unwrap();
    assert_eq!(active, (0, 1, Some(boot.to_string())));
    store.release_effect(reservation).unwrap();
    let settled: (i64, i64, Option<String>) = store
        .conn
        .query_row(
            "SELECT reserved_effects,active_effects,effect_boot_id FROM sandbox_custody_roots WHERE custody_id=?1",
            [custody_id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .unwrap();
    assert_eq!(settled, (0, 0, None));
}

#[test]
fn h1_v83_failed_reserved_bind_never_publishes_an_executable_projection() {
    let mut store = Store::open_in_memory().unwrap();
    let session = make_test_session();
    store.insert_session(&session).unwrap();
    store
        .settle_reserved_custody_failure(
            session.id,
            rsi_common::types::SandboxCustodyErrorCodeV1::WorktreeMismatch,
        )
        .unwrap();
    let row: (String, String, String, Option<String>) = store
        .conn
        .query_row(
            "SELECT s.status,s.stop_reason,p.freshness,p.effective_cwd FROM sessions s JOIN session_execution_projections p ON p.session_id=s.id WHERE s.id=?1",
            [session.id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .unwrap();
    assert_eq!(row.0, "Failed");
    assert_eq!(row.1, "sandbox_custody:worktree_mismatch");
    assert_eq!(row.2, "invalid");
    assert_eq!(row.3, None);

    // A duplicate or foreign settlement is a no-op: it must not overwrite a
    // row another lifecycle path already settled.
    store
        .conn
        .execute(
            "UPDATE sessions SET status='Completed', stop_reason='foreign-settlement' WHERE id=?1",
            [session.id.to_string()],
        )
        .unwrap();
    store
        .settle_reserved_custody_failure(
            session.id,
            rsi_common::types::SandboxCustodyErrorCodeV1::RootMissing,
        )
        .unwrap();
    let preserved: (String, Option<String>) = store
        .conn
        .query_row(
            "SELECT status,stop_reason FROM sessions WHERE id=?1",
            [session.id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .unwrap();
    assert_eq!(
        preserved,
        ("Completed".into(), Some("foreign-settlement".into()))
    );
}

#[test]
fn h1_v83_failed_revalidation_quarantines_an_idle_root_and_removes_effective_cwd() {
    use super::sandbox_custody::{CustodyCause, NewCustodyRoot, SessionCustodyBinding};

    let mut store = Store::open_in_memory().unwrap();
    let mut session = make_test_session();
    let custody_id = Uuid::new_v4();
    session.sandbox_kind = Some(rsi_common::types::SandboxKind::GitWorktree);
    session.sandbox_root = Some(PathBuf::from("/tmp/h1-v83-invalid-root"));
    session.sandbox_branch = Some("rsi/h1-v83-invalid".into());
    session.sandbox_cleanup_state = Some(rsi_common::types::SandboxCleanupState::Live);
    store
        .insert_session_with_custody(
            &session,
            SessionCustodyBinding::New(NewCustodyRoot {
                custody_id,
                canonical_repo_dir: session.working_dir.display().to_string(),
                sandbox_root: "/tmp/h1-v83-invalid-root".into(),
                sandbox_branch: "rsi/h1-v83-invalid".into(),
                repository_identity: "test-repository".into(),
                source_commit: "0123456789012345678901234567890123456789".into(),
                cause: CustodyCause::FreshLaunch,
            }),
        )
        .unwrap();
    store
        .record_failed_revalidation(
            custody_id,
            1,
            rsi_common::types::SandboxCustodyErrorCodeV1::WorktreeMismatch,
            rsi_common::types::SandboxCustodyTransitionV1::EffectRevalidation,
        )
        .unwrap();
    let root: (String, Option<String>, i64, i64, i64) = store
        .conn
        .query_row(
            "SELECT state,owner_session_id,generation,reserved_effects,active_effects FROM sandbox_custody_roots WHERE custody_id=?1",
            [custody_id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?)),
        )
        .unwrap();
    assert_eq!(root, ("quarantined".into(), None, 2, 0, 0));
    let projection: (String, Option<String>) = store
        .conn
        .query_row(
            "SELECT freshness,effective_cwd FROM session_execution_projections WHERE session_id=?1",
            [session.id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .unwrap();
    assert_eq!(projection, ("invalid".into(), None));
}

