#[test]
fn h1_v83_startup_reconciliation_persistence_failure_blocks_readiness() {
    use crate::sandbox::custody::CustodyService;

    let mut fixture =
        h1_v83_real_custody_fixture(SessionStatus::Completed, "startup-settlement-failure");
    fixture
        .store
        .conn
        .execute(
            "UPDATE sessions SET sandbox_branch='fabricated-branch' WHERE id=?1",
            [fixture.parent.id.to_string()],
        )
        .unwrap();
    fixture
        .store
        .conn
        .execute_batch(
            "CREATE TRIGGER h1_v83_fail_startup_revalidation
               BEFORE UPDATE OF validation_state ON sandbox_custody_roots
               WHEN NEW.validation_state='invalid'
               BEGIN SELECT RAISE(ABORT, 'injected-startup-revalidation-failure'); END;",
        )
        .unwrap();

    let error = CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base)
        .expect_err("a failed revalidation settlement must block startup readiness");
    assert!(
        error
            .to_string()
            .contains("injected-startup-revalidation-failure"),
        "the persistence failure must propagate instead of becoming custody_changed: {error}"
    );
    let root: (String, i64) = fixture
        .store
        .conn
        .query_row(
            "SELECT state,event_sequence FROM sandbox_custody_roots WHERE custody_id=?1",
            [fixture.custody_id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .unwrap();
    assert_eq!(root, ("live".into(), 1));
}

#[test]
fn h1_v83_typed_startup_settlement_failures_propagate_without_invalidation() {
    use crate::sandbox::custody::{
        CustodyService, StartupSettlementFailureForTest, fail_next_startup_settlement_for_test,
    };

    #[derive(Debug, PartialEq)]
    struct StartupSettlementSnapshot {
        root: (
            String,
            Option<String>,
            i64,
            i64,
            String,
            Option<i64>,
            Option<String>,
            Option<String>,
        ),
        projection: (
            String,
            String,
            Option<String>,
            Option<String>,
            Option<i64>,
            Option<String>,
            Option<String>,
            String,
        ),
        session: (
            String,
            Option<String>,
            Option<String>,
            Option<String>,
            Option<String>,
        ),
    }

    for (failure, expected) in [
        (
            StartupSettlementFailureForTest::CustodyChanged,
            "custody_changed",
        ),
        (
            StartupSettlementFailureForTest::PersistenceTransitionFailed,
            "persistence_transition_failed",
        ),
        (
            StartupSettlementFailureForTest::UnknownStructured,
            "unknown_structured_startup_failure",
        ),
    ] {
        let mut fixture = h1_v83_real_custody_fixture(SessionStatus::Completed, expected);
        let snapshot = |store: &Store, custody_id: Uuid, session_id: Uuid| {
            store.conn.query_row(
                "SELECT
                    r.state,r.owner_session_id,r.generation,r.event_sequence,
                    r.validation_state,r.validated_generation,r.validated_at,r.validation_error_code,
                    p.execution_state,p.freshness,p.effective_cwd,p.custody_id,p.custody_generation,
                    p.validated_at,p.error_code,p.updated_at,
                    s.status,s.stop_reason,s.sandbox_cleanup_state,s.sandbox_root,s.sandbox_branch
                 FROM sandbox_custody_roots r
                 JOIN session_execution_projections p ON p.session_id=?2
                 JOIN sessions s ON s.id=p.session_id
                 WHERE r.custody_id=?1",
                rusqlite::params![custody_id.to_string(), session_id.to_string()],
                |row| {
                    Ok(StartupSettlementSnapshot {
                        root: (
                            row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?, row.get(6)?, row.get(7)?,
                        ),
                        projection: (
                            row.get(8)?, row.get(9)?, row.get(10)?, row.get(11)?, row.get(12)?, row.get(13)?, row.get(14)?, row.get(15)?,
                        ),
                        session: (row.get(16)?, row.get(17)?, row.get(18)?, row.get(19)?, row.get(20)?),
                    })
                },
            ).unwrap()
        };
        let before = snapshot(&fixture.store, fixture.custody_id, fixture.parent.id);
        fail_next_startup_settlement_for_test(failure);
        let error = CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base)
            .expect_err("typed startup settlement uncertainty must block readiness");
        assert!(error.to_string().contains(expected), "{error}");
        let after = snapshot(&fixture.store, fixture.custody_id, fixture.parent.id);
        assert_eq!(
            after, before,
            "typed failure must not publish invalidation/readiness"
        );
    }
}

#[test]
fn h1_v83_startup_reverse_event_participant_mismatch_quarantines_aggregate() {
    use super::sandbox_custody::{CustodyCause, SessionCustodyBinding};
    use crate::sandbox::custody::CustodyService;

    let mut fixture = h1_v83_real_custody_fixture(SessionStatus::Completed, "reverse-event");
    let successor = h1_v83_successor(&fixture, SessionStatus::Completed);
    fixture.store.insert_session(&successor).unwrap();
    fixture
        .store
        .bind_reserved_session_custody(
            successor.id,
            SessionCustodyBinding::Transfer {
                custody_id: fixture.custody_id,
                from_session_id: fixture.parent.id,
                generation: 1,
                cause: CustodyCause::Rotation,
                origin_session_id: Some(fixture.parent.id),
                scheduled_job_id: None,
            },
        )
        .unwrap();
    // Immutable event history still names the transferred parent, but both
    // mutable Session discovery facts are corrupted. Reverse discovery must
    // include it and fail closed rather than accepting the successor alone.
    fixture
        .store
        .conn
        .execute(
            "UPDATE sessions SET sandbox_custody_id=NULL,sandbox_root=NULL,sandbox_branch=NULL WHERE id=?1",
            [fixture.parent.id.to_string()],
        )
        .unwrap();

    CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
    let state: String = fixture
        .store
        .conn
        .query_row(
            "SELECT state FROM sandbox_custody_roots WHERE custody_id=?1",
            [fixture.custody_id.to_string()],
            |row| row.get(0),
        )
        .unwrap();
    assert_eq!(state, "quarantined");
}

#[test]
fn h1_v83_startup_reconciles_existing_aggregate_across_participant_pages() {
    use super::sandbox_custody::{CustodyCause, SessionCustodyBinding};
    use crate::sandbox::custody::CustodyService;

    let mut fixture = h1_v83_real_custody_fixture(SessionStatus::Completed, "participant-pages");
    let mut owner = fixture.parent.id;
    let mut generation = 1_u64;
    // PARTICIPANT_PAGE is 64; this forces two keyset pages while every
    // nonowner remains a source-authentic immutable transfer participant.
    for _ in 0..64 {
        let successor = h1_v83_successor(&fixture, SessionStatus::Completed);
        fixture.store.insert_session(&successor).unwrap();
        fixture
            .store
            .bind_reserved_session_custody(
                successor.id,
                SessionCustodyBinding::Transfer {
                    custody_id: fixture.custody_id,
                    from_session_id: owner,
                    generation,
                    cause: CustodyCause::Rotation,
                    origin_session_id: Some(owner),
                    scheduled_job_id: None,
                },
            )
            .unwrap();
        owner = successor.id;
        generation += 1;
    }

    CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
    let root: (String, String, i64) = fixture
        .store
        .conn
        .query_row(
            "SELECT state,owner_session_id,generation FROM sandbox_custody_roots WHERE custody_id=?1",
            [fixture.custody_id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .unwrap();
    assert_eq!(root, ("live".into(), owner.to_string(), generation as i64));
}

