#[test]
fn h1_v83_startup_reconstructs_legacy_lineage_idempotently() {
    use crate::sandbox::custody::CustodyService;
    use rsi_common::types::{SandboxKind, SessionStatus};

    let mut fixture = h1_v83_real_custody_fixture(SessionStatus::Completed, "legacy-lineage");
    let mut allocation = make_test_session();
    let root = fixture.sandbox_base.join(allocation.id.to_string());
    let branch = format!("rsi/h1-v83-legacy-lineage-{}", allocation.id);
    h1_v83_git(
        &fixture.canonical,
        &[
            "worktree",
            "add",
            "-qb",
            &branch,
            root.to_str().unwrap(),
            "HEAD",
        ],
    );
    allocation.working_dir = fixture.canonical.clone();
    allocation.sandbox_kind = Some(SandboxKind::GitWorktree);
    allocation.sandbox_root = Some(root.clone());
    allocation.sandbox_branch = Some(branch);
    allocation.sandbox_cleanup_state = None;
    allocation.status = SessionStatus::Completed;
    let mut successor = allocation.clone();
    successor.id = Uuid::new_v4();
    successor.status = SessionStatus::Archived;
    successor.continued_from = Some(allocation.id);
    successor.rotation_depth += 1;
    fixture.store.insert_session(&allocation).unwrap();
    fixture.store.insert_session(&successor).unwrap();
    CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
    let events: (i64, String, i64) = fixture.store.conn.query_row(
        "SELECT (SELECT count(*) FROM sandbox_custody_events e WHERE e.custody_id=r.custody_id),(SELECT to_owner_session_id FROM sandbox_custody_events e WHERE e.custody_id=r.custody_id AND sequence=1),generation FROM sandbox_custody_roots r WHERE sandbox_root=?1",
        [root.display().to_string()], |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
    ).unwrap();
    assert_eq!(events, (2, allocation.id.to_string(), 2));
    CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
    let count: i64 = fixture.store.conn.query_row("SELECT count(*) FROM sandbox_custody_events WHERE custody_id=(SELECT custody_id FROM sandbox_custody_roots WHERE sandbox_root=?1)", [root.display().to_string()], |row| row.get(0)).unwrap();
    assert_eq!(
        count, 2,
        "reopen/reconcile must not duplicate legacy events"
    );
}

#[test]
fn h1_v83_startup_legacy_rotation_resets_parent_retry_budget() {
    use crate::sandbox::custody::CustodyService;
    use rsi_common::types::{SandboxCleanupState, SandboxKind, SessionStatus};

    let mut fixture =
        h1_v83_real_custody_fixture(SessionStatus::Completed, "legacy-rotation-reset");
    let mut allocation = make_test_session();
    let root = fixture.sandbox_base.join(allocation.id.to_string());
    let branch = format!("rsi/h1-v83-legacy-rotation-reset-{}", allocation.id);
    h1_v83_git(
        &fixture.canonical,
        &[
            "worktree",
            "add",
            "-qb",
            &branch,
            root.to_str().unwrap(),
            "HEAD",
        ],
    );
    allocation.status = SessionStatus::Completed;
    allocation.working_dir = fixture.canonical.clone();
    allocation.sandbox_kind = Some(SandboxKind::GitWorktree);
    allocation.sandbox_root = Some(root.clone());
    allocation.sandbox_branch = Some(branch);
    allocation.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
    allocation.retry_attempt = Some(1);
    allocation.max_retries = Some(3);
    let mut successor = allocation.clone();
    successor.id = Uuid::new_v4();
    successor.continued_from = Some(allocation.id);
    successor.rotation_depth = 1;
    successor.retry_attempt = None;
    successor.max_retries = None;
    fixture.store.insert_session(&allocation).unwrap();
    fixture.store.insert_session(&successor).unwrap();

    CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
    let cause: String = fixture.store.conn.query_row(
        "SELECT cause FROM sandbox_custody_events WHERE custody_id=(SELECT custody_id FROM sandbox_custody_roots WHERE sandbox_root=?1) AND sequence=2",
        [root.display().to_string()], |row| row.get(0),
    ).unwrap();
    assert_eq!(cause, "rotation");

    // This is otherwise the same production-authentic registered two-row
    // rotation lineage. The sole defect is successor retry metadata, which a
    // production rotation must reset to None/None.
    let mut invalid_allocation = make_test_session();
    let invalid_root = fixture.sandbox_base.join(invalid_allocation.id.to_string());
    let invalid_branch = format!("rsi/h1-v83-invalid-rotation-{}", invalid_allocation.id);
    h1_v83_git(
        &fixture.canonical,
        &[
            "worktree",
            "add",
            "-qb",
            &invalid_branch,
            invalid_root.to_str().unwrap(),
            "HEAD",
        ],
    );
    invalid_allocation.status = SessionStatus::Completed;
    invalid_allocation.working_dir = fixture.canonical.clone();
    invalid_allocation.sandbox_kind = Some(SandboxKind::GitWorktree);
    invalid_allocation.sandbox_root = Some(invalid_root.clone());
    invalid_allocation.sandbox_branch = Some(invalid_branch);
    invalid_allocation.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
    let mut invalid = invalid_allocation.clone();
    invalid.id = Uuid::new_v4();
    invalid.continued_from = Some(invalid_allocation.id);
    invalid.rotation_depth = 1;
    invalid.retry_attempt = Some(1);
    invalid.max_retries = Some(3);
    fixture.store.insert_session(&invalid_allocation).unwrap();
    fixture.store.insert_session(&invalid).unwrap();
    CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
    let invalid_projection: (String, String) = fixture
        .store
        .conn
        .query_row(
            "SELECT freshness,(SELECT status FROM sessions WHERE id=?1) FROM session_execution_projections WHERE session_id=?1",
            [invalid.id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .unwrap();
    assert_eq!(invalid_projection, ("invalid".into(), "Completed".into()));
}

