#[test]
fn h1_v83_startup_terminal_root_authenticates_retained_evidence_and_missing_history() {
    use super::sandbox_custody::CustodyCause;
    use crate::sandbox::custody::CustodyService;

    for case in [
        "valid",
        "missing",
        "substituted_directory",
        "dangling_symlink",
        "wrong_branch",
    ] {
        let mut fixture = h1_v83_real_custody_fixture(SessionStatus::Completed, case);
        fixture
            .store
            .tombstone_custody_root(fixture.custody_id, 1, CustodyCause::Purge)
            .unwrap();
        match case {
            "valid" => {}
            "missing" => std::fs::remove_dir_all(&fixture.root).unwrap(),
            "substituted_directory" => {
                std::fs::remove_dir_all(&fixture.root).unwrap();
                std::fs::create_dir(&fixture.root).unwrap();
            }
            "dangling_symlink" => {
                std::fs::remove_dir_all(&fixture.root).unwrap();
                std::os::unix::fs::symlink(fixture.root.join("missing"), &fixture.root).unwrap();
            }
            "wrong_branch" => {
                h1_v83_git(
                    &fixture.root,
                    &["checkout", "-qb", "rsi/h1-v83-wrong-terminal"],
                );
            }
            _ => unreachable!(),
        }

        CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
        CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
        let actual: (String, i64, i64, String, String, Option<String>) = fixture
            .store
            .conn
            .query_row(
                "SELECT r.state,r.generation,r.event_sequence,p.execution_state,p.freshness,p.effective_cwd
                 FROM sandbox_custody_roots r
                 JOIN session_execution_projections p ON p.session_id=?2
                 WHERE r.custody_id=?1",
                rusqlite::params![fixture.custody_id.to_string(), fixture.parent.id.to_string()],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?)),
            )
            .unwrap();
        let expected = if matches!(case, "valid" | "missing") {
            (
                "purged".to_owned(),
                2,
                2,
                "historical_purged".to_owned(),
                "verified".to_owned(),
                None,
            )
        } else {
            (
                "quarantined".to_owned(),
                3,
                3,
                "invalid".to_owned(),
                "invalid".to_owned(),
                None,
            )
        };
        assert_eq!(actual, expected, "terminal case {case}");
    }
}

#[test]
fn h1_v83_startup_terminal_missing_static_identity_never_publishes_history() {
    use super::sandbox_custody::CustodyCause;
    use crate::sandbox::custody::CustodyService;

    let assert_quarantined = |fixture: &mut H1V83RealCustodyFixture, base: &std::path::Path| {
        CustodyService::reconcile_startup(&mut fixture.store, base).unwrap();
        CustodyService::reconcile_startup(&mut fixture.store, base).unwrap();
        let actual: (String, i64, i64, String, String, Option<String>) = fixture
            .store
            .conn
            .query_row(
                "SELECT r.state,r.generation,r.event_sequence,p.execution_state,p.freshness,p.effective_cwd
                 FROM sandbox_custody_roots r
                 JOIN session_execution_projections p ON p.session_id=?2
                 WHERE r.custody_id=?1",
                rusqlite::params![fixture.custody_id.to_string(), fixture.parent.id.to_string()],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?, row.get(4)?, row.get(5)?)),
            )
            .unwrap();
        assert_eq!(
            actual,
            (
                "quarantined".to_owned(),
                3,
                3,
                "invalid".to_owned(),
                "invalid".to_owned(),
                None,
            )
        );
    };

    let mut outside = h1_v83_real_custody_fixture(SessionStatus::Completed, "missing-outside");
    outside
        .store
        .tombstone_custody_root(outside.custody_id, 1, CustodyCause::Purge)
        .unwrap();
    std::fs::remove_dir_all(&outside.root).unwrap();
    let other_base = outside._tempdir.path().join("other-canonical-base");
    std::fs::create_dir(&other_base).unwrap();
    assert_quarantined(&mut outside, &other_base);

    // The root name must fail to parse as a UUID, not merely differ from the
    // owning session's id: `allocate_replacement` (git_worktree.rs) legitimately
    // allocates a fresh, session-unrelated `Uuid::new_v4()` root name for a
    // restored session (see `restore_archived_session_with_fresh_custody`), and
    // `insert_new_root` records that literal folder name as `allocation_id`.
    // A same-row, self-consistent valid-but-distinct UUID is therefore an
    // authenticated identity, not a defect; only a name that cannot parse as a
    // UUID at all (and so falls back to the owning session id, which then
    // mismatches the actual on-disk folder name) still exercises a genuine
    // `RootIdentityMismatch`.
    let mut wrong_name = h1_v83_real_custody_fixture_with_static_identity(
        SessionStatus::Completed,
        "missing-wrong-name",
        Some("not-a-uuid-allocation".to_string()),
        None,
    );
    wrong_name
        .store
        .tombstone_custody_root(wrong_name.custody_id, 1, CustodyCause::Purge)
        .unwrap();
    std::fs::remove_dir_all(&wrong_name.root).unwrap();
    let base = wrong_name.sandbox_base.clone();
    assert_quarantined(&mut wrong_name, &base);

    let mut repository_alias =
        h1_v83_real_custody_fixture(SessionStatus::Completed, "repository-alias");
    repository_alias
        .store
        .tombstone_custody_root(repository_alias.custody_id, 1, CustodyCause::Purge)
        .unwrap();
    let alias = repository_alias._tempdir.path().join("canonical-alias");
    std::os::unix::fs::symlink(&repository_alias.canonical, &alias).unwrap();
    repository_alias
        .store
        .conn
        .execute(
            "UPDATE sessions SET working_dir=?2 WHERE id=?1",
            rusqlite::params![
                repository_alias.parent.id.to_string(),
                alias.display().to_string()
            ],
        )
        .unwrap();
    let base = repository_alias.sandbox_base.clone();
    assert_quarantined(&mut repository_alias, &base);
}

