#[test]
fn h1_v83_startup_terminal_history_is_idempotent_across_file_backed_reopen() {
    use crate::sandbox::custody::CustodyService;
    use rsi_common::types::SandboxCustodyErrorCodeV1;

    let mut fixture = h1_v83_real_custody_fixture(SessionStatus::Failed, "file-reopen");
    fixture
        .store
        .record_custody_cleanup_failure(
            fixture.custody_id,
            1,
            SandboxCustodyErrorCodeV1::CleanupFailed,
        )
        .unwrap();
    CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
    let database = fixture._tempdir.path().join("startup-history.db");
    fixture
        .store
        .conn
        .execute("VACUUM INTO ?1", [database.display().to_string()])
        .unwrap();
    let sandbox_base = fixture.sandbox_base.clone();
    let session_id = fixture.parent.id;
    let custody_id = fixture.custody_id;
    drop(fixture.store);

    let mut reopened = Store::open(&database).unwrap();
    CustodyService::reconcile_startup(&mut reopened, &sandbox_base).unwrap();
    let terminal: (String, String, i64, i64) = reopened.conn.query_row(
        "SELECT state,validation_state,generation,event_sequence FROM sandbox_custody_roots WHERE custody_id=?1",
        [custody_id.to_string()],
        |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
    ).unwrap();
    assert_eq!(terminal, ("failed".into(), "verified".into(), 2, 2));
    let projection: (String, String) = reopened.conn.query_row(
        "SELECT execution_state,freshness FROM session_execution_projections WHERE session_id=?1",
        [session_id.to_string()],
        |row| Ok((row.get(0)?, row.get(1)?)),
    ).unwrap();
    assert_eq!(
        projection,
        ("historical_cleanup_failed".into(), "verified".into())
    );
}

#[test]
fn startup_settles_unbound_reserved_successor_before_authenticating_owner() {
    use crate::sandbox::custody::CustodyService;

    let mut fixture = h1_v83_real_custody_fixture(SessionStatus::Completed, "startup-reservation");
    let mut successor = h1_v83_successor(&fixture, SessionStatus::Starting);
    successor.continued_from = Some(fixture.parent.id);
    successor.rotation_depth = fixture.parent.rotation_depth + 1;
    let invocation_id = Uuid::new_v4();
    let now = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Nanos, true);
    fixture
        .store
        .conn
        .execute(
            "INSERT INTO model_invocations (
             id,purpose,invocation_kind,foreground,paid_risk,admission_status,
             status,trigger_source,session_id,policy_snapshot_json,created_at,started_at
         ) VALUES (?1,'session.rotate.child','model','foreground','paid_capable',
                   'admitted','running','startup_orphan_test',?2,'{}',?3,?3)",
            rusqlite::params![invocation_id.to_string(), successor.id.to_string(), now],
        )
        .unwrap();
    fixture
        .store
        .insert_reserved_rotation_session_with_invocation(
            &successor,
            invocation_id,
            "test-rotation",
        )
        .unwrap();
    assert_eq!(
        fixture
            .store
            .startup_unbound_successor_page(None, 10)
            .unwrap(),
        vec![successor.id]
    );

    CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
    let child = fixture.store.get_session(successor.id).unwrap().unwrap();
    assert_eq!(child.status, SessionStatus::Failed);
    assert_eq!(
        child.stop_reason.as_deref(),
        Some("sandbox_custody:ownership_missing")
    );
    assert!(
        fixture
            .store
            .startup_unbound_successor_page(None, 10)
            .unwrap()
            .is_empty()
    );
    let root: (String, String, i64) = fixture.store.conn.query_row(
        "SELECT state,validation_state,generation FROM sandbox_custody_roots WHERE custody_id=?1",
        [fixture.custody_id.to_string()],
        |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
    ).unwrap();
    assert_eq!(root, ("live".into(), "verified".into(), 1));
    assert_eq!(
        fixture
            .store
            .get_session(fixture.parent.id)
            .unwrap()
            .unwrap()
            .status,
        SessionStatus::Completed
    );
    CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
    assert_eq!(
        fixture
            .store
            .get_session(successor.id)
            .unwrap()
            .unwrap()
            .status,
        SessionStatus::Failed
    );
}

