#[test]
fn h1_v83_startup_diagnostic_caps_257_direct_entries_without_following_sentinel() {
    use crate::sandbox::custody::{CustodyService, take_startup_diagnostics_for_test};

    let _ = take_startup_diagnostics_for_test();
    let mut fixture = h1_v83_real_custody_fixture(SessionStatus::Completed, "startup-overflow");
    for _ in 0..257 {
        std::fs::create_dir(fixture.sandbox_base.join(Uuid::new_v4().to_string())).unwrap();
    }
    let sentinel = tempfile::NamedTempFile::new().unwrap();
    std::fs::write(sentinel.path(), b"do-not-touch").unwrap();
    #[cfg(unix)]
    std::os::unix::fs::symlink(sentinel.path(), fixture.sandbox_base.join("sentinel-link"))
        .unwrap();

    CustodyService::reconcile_startup(&mut fixture.store, &fixture.sandbox_base).unwrap();
    assert_eq!(std::fs::read(sentinel.path()).unwrap(), b"do-not-touch");
    let diagnostics = take_startup_diagnostics_for_test();
    assert!(
        diagnostics
            .iter()
            .any(|(_, reason)| reason == "base_directory_diagnostic_overflow")
    );
}

