#[test]
fn event_watermark_moves_on_append_and_on_inplace_rewrite() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let session = make_test_session();
    store.insert_session(&session).unwrap();

    // No events: no watermark. Distinguishes "empty" from "unknown" so the
    // sync fast path cannot mistake an empty session for an indexed one.
    assert_eq!(store.event_watermark(session.id).unwrap(), None);

    let event1 = make_test_event(session.id, 1);
    let id1 = store.insert_event(&event1).unwrap();
    let after_first = store.event_watermark(session.id).unwrap();
    assert!(after_first.is_some());

    // Stable across repeated probes — this is what makes the skip safe.
    assert_eq!(store.event_watermark(session.id).unwrap(), after_first);

    // Append moves it.
    store.insert_event(&make_test_event(session.id, 2)).unwrap();
    let after_second = store.event_watermark(session.id).unwrap();
    assert_ne!(after_second, after_first);

    // In-place content rewrite (context offload) moves it too, even though
    // count and max sequence are unchanged. This is the case a count-only
    // watermark would silently miss.
    store
        .update_event_content(id1, "replaced with a substantially different body")
        .unwrap();
    let after_rewrite = store.event_watermark(session.id).unwrap();
    assert_ne!(after_rewrite, after_second);

    // Watermark is per-session: another session's events do not bleed in.
    let mut other = make_test_session();
    other.id = uuid::Uuid::new_v4();
    store.insert_session(&other).unwrap();
    assert_eq!(store.event_watermark(other.id).unwrap(), None);
    assert_eq!(store.event_watermark(session.id).unwrap(), after_rewrite);
}

#[test]
fn test_insert_and_load_events() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let session = make_test_session();
    store.insert_session(&session).unwrap();

    // Insert 3 events
    let event1 = make_test_event(session.id, 1);
    let event2 = ConversationEvent {
        id: 0,
        session_id: session.id,
        sequence: 2,
        event_type: EventType::ToolUse,
        role: None,
        content: String::new(),
        tool_name: Some("read_file".to_string()),
        tool_input: Some(Box::new(serde_json::json!({"path": "/tmp/test.txt"}))),
        created_at: chrono::Utc::now(),
        offload_id: None,
        tool_use_id: None,
        metadata: None,
    };
    let event3 = make_test_event(session.id, 3);

    store.insert_event(&event1).unwrap();
    store.insert_event(&event2).unwrap();
    store.insert_event(&event3).unwrap();

    // Load events
    let events = store.load_events(session.id).unwrap();
    assert_eq!(events.len(), 3);

    // Verify ordering
    assert_eq!(events[0].sequence, 1);
    assert_eq!(events[1].sequence, 2);
    assert_eq!(events[2].sequence, 3);

    // Verify field integrity
    assert_eq!(events[0].event_type, EventType::Message);
    assert_eq!(events[0].role, Some(Role::Assistant));
    assert_eq!(events[0].content, "Message 1");

    assert_eq!(events[1].event_type, EventType::ToolUse);
    assert_eq!(events[1].role, None);
    assert_eq!(events[1].content, "");
    assert_eq!(events[1].tool_name, Some("read_file".to_string()));
    assert!(events[1].tool_input.is_some());

    assert_eq!(events[2].content, "Message 3");
}

#[test]
fn test_load_events_since_sequence() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let session = make_test_session();
    store.insert_session(&session).unwrap();

    // Insert 5 events with sequences 1..5
    for seq in 1..=5 {
        let event = make_test_event(session.id, seq);
        store.insert_event(&event).unwrap();
    }

    // Full fetch (None) — all 5
    let all = store.load_events_since(session.id, None).unwrap();
    assert_eq!(all.len(), 5);

    // Since sequence 0 — all 5 (sequence > 0)
    let since_0 = store.load_events_since(session.id, Some(0)).unwrap();
    assert_eq!(since_0.len(), 5);

    // Since sequence 3 — events 4, 5
    let since_3 = store.load_events_since(session.id, Some(3)).unwrap();
    assert_eq!(since_3.len(), 2);
    assert_eq!(since_3[0].sequence, 4);
    assert_eq!(since_3[1].sequence, 5);

    // Since sequence 5 — empty (no events after 5)
    let since_5 = store.load_events_since(session.id, Some(5)).unwrap();
    assert!(since_5.is_empty());

    // Since sequence 100 — empty
    let since_100 = store.load_events_since(session.id, Some(100)).unwrap();
    assert!(since_100.is_empty());
}

#[test]
fn test_event_autoincrement_id() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let session = make_test_session();
    store.insert_session(&session).unwrap();

    let id1 = store.insert_event(&make_test_event(session.id, 1)).unwrap();
    let id2 = store.insert_event(&make_test_event(session.id, 2)).unwrap();
    let id3 = store.insert_event(&make_test_event(session.id, 3)).unwrap();

    // IDs should be sequential and non-zero
    assert!(id1 > 0);
    assert!(id2 > 0);
    assert!(id3 > 0);
    assert_eq!(id2, id1 + 1);
    assert_eq!(id3, id2 + 1);

    // Verify loaded events have these IDs
    let events = store.load_events(session.id).unwrap();
    assert_eq!(events[0].id, id1);
    assert_eq!(events[1].id, id2);
    assert_eq!(events[2].id, id3);
}

