#[test]
fn test_session_metadata_persistence() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let mut session = make_test_session();
    store.insert_session(&session).unwrap();

    // Simulate session completion: populate metadata
    session.cost_usd = Some(0.0456);
    session.duration_ms = Some(12345);
    session.num_turns = Some(5);
    session.model = Some("claude-sonnet-5".to_string());
    session.input_tokens = Some(50000);
    session.output_tokens = Some(1200);
    session.context_window = Some(200000);
    session.total_input_tokens = Some(45000);
    session.total_output_tokens = Some(2500);
    session.total_cache_creation_tokens = Some(10000);
    session.total_cache_read_tokens = Some(30000);
    session.stop_reason = Some("end_turn".to_string());

    store.update_session_metadata(&session).unwrap();

    // Verify via get_session
    let loaded = store.get_session(session.id).unwrap().unwrap();
    assert_eq!(loaded.cost_usd, Some(0.0456));
    assert_eq!(loaded.duration_ms, Some(12345));
    assert_eq!(loaded.num_turns, Some(5));
    assert_eq!(loaded.model, Some("claude-sonnet-5".to_string()));
    assert_eq!(loaded.input_tokens, Some(50000));
    assert_eq!(loaded.output_tokens, Some(1200));
    assert_eq!(loaded.context_window, Some(200000));
    assert_eq!(loaded.total_input_tokens, Some(45000));
    assert_eq!(loaded.total_output_tokens, Some(2500));
    assert_eq!(loaded.total_cache_creation_tokens, Some(10000));
    assert_eq!(loaded.total_cache_read_tokens, Some(30000));
    assert_eq!(loaded.stop_reason, Some("end_turn".to_string()));

    // Verify via load_sessions too
    let all = store.load_sessions().unwrap();
    assert_eq!(all.len(), 1);
    assert_eq!(all[0].cost_usd, Some(0.0456));
    assert_eq!(all[0].context_window, Some(200000));
    assert_eq!(all[0].total_input_tokens, Some(45000));
    assert_eq!(all[0].total_output_tokens, Some(2500));
    assert_eq!(all[0].total_cache_creation_tokens, Some(10000));
    assert_eq!(all[0].total_cache_read_tokens, Some(30000));
    assert_eq!(all[0].stop_reason, Some("end_turn".to_string()));
}

#[test]
fn test_schema_migration_idempotent() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");

    // Open store twice — second open should not error
    {
        let _store = Store::open(&db_path).unwrap();
    }
    {
        let store = Store::open(&db_path).unwrap();

        // Verify user_version is current (all migrations applied)
        let version: i32 = store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .unwrap();
        // schema-version-bump (RSI-020): pin to LATEST_SCHEMA_VERSION constant so future migrations don't recur this cluster.
        assert_eq!(version, LATEST_SCHEMA_VERSION);

        // Verify turn_metrics and projects tables exist
        let mut stmt = store
            .conn
            .prepare("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")
            .unwrap();
        let tables: Vec<String> = stmt
            .query_map([], |row| row.get(0))
            .unwrap()
            .filter_map(|r| r.ok())
            .collect();
        assert!(tables.contains(&"turn_metrics".to_string()));
        assert!(tables.contains(&"projects".to_string()));
        assert!(tables.contains(&"context_snapshots".to_string()));
        assert!(tables.contains(&"model_segments".to_string()));
    }
}

#[test]
fn h1_v85_fresh_catalog_is_private_and_idempotent() {
    let dir = tempfile::tempdir().expect("temporary V85 database");
    let path = dir.path().join("v85.db");
    let store = Store::open(&path).expect("fresh V85 Store opens");
    let version: i32 = store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .expect("read V85 version");
    assert_eq!(version, LATEST_SCHEMA_VERSION);
    for relation in V85_TABLES {
        assert!(
            table_exists(&store.conn, relation),
            "missing V85 `{relation}`"
        );
    }
    let columns = table_columns(&store.conn, "sessions");
    assert!(
        columns
            .iter()
            .any(|column| column == "execution_origin_claim_id")
    );
    assert!(
        columns
            .iter()
            .any(|column| column == "execution_origin_write_seq")
    );
    drop(store);
    Store::open(&path).expect("V85 reopen is idempotent");
}

fn h1_v85_v84_snapshot(connection: &Connection) -> Vec<String> {
    Store::register_sql_functions(connection).expect("register V84 snapshot SQL functions");
    let tx = connection
        .unchecked_transaction()
        .expect("open V84 catalog snapshot transaction");
    let catalog = super::origin_authority::v84_catalog_fingerprint(&tx)
        .expect("fingerprint exact V84 catalog");
    drop(tx);
    let mut snapshot = vec![format!("catalog|{catalog}")];
    for table in ["sessions", "scheduled_jobs"]
        .into_iter()
        .chain(V83_TABLES)
        .chain(V84_TABLES)
    {
        snapshot.push(format!(
            "{table}|{}",
            table_fingerprint(connection, table).expect("fingerprint V84 data")
        ));
    }
    snapshot.push(format!(
        "user_version|{}",
        connection
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .expect("read V84 user version")
    ));
    snapshot.push(format!(
        "foreign_key_check|{}",
        connection
            .query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |row| {
                row.get::<_, i64>(0)
            })
            .expect("check V84 foreign keys")
    ));
    snapshot.push(format!(
        "integrity_check|{}",
        connection
            .query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0))
            .expect("check V84 integrity")
    ));
    snapshot
}

