fn h1_rb_insert_fixed_session(store: &Store, id: Uuid, sandbox: bool) {
    use rsi_common::types::{SandboxCleanupState, SandboxKind};

    let fixed = chrono::DateTime::parse_from_rfc3339(H1_RB_NOW)
        .unwrap()
        .with_timezone(&chrono::Utc);
    let mut session = make_test_session();
    session.id = id;
    session.created_at = fixed;
    session.updated_at = fixed;
    session.working_dir = PathBuf::from(format!("/tmp/h1-rb/repo/{id}"));
    if sandbox {
        session.sandbox_kind = Some(SandboxKind::GitWorktree);
        session.sandbox_root = Some(PathBuf::from(format!("/tmp/h1-rb/sandbox/{id}")));
        session.sandbox_branch = Some(format!("rsi/h1-rb-{id}"));
        session.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
    }
    store
        .insert_session(&session)
        .unwrap_or_else(|error| panic!("insert fixed RB Session {id}: {error}"));
}

fn h1_rb_insert_fixed_custody(
    store: &Store,
    session_id: Uuid,
    custody_id: Uuid,
    event_id: Uuid,
    cause: &str,
    origin_session_id: Option<Uuid>,
    scheduled_job_id: Option<Uuid>,
) {
    let sandbox_root = format!("/tmp/h1-rb/sandbox/{session_id}");
    let sandbox_branch = format!("rsi/h1-rb-{session_id}");
    store
        .conn
        .execute(
            "INSERT INTO sandbox_custody_roots(
            custody_id,canonical_repo_dir,sandbox_root,sandbox_branch,repository_identity,
            source_commit,state,owner_session_id,generation,event_sequence,validation_state,
            validated_generation,validated_at,validation_error_code,effect_boot_id,
            reserved_effects,active_effects,created_at,updated_at,tombstoned_at
         ) VALUES(?1,?2,?3,?4,?5,?6,'live',?7,1,1,'verified',1,?8,NULL,NULL,0,0,?8,?8,NULL)",
            rusqlite::params![
                custody_id.to_string(),
                format!("/tmp/h1-rb/repo/{session_id}"),
                sandbox_root,
                sandbox_branch,
                format!("repo:h1-rb:{custody_id}"),
                H1_RB_HEAD,
                session_id.to_string(),
                H1_RB_NOW,
            ],
        )
        .unwrap_or_else(|error| panic!("insert fixed RB custody {custody_id}: {error}"));
    store
        .conn
        .execute(
            "INSERT INTO sandbox_custody_events(
            event_id,custody_id,sequence,event_kind,cause,from_generation,to_generation,
            from_owner_session_id,to_owner_session_id,origin_session_id,scheduled_job_id,
            prior_state,next_state,error_code,occurred_at
         ) VALUES(?1,?2,1,'allocated',?3,NULL,1,NULL,?4,?5,?6,NULL,'live',NULL,?7)",
            rusqlite::params![
                event_id.to_string(),
                custody_id.to_string(),
                cause,
                session_id.to_string(),
                origin_session_id.map(|id| id.to_string()),
                scheduled_job_id.map(|id| id.to_string()),
                H1_RB_NOW,
            ],
        )
        .unwrap_or_else(|error| panic!("insert fixed RB custody event {event_id}: {error}"));
    store
        .conn
        .execute(
            "UPDATE sessions SET sandbox_custody_id=?1 WHERE id=?2",
            rusqlite::params![custody_id.to_string(), session_id.to_string()],
        )
        .unwrap();
    store
        .conn
        .execute(
            "UPDATE session_execution_projections
         SET execution_state='live_sandboxed',freshness='verified',
             canonical_repo_dir=?1,effective_cwd=?2,custody_id=?3,custody_generation=1,
             validated_at=?4,error_code=NULL,updated_at=?4
         WHERE session_id=?5",
            rusqlite::params![
                format!("/tmp/h1-rb/repo/{session_id}"),
                format!("/tmp/h1-rb/sandbox/{session_id}"),
                custody_id.to_string(),
                H1_RB_NOW,
                session_id.to_string(),
            ],
        )
        .unwrap();
}

