#[allow(clippy::expect_used)]
fn h1_v87_force_sql(connection: &Connection, table: &str, sql: &str) {
    let triggers = connection
        .prepare(
            "SELECT name,sql FROM sqlite_master
             WHERE type='trigger' AND tbl_name=?1 AND sql IS NOT NULL
             ORDER BY name",
        )
        .expect("prepare hostile trigger inventory")
        .query_map([table], |row| {
            Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?))
        })
        .expect("query hostile trigger inventory")
        .collect::<rusqlite::Result<Vec<_>>>()
        .expect("collect hostile trigger inventory");
    connection
        .execute_batch("PRAGMA foreign_keys=OFF; PRAGMA ignore_check_constraints=ON;")
        .expect("open hostile persisted-row mutation window");
    for (name, _) in &triggers {
        connection
            .execute_batch(&format!("DROP TRIGGER \"{name}\";"))
            .expect("drop mutation guard for one-predicate fixture");
    }
    connection
        .execute_batch(sql)
        .expect("apply one-predicate hostile mutation");
    for (_, trigger_sql) in triggers {
        connection
            .execute_batch(&format!("{trigger_sql};"))
            .expect("restore exact mutation guard");
    }
    connection
        .execute_batch("PRAGMA ignore_check_constraints=OFF; PRAGMA foreign_keys=ON;")
        .expect("close hostile persisted-row mutation window");
}

