fn h1_v87_assert_catalog_clean(connection: &Connection, label: &str) {
    assert_eq!(
        connection
            .query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |row| {
                row.get::<_, i64>(0)
            })
            .unwrap(),
        0,
        "{label}: foreign keys"
    );
    assert_eq!(
        connection
            .query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0))
            .unwrap(),
        "ok",
        "{label}: integrity"
    );
}

fn h1_v87_assert_trigger_refusal(
    result: rusqlite::Result<usize>,
    expected_message: &str,
    label: &str,
) {
    match result {
        Err(rusqlite::Error::SqliteFailure(code, Some(message))) => {
            assert_eq!(
                code.extended_code,
                rusqlite::ffi::SQLITE_CONSTRAINT_TRIGGER,
                "{label}: rejection must come from the expected SQLite trigger"
            );
            assert_eq!(
                message, expected_message,
                "{label}: rejection must name the exact owning trigger"
            );
        }
        Err(error) => panic!("{label}: wrong rejection source: {error}"),
        Ok(changed) => panic!("{label}: hostile Session update changed {changed} row(s)"),
    }
}

fn h1_v88_assert_constraint_refusal<T>(
    result: rusqlite::Result<T>,
    expected_code: i32,
    expected_message: &str,
    label: &str,
) {
    match result {
        Err(rusqlite::Error::SqliteFailure(code, Some(message))) => {
            assert_eq!(
                code.extended_code, expected_code,
                "{label}: rejection must come from the owning SQLite constraint"
            );
            assert_eq!(
                message, expected_message,
                "{label}: rejection must name the exact owning constraint"
            );
        }
        Err(error) => panic!("{label}: wrong rejection source: {error}"),
        Ok(_) => panic!("{label}: hostile statement unexpectedly committed"),
    }
}

fn h1_v87_assert_session_fence_refusal(result: rusqlite::Result<usize>, label: &str) {
    h1_v87_assert_trigger_refusal(result, "invalid execution origin session binding", label);
}

