fn h1_v87_try_hostile_finalize(
    fixture: &H1V87BoundFixture,
    predicate: H1V87FinalizePredicate,
) -> rusqlite::Result<usize> {
    let claim = if matches!(predicate, H1V87FinalizePredicate::SessionRetainsClaim) {
        Some(fixture.claim.clone())
    } else {
        None
    };
    let sequence = match predicate {
        H1V87FinalizePredicate::SessionEqualSequence => 2,
        H1V87FinalizePredicate::SessionSkippedSequence => 4,
        _ => 3,
    };
    let status = if matches!(predicate, H1V87FinalizePredicate::SessionStatus) {
        "Failed"
    } else {
        "Completed"
    };
    let stop_reason = if matches!(predicate, H1V87FinalizePredicate::SessionStopReason) {
        "wrong"
    } else {
        "finished"
    };
    let pending_archive = i64::from(matches!(
        predicate,
        H1V87FinalizePredicate::SessionPendingArchive
    ));
    let custody = if matches!(predicate, H1V87FinalizePredicate::SessionCustody) {
        fixture.alternate_custody.clone()
    } else if fixture.sandbox {
        Some(fixture.authority.clone())
    } else {
        None
    };
    fixture.store.conn.execute(
        "UPDATE sessions SET execution_origin_claim_id=?1,execution_origin_write_seq=?2,status=?3,stop_reason=?4,pending_archive=?5,sandbox_custody_id=?6 WHERE id=?7",
        rusqlite::params![claim, sequence, status, stop_reason, pending_archive, custody, fixture.session_id.to_string()],
    )
}

#[test]
fn h1_v87_session_fence_finalize_requires_complete_terminal_bundle() {
    for sandbox in [false, true] {
        let predicates = H1_V87_FINALIZE_PREDICATES.iter().copied().chain(
            sandbox
                .then_some(H1_V87_FINALIZE_SANDBOX_PREDICATES)
                .into_iter()
                .flatten()
                .copied(),
        );
        for (index, predicate) in predicates.enumerate() {
            let mut fixture = h1_v87_bound_fixture(
                0x87d0_0000 + (index as u128 * 0x10) + u128::from(sandbox),
                sandbox,
            );
            h1_v87_advance_provider_live(&mut fixture);
            let facts = h1_v87_prepare_finalize(&mut fixture, false);
            h1_v87_stage_terminal_bundle(&mut fixture, &facts);
            if let Some((table, bad, _)) = h1_v87_finalize_mutation_sql(&fixture, &facts, predicate)
            {
                h1_v87_force_sql(&fixture.store.conn, table, &bad);
            }
            let before = h1_v87_session_fingerprint(&fixture);
            h1_v87_assert_session_fence_refusal(
                h1_v87_try_hostile_finalize(&fixture, predicate),
                &format!("{sandbox:?} {predicate:?} finalize"),
            );
            assert_eq!(
                h1_v87_session_fingerprint(&fixture),
                before,
                "{sandbox:?} {predicate:?} refusal changes Session bytes"
            );
            if let Some((table, _, good)) =
                h1_v87_finalize_mutation_sql(&fixture, &facts, predicate)
            {
                h1_v87_force_sql(&fixture.store.conn, table, &good);
            }
            h1_v87_assert_catalog_clean(
                &fixture.store.conn,
                &format!("{sandbox:?} {predicate:?} restored finalize"),
            );
            h1_v87_unbind_session(&fixture).unwrap_or_else(|error| {
                panic!("{sandbox:?} {predicate:?} positive finalize: {error}")
            });
        }
    }

    for (sandbox, with_c5) in [(false, false), (true, false)] {
        let mut fixture = h1_v87_bound_fixture(0x87d0 + u128::from(sandbox), sandbox);
        h1_v87_advance_provider_live(&mut fixture);
        h1_v87_complete_finalize(&mut fixture, with_c5);
        let row = fixture.store.conn.query_row(
            "SELECT status,stop_reason,execution_origin_claim_id,execution_origin_write_seq FROM sessions WHERE id=?1",
            [fixture.session_id.to_string()],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?, row.get::<_, Option<String>>(2)?, row.get::<_, i64>(3)?)),
        ).expect("read finalized Session");
        assert_eq!(row, ("Completed".into(), "finished".into(), None, 3));
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct H1V87AtomicSnapshot {
    version: i32,
    catalog: String,
    tables: Vec<(&'static str, String)>,
    foreign_key_errors: i64,
    foreign_key_diagnostics: Vec<(String, i64, String, i64)>,
    integrity: String,
}

fn h1_v87_atomic_snapshot(connection: &Connection) -> H1V87AtomicSnapshot {
    const TABLES: &[&str] = &[
        "sessions",
        "execution_origin_authorities",
        "execution_origin_members",
        "execution_origin_claims",
        "execution_origin_events",
        "execution_origin_receipts",
        "sandbox_custody_roots",
        "model_invocations",
        "daemon_settings",
    ];
    H1V87AtomicSnapshot {
        version: connection
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .unwrap(),
        catalog: query_fingerprint(
            connection,
            "SELECT type,name,coalesce(tbl_name,''),coalesce(sql,'') FROM sqlite_master ORDER BY type,name",
        )
        .unwrap(),
        tables: TABLES
            .iter()
            .map(|table| (*table, table_fingerprint(connection, table).unwrap()))
            .collect(),
        foreign_key_errors: connection
            .query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |row| {
                row.get(0)
            })
            .unwrap(),
        foreign_key_diagnostics: connection
            .prepare("PRAGMA foreign_key_check")
            .unwrap()
            .query_map([], |row| {
                Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?))
            })
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap(),
        integrity: connection
            .query_row("PRAGMA integrity_check", [], |row| row.get(0))
            .unwrap(),
    }
}

fn h1_v87_initial_transaction_base(base: u128, sandbox: bool) -> H1V87BoundFixture {
    let fixture = h1_v87_bind_ready_fixture(base, sandbox);
    h1_v87_force_sql(
        &fixture.store.conn,
        "execution_origin_transition_commands",
        &format!(
            "DELETE FROM execution_origin_transition_commands WHERE claim_id='{}'",
            fixture.claim
        ),
    );
    h1_v87_force_sql(
        &fixture.store.conn,
        "execution_origin_active_claim_couplings",
        &format!(
            "DELETE FROM execution_origin_active_claim_couplings WHERE claim_id='{}'",
            fixture.claim
        ),
    );
    h1_v87_force_sql(
        &fixture.store.conn,
        "execution_origin_authorities",
        &format!(
            "UPDATE execution_origin_authorities SET phase='idle',active_claim_id=NULL,claim_generation=0,event_sequence=2,boot_id=NULL WHERE authority_uuid='{}'",
            fixture.authority
        ),
    );
    h1_v87_force_sql(
        &fixture.store.conn,
        "execution_origin_events",
        &format!(
            "DELETE FROM execution_origin_events WHERE authority_uuid='{}' AND sequence=3",
            fixture.authority
        ),
    );
    h1_v87_force_sql(
        &fixture.store.conn,
        "execution_origin_claims",
        &format!(
            "DELETE FROM execution_origin_claims WHERE claim_id='{}'",
            fixture.claim
        ),
    );
    if sandbox {
        h1_v87_force_sql(
            &fixture.store.conn,
            "sandbox_custody_roots",
            &format!(
                "UPDATE sandbox_custody_roots SET effect_boot_id=NULL,active_effects=0 WHERE custody_id='{}'",
                fixture.authority
            ),
        );
    }
    h1_v87_assert_catalog_clean(&fixture.store.conn, "initial transaction base");
    fixture
}

fn h1_v87_fail_transaction_boundary(
    boundary: usize,
    fail_after: Option<usize>,
) -> rusqlite::Result<()> {
    if fail_after == Some(boundary) {
        Err(rusqlite::Error::InvalidQuery)
    } else {
        Ok(())
    }
}

fn h1_v87_execute_bind_transaction(
    fixture: &H1V87BoundFixture,
    fail_after: Option<usize>,
) -> rusqlite::Result<()> {
    let authority_kind = if fixture.sandbox {
        "sandbox"
    } else {
        "ordinary"
    };
    let tx = Transaction::new_unchecked(&fixture.store.conn, TransactionBehavior::Immediate)?;
    tx.execute(
        "INSERT INTO execution_origin_active_claim_couplings(claim_id,authority_kind,authority_uuid,claim_phase,authority_phase,owner_session_id,claimant_kind,expected_owner_generation,owner_generation,expected_claim_generation,claim_generation,claim_boot_id,authority_active_claim_id,authority_boot_id) VALUES(?1,?2,?3,'claimed','claimed',?4,'continue',1,1,0,1,'v87-boot',?1,'v87-boot')",
        rusqlite::params![fixture.claim, authority_kind, fixture.authority, fixture.session_id.to_string()],
    )?;
    h1_v87_fail_transaction_boundary(1, fail_after)?;
    tx.execute(
        "INSERT INTO execution_origin_claims(claim_id,request_key,authority_kind,authority_uuid,requested_origin_session_id,source_session_id,claimant_session_id,claimant_kind,trigger_kind,expected_owner_generation,expected_claim_generation,prior_session_status,boot_id,model_invocation_id,model_no_execution_request_json,model_no_execution_request_digest,provider_create_state,authorized_session_status,authorized_session_write_seq,phase,claimed_at,updated_at,committed_binding) VALUES(?1,?2,?3,?4,?5,?5,?5,'continue','direct',1,0,'Completed','v87-boot',?6,'{}',?7,'not_attempted','Starting',1,'claimed',?8,?8,'active')",
        rusqlite::params![fixture.claim, fixture.request_key, authority_kind, fixture.authority, fixture.session_id.to_string(), Uuid::from_u128(fixture.session_id.as_u128() + 5).to_string(), format!("sha256:{}", "f".repeat(64)), fixture.now],
    )?;
    h1_v87_fail_transaction_boundary(2, fail_after)?;
    if fixture.sandbox {
        tx.execute(
            "UPDATE sandbox_custody_roots SET effect_boot_id='v87-boot',active_effects=1,updated_at=?1 WHERE custody_id=?2",
            rusqlite::params![fixture.now, fixture.authority],
        )?;
    } else {
        let _: i64 = tx.query_row("SELECT 1", [], |row| row.get(0))?;
    }
    h1_v87_fail_transaction_boundary(3, fail_after)?;
    h1_v88_apply_transition_command(
        &tx,
        authority_kind,
        &fixture.authority,
        &fixture.claim,
        "claimed",
        &fixture.session_id.to_string(),
        1,
        1,
        Some(&fixture.claim),
        Some("v87-boot"),
        None,
        None,
        "claimed",
        fixture.now,
    )?;
    h1_v87_fail_transaction_boundary(4, fail_after)?;
    tx.execute(
        "UPDATE sessions SET execution_origin_claim_id=?1,execution_origin_write_seq=1,status='Starting' WHERE id=?2",
        rusqlite::params![fixture.claim, fixture.session_id.to_string()],
    )?;
    h1_v87_fail_transaction_boundary(5, fail_after)?;
    let _: i64 = tx.query_row("SELECT 1", [], |row| row.get(0))?;
    h1_v87_fail_transaction_boundary(6, fail_after)?;
    tx.commit()
}

fn h1_v87_execute_finalize_transaction(
    fixture: &H1V87BoundFixture,
    facts: &H1V87FinalizeFacts,
    fail_after: Option<usize>,
) -> rusqlite::Result<()> {
    let authority_kind = if fixture.sandbox {
        "sandbox"
    } else {
        "ordinary"
    };
    let tx = Transaction::new_unchecked(&fixture.store.conn, TransactionBehavior::Immediate)?;
    let prepared_count: i64 = tx.query_row(
        "SELECT count(*) FROM execution_origin_claims c JOIN execution_origin_authorities a ON a.authority_kind=c.authority_kind AND a.authority_uuid=c.authority_uuid WHERE c.claim_id=?1 AND c.phase='settling' AND c.prepared_terminal_status='Completed' AND c.prepared_stop_reason='finished' AND c.prepared_session_write_seq=3 AND a.phase='settling' AND a.active_claim_id=c.claim_id",
        [fixture.claim.as_str()],
        |row| row.get(0),
    )?;
    if prepared_count != 1 {
        return Err(rusqlite::Error::QueryReturnedNoRows);
    }
    h1_v87_fail_transaction_boundary(1, fail_after)?;
    tx.execute(
        "INSERT INTO daemon_settings(key,value,updated_at) VALUES('h1-v87-c5','settled',?1)",
        [fixture.now],
    )?;
    h1_v87_fail_transaction_boundary(2, fail_after)?;
    if fixture.sandbox {
        tx.execute(
            "UPDATE sandbox_custody_roots SET effect_boot_id=NULL,active_effects=0,updated_at=?1 WHERE custody_id=?2",
            rusqlite::params![fixture.now, fixture.authority],
        )?;
    } else {
        let _: i64 = tx.query_row("SELECT 1", [], |row| row.get(0))?;
    }
    h1_v87_fail_transaction_boundary(3, fail_after)?;
    h1_v88_advance_coupling(&tx, &fixture.claim, "settled", "settling")?;
    h1_v87_fail_transaction_boundary(4, fail_after)?;
    tx.execute(
        "UPDATE execution_origin_claims SET phase='settled',updated_at=?1 WHERE claim_id=?2",
        rusqlite::params![fixture.now, fixture.claim],
    )?;
    h1_v87_fail_transaction_boundary(5, fail_after)?;
    tx.execute(
        "INSERT INTO execution_origin_receipts(receipt_id,request_key,claim_id,authority_kind,authority_uuid,requested_origin_session_id,source_session_id,claimant_session_id,scheduled_job_id,scheduled_fire_at,outcome,code,occurred_at) VALUES(?1,?2,?3,?4,?5,?6,?6,?6,NULL,NULL,'settled','finished',?7)",
        rusqlite::params![facts.receipt, fixture.request_key, fixture.claim, authority_kind, fixture.authority, fixture.session_id.to_string(), fixture.now],
    )?;
    h1_v87_fail_transaction_boundary(6, fail_after)?;
    h1_v88_apply_final_transition(
        &tx,
        authority_kind,
        &fixture.authority,
        &fixture.claim,
        "cli_reaped",
        fixture.now,
    )?;
    h1_v87_fail_transaction_boundary(7, fail_after)?;
    tx.execute(
        "UPDATE sessions SET execution_origin_claim_id=NULL,execution_origin_write_seq=3,status='Completed',stop_reason='finished' WHERE id=?1",
        [fixture.session_id.to_string()],
    )?;
    h1_v87_fail_transaction_boundary(8, fail_after)?;
    let _: i64 = tx.query_row("SELECT 1", [], |row| row.get(0))?;
    h1_v87_fail_transaction_boundary(9, fail_after)?;
    tx.commit()
}

#[test]
fn h1_v87_session_fence_ordered_transactions_commit_or_rollback_atomically() {
    for boundary in 1..=6 {
        let fixture = h1_v87_initial_transaction_base(0x87e0_0000 + boundary as u128, true);
        let before = h1_v87_atomic_snapshot(&fixture.store.conn);
        assert!(
            h1_v87_execute_bind_transaction(&fixture, Some(boundary)).is_err(),
            "bind boundary {boundary} must inject failure"
        );
        assert_eq!(
            h1_v87_atomic_snapshot(&fixture.store.conn),
            before,
            "bind boundary {boundary} must roll back every catalog byte"
        );
    }

    for sandbox in [false, true] {
        let fixture = h1_v87_initial_transaction_base(0x87e1_0000 + u128::from(sandbox), sandbox);
        h1_v87_execute_bind_transaction(&fixture, None)
            .expect("complete immediate bind transaction commits");
        assert_eq!(
            fixture
                .store
                .conn
                .query_row(
                    "SELECT status,execution_origin_claim_id,execution_origin_write_seq FROM sessions WHERE id=?1",
                    [fixture.session_id.to_string()],
                    |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?, row.get::<_, i64>(2)?)),
                )
                .unwrap(),
            ("Starting".into(), fixture.claim.clone(), 1)
        );
        h1_v87_assert_catalog_clean(&fixture.store.conn, "committed bind transaction");
    }

    for boundary in 1..=9 {
        let mut fixture = h1_v87_bound_fixture(0x87e2_0000 + boundary as u128, true);
        h1_v87_advance_provider_live(&mut fixture);
        let facts = h1_v87_prepare_finalize(&mut fixture, false);
        let before = h1_v87_atomic_snapshot(&fixture.store.conn);
        assert!(
            h1_v87_execute_finalize_transaction(&fixture, &facts, Some(boundary)).is_err(),
            "finalize boundary {boundary} must inject failure"
        );
        assert_eq!(
            h1_v87_atomic_snapshot(&fixture.store.conn),
            before,
            "finalize boundary {boundary} must roll back every catalog byte"
        );
    }

    for sandbox in [false, true] {
        let mut fixture = h1_v87_bound_fixture(0x87e3_0000 + u128::from(sandbox), sandbox);
        h1_v87_advance_provider_live(&mut fixture);
        let facts = h1_v87_prepare_finalize(&mut fixture, false);
        h1_v87_execute_finalize_transaction(&fixture, &facts, None)
            .expect("complete immediate finalize transaction commits");
        assert_eq!(
            fixture
                .store
                .conn
                .query_row(
                    "SELECT status,stop_reason,execution_origin_claim_id,execution_origin_write_seq FROM sessions WHERE id=?1",
                    [fixture.session_id.to_string()],
                    |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?, row.get::<_, Option<String>>(2)?, row.get::<_, i64>(3)?)),
                )
                .unwrap(),
            ("Completed".into(), "finished".into(), None, 3)
        );
        h1_v87_assert_catalog_clean(&fixture.store.conn, "committed finalize transaction");
    }
}

fn h1_v88_canonical_c5(
    source_session_id: Uuid,
    cause: &str,
    staged_at: &str,
) -> (String, String, String) {
    let value = format!(
        r#"{{"version":1,"source_session_id":"{source_session_id}","cause":"{cause}","staged_at":"{staged_at}"}}"#
    );
    let digest = format!("sha256:{:x}", sha2::Sha256::digest(value.as_bytes()));
    (
        super::daemon_settings::c5_autofile_pending_key(source_session_id),
        value,
        digest,
    )
}

#[test]
fn h1_v88_static_state_machine_private_validators_are_canonical_and_fail_closed() {
    use rsi_common::types::{idea_controller_candidate_session_id, idea_controller_reservation_id};

    let source = Uuid::from_u128(0x8801);
    let invocation = Uuid::from_u128(0x8802);
    let project = Uuid::from_u128(0x8803);
    let idea = Uuid::from_u128(0x8804);
    let base_event = Uuid::from_u128(0x8805);
    let action_digest = format!("sha256:{}", "a".repeat(64));
    let transfer_key = format!("controller:rotation:{source}:{invocation}:{action_digest}");
    let reservation = idea_controller_reservation_id(idea, &transfer_key);
    let candidate = idea_controller_candidate_session_id(reservation);
    let expires = "2026-08-21T01:02:03.000000004Z";
    let controller = |claimant_kind: &str,
                      claimant: &str,
                      key: Option<&str>,
                      reservation_id: Option<&str>,
                      expiry: Option<&str>| {
        super::origin_authority::execution_origin_controller_is_canonical(
            claimant_kind,
            &source.to_string(),
            claimant,
            Some(&invocation.to_string()),
            Some(&action_digest),
            None,
            None,
            Some(&project.to_string()),
            Some(&idea.to_string()),
            key,
            reservation_id,
            Some(&candidate.to_string()),
            Some("7"),
            Some(&base_event.to_string()),
            expiry,
        )
    };
    assert!(controller(
        "rotation",
        &candidate.to_string(),
        Some(&transfer_key),
        Some(&reservation.to_string()),
        Some(expires)
    ));
    assert!(!controller(
        "continue",
        &candidate.to_string(),
        Some(&transfer_key),
        Some(&reservation.to_string()),
        Some(expires)
    ));
    assert!(!controller(
        "rotation",
        &Uuid::nil().to_string(),
        Some(&transfer_key),
        Some(&reservation.to_string()),
        Some(expires)
    ));
    assert!(!controller(
        "rotation",
        &candidate.to_string(),
        Some("controller:rotation:altered"),
        Some(&reservation.to_string()),
        Some(expires)
    ));
    assert!(!controller(
        "rotation",
        &candidate.to_string(),
        Some(&transfer_key),
        Some(&Uuid::nil().to_string()),
        Some(expires)
    ));
    assert!(!controller(
        "rotation",
        &candidate.to_string(),
        Some(&transfer_key),
        Some(&reservation.to_string().to_ascii_uppercase()),
        Some(expires)
    ));
    assert!(!controller(
        "rotation",
        &candidate.to_string(),
        Some(&transfer_key),
        Some(&reservation.to_string()),
        Some("2026-08-21T01:02:03Z")
    ));
    assert!(
        super::origin_authority::execution_origin_controller_is_canonical(
            "continue",
            &source.to_string(),
            &source.to_string(),
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
            None,
        )
    );

    let staged_at = "2026-08-21T02:03:04.000000005Z";
    let (key, value, digest) = h1_v88_canonical_c5(source, "non-zero-exit", staged_at);
    let c5 = |status: Option<&str>,
              cause: Option<&str>,
              marker_key: Option<&str>,
              marker_value: Option<&str>,
              at: Option<&str>,
              marker_digest: Option<&str>,
              expected: Option<i64>,
              max: Option<i64>| {
        super::origin_authority::execution_origin_c5_is_canonical(
            &source.to_string(),
            status,
            cause,
            marker_key,
            marker_value,
            at,
            marker_digest,
            expected,
            max,
        )
    };
    assert!(c5(
        Some("Failed"),
        Some("non-zero-exit"),
        Some(&key),
        Some(&value),
        Some(staged_at),
        Some(&digest),
        Some(1),
        Some(2)
    ));
    let terminal_invocation_id = Uuid::from_u128(0x8806);
    let value_v2 = format!(
        r#"{{"version":2,"source_session_id":"{source}","cause":"non-zero-exit","staged_at":"{staged_at}","terminal_model_invocation_id":"{terminal_invocation_id}"}}"#
    );
    let digest_v2 = format!("sha256:{:x}", sha2::Sha256::digest(value_v2.as_bytes()));
    assert!(c5(
        Some("Failed"),
        Some("non-zero-exit"),
        Some(&key),
        Some(&value_v2),
        Some(staged_at),
        Some(&digest_v2),
        Some(1),
        Some(2)
    ));
    assert!(c5(
        Some("Completed"),
        None,
        None,
        None,
        None,
        None,
        None,
        None
    ));
    for hostile in [
        c5(
            Some("Completed"),
            Some("non-zero-exit"),
            Some(&key),
            Some(&value),
            Some(staged_at),
            Some(&digest),
            Some(1),
            Some(2),
        ),
        c5(Some("Failed"), None, None, None, None, None, None, None),
        c5(
            Some("Failed"),
            Some("unknown"),
            Some(&key),
            Some(&value),
            Some(staged_at),
            Some(&digest),
            Some(1),
            Some(2),
        ),
        c5(
            Some("Failed"),
            Some("non-zero-exit"),
            Some("c5.autofile.pending.v1/00000000-0000-0000-0000-000000000000"),
            Some(&value),
            Some(staged_at),
            Some(&digest),
            Some(1),
            Some(2),
        ),
        c5(
            Some("Failed"),
            Some("non-zero-exit"),
            Some(&key),
            Some(&value.replace("\"version\":1,", "")),
            Some(staged_at),
            Some(&digest),
            Some(1),
            Some(2),
        ),
        c5(
            Some("Failed"),
            Some("non-zero-exit"),
            Some(&key),
            Some(&value),
            Some(staged_at),
            Some(&format!("sha256:{}", "0".repeat(64))),
            Some(3),
            Some(2),
        ),
    ] {
        assert!(!hostile);
    }

    let connection = Connection::open_in_memory().unwrap();
    Store::register_sql_functions(&connection).unwrap();
    let type_mismatch: i64 = connection
        .query_row(
            "SELECT rsi_execution_origin_c5_is_canonical(1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL)",
            [],
            |row| row.get(0),
        )
        .unwrap();
    assert_eq!(type_mismatch, 0);
}

fn h1_v88_registered_validator_result(
    connection: &Connection,
    function: &str,
    arguments: &[rusqlite::types::Value],
) -> i64 {
    let placeholders = (1..=arguments.len())
        .map(|index| format!("?{index}"))
        .collect::<Vec<_>>()
        .join(",");
    connection
        .query_row(
            &format!("SELECT {function}({placeholders})"),
            rusqlite::params_from_iter(arguments.iter()),
            |row| row.get(0),
        )
        .unwrap_or_else(|error| panic!("call registered {function}: {error}"))
}

fn h1_v88_insert_validator_probe(
    connection: &Connection,
    table: &str,
    arguments: &[rusqlite::types::Value],
) -> rusqlite::Result<usize> {
    let placeholders = (1..=arguments.len())
        .map(|index| format!("?{index}"))
        .collect::<Vec<_>>()
        .join(",");
    connection.execute(
        &format!("INSERT INTO {table} VALUES({placeholders})"),
        rusqlite::params_from_iter(arguments.iter()),
    )
}

fn h1_v88_mutated_validator_arguments(
    canonical: &[rusqlite::types::Value],
    index: usize,
    value: rusqlite::types::Value,
) -> Vec<rusqlite::types::Value> {
    let mut mutated = canonical.to_vec();
    mutated[index] = value;
    mutated
}

