#[derive(Clone, Copy, Debug)]
enum H1FqrrevV87TerminalHostile {
    MissingInvocation,
    ForeignInvocation,
    NonterminalInvocation,
    MissingC5Setting,
    WrongC5Setting,
}

fn h1_fqrrev_apply_active_terminal_hostile(
    connection: &Connection,
    binding: &H1TrrevV87Binding,
    terminal_phase: bool,
    hostile: H1FqrrevV87TerminalHostile,
) {
    let terminal: String = connection
        .query_row(
            "SELECT terminal_model_invocation_id FROM execution_origin_claims WHERE claim_id=?1",
            [binding.claim.as_str()],
            |row| row.get(0),
        )
        .unwrap();
    match hostile {
        H1FqrrevV87TerminalHostile::MissingInvocation => h1_v87_force_sql(
            connection,
            "execution_origin_claims",
            &format!(
                "UPDATE execution_origin_claims SET terminal_model_invocation_id='{}' WHERE claim_id='{}'",
                Uuid::from_u128(0x8804_f201 + u128::from(binding.sandbox)),
                binding.claim
            ),
        ),
        H1FqrrevV87TerminalHostile::ForeignInvocation => h1_v87_force_sql(
            connection,
            "model_invocations",
            &format!(
                "UPDATE model_invocations SET session_id='{}' WHERE id='{terminal}'",
                Uuid::from_u128(0x8804_0020)
            ),
        ),
        H1FqrrevV87TerminalHostile::NonterminalInvocation => h1_v87_force_sql(
            connection,
            "model_invocations",
            &format!("UPDATE model_invocations SET status='running' WHERE id='{terminal}'"),
        ),
        H1FqrrevV87TerminalHostile::MissingC5Setting
        | H1FqrrevV87TerminalHostile::WrongC5Setting => {
            let session = Uuid::parse_str(&binding.session).unwrap();
            let (key, value, digest) = h1_v88_canonical_c5(session, "non-zero-exit", binding.now);
            h1_v87_force_sql(
                connection,
                "execution_origin_claims",
                &format!(
                    "UPDATE execution_origin_claims SET prepared_terminal_status='Failed',prepared_stop_reason='failed',prepared_c5_cause='non-zero-exit',prepared_c5_key='{key}',prepared_c5_value='{value}',prepared_c5_at='{}',prepared_c5_digest='{digest}',prepared_c5_expected_retry_count=1,prepared_c5_max_retries=2 WHERE claim_id='{}'",
                    binding.now, binding.claim
                ),
            );
            connection
                .execute("DELETE FROM daemon_settings WHERE key=?1", [key.as_str()])
                .unwrap();
            if matches!(hostile, H1FqrrevV87TerminalHostile::WrongC5Setting) {
                connection
                    .execute(
                        "INSERT INTO daemon_settings(key,value,updated_at) VALUES(?1,'wrong',?2)",
                        rusqlite::params![key, binding.now],
                    )
                    .unwrap();
            }
        }
    }
    if terminal_phase {
        h1_v87_force_sql(
            connection,
            "execution_origin_claims",
            &format!(
                "UPDATE execution_origin_claims SET phase=CASE prepared_terminal_status WHEN 'Failed' THEN 'failed' ELSE 'settled' END WHERE claim_id='{}'",
                binding.claim
            ),
        );
    }
    let tx = connection.unchecked_transaction().unwrap();
    let schema_version = tx
        .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
        .unwrap();
    match schema_version {
        87 => super::origin_authority::validate_v87_catalog(&tx)
            .expect("FQRREV terminal hostile retains exact V87 catalog"),
        90 => super::h1_v91_validate_v90_catalog(&tx)
            .expect("FQRREV terminal hostile retains exact V90 catalog"),
        version => panic!("FQRREV terminal hostile has unexpected schema V{version}"),
    }
    tx.commit().unwrap();
    if schema_version == 87 {
        h1_v87_assert_catalog_clean(connection, &format!("FQRREV terminal {hostile:?}"));
    } else {
        assert_eq!(
            connection
                .query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0))
                .unwrap(),
            "ok",
            "FQRREV terminal {hostile:?}: integrity"
        );
    }
}

fn h1_fqrrev_build_active_terminal_hostile(
    path: &std::path::Path,
    sandbox: bool,
    terminal_phase: bool,
    hostile: H1FqrrevV87TerminalHostile,
) -> H1TrrevV87Binding {
    let binding = h1_trrev_build_exact_v87_binding(path, sandbox, "settling", false);
    let connection = h1_trrev_open_exact_v87(path);
    h1_fqrrev_apply_active_terminal_hostile(&connection, &binding, terminal_phase, hostile);
    binding
}

