fn h1_fqrrev_pin_exact_v90(path: &std::path::Path) {
    h1_v91_test_fail_next_migration(H1V91MigrationFault::AfterPreflight);
    let error = match Store::open(path) {
        Ok(_) => panic!("valid predecessor must stop at the V91 preflight seam"),
        Err(error) => error,
    };
    h1_v91_test_clear_migration_fault();
    assert_eq!(
        error.to_string(),
        "Store error: injected V91 migration fault: AfterPreflight"
    );
    let connection = h1_trrev_open_exact_v87(path);
    assert_eq!(
        connection
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        90
    );
    let tx = connection.unchecked_transaction().unwrap();
    super::h1_v91_validate_v90_catalog(&tx).expect("pin exact V90 catalog");
    tx.commit().unwrap();
    h1_v87_assert_catalog_clean(&connection, "exact V90 predecessor");
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct H1V91AtomicSnapshot {
    core: H1V87AtomicSnapshot,
    tail: Vec<(&'static str, String)>,
}

fn h1_v91_atomic_snapshot(connection: &Connection) -> H1V91AtomicSnapshot {
    H1V91AtomicSnapshot {
        core: h1_v87_atomic_snapshot(connection),
        tail: [
            "execution_origin_active_claim_couplings",
            "execution_origin_transition_commands",
            "session_execution_projections",
            "master_no_idle_capacity_incidents",
            "master_no_idle_capacity_attempts",
        ]
        .into_iter()
        .map(|table| (table, table_fingerprint(connection, table).unwrap()))
        .collect(),
    }
}

fn h1_fqrrev_assert_refusal_at_every_v91_seam(
    source: &std::path::Path,
    directory: &std::path::Path,
    label: &str,
    expected: &str,
) {
    for fault in H1V91MigrationFault::ALL {
        let path = directory.join(format!("{label}-{fault:?}.sqlite"));
        std::fs::copy(source, &path).unwrap();
        let before_connection = h1_trrev_open_exact_v87(&path);
        let before = h1_v91_atomic_snapshot(&before_connection);
        drop(before_connection);
        h1_v91_test_fail_next_migration(fault);
        let error = match Store::open(&path) {
            Ok(_) => panic!("{label} unexpectedly migrated at {fault:?}"),
            Err(error) => error,
        };
        h1_v91_test_clear_migration_fault();
        assert_eq!(error.to_string(), expected, "{label} at {fault:?}");
        let after_connection = h1_trrev_open_exact_v87(&path);
        assert_eq!(
            h1_v91_atomic_snapshot(&after_connection),
            before,
            "{label} at {fault:?} changed exact V90 version, catalog, rows, FK diagnostics, or integrity",
        );
    }
}

