fn h1_rb_build_checkpoint_dag(directory: &std::path::Path) -> Vec<(i32, PathBuf)> {
    let c87 = directory.join("h1-rb-c87.sqlite");
    h1_v88_create_data_bearing_v87_fixture(&c87);

    let c84 = directory.join("h1-rb-c84.sqlite");
    h1_rb_create_complete_v84_checkpoint(&c84);
    let c85 = directory.join("h1-rb-c85.sqlite");
    let c86 = directory.join("h1-rb-c86.sqlite");
    for (version, path) in [(85, &c85), (86, &c86)] {
        h1_rb_checkpoint_copy(&c87, path, version);
    }
    let c88 = directory.join("h1-rb-c88.sqlite");
    h1_rb_checkpoint_copy(&c87, &c88, 88);
    let c89 = directory.join("h1-rb-c89.sqlite");
    h1_rb_checkpoint_copy(&c88, &c89, 89);
    let c90 = directory.join("h1-rb-c90.sqlite");
    h1_rb_checkpoint_copy(&c89, &c90, 90);
    vec![
        (84, c84),
        (85, c85),
        (86, c86),
        (87, c87),
        (88, c88),
        (89, c89),
        (90, c90),
    ]
}

fn h1_rb_assert_unarmed_v91_replay(connection: &Connection, predecessor_version: i32, label: &str) {
    assert_eq!(
        connection
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        LATEST_SCHEMA_VERSION,
        "{label}: unarmed replay did not reach schema head"
    );
    for table in V92_TABLES {
        assert!(
            table_exists(connection, table),
            "{label}: V92 table `{table}` missing"
        );
    }
    h1_rb_assert_v84_sentinels(connection, label);
    for table in ["sessions", "scheduled_jobs"]
        .into_iter()
        .chain(V83_TABLES)
        .chain(V84_TABLES)
    {
        h1_rb_assert_nonempty(connection, table, label);
    }
    if predecessor_version >= 85 {
        for table in V85_TABLES {
            h1_rb_assert_nonempty(connection, table, label);
        }
    }
    if predecessor_version >= 88 {
        for table in [
            "execution_origin_active_claim_couplings",
            "execution_origin_transition_commands",
        ] {
            h1_rb_assert_nonempty(connection, table, label);
        }
    }
    if predecessor_version >= 89 {
        for table in V89_TABLES {
            h1_rb_assert_nonempty(connection, table, label);
        }
    }
    // Opening the checkpoint through `Store::new` already authenticated the
    // exact V91 predecessor before V92 was applied.  At schema head the V92
    // ledger intentionally changes the catalog, so the V91 equality validator
    // is no longer applicable here; the V92 table assertions above plus the
    // integrity diagnostics below cover the replayed head.
    assert_eq!(
        connection
            .query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |row| {
                row.get::<_, i64>(0)
            })
            .unwrap(),
        0,
        "{label}: replayed V91 foreign-key diagnostics"
    );
    assert_eq!(
        connection
            .query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0))
            .unwrap(),
        "ok",
        "{label}: replayed V91 integrity"
    );
}

#[test]
fn h1_rb_full_v84_graph_is_nonempty_rewindable_and_replayable() {
    let directory = tempfile::tempdir().expect("RB checkpoint directory");
    let checkpoints = h1_rb_build_checkpoint_dag(directory.path());
    let immutable = checkpoints
        .iter()
        .map(|(version, path)| {
            let connection = h1_trrev_open_exact_v87(path);
            h1_rb_assert_exact_inventory(&connection, *version, &format!("immutable C{version}"));
            h1_rb_assert_v84_sentinels(&connection, &format!("immutable C{version}"));
            (*version, h1_rb_complete_snapshot(&connection, *version))
        })
        .collect::<Vec<_>>();

    let checkpoint = |version: i32| {
        checkpoints
            .iter()
            .find(|(candidate, _)| *candidate == version)
            .unwrap()
            .1
            .as_path()
    };
    let mut executed = 0usize;
    macro_rules! run_cohort {
        ($version:literal, $faults:expr, $arm:path, $needle:literal) => {{
            for fault in $faults {
                executed += 1;
                let label = format!("V{}::{fault:?}", $version + 1);
                let path = directory
                    .path()
                    .join(format!("h1-rb-v{}-{fault:?}.sqlite", $version + 1));
                std::fs::copy(checkpoint($version), &path).unwrap();
                let before_connection = h1_trrev_open_exact_v87(&path);
                let before = h1_rb_complete_snapshot(&before_connection, $version);
                h1_rb_assert_v84_sentinels(&before_connection, &label);
                drop(before_connection);
                $arm(fault);
                let error = match Store::open(&path) {
                    Ok(_) => panic!("{label} unexpectedly committed"),
                    Err(error) => error,
                };
                assert!(
                    error.to_string().contains($needle),
                    "{label} failed before its armed seam: {error}"
                );
                let raw = h1_trrev_open_exact_v87(&path);
                let after = h1_rb_complete_snapshot(&raw, $version);
                if after != before {
                    let changed_tables = after
                        .tables
                        .iter()
                        .zip(&before.tables)
                        .filter_map(|(left, right)| (left != right).then_some((&left.0, &right.0)))
                        .collect::<Vec<_>>();
                    panic!(
                        "{label} complete snapshot drift: version {}->{}, catalog={}, tables={changed_tables:?}, fk={}, integrity={}",
                        before.version,
                        after.version,
                        after.catalog == before.catalog,
                        after.foreign_key_diagnostics == before.foreign_key_diagnostics,
                        after.integrity == before.integrity,
                    );
                }
                drop(raw);
                let repaired = Store::open(&path)
                    .unwrap_or_else(|error| panic!("{label} unarmed V91 replay failed: {error}"));
                h1_rb_assert_unarmed_v91_replay(&repaired.conn, $version, &label);
                drop(repaired);
                Store::open(&path).unwrap_or_else(|error| {
                    panic!("{label} idempotent V91 reopen failed: {error}")
                });
            }
        }};
    }

    run_cohort!(
        84,
        H1V85MigrationFault::ALL,
        h1_v85_test_fail_next_migration,
        "injected V85 migration fault"
    );
    run_cohort!(
        85,
        H1V86MigrationFault::ALL,
        h1_v86_test_fail_next_migration,
        "injected V86 migration fault"
    );
    run_cohort!(
        86,
        H1V87MigrationFault::ALL,
        h1_v87_test_fail_next_migration,
        "injected V87 migration fault"
    );
    run_cohort!(
        87,
        H1V88MigrationFault::ALL,
        h1_v88_test_fail_next_migration,
        "injected V88 migration fault"
    );
    run_cohort!(
        88,
        V89MigrationFault::ALL,
        v89_test_fail_next_migration,
        "injected V89 migration fault"
    );
    run_cohort!(
        89,
        V90MigrationFault::ALL,
        v90_test_fail_next_migration,
        "injected V90 migration fault"
    );
    run_cohort!(
        90,
        H1V91MigrationFault::ALL,
        h1_v91_test_fail_next_migration,
        "injected V91 migration fault"
    );
    h1_v88_test_clear_migration_fault();
    h1_v91_test_clear_migration_fault();

    assert_eq!(
        executed,
        H1V85MigrationFault::ALL.len()
            + H1V86MigrationFault::ALL.len()
            + H1V87MigrationFault::ALL.len()
            + H1V88MigrationFault::ALL.len()
            + V89MigrationFault::ALL.len()
            + V90MigrationFault::ALL.len()
            + H1V91MigrationFault::ALL.len()
    );
    assert_eq!(executed, 8 + 8 + 6 + 8 + 7 + 10 + 4);
    assert_eq!(executed, 51);

    for ((version, path), (_, expected)) in checkpoints.iter().zip(immutable) {
        let connection = h1_trrev_open_exact_v87(path);
        assert_eq!(
            h1_rb_complete_snapshot(&connection, *version),
            expected,
            "C{version} was mutated while executing another cohort"
        );
    }
}

#[test]
fn h1_v91_refuses_catalog_integrity_and_foreign_key_drift_without_mutation() {
    for case in ["catalog", "integrity", "foreign key"] {
        let store = Store::open_in_memory().expect("open V91 refusal fixture");
        let mut session = make_test_session();
        session.id = Uuid::from_u128(match case {
            "catalog" => 0x9100_0010,
            "integrity" => 0x9100_0020,
            "foreign key" => 0x9100_0030,
            _ => unreachable!(),
        });
        store
            .insert_session(&session)
            .expect("insert V91 refusal Session");
        store
            .init_schema()
            .expect("stabilize unversioned repairs before the V91 refusal rewind");
        rewind_store_to_schema_version(&store.conn, 90);
        match case {
            "catalog" => store
                .conn
                .execute_batch("CREATE INDEX h1_v91_hostile_catalog_drift ON sessions(status);")
                .unwrap(),
            "integrity" => store
                .conn
                .execute_batch(&format!(
                    "PRAGMA ignore_check_constraints=ON;
                     UPDATE session_execution_projections SET schema_version=2
                     WHERE session_id='{}';
                     PRAGMA ignore_check_constraints=OFF;",
                    session.id
                ))
                .unwrap(),
            "foreign key" => store
                .conn
                .execute_batch(&format!(
                    "PRAGMA foreign_keys=OFF;
                     UPDATE session_execution_projections
                     SET custody_id='00000000-0000-4000-8000-000000009100'
                     WHERE session_id='{}';
                     PRAGMA foreign_keys=ON;",
                    session.id
                ))
                .unwrap(),
            _ => unreachable!(),
        }
        let before = h1_v91_atomic_snapshot(&store.conn);
        let error = store.init_schema().expect_err(case);
        let rendered = error.to_string();
        match case {
            "catalog" => assert!(
                rendered.contains("V91 requires exact accepted V90 source catalog"),
                "{rendered}"
            ),
            "integrity" => assert!(
                rendered.contains("V91 requires integrity_check=ok"),
                "{rendered}"
            ),
            "foreign key" => assert!(
                rendered.contains("V91 exact-predecessor foreign-key check found"),
                "{rendered}"
            ),
            _ => unreachable!(),
        }
        assert_eq!(
            h1_v91_atomic_snapshot(&store.conn),
            before,
            "V91 {case} refusal must not mutate catalog, data, or version"
        );
        assert_eq!(before.core.version, 90);
    }
}

#[test]
