#[test]
fn test_delete_project_clears_session_project_id() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let project = make_test_project("to-delete");
    store.insert_project(&project).unwrap();
    let other_project = make_test_project("retained project");
    store.insert_project(&other_project).unwrap();
    assert_eq!(store.manager_authority_epoch(project.id).unwrap(), 1);

    let mut session = make_test_session();
    session.project_id = Some(project.id);
    store.insert_session(&session).unwrap();

    // Verify session has project_id
    let loaded_session = store.get_session(session.id).unwrap().unwrap();
    assert_eq!(loaded_session.project_id, Some(project.id));

    // Delete project
    store.delete_project(project.id).unwrap();

    // Verify project is gone
    assert!(store.get_project(project.id).unwrap().is_none());

    // Verify session's project_id is now NULL
    let loaded_session = store.get_session(session.id).unwrap().unwrap();
    assert!(loaded_session.project_id.is_none());
    assert_eq!(
        store
            .conn
            .query_row(
                "SELECT count(*) FROM manager_authority_epochs WHERE project_id=?1",
                [project.id.to_string()],
                |row| row.get::<_, i64>(0),
            )
            .unwrap(),
        0
    );
    assert_eq!(store.manager_authority_epoch(other_project.id).unwrap(), 1);
    assert_eq!(
        store.get_project(other_project.id).unwrap().unwrap().name,
        other_project.name
    );
    store.delete_project(project.id).unwrap(); // Preserve absent-project no-op.
}

fn project_delete_rows(store: &Store, table: &str) -> Vec<Vec<rusqlite::types::Value>> {
    let mut statement = store
        .conn
        .prepare(&format!("SELECT * FROM {table} ORDER BY rowid"))
        .unwrap();
    let columns = statement.column_count();
    statement
        .query_map([], |row| {
            (0..columns).map(|column| row.get(column)).collect()
        })
        .unwrap()
        .collect::<rusqlite::Result<_>>()
        .unwrap()
}

fn assert_project_delete_preserves_state(
    store: &Store,
    project: Uuid,
) -> crate::error::DaemonError {
    let snapshot = || {
        [
            "projects",
            "sessions",
            "manager_authority_epochs",
            "harness_manager_scopes",
            "harness_manager_rotation_edges",
            "harness_manager_v2_operations",
            "harness_manager_v2_events",
            "manager_root_successions",
            "manager_root_transitions",
            "manager_root_resource_origins",
        ]
        .map(|table| project_delete_rows(store, table))
    };
    assert!(store.conn.is_autocommit());
    let before = snapshot();
    let error = store.delete_project(project).unwrap_err();
    assert_eq!(
        snapshot(),
        before,
        "failed deletion must roll back every row"
    );
    assert!(store.conn.is_autocommit());
    error
}

#[test]
fn test_delete_project_preserves_appointments_and_revocations_across_v111_backfill() {
    use rsi_common::harness_manager::ConfigureHarnessManagerRequestV1;

    for backfilled in [false, true] {
        for revoked in [None, Some(false), Some(true)] {
            let store = Store::open_in_memory().unwrap();
            let project = make_test_project("project deletion appointment control");
            store.insert_project(&project).unwrap();
            let mut manager = make_test_session();
            manager.project_id = Some(project.id);
            manager.session_kind = SessionKind::Standard;
            manager.parent_id = None;
            store.insert_session(&manager).unwrap();
            if let Some(revoked) = revoked {
                let mut request = ConfigureHarnessManagerRequestV1 {
                    project_id: project.id,
                    session_id: manager.id,
                    epic_ids: None,
                    group_ids: Vec::new(),
                    expected_row_version: 0,
                };
                let scope = store.configure_harness_manager(&request).unwrap();
                if revoked {
                    request.epic_ids = Some(Vec::new());
                    request.expected_row_version = scope.row_version;
                    store.configure_harness_manager(&request).unwrap();
                }
            }
            if backfilled {
                // Run the actual V111 backfill over the released V110 shape.
                rewind_store_to_schema_version(&store.conn, 110);
                store.init_schema().unwrap();
            }
            assert_eq!(
                store.manager_authority_epoch(project.id).unwrap(),
                if backfilled {
                    1
                } else {
                    match revoked {
                        None => 1,
                        Some(false) => 2,
                        Some(true) => 3,
                    }
                }
            );
            if revoked.is_some() {
                assert_project_delete_preserves_state(&store, project.id);
            } else {
                let remaining_epochs = project_delete_rows(&store, "manager_authority_epochs")
                    .into_iter()
                    .filter(|row| row[0] != rusqlite::types::Value::Text(project.id.to_string()))
                    .collect::<Vec<_>>();
                store.delete_project(project.id).unwrap();
                assert!(store.get_project(project.id).unwrap().is_none());
                assert!(
                    store
                        .get_session(manager.id)
                        .unwrap()
                        .unwrap()
                        .project_id
                        .is_none()
                );
                assert_eq!(
                    project_delete_rows(&store, "manager_authority_epochs"),
                    remaining_epochs
                );
            }
        }
    }
}

#[test]
fn test_delete_project_preserves_v111_seeded_rotation_history_without_appointment() {
    for retired in [false, true] {
        let store = Store::open_in_memory().unwrap();
        let project = make_test_project("retained rotation history");
        store.insert_project(&project).unwrap();
        let mut predecessor = make_test_session();
        predecessor.project_id = Some(project.id);
        predecessor.status = SessionStatus::Archived;
        store.insert_session(&predecessor).unwrap();
        let mut successor = predecessor.clone();
        successor.id = Uuid::new_v4();
        successor.continued_from = Some(predecessor.id);
        successor.rotation_depth += 1;
        successor.status = SessionStatus::Running;
        store.insert_session(&successor).unwrap();
        rewind_store_to_schema_version(&store.conn, 110);
        let timestamp = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Nanos, true);
        // Retained V103 receipts reference sessions, not projects or scopes.
        store.conn.execute(
            "INSERT INTO harness_manager_rotation_edges(predecessor_session_id,successor_session_id,committed_at,retired_at) VALUES(?1,?2,?3,?4)",
            params![predecessor.id.to_string(), successor.id.to_string(), timestamp, retired.then_some(&timestamp)],
        ).unwrap();
        store.init_schema().unwrap();
        assert_eq!(store.manager_authority_epoch(project.id).unwrap(), 1);
        assert!(store.get_harness_manager(project.id).unwrap().is_none());
        assert_project_delete_preserves_state(&store, project.id);
    }
}

