#[test]
fn test_delete_project_fails_closed_for_missing_or_unknown_epoch() {
    use rusqlite::types::Value;

    for epoch in [
        None,
        Some(Value::Integer(i64::MAX)),
        Some(Value::Integer(0)),
        Some(Value::Integer(-1)),
        Some(Value::Real(1.5)),
        Some(Value::Text("unknown".into())),
        Some(Value::Blob(vec![b'1'])),
    ] {
        let store = Store::open_in_memory().unwrap();
        let project = make_test_project("unknown authority control");
        store.insert_project(&project).unwrap();
        let mut session = make_test_session();
        session.project_id = Some(project.id);
        store.insert_session(&session).unwrap();
        if let Some(epoch) = epoch {
            // Corrupt only this in-memory fixture; foreign keys stay enabled.
            store
                .conn
                .execute_batch("PRAGMA ignore_check_constraints=ON;")
                .unwrap();
            store
                .conn
                .execute(
                    "UPDATE manager_authority_epochs SET epoch=?2 WHERE project_id=?1",
                    params![project.id.to_string(), epoch],
                )
                .unwrap();
            store
                .conn
                .execute_batch("PRAGMA ignore_check_constraints=OFF;")
                .unwrap();
        } else {
            store
                .conn
                .execute(
                    "DELETE FROM manager_authority_epochs WHERE project_id=?1",
                    [project.id.to_string()],
                )
                .unwrap();
        }
        assert_project_delete_preserves_state(&store, project.id);
    }
}

#[test]
fn test_delete_project_retains_manager_audit_origins_and_succession_references() {
    for history in ["event", "origin", "succession"] {
        let store = Store::open_in_memory().unwrap();
        let project = make_test_project("retained manager evidence");
        store.insert_project(&project).unwrap();
        let mut manager = make_test_session();
        manager.project_id = Some(project.id);
        store.insert_session(&manager).unwrap();
        let timestamp = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Nanos, true);
        match history {
            "event" => {
                store.conn.execute(
                    "INSERT INTO harness_manager_v2_events(project_id,manager_session_id,scope_version,kind,record_key,row_version,payload_json,created_at) VALUES(?1,?2,1,'retained','history',1,'{}',?3)",
                    params![project.id.to_string(),manager.id.to_string(),timestamp],
                ).unwrap();
            }
            "origin" => {
                // Zero known spend and no occurrence do not erase provenance.
                store.conn.execute(
                    "INSERT INTO manager_root_resource_origins(session_id,project_id,manager_session_id,scope_version,provider,zero_origin,known_floor_usd,created_at) VALUES(?2,?1,?2,1,'Codex',0,0,?3)",
                    params![project.id.to_string(),manager.id.to_string(),timestamp],
                ).unwrap();
            }
            "succession" => {
                let operation = Uuid::new_v4();
                store.conn.execute(
                    "INSERT INTO harness_manager_v2_operations(id,project_id,manager_session_id,scope_version,policy_version,idempotency_key,fingerprint,kind,payload_json,state,not_before,created_at,updated_at) VALUES(?1,?2,?3,1,1,'retained-root','fixture','succeed_manager','{}','queued',?4,?4,?4)",
                    params![operation.to_string(),project.id.to_string(),manager.id.to_string(),timestamp],
                ).unwrap();
                store.conn.execute(
                    "INSERT INTO manager_root_successions(operation_id,project_id,manager_session_id,predecessor_session_id,candidate_session_id,launch_attempt_id,model_invocation_id,scope_version,policy_version,authority_epoch,frozen_json,state,row_version,created_at,updated_at) VALUES(?1,?2,?3,?3,?4,?5,?6,1,1,1,'{}','reserved',1,?7,?7)",
                    params![operation.to_string(),project.id.to_string(),manager.id.to_string(),Uuid::new_v4().to_string(),Uuid::new_v4().to_string(),Uuid::new_v4().to_string(),timestamp],
                ).unwrap();
                assert_eq!(
                    project_delete_rows(&store, "manager_root_transitions").len(),
                    1
                );
            }
            _ => unreachable!(),
        }
        assert_eq!(store.manager_authority_epoch(project.id).unwrap(), 1);
        assert!(store.get_harness_manager(project.id).unwrap().is_none());
        let error = assert_project_delete_preserves_state(&store, project.id);
        assert!(
            matches!(error, crate::error::DaemonError::Database(rusqlite::Error::SqliteFailure(error, _)) if error.extended_code == rusqlite::ffi::SQLITE_CONSTRAINT_FOREIGNKEY)
        );
    }
}

#[test]
fn test_delete_project_extra_foreign_keys_roll_back_epoch_and_session_changes() {
    for reference in [
        "manager_authority_epochs(project_id)",
        "projects(id) DEFERRABLE INITIALLY DEFERRED",
    ] {
        let store = Store::open_in_memory().unwrap();
        let project = make_test_project("additional foreign key control");
        store.insert_project(&project).unwrap();
        let mut session = make_test_session();
        session.project_id = Some(project.id);
        store.insert_session(&session).unwrap();
        store
            .conn
            .execute_batch(&format!(
                "CREATE TABLE project_delete_blocker(project_id TEXT REFERENCES {reference});"
            ))
            .unwrap();
        store
            .conn
            .execute(
                "INSERT INTO project_delete_blocker VALUES(?1)",
                [project.id.to_string()],
            )
            .unwrap();
        let before = project_delete_rows(&store, "project_delete_blocker");
        let error = assert_project_delete_preserves_state(&store, project.id);
        assert!(
            matches!(error, crate::error::DaemonError::Database(rusqlite::Error::SqliteFailure(error, _)) if error.extended_code == rusqlite::ffi::SQLITE_CONSTRAINT_FOREIGNKEY)
        );
        assert_eq!(
            project_delete_rows(&store, "project_delete_blocker"),
            before
        );
    }
}

#[test]
fn test_find_project_for_path() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let p1 = Project {
        path: Some(PathBuf::from("/home/user")),
        ..make_test_project("user-home")
    };
    let p2 = Project {
        path: Some(PathBuf::from("/home/user/projects")),
        ..make_test_project("projects")
    };
    let p3 = Project {
        path: Some(PathBuf::from("/home/user/projects/flywheel")),
        ..make_test_project("flywheel")
    };
    let p4 = make_test_project("no-path"); // path is None

    store.insert_project(&p1).unwrap();
    store.insert_project(&p2).unwrap();
    store.insert_project(&p3).unwrap();
    store.insert_project(&p4).unwrap();

    // Exact match should return the project
    let found = store
        .find_project_for_path(&PathBuf::from("/home/user/projects/flywheel"))
        .unwrap();
    assert_eq!(found.unwrap().name, "flywheel");

    // Subdirectory should match longest prefix
    let found = store
        .find_project_for_path(&PathBuf::from("/home/user/projects/flywheel/crates"))
        .unwrap();
    assert_eq!(found.unwrap().name, "flywheel");

    // /home/user/projects/other should match "projects" not "flywheel"
    let found = store
        .find_project_for_path(&PathBuf::from("/home/user/projects/other"))
        .unwrap();
    assert_eq!(found.unwrap().name, "projects");

    // Completely unrelated path returns None
    let found = store
        .find_project_for_path(&PathBuf::from("/opt/something"))
        .unwrap();
    assert!(found.is_none());
}

#[test]
fn test_load_sessions_by_project() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let project = make_test_project("my-project");
    store.insert_project(&project).unwrap();

    // Create sessions: 2 assigned to project, 1 unassigned
    let mut s1 = make_test_session();
    s1.project_id = Some(project.id);
    let mut s2 = make_test_session();
    s2.project_id = Some(project.id);
    // `make_test_session()` defaults `project_id` to `Some(d04_test_project_id())`
    // (changed by cf01ae43, "feat: implement D04 issue linkage"), so an
    // unassigned session must now say so explicitly.
    let mut s3 = make_test_session();
    s3.project_id = None;

    store.insert_session(&s1).unwrap();
    store.insert_session(&s2).unwrap();
    store.insert_session(&s3).unwrap();

    // Load project sessions
    let project_sessions = store.load_sessions_by_project(Some(project.id)).unwrap();
    assert_eq!(project_sessions.len(), 2);

    // Load unassigned sessions
    let unassigned = store.load_sessions_by_project(None).unwrap();
    assert_eq!(unassigned.len(), 1);
    assert_eq!(unassigned[0].id, s3.id);

    // load_sessions returns all
    let all = store.load_sessions().unwrap();
    assert_eq!(all.len(), 3);
}

#[test]
fn test_update_session_project() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let project = make_test_project("my-project");
    store.insert_project(&project).unwrap();

    // `make_test_session()` defaults `project_id` to `Some(d04_test_project_id())`
    // (changed by cf01ae43, "feat: implement D04 issue linkage"); this test is
    // about the unassigned -> assigned -> unassigned cycle, so start unassigned.
    let mut session = make_test_session();
    session.project_id = None;
    store.insert_session(&session).unwrap();

    // Initially unassigned
    let loaded = store.get_session(session.id).unwrap().unwrap();
    assert!(loaded.project_id.is_none());

    // Assign to project
    store
        .update_session_project(session.id, Some(project.id))
        .unwrap();
    let loaded = store.get_session(session.id).unwrap().unwrap();
    assert_eq!(loaded.project_id, Some(project.id));

    // Unassign
    store.update_session_project(session.id, None).unwrap();
    let loaded = store.get_session(session.id).unwrap().unwrap();
    assert!(loaded.project_id.is_none());
}

