/// V43 migration (`tag` column + `session_tags` table + `topologies` table):
/// open at head, seed sessions, drop V43 artifacts, pin user_version back to 42,
/// re-open, assert V43 re-runs cleanly and rows are intact. Idempotent on re-open.
#[test]
fn migration_v43_adds_tag_column_and_topologies_tables() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("rsi.db");

    // Initial open: head schema (V43+).
    {
        let store = Store::open(&db_path).unwrap();
        for _ in 0..10 {
            store.insert_session(&make_test_session()).unwrap();
        }
        h1_restore_v90_fixture(&store.conn);
        // Drop V43 artifacts and pin version back so the V43 block re-runs.
        store
            .conn
            .execute("DROP INDEX IF EXISTS idx_sessions_tag", [])
            .unwrap();
        store
            .conn
            .execute("DROP INDEX IF EXISTS idx_session_tags_tag", [])
            .unwrap();
        store
            .conn
            .execute("DROP INDEX IF EXISTS idx_topologies_name", [])
            .unwrap();
        store
            .conn
            .execute("DROP TABLE IF EXISTS session_tags", [])
            .unwrap();
        store
            .conn
            .execute("DROP TABLE IF EXISTS topologies", [])
            .unwrap();
        // SQLite ≥ 3.35 supports DROP COLUMN; CI dev sqlite is current. If this
        // ever fails on an older sqlite, fall back to CREATE TABLE _new + INSERT
        // INTO + DROP + RENAME rewrite.
        store
            .conn
            .execute("ALTER TABLE sessions DROP COLUMN tag", [])
            .unwrap();
        // Rewind version AND schema together (issue #26): the V77..V82
        // relations must be torn down or the replayed chain aborts in
        // V77's preflight and every later step goes unexercised.
        rewind_store_to_schema_version(&store.conn, 42);
    }

    // Re-open: V43 must re-run.
    {
        let store = Store::open(&db_path).unwrap();
        let version: i32 = store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .unwrap();
        assert_eq!(version, LATEST_SCHEMA_VERSION);

        // tag column present.
        let tag_count: i64 = store
            .conn
            .query_row(
                "SELECT COUNT(*) FROM pragma_table_info('sessions') WHERE name = 'tag'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(tag_count, 1, "tag column must exist on sessions");

        // session_tags + topologies tables present.
        let mut stmt = store
            .conn
            .prepare(
                "SELECT name FROM sqlite_master \
                 WHERE type='table' AND name IN ('session_tags', 'topologies') \
                 ORDER BY name",
            )
            .unwrap();
        let tables: Vec<String> = stmt
            .query_map([], |row| row.get::<_, String>(0))
            .unwrap()
            .collect::<std::result::Result<Vec<_>, _>>()
            .unwrap();
        assert_eq!(
            tables,
            vec!["session_tags".to_string(), "topologies".to_string()],
        );

        // All three indexes present.
        for ix in [
            "idx_sessions_tag",
            "idx_session_tags_tag",
            "idx_topologies_name",
        ] {
            let exists: i64 = store
                .conn
                .query_row(
                    "SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name = ?1",
                    [ix],
                    |row| row.get(0),
                )
                .unwrap();
            assert_eq!(exists, 1, "index {ix} must exist");
        }

        // Seed rows survive.
        let total: i64 = store
            .conn
            .query_row("SELECT COUNT(*) FROM sessions", [], |row| row.get(0))
            .unwrap();
        assert_eq!(total, 10, "seed count regression");
    }

    // Idempotent re-open.
    {
        let store = Store::open(&db_path).unwrap();
        let v: i32 = store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .unwrap();
        assert_eq!(v, LATEST_SCHEMA_VERSION);
    }
}

/// After V43 runs, every session loaded via the normal restore path
/// carries `tag = ""` and `tags = []`. P1.1 leaves daemon-side population
/// for P1.5; restored sessions land at the row-mapper defaults.
#[test]
fn tag_default_empty_after_v43_upgrade() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("rsi.db");
    let store = Store::open(&db_path).unwrap();

    let mut s = make_test_session();
    s.query = "default-empty-test".to_string();
    let id = s.id;
    store.insert_session(&s).unwrap();

    // load_sessions exercises SessionRow::into_session() which hard-codes
    // tag/tags to defaults this ticket.
    let loaded = store.load_sessions().unwrap();
    let target = loaded
        .iter()
        .find(|x| x.id == id)
        .expect("inserted session must load");
    assert_eq!(target.tag, "", "Session.tag default must be empty string");
    assert!(
        target.tags.is_empty(),
        "Session.tags default must be empty Vec",
    );
}

/// Insert two `topologies` rows with the same name; the second insert must
/// fail with a UNIQUE constraint violation. Verifies the migration's
/// `name TEXT NOT NULL UNIQUE` clause survived the multi-statement DDL.
#[test]
fn topology_unique_name_constraint() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("rsi.db");
    let store = Store::open(&db_path).unwrap();

    let now = chrono::Utc::now().to_rfc3339();
    let id1 = Uuid::new_v4().to_string();
    let id2 = Uuid::new_v4().to_string();

    store
        .conn
        .execute(
            "INSERT INTO topologies (id, name, definition_json, created_at, updated_at) \
             VALUES (?1, ?2, ?3, ?4, ?5)",
            rusqlite::params![&id1, "duplicate-name", "{}", &now, &now],
        )
        .unwrap();

    let result = store.conn.execute(
        "INSERT INTO topologies (id, name, definition_json, created_at, updated_at) \
         VALUES (?1, ?2, ?3, ?4, ?5)",
        rusqlite::params![&id2, "duplicate-name", "{}", &now, &now],
    );

    let err = result.expect_err("second insert must fail");
    let msg = format!("{err}");
    assert!(
        msg.contains("UNIQUE constraint failed"),
        "expected UNIQUE constraint failure, got: {msg}",
    );
}

/// Round-trip: a Session with `lead_session_id: Some(_)` survives insert + read.
#[test]
fn session_lead_session_id_round_trip() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let mut epic = make_test_session();
    epic.session_kind = rsi_common::types::SessionKind::Epic;
    let lead_uuid = uuid::Uuid::new_v4();
    epic.lead_session_id = Some(lead_uuid);
    store.insert_session(&epic).unwrap();

    let fetched = store
        .get_session(epic.id)
        .unwrap()
        .expect("session present");
    assert_eq!(fetched.lead_session_id, Some(lead_uuid));

    // Clear and verify.
    store.set_lead_session(epic.id, None).unwrap();
    let after_clear = store.get_session(epic.id).unwrap().unwrap();
    assert_eq!(after_clear.lead_session_id, None);

    // try_promote_lead_if_unset wins on first call, loses on second.
    let candidate_a = uuid::Uuid::new_v4();
    let candidate_b = uuid::Uuid::new_v4();
    assert!(
        store
            .try_promote_lead_if_unset(epic.id, candidate_a)
            .unwrap()
    );
    assert!(
        !store
            .try_promote_lead_if_unset(epic.id, candidate_b)
            .unwrap()
    );
    let after_promote = store.get_session(epic.id).unwrap().unwrap();
    assert_eq!(after_promote.lead_session_id, Some(candidate_a));

    // clear_lead_session_if_matches NULLs only matching rows.
    store.clear_lead_session_if_matches(candidate_a).unwrap();
    let after_target_clear = store.get_session(epic.id).unwrap().unwrap();
    assert_eq!(after_target_clear.lead_session_id, None);

    // find_epics_by_lead returns the container holding the pointer.
    store.set_lead_session(epic.id, Some(candidate_a)).unwrap();
    let found = store.find_epics_by_lead(candidate_a).unwrap();
    assert_eq!(found, vec![epic.id]);
    let none_found = store.find_epics_by_lead(uuid::Uuid::new_v4()).unwrap();
    assert!(none_found.is_empty());
}

