#[test]
fn test_rpc_delete_container_empty_succeeds_via_has_children() {
    // Verify the delete-container guard primitive: an empty container
    // returns has_children=false, so the RPC handler proceeds with delete.
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let mut group = make_test_session();
    group.session_kind = rsi_common::types::SessionKind::Group;
    store.insert_session(&group).unwrap();

    assert!(
        !store.has_children(group.id).unwrap(),
        "empty group has no children"
    );
}

#[test]
fn test_rpc_delete_container_non_empty_rejected_via_has_children() {
    // Verify the inverse: a container with at least one child returns
    // has_children=true, which the RPC handler converts to InvalidParam.
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let mut group = make_test_session();
    group.session_kind = rsi_common::types::SessionKind::Group;
    store.insert_session(&group).unwrap();

    let mut child = make_test_session();
    child.session_kind = rsi_common::types::SessionKind::Standard;
    child.parent_id = Some(group.id);
    store.insert_session(&child).unwrap();

    assert!(
        store.has_children(group.id).unwrap(),
        "group with child reports children"
    );
}

#[test]
fn test_list_children_root_and_parent_scopes() {
    // list_children(None) returns top-level rows; list_children(Some(id))
    // returns direct children only — no recursion.
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let mut top = make_test_session();
    top.session_kind = rsi_common::types::SessionKind::Group;
    store.insert_session(&top).unwrap();

    let mut child_a = make_test_session();
    child_a.parent_id = Some(top.id);
    store.insert_session(&child_a).unwrap();

    let mut child_b = make_test_session();
    child_b.parent_id = Some(top.id);
    store.insert_session(&child_b).unwrap();

    let roots = store.list_children(None).unwrap();
    assert_eq!(roots.len(), 1);
    assert_eq!(roots[0].id, top.id);

    let kids = store.list_children(Some(top.id)).unwrap();
    assert_eq!(kids.len(), 2);
    let ids: std::collections::HashSet<_> = kids.iter().map(|s| s.id).collect();
    assert!(ids.contains(&child_a.id));
    assert!(ids.contains(&child_b.id));
}

#[test]
fn test_update_session_parent_persists_reparent() {
    // Reparenting via update_session_parent() flips the indexed column
    // and the change is visible through subsequent list_children() calls.
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let mut g1 = make_test_session();
    g1.session_kind = rsi_common::types::SessionKind::Group;
    store.insert_session(&g1).unwrap();

    let mut g2 = make_test_session();
    g2.session_kind = rsi_common::types::SessionKind::Group;
    store.insert_session(&g2).unwrap();

    let mut child = make_test_session();
    child.parent_id = Some(g1.id);
    store.insert_session(&child).unwrap();

    assert_eq!(store.list_children(Some(g1.id)).unwrap().len(), 1);
    assert_eq!(store.list_children(Some(g2.id)).unwrap().len(), 0);

    store.update_session_parent(child.id, Some(g2.id)).unwrap();

    assert_eq!(store.list_children(Some(g1.id)).unwrap().len(), 0);
    assert_eq!(store.list_children(Some(g2.id)).unwrap().len(), 1);

    // None unwinds to root.
    store.update_session_parent(child.id, None).unwrap();
    assert_eq!(store.list_children(Some(g2.id)).unwrap().len(), 0);
    let roots = store.list_children(None).unwrap();
    assert!(roots.iter().any(|s| s.id == child.id));
}

#[test]
fn test_load_parent_index_snapshot() {
    // Cycle detector relies on a single snapshot of (id -> parent_id)
    // mappings. Make sure the helper reflects the persisted state.
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let mut top = make_test_session();
    top.session_kind = rsi_common::types::SessionKind::Group;
    store.insert_session(&top).unwrap();

    let mut child = make_test_session();
    child.parent_id = Some(top.id);
    store.insert_session(&child).unwrap();

    let idx = store.load_parent_index().unwrap();
    assert_eq!(idx.get(&top.id).copied(), Some(None));
    assert_eq!(idx.get(&child.id).copied(), Some(Some(top.id)));
}

/// V47 migration (`topology_node_id` + `topology_iteration` columns + compound index):
/// open at head, drop the V47 artifacts, pin user_version back to 46, re-open,
/// assert V47 re-runs cleanly. Also verify pre-V47 rows deserialize with correct defaults.
#[test]
fn migration_v47_adds_topology_columns_and_index() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("rsi.db");

    // Initial open: head schema (V47+).
    {
        let store = Store::open(&db_path).unwrap();
        let version: i32 = store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .unwrap();
        assert_eq!(version, LATEST_SCHEMA_VERSION);

        // Both columns must exist.
        let col_node: i64 = store
            .conn
            .query_row(
                "SELECT COUNT(*) FROM pragma_table_info('sessions') WHERE name='topology_node_id'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(col_node, 1, "topology_node_id column must exist");

        let col_iter: i64 = store
            .conn
            .query_row(
                "SELECT COUNT(*) FROM pragma_table_info('sessions') WHERE name='topology_iteration'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(col_iter, 1, "topology_iteration column must exist");

        // Index must exist.
        let idx: i64 = store
            .conn
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name='idx_sessions_topology_node'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(idx, 1, "idx_sessions_topology_node must exist");

        // Insert a session (topology fields default), then roll back and re-run.
        let session = make_test_session();
        store.insert_session(&session).unwrap();

        let loaded = store.get_session(session.id).unwrap().unwrap();
        assert_eq!(
            loaded.topology_node_id, None,
            "pre-V47 row: topology_node_id must default to None"
        );
        assert_eq!(
            loaded.topology_iteration, 0,
            "pre-V47 row: topology_iteration must default to 0"
        );

        h1_restore_v90_fixture(&store.conn);
        // Rollback V47 artifacts to exercise migration re-run.
        store
            .conn
            .execute("DROP INDEX IF EXISTS idx_sessions_topology_node", [])
            .unwrap();
        // Rewind version AND schema together (issue #26): the V77..V82
        // relations must be torn down or the replayed chain aborts in
        // V77's preflight and every later step goes unexercised.
        rewind_store_to_schema_version(&store.conn, 46);
    }

    // Re-open: V47 must re-run and add the index back.
    {
        let store = Store::open(&db_path).unwrap();
        let version: i32 = store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .unwrap();
        assert_eq!(version, LATEST_SCHEMA_VERSION);

        let idx: i64 = store
            .conn
            .query_row(
                "SELECT COUNT(*) FROM sqlite_master WHERE type='index' AND name='idx_sessions_topology_node'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(idx, 1, "idx_sessions_topology_node must re-exist");
    }

    // Idempotent re-open.
    {
        let store = Store::open(&db_path).unwrap();
        let v: i32 = store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .unwrap();
        assert_eq!(v, LATEST_SCHEMA_VERSION);
    }
}

/// V48 (RSI-026): `daemon_settings` key-value table exists with the
