/// V70 migration (`work_time_ms` column, TD1): seed a V69 DB with session
/// rows, migrate, verify the column exists and all pre-V70 rows carry NULL.
/// Idempotent on re-open. Clone of `migration_v41_adds_approval_wait_ms_column`.
#[test]
fn migration_v70_adds_work_time_ms_column() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");

    // Open at current head (establishes full schema), seed rows, then pin
    // back to V69 and drop the work_time_ms column so the V70 block runs.
    {
        let store = Store::open(&db_path).unwrap();
        for _ in 0..50 {
            store.insert_session(&make_test_session()).unwrap();
        }
        h1_restore_v90_fixture(&store.conn);
        store
            .conn
            .execute("ALTER TABLE sessions DROP COLUMN work_time_ms", [])
            .unwrap();
        // Rewind version AND schema together (issue #26): the V77..V82
        // relations must be torn down or the replayed chain aborts in
        // V77's preflight and every later step goes unexercised.
        rewind_store_to_schema_version(&store.conn, 69);
    }

    // First open: V69 -> schema head (V70).
    {
        let store = Store::open(&db_path).unwrap();
        let version: i32 = store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .unwrap();
        assert_eq!(
            version, LATEST_SCHEMA_VERSION,
            "first open did not land V70"
        );
        assert_post_v77_chain_replayed(&store.conn);
        assert_post_v77_chain_replayed(&store.conn);
        assert_post_v77_chain_replayed(&store.conn);
        assert_post_v77_chain_replayed(&store.conn);
        assert_post_v77_chain_replayed(&store.conn);

        // Column present.
        let col_cnt: i64 = store
            .conn
            .query_row(
                "SELECT COUNT(*) FROM pragma_table_info('sessions') WHERE name = 'work_time_ms'",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(col_cnt, 1, "work_time_ms column missing after V70");

        // Every seeded row has work_time_ms = NULL (pre-V70 rows are unmeasured).
        let non_null: i64 = store
            .conn
            .query_row(
                "SELECT COUNT(*) FROM sessions WHERE work_time_ms IS NOT NULL",
                [],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(non_null, 0, "pre-V70 rows must carry work_time_ms = NULL");

        let total: i64 = store
            .conn
            .query_row("SELECT COUNT(*) FROM sessions", [], |row| row.get(0))
            .unwrap();
        assert_eq!(total, 50, "seed count regression");
    }

    // Second open: idempotent — no error, still at schema head.
    {
        let store = Store::open(&db_path).unwrap();
        let version: i32 = store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .unwrap();
        assert_eq!(
            version, LATEST_SCHEMA_VERSION,
            "re-open must leave user_version at schema head"
        );
    }
}

/// Store round-trip: `work_time_ms` threads through `insert_session` and
/// `update_session_metadata` and is read back unchanged. Template mirrors
/// the `duration_ms` / `approval_wait_ms` round-trips above.
#[test]
fn work_time_ms_persists_through_insert_and_metadata_update() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");
    let store = Store::open(&db_path).unwrap();

    let mut session = make_test_session();
    session.work_time_ms = Some(0);
    store.insert_session(&session).unwrap();

    let loaded = store.get_session(session.id).unwrap().unwrap();
    assert_eq!(
        loaded.work_time_ms,
        Some(0),
        "insert_session must persist the launch floor"
    );

    // Simulate a snapshot-tick / finalize flush advancing the floor.
    session.work_time_ms = Some(12345);
    store.update_session_metadata(&session).unwrap();

    let loaded = store.get_session(session.id).unwrap().unwrap();
    assert_eq!(
        loaded.work_time_ms,
        Some(12345),
        "update_session_metadata must persist the advanced floor"
    );
}

/// Restart-survival (hermetic, store layer): `restore_sessions`'s crash-recovery
/// flip (Running/Starting -> Failed) goes through `update_status`, a disjoint-
/// column UPDATE. Verify it does not clobber a previously persisted
/// `work_time_ms` floor, and that the value survives a full `Store` close +
/// reopen (simulating a daemon restart) unchanged — never reset, never
/// decreased. Complements the SessionManager-level
/// `restore_sessions_preserves_work_time_ms_floor` test in `session::launch::tests`.
#[test]
fn work_time_ms_survives_status_flip_and_store_reopen() {
    let dir = tempfile::tempdir().unwrap();
    let db_path = dir.path().join("test.db");

    let session_id = {
        let store = Store::open(&db_path).unwrap();
        let mut session = make_test_session();
        session.status = SessionStatus::Running;
        session.work_time_ms = Some(48_000);
        store.insert_session(&session).unwrap();

        // Exactly the mutation `restore_sessions` performs on a crash-recovered
        // Running/Starting row: a disjoint-column status flip.
        store
            .update_session_status(session.id, SessionStatus::Failed)
            .unwrap();

        let loaded = store.get_session(session.id).unwrap().unwrap();
        assert_eq!(loaded.status, SessionStatus::Failed);
        assert_eq!(
            loaded.work_time_ms,
            Some(48_000),
            "status flip must not clobber the work_time_ms floor"
        );
        session.id
    };

    // Simulate a daemon restart: close (drop) and reopen the Store against
    // the same db_path.
    {
        let store = Store::open(&db_path).unwrap();
        let loaded = store.get_session(session_id).unwrap().unwrap();
        assert_eq!(
            loaded.work_time_ms,
            Some(48_000),
            "work_time_ms must survive a Store close + reopen unchanged"
        );
    }
}

