/// A persisted legal Group → Epic → Task chain for V97 agent Issue tests.
/// The Epic lead pointer is set through the normal Store path so the V92 lead
/// generation witness exists exactly as it does in production.
fn issue_v97_authority_fixture() -> (Store, Uuid, Project) {
    let store = Store::open_in_memory().unwrap();
    let (lead, project) = seed_issue_v97_authority_topology(&store);
    (store, lead, project)
}

/// Project, Group, Epic and its current lead (returned) on an existing store.
#[allow(clippy::unwrap_used)]
fn seed_issue_v97_authority_topology(store: &Store) -> (Uuid, Project) {
    let project = make_test_project("V97 guarded Issue project");
    store.insert_project(&project).unwrap();

    let mut group = make_test_session();
    group.project_id = Some(project.id);
    group.session_kind = SessionKind::Group;
    store.insert_session(&group).unwrap();

    let mut epic = make_test_session();
    epic.project_id = Some(project.id);
    epic.session_kind = SessionKind::Epic;
    epic.parent_id = Some(group.id);
    store.insert_session(&epic).unwrap();

    let mut caller = make_test_session();
    caller.project_id = Some(project.id);
    caller.session_kind = SessionKind::Task;
    caller.parent_id = Some(epic.id);
    store.insert_session(&caller).unwrap();
    store.set_lead_session(epic.id, Some(caller.id)).unwrap();
    (caller.id, project)
}

#[test]
#[allow(clippy::unwrap_used)]
fn agent_list_issues_ready_filter_matches_operator_projection_and_pages() {
    let (store, lead, project) = issue_v97_authority_fixture();
    let blocker = store
        .create_issue(&NewIssue {
            project_id: project.id,
            ..make_new_issue("ready blocker")
        })
        .unwrap();
    let target = store
        .create_issue(&NewIssue {
            project_id: project.id,
            ..make_new_issue("blocked target")
        })
        .unwrap();
    let dependent = store
        .create_issue(&NewIssue {
            project_id: project.id,
            ..make_new_issue("blocked dependent")
        })
        .unwrap();
    let other = store
        .create_issue(&NewIssue {
            project_id: project.id,
            ..make_new_issue("other ready")
        })
        .unwrap();
    store.add_issue_dep(target.id, blocker.id).unwrap();
    store.add_issue_dep(dependent.id, target.id).unwrap();

    let legacy_rows = store
        .agent_list_issues(lead, &rsi_common::rpc::AgentListIssuesRequestV1::default())
        .unwrap()
        .issues;
    assert_eq!(
        legacy_rows.iter().map(|issue| issue.id).collect::<Vec<_>>(),
        vec![blocker.id, target.id, dependent.id, other.id],
        "ready=false preserves the existing active Issue page"
    );

    let collect_ready_pages = || {
        let mut cursor = None;
        let mut ids = Vec::new();
        loop {
            let page = store
                .agent_list_issues(
                    lead,
                    &rsi_common::rpc::AgentListIssuesRequestV1 {
                        limit: Some(1),
                        ready: true,
                        cursor,
                        ..Default::default()
                    },
                )
                .unwrap();
            ids.extend(page.issues.into_iter().map(|issue| issue.id));
            let Some(next) = page.next_cursor else {
                break;
            };
            cursor = Some(next);
        }
        ids
    };
    let operator_ready = store
        .list_ready_issues(Some(project.id), None)
        .unwrap()
        .into_iter()
        .map(|issue| issue.id)
        .collect::<std::collections::HashSet<_>>();
    assert_eq!(
        collect_ready_pages()
            .into_iter()
            .collect::<std::collections::HashSet<_>>(),
        operator_ready,
        "paged agent readiness matches the operator projection"
    );
    assert_eq!(operator_ready, [blocker.id, other.id].into_iter().collect());

    store
        .update_issue_status(blocker.id, IssueStatus::Closed)
        .unwrap();
    let after_close = store
        .list_ready_issues(Some(project.id), None)
        .unwrap()
        .into_iter()
        .map(|issue| issue.id)
        .collect::<std::collections::HashSet<_>>();
    assert_eq!(
        collect_ready_pages()
            .into_iter()
            .collect::<std::collections::HashSet<_>>(),
        after_close,
        "closing the blocker adds its dependent to the paged ready projection"
    );
    assert!(after_close.contains(&target.id));
    assert!(!after_close.contains(&dependent.id));
}

#[test]
#[allow(clippy::unwrap_used)]
fn agent_get_issue_returns_dependency_graph_to_lead_and_issue_coordinate_manager() {
    use rsi_common::rpc::AgentGetIssueRequestV1;

    let (store, lead, project) = issue_v97_authority_fixture();
    let blocker = store
        .create_issue(&NewIssue {
            project_id: project.id,
            ..make_new_issue("graph blocker")
        })
        .unwrap();
    let target = store
        .create_issue(&NewIssue {
            project_id: project.id,
            ..make_new_issue("graph target")
        })
        .unwrap();
    let dependent = store
        .create_issue(&NewIssue {
            project_id: project.id,
            ..make_new_issue("graph dependent")
        })
        .unwrap();
    store.add_issue_dep(target.id, blocker.id).unwrap();
    store.add_issue_dep(dependent.id, target.id).unwrap();

    let manager = insert_manager_session(&store, project.id);
    appoint_issue_coordinator(&store, project.id, manager.id, 0, "graph-manager-grant");
    for caller in [lead, manager.id] {
        let result = store
            .agent_get_issue(
                caller,
                &AgentGetIssueRequestV1 {
                    issue_id: target.id,
                },
            )
            .unwrap();
        assert_eq!(result.issue.title, "graph target");
        assert!(!result.blocked_by_truncated);
        assert!(!result.blocks_truncated);
        assert_eq!(
            result.blocked_by,
            vec![rsi_common::types::AgentIssueDependencyRefV1 {
                id: blocker.id,
                display_number: blocker.display_number,
                status: IssueStatus::Open,
            }]
        );
        assert_eq!(
            result.blocks,
            vec![rsi_common::types::AgentIssueDependencyRefV1 {
                id: dependent.id,
                display_number: dependent.display_number,
                status: IssueStatus::Open,
            }]
        );
        let json = serde_json::to_value(&result).unwrap();
        assert_eq!(json["title"], "graph target");
        assert_eq!(json["blocked_by"][0]["id"], blocker.id.to_string());
        assert_eq!(json["blocked_by_truncated"], false);
        assert_eq!(json["blocks_truncated"], false);
        assert_eq!(
            json["blocks"][0]["display_number"],
            dependent.display_number
        );
    }

    let overflow_blockers = (0..256)
        .map(|index| {
            store
                .create_issue(&NewIssue {
                    project_id: project.id,
                    ..make_new_issue(&format!("overflow blocker {index:03}"))
                })
                .unwrap()
        })
        .collect::<Vec<_>>();
    for overflow_blocker in &overflow_blockers {
        store.add_issue_dep(target.id, overflow_blocker.id).unwrap();
    }
    let overflow_result = store
        .agent_get_issue(
            lead,
            &AgentGetIssueRequestV1 {
                issue_id: target.id,
            },
        )
        .unwrap();
    assert_eq!(overflow_result.blocked_by.len(), 256);
    assert_eq!(overflow_result.blocked_by[0].id, blocker.id);
    assert_eq!(
        overflow_result.blocked_by[255].id,
        overflow_blockers[254].id
    );
    assert!(overflow_result.blocked_by_truncated);
    assert_eq!(
        overflow_result.blocks,
        vec![rsi_common::types::AgentIssueDependencyRefV1 {
            id: dependent.id,
            display_number: dependent.display_number,
            status: IssueStatus::Open,
        }]
    );
    assert!(!overflow_result.blocks_truncated);
    assert_eq!(
        serde_json::to_value(&overflow_result).unwrap()["blocked_by_truncated"],
        true
    );

    let worker = insert_manager_session(&store, project.id);
    let denied = store
        .agent_get_issue(
            worker.id,
            &AgentGetIssueRequestV1 {
                issue_id: target.id,
            },
        )
        .unwrap_err()
        .to_string();
    assert!(denied.contains("authority_denied"), "{denied}");
}

#[test]
fn issue_v97_migration_backfills_deterministic_baseline_event() {
    let directory = tempfile::tempdir().unwrap();
    let database = directory.path().join("v97-baseline.sqlite");
    let issue_id = {
        let store = Store::open(&database).unwrap();
        let project = make_test_project("V97 baseline project");
        store.insert_project(&project).unwrap();
        let issue = store
            .create_issue(&NewIssue {
                project_id: project.id,
                ..make_new_issue("V97 baseline")
            })
            .unwrap();
        rewind_store_to_schema_version(&store.conn, 96);
        issue.id
    };
    let store = Store::open(&database).unwrap();
    let issue = store.get_issue(issue_id).unwrap().unwrap();
    assert_eq!(issue.row_version, 1);
    assert!(issue.archived_at.is_none());
    let event = store
        .list_issue_events_v1(&rsi_common::types::IssueEventPageRequestV1 {
            issue_id,
            after_sequence: 0,
            limit: None,
        })
        .unwrap()
        .events
        .pop()
        .unwrap();
    assert_eq!(
        event.operation,
        rsi_common::types::IssueEventOperationV1::BaselineImported
    );
    assert_eq!(event.sequence, 1);
    assert_eq!(event.issue, issue);
}

#[test]
fn issue_v97_fault_after_baseline_rolls_back_to_exact_v96_then_repairs_once() {
    let directory = tempfile::tempdir().unwrap();
    let database = directory.path().join("v97-fault.sqlite");
    {
        let store = Store::open(&database).unwrap();
        let project = make_test_project("V97 fault project");
        store.insert_project(&project).unwrap();
        store
            .create_issue(&NewIssue {
                project_id: project.id,
                ..make_new_issue("fault baseline")
            })
            .unwrap();
        rewind_store_to_schema_version(&store.conn, 96);
    }
    super::issue_v97_test_fail_next_migration(super::IssueV97MigrationFault::AfterBaselineCopy);
    assert!(Store::open(&database).is_err());
    let raw = Connection::open(&database).unwrap();
    assert_eq!(
        raw.query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        96
    );
    assert_eq!(
        raw.query_row(
            "SELECT count(*) FROM sqlite_master WHERE name='issue_events'",
            [],
            |row| row.get::<_, i64>(0),
        )
        .unwrap(),
        0
    );
    drop(raw);
    let repaired = Store::open(&database).unwrap();
    assert_eq!(
        repaired
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        LATEST_SCHEMA_VERSION
    );
    assert_eq!(
        repaired
            .conn
            .query_row("SELECT count(*) FROM issue_events", [], |row| row
                .get::<_, i64>(0))
            .unwrap(),
        1
    );
}

fn issue_v97_build_exact_v96_fixture(path: &Path, issue_count: usize) {
    let store = Store::open(path).unwrap();
    let project = make_test_project(&format!("V97 migration fixture {issue_count}"));
    store.insert_project(&project).unwrap();
    let mut issues = Vec::new();
    for index in 0..issue_count {
        issues.push(
            store
                .create_issue(&NewIssue {
                    project_id: project.id,
                    title: format!("fixture Issue {index:04}"),
                    body: format!("data-bearing body {index}"),
                    priority: Some(u8::try_from(index % 4 + 1).unwrap()),
                    labels: vec!["v97".to_string(), format!("fixture-{index}")],
                    created_by_session_id: None,
                    assignee: (index % 2 == 0).then(|| "migration-owner".to_string()),
                    idea_id: None,
                    source_event_id: None,
                    source_finding_ref: None,
                })
                .unwrap(),
        );
    }
    for pair in issues.chunks_exact(2) {
        store.add_issue_dep(pair[1].id, pair[0].id).unwrap();
    }
    rewind_store_to_schema_version(&store.conn, 96);
}

#[test]
fn issue_v97_every_fault_rolls_back_and_repairs_fresh_copied_and_large_fixtures() {
    let directory = tempfile::tempdir().unwrap();
    for (fixture_name, issue_count) in [("fresh", 0), ("copied", 3), ("large", 64)] {
        let source = directory
            .path()
            .join(format!("{fixture_name}-source.sqlite"));
        issue_v97_build_exact_v96_fixture(&source, issue_count);
        let source_connection = Connection::open(&source).unwrap();
        Store::register_sql_functions(&source_connection).unwrap();
        let expected_v96 = d04_database_snapshot(&source_connection).unwrap();
        assert_eq!(expected_v96.version, 96);
        drop(source_connection);

        let reference = directory
            .path()
            .join(format!("{fixture_name}-reference.sqlite"));
        std::fs::copy(&source, &reference).unwrap();
        let reference_store = Store::open(&reference).unwrap();
        let expected_head = d04_database_snapshot(&reference_store.conn).unwrap();
        assert_eq!(expected_head.version, LATEST_SCHEMA_VERSION);
        assert_eq!(
            reference_store
                .conn
                .query_row("SELECT count(*) FROM issue_events", [], |row| row
                    .get::<_, usize>(0))
                .unwrap(),
            issue_count
        );
        drop(reference_store);

        for fault in super::IssueV97MigrationFault::ALL {
            let candidate = directory
                .path()
                .join(format!("{fixture_name}-{fault:?}.sqlite"));
            std::fs::copy(&source, &candidate).unwrap();
            super::issue_v97_test_fail_next_migration(fault);
            assert!(
                Store::open(&candidate).is_err(),
                "{fixture_name} fixture unexpectedly crossed {fault:?}"
            );
            let rolled_back = Connection::open(&candidate).unwrap();
            Store::register_sql_functions(&rolled_back).unwrap();
            assert_eq!(
                d04_database_snapshot(&rolled_back).unwrap(),
                expected_v96,
                "{fixture_name} fixture did not roll back exactly at {fault:?}"
            );
            drop(rolled_back);

            let repaired = Store::open(&candidate).unwrap();
            assert_eq!(
                d04_database_snapshot(&repaired.conn).unwrap(),
                expected_head,
                "{fixture_name} fixture did not repair exactly after {fault:?}"
            );
            drop(repaired);
            let reopened = Store::open(&candidate).unwrap();
            assert_eq!(
                d04_database_snapshot(&reopened.conn).unwrap(),
                expected_head,
                "{fixture_name} fixture changed on second reopen after {fault:?}"
            );
        }
    }
}

#[test]
fn issue_v97_rejects_malformed_v96_columns_indexes_foreign_keys_and_retained_catalog() {
    let directory = tempfile::tempdir().unwrap();
    for hostile in [
        "columns",
        "index",
        "foreign_key",
        "retained",
        "retained_index",
        "tool_column",
        "tool_index",
    ] {
        let database = directory.path().join(format!("malformed-{hostile}.sqlite"));
        issue_v97_build_exact_v96_fixture(&database, 0);
        let connection = Connection::open(&database).unwrap();
        match hostile {
            "columns" => {
                connection
                    .execute("ALTER TABLE issues ADD COLUMN hostile TEXT", [])
                    .unwrap();
            }
            "index" => {
                connection
                    .execute_batch(
                        "DROP INDEX idx_issues_project_ready;
                         CREATE INDEX idx_issues_project_ready ON issues(project_id,status,id);",
                    )
                    .unwrap();
            }
            "foreign_key" => {
                connection
                    .execute_batch(
                        "PRAGMA writable_schema=ON;
                         UPDATE sqlite_master
                         SET sql=replace(sql,
                           'FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT',
                           'CHECK(project_id IS NOT NULL)')
                         WHERE type='table' AND name='issues';
                         PRAGMA schema_version=123456;
                         PRAGMA writable_schema=OFF;",
                    )
                    .unwrap();
            }
            "retained" => {
                connection
                    .execute("DROP TRIGGER source_worktree_settlement_runs_no_delete", [])
                    .unwrap();
            }
            "retained_index" => {
                connection
                    .execute_batch(
                        "DROP INDEX idx_source_worktree_settlement_runs_state;
                         CREATE INDEX idx_source_worktree_settlement_runs_state
                             ON source_worktree_settlement_runs(state,run_id);",
                    )
                    .unwrap();
            }
            "tool_column" => {
                connection
                    .execute("ALTER TABLE conversation_events DROP COLUMN metadata", [])
                    .unwrap();
            }
            "tool_index" => {
                connection
                    .execute_batch(
                        "DROP INDEX idx_events_tool_use_id;
                         CREATE INDEX idx_events_tool_use_id
                             ON conversation_events(sequence);",
                    )
                    .unwrap();
            }
            _ => unreachable!(),
        }
        drop(connection);
        let error = Store::open(&database)
            .err()
            .expect("malformed V96 source must be rejected")
            .to_string();
        assert!(
            error.contains("V97")
                || error.contains("V94 settlement catalog")
                || error.contains("V95 settlement catalog")
                || error.contains("Issue catalog SQL mismatch")
                || error.contains("V94 Issue table SQL"),
            "unexpected malformed {hostile} error: {error}"
        );
        let raw = Connection::open(&database).unwrap();
        assert_eq!(
            raw.query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            96
        );
    }
}

#[derive(Clone, Copy, Debug)]
enum IssueV94HostileSemantic {
    DeclaredType,
    Nullability,
    UncheckedDefault,
    CheckClause,
    ConstraintClause,
}

fn issue_v97_issue_table_sql(connection: &Connection) -> String {
    connection
        .query_row(
            "SELECT sql FROM sqlite_master WHERE type='table' AND name='issues'",
            [],
            |row| row.get(0),
        )
        .unwrap()
}

fn issue_v97_explicit_index_sql(connection: &Connection) -> Vec<(String, String)> {
    connection
        .prepare(
            "SELECT name,sql FROM sqlite_master
             WHERE type='index' AND tbl_name IN ('issues','issue_deps') AND sql IS NOT NULL
             ORDER BY name",
        )
        .unwrap()
        .query_map([], |row| Ok((row.get(0)?, row.get(1)?)))
        .unwrap()
        .collect::<rusqlite::Result<Vec<_>>>()
        .unwrap()
}

fn issue_v97_catalog_bytes(connection: &Connection) -> Vec<u8> {
    let rows = connection
        .prepare(
            "SELECT type,name,tbl_name,COALESCE(sql,'') FROM sqlite_master
             ORDER BY type,name,tbl_name,COALESCE(sql,'')",
        )
        .unwrap()
        .query_map([], |row| {
            Ok([
                row.get::<_, String>(0)?,
                row.get::<_, String>(1)?,
                row.get::<_, String>(2)?,
                row.get::<_, String>(3)?,
            ])
        })
        .unwrap()
        .collect::<rusqlite::Result<Vec<_>>>()
        .unwrap();
    let mut bytes = Vec::new();
    for row in rows {
        for value in row {
            bytes.extend_from_slice(&(value.len() as u64).to_be_bytes());
            bytes.extend_from_slice(value.as_bytes());
        }
    }
    bytes
}

fn issue_v97_replace_issue_table_sql(connection: &Connection, replacement: &str) {
    let schema_version: i64 = connection
        .query_row("PRAGMA schema_version", [], |row| row.get(0))
        .unwrap();
    connection
        .pragma_update(None, "writable_schema", true)
        .unwrap();
    connection
        .execute(
            "UPDATE sqlite_master SET sql=?1 WHERE type='table' AND name='issues'",
            [replacement],
        )
        .unwrap();
    connection
        .pragma_update(None, "schema_version", schema_version + 1)
        .unwrap();
    connection
        .pragma_update(None, "writable_schema", false)
        .unwrap();
}

fn issue_v97_apply_hostile_semantic(
    connection: &Connection,
    hostile: IssueV94HostileSemantic,
) -> String {
    let canonical = issue_v97_issue_table_sql(connection);
    let (source, replacement) = match hostile {
        IssueV94HostileSemantic::DeclaredType => ("title TEXT NOT NULL", "title BLOB NOT NULL"),
        IssueV94HostileSemantic::Nullability => ("title TEXT NOT NULL", "title TEXT"),
        IssueV94HostileSemantic::UncheckedDefault => (
            "created_at TEXT NOT NULL",
            "created_at TEXT NOT NULL DEFAULT ''",
        ),
        IssueV94HostileSemantic::CheckClause => (
            "priority INTEGER CHECK(priority IS NULL OR priority BETWEEN 1 AND 4)",
            "priority INTEGER CHECK(priority IS NULL OR priority BETWEEN 0 AND 4)",
        ),
        IssueV94HostileSemantic::ConstraintClause => (
            "UNIQUE(id, project_id)",
            "UNIQUE(id, project_id) ON CONFLICT IGNORE",
        ),
    };
    assert_eq!(
        canonical.matches(source).count(),
        1,
        "hostile {hostile:?} fixture must rewrite exactly one static clause"
    );
    let rewritten = canonical.replacen(source, replacement, 1);
    for retained in [
        "body TEXT NOT NULL DEFAULT ''",
        "status TEXT NOT NULL DEFAULT 'Open'",
        "labels TEXT NOT NULL DEFAULT '[]'",
        "FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE RESTRICT",
        "FOREIGN KEY(idea_id, project_id) REFERENCES ideas(id, project_id) ON DELETE RESTRICT",
        "FOREIGN KEY(source_event_id, idea_id, project_id)",
        "REFERENCES idea_events(id, idea_id, project_id) ON DELETE RESTRICT",
    ] {
        assert!(
            rewritten.contains(retained),
            "hostile {hostile:?} fixture changed retained V94 clause {retained}"
        );
    }
    issue_v97_replace_issue_table_sql(connection, &rewritten);
    canonical
}

#[test]
fn issue_v97_hostile_v96_semantics_reject_before_ddl_then_repair_and_reopen_stably() {
    let directory = tempfile::tempdir().unwrap();
    let source = directory.path().join("hostile-semantics-source.sqlite");
    issue_v97_build_exact_v96_fixture(&source, 4);
    let source_connection = Connection::open(&source).unwrap();
    Store::register_sql_functions(&source_connection).unwrap();
    let expected_v96 = d04_database_snapshot(&source_connection).unwrap();
    let canonical_issue_sql = issue_v97_issue_table_sql(&source_connection);
    let canonical_index_sql = issue_v97_explicit_index_sql(&source_connection);
    drop(source_connection);

    let reference = directory.path().join("hostile-semantics-reference.sqlite");
    std::fs::copy(&source, &reference).unwrap();
    let reference_store = Store::open(&reference).unwrap();
    let expected_v97 = d04_database_snapshot(&reference_store.conn).unwrap();
    drop(reference_store);

    for hostile in [
        IssueV94HostileSemantic::DeclaredType,
        IssueV94HostileSemantic::Nullability,
        IssueV94HostileSemantic::UncheckedDefault,
        IssueV94HostileSemantic::CheckClause,
        IssueV94HostileSemantic::ConstraintClause,
    ] {
        let candidate = directory.path().join(format!("hostile-{hostile:?}.sqlite"));
        std::fs::copy(&source, &candidate).unwrap();
        let hostile_connection = Connection::open(&candidate).unwrap();
        Store::register_sql_functions(&hostile_connection).unwrap();
        assert_eq!(
            issue_v97_apply_hostile_semantic(&hostile_connection, hostile),
            canonical_issue_sql
        );
        assert_eq!(
            issue_v97_explicit_index_sql(&hostile_connection),
            canonical_index_sql,
            "hostile {hostile:?} fixture changed exact V96 index SQL"
        );
        let hostile_before = d04_database_snapshot(&hostile_connection).unwrap();
        let hostile_catalog_bytes = issue_v97_catalog_bytes(&hostile_connection);
        assert_eq!(hostile_before.version, 96);
        assert_ne!(hostile_before.catalog, expected_v96.catalog);
        assert_eq!(hostile_before.issues, expected_v96.issues);
        assert_eq!(hostile_before.issue_deps, expected_v96.issue_deps);
        drop(hostile_connection);

        let error = Store::open(&candidate)
            .err()
            .expect("hostile V96 semantics must reject before V97 DDL")
            .to_string();
        assert!(
            error.contains("Issue catalog"),
            "unexpected hostile {hostile:?} error: {error}"
        );

        let rejected = Connection::open(&candidate).unwrap();
        Store::register_sql_functions(&rejected).unwrap();
        assert_eq!(
            issue_v97_catalog_bytes(&rejected),
            hostile_catalog_bytes,
            "hostile {hostile:?} rejection changed catalog bytes"
        );
        assert_eq!(
            d04_database_snapshot(&rejected).unwrap(),
            hostile_before,
            "hostile {hostile:?} rejection changed catalog bytes, Issue/dependency data, integrity/FK state, or user_version"
        );
        assert!(!table_exists(&rejected, "issue_events"));
        for column in ["row_version", "archived_at"] {
            assert!(
                !table_columns(&rejected, "issues")
                    .iter()
                    .any(|candidate| candidate == column),
                "hostile {hostile:?} rejection created issues.{column}"
            );
        }

        issue_v97_replace_issue_table_sql(&rejected, &canonical_issue_sql);
        assert_eq!(
            d04_database_snapshot(&rejected).unwrap(),
            expected_v96,
            "hostile {hostile:?} repair did not restore the canonical V96 source"
        );
        drop(rejected);

        let repaired = Store::open(&candidate).unwrap();
        assert_eq!(
            d04_database_snapshot(&repaired.conn).unwrap(),
            expected_v97,
            "hostile {hostile:?} source did not migrate exactly once after repair"
        );
        drop(repaired);
        let reopened = Store::open(&candidate).unwrap();
        assert_eq!(
            d04_database_snapshot(&reopened.conn).unwrap(),
            expected_v97,
            "hostile {hostile:?} repaired V96 source changed on second reopen"
        );
    }
}

#[test]
fn issue_v97_all_shipped_histories_share_exact_v96_issue_projection_and_migrate_stably() {
    let directory = tempfile::tempdir().unwrap();
    let mut accepted_issue_catalog = None;
    for history in ["fresh", "legacy-v0", "deployed-additive", "pre-antigravity"] {
        let database = directory.path().join(format!("history-{history}.sqlite"));
        match history {
            "fresh" => {
                super::v89_test_fail_next_migration(super::V89MigrationFault::AfterPreflight);
                let error = match Store::open(&database) {
                    Ok(_) => panic!("fresh history unexpectedly crossed V89 preflight"),
                    Err(error) => error.to_string(),
                };
                assert!(error.contains("injected V89 migration fault"));
            }
            "legacy-v0" => {
                let connection = create_legacy_v0_fixture(&database);
                seed_legacy_v0_session(&connection);
                drop(connection);
                super::v89_test_fail_next_migration(super::V89MigrationFault::AfterPreflight);
                let error = match Store::open(&database) {
                    Ok(_) => panic!("legacy V0 history unexpectedly crossed V89 preflight"),
                    Err(error) => error.to_string(),
                };
                assert!(error.contains("injected V89 migration fault"));
            }
            "deployed-additive" => drop(create_deployed_additive_v88_fixture(&database)),
            "pre-antigravity" => drop(create_v88_pre_antigravity_fixture(&database)),
            _ => unreachable!(),
        }

        super::issue_v97_test_fail_next_migration(super::IssueV97MigrationFault::AfterPreflight);
        let error = match Store::open(&database) {
            Ok(_) => panic!("supported {history} history unexpectedly crossed V97 preflight"),
            Err(error) => error.to_string(),
        };
        assert!(
            error.contains("injected V97 Issue migration fault: AfterPreflight"),
            "supported {history} history did not pass exact V96 preflight: {error}"
        );
        let v96 = Connection::open(&database).unwrap();
        Store::register_sql_functions(&v96).unwrap();
        assert_eq!(
            v96.query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            96
        );
        let tx = v96.unchecked_transaction().unwrap();
        super::issues::validate_v96_issue_source_catalog(&tx)
            .expect("supported history must expose the exact retained V96 Issue projection");
        tx.rollback().unwrap();
        let catalog = query_fingerprint(
            &v96,
            "SELECT type,name,tbl_name,COALESCE(sql,'') FROM sqlite_master
             WHERE tbl_name IN ('issues','issue_deps')
             ORDER BY type,name,tbl_name,COALESCE(sql,'')",
        )
        .unwrap();
        if let Some(expected) = accepted_issue_catalog.as_ref() {
            assert_eq!(
                &catalog, expected,
                "supported {history} V96 history has a different Issue projection identity"
            );
        } else {
            accepted_issue_catalog = Some(catalog);
        }
        drop(v96);

        let migrated = Store::open(&database)
            .unwrap_or_else(|error| panic!("supported {history} failed at schema head: {error}"));
        let expected_head = d04_database_snapshot(&migrated.conn).unwrap();
        assert_eq!(expected_head.version, LATEST_SCHEMA_VERSION);
        drop(migrated);
        let reopened = Store::open(&database).unwrap();
        assert_eq!(
            d04_database_snapshot(&reopened.conn).unwrap(),
            expected_head,
            "supported {history} schema-head descendant changed on second reopen"
        );
    }
}

#[test]
fn issue_v97_to_v96_rewind_preserves_exact_catalog_projection_dependencies_and_fks() {
    let directory = tempfile::tempdir().unwrap();
    let database = directory.path().join("v97-rewind-parity.sqlite");
    issue_v97_build_exact_v96_fixture(&database, 8);
    let before = Connection::open(&database).unwrap();
    Store::register_sql_functions(&before).unwrap();
    let expected = d04_database_snapshot(&before).unwrap();
    drop(before);

    let migrated = Store::open(&database).unwrap();
    assert_eq!(
        migrated
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        LATEST_SCHEMA_VERSION
    );
    // `Store::open` migrates to the schema head, which is now past V97, so the
    // whole tail above V96 has to come off before the V96 parity comparison.
    rewind_store_to_schema_version(&migrated.conn, 96);
    assert_eq!(d04_database_snapshot(&migrated.conn).unwrap(), expected);
    drop(migrated);

    let reopened = Connection::open(&database).unwrap();
    Store::register_sql_functions(&reopened).unwrap();
    assert_eq!(d04_database_snapshot(&reopened).unwrap(), expected);
}

#[test]
fn agent_issue_status_archive_restore_replay_and_history_are_atomic() {
    let (store, caller, project) = issue_v97_authority_fixture();
    let issue = store
        .create_issue(&NewIssue {
            project_id: project.id,
            ..make_new_issue("guarded lifecycle")
        })
        .unwrap();
    let in_progress = store
        .agent_update_issue_status(
            caller,
            &rsi_common::rpc::AgentUpdateIssueStatusRequestV1 {
                issue_id: issue.id,
                status: IssueStatus::InProgress,
                expected_row_version: issue.row_version,
                idempotency_key: "v97-start".into(),
            },
        )
        .unwrap();
    assert_eq!(in_progress.issue.row_version, 2);
    let replay = store
        .agent_update_issue_status(
            caller,
            &rsi_common::rpc::AgentUpdateIssueStatusRequestV1 {
                issue_id: issue.id,
                status: IssueStatus::InProgress,
                expected_row_version: issue.row_version,
                idempotency_key: "v97-start".into(),
            },
        )
        .unwrap();
    assert!(replay.deduplicated);
    assert_eq!(replay.event.id, in_progress.event.id);
    let closed = store
        .agent_update_issue_status(
            caller,
            &rsi_common::rpc::AgentUpdateIssueStatusRequestV1 {
                issue_id: issue.id,
                status: IssueStatus::Closed,
                expected_row_version: in_progress.issue.row_version,
                idempotency_key: "v97-close".into(),
            },
        )
        .unwrap();
    let archived = store
        .agent_archive_issue(
            caller,
            &rsi_common::rpc::AgentArchiveIssueRequestV1 {
                issue_id: issue.id,
                expected_row_version: closed.issue.row_version,
                idempotency_key: "v97-archive".into(),
            },
        )
        .unwrap();
    assert!(archived.issue.archived_at.is_some());
    assert!(
        !store
            .list_ready_issues(Some(project.id), None)
            .unwrap()
            .iter()
            .any(|candidate| candidate.id == issue.id)
    );
    let restored = store
        .agent_restore_issue(
            caller,
            &rsi_common::rpc::AgentRestoreIssueRequestV1 {
                issue_id: issue.id,
                expected_row_version: archived.issue.row_version,
                idempotency_key: "v97-restore".into(),
            },
        )
        .unwrap();
    assert!(restored.issue.archived_at.is_none());
    assert_eq!(restored.issue.status, IssueStatus::Closed);
    let history = store
        .agent_list_issue_events(
            caller,
            &rsi_common::types::IssueEventPageRequestV1 {
                issue_id: issue.id,
                after_sequence: 0,
                limit: None,
            },
        )
        .unwrap();
    assert_eq!(
        history
            .events
            .iter()
            .map(|event| event.sequence)
            .collect::<Vec<_>>(),
        vec![1, 2, 3, 4, 5],
    );
    assert!(
        store
            .conn
            .execute("DELETE FROM issues WHERE id=?1", [issue.id.to_string()])
            .is_err()
    );
    assert!(
        store
            .conn
            .execute(
                "DELETE FROM issue_events WHERE issue_id=?1",
                [issue.id.to_string()]
            )
            .is_err()
    );
}

