// Manager Issue mutations (Issue #639): `issue_events` manager actor
// ---------------------------------------------------------------------------

/// Every `issue_events` row, every column, in a stable order.
#[allow(clippy::unwrap_used)]
fn issue_event_rows(connection: &Connection) -> Vec<Vec<rusqlite::types::Value>> {
    let mut statement = connection
        .prepare(
            "SELECT id,project_id,issue_id,sequence,operation,actor_kind,actor_session_id,
                    owning_epic_id,actor_label,expected_row_version,resulting_row_version,
                    idempotency_key,request_fingerprint,request_json,result_json,occurred_at
             FROM issue_events ORDER BY id",
        )
        .unwrap();
    statement
        .query_map([], |row| {
            (0..16)
                .map(|index| row.get::<_, rusqlite::types::Value>(index))
                .collect::<rusqlite::Result<Vec<_>>>()
        })
        .unwrap()
        .collect::<rusqlite::Result<Vec<_>>>()
        .unwrap()
}

#[allow(clippy::unwrap_used)]
fn schema_version(connection: &Connection) -> i32 {
    connection
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .unwrap()
}

#[allow(clippy::unwrap_used)]
fn validate_manager_actor_catalog_on(connection: &Connection) -> Result<()> {
    let tx = connection.unchecked_transaction().unwrap();
    let outcome = super::issues::manager_actor_migration::validate_manager_actor_catalog(&tx);
    tx.rollback().unwrap();
    outcome
}

/// Seed operator, session-create (no owning Epic) and lead-mutation (owning
/// Epic) events so the copy covers every pre-migration provenance shape.
#[allow(clippy::unwrap_used)]
fn seed_pre_manager_issue_history(store: &Store, lead: Uuid, project: Uuid) -> Issue {
    use rsi_common::rpc::{AgentUpdateIssueRequestV1, AgentUpdateIssueStatusRequestV1};
    store
        .create_agent_issue_idempotent_with_key(
            lead,
            Uuid::new_v4(),
            &NewIssue {
                project_id: project,
                created_by_session_id: Some(lead),
                ..make_new_issue("session created issue")
            },
            "session-create",
        )
        .unwrap();
    let issue = store
        .create_issue(&NewIssue {
            project_id: project,
            ..make_new_issue("operator created issue")
        })
        .unwrap();
    let updated = store
        .agent_update_issue(
            lead,
            &AgentUpdateIssueRequestV1 {
                issue_id: issue.id,
                expected_row_version: issue.row_version,
                idempotency_key: "lead-update".into(),
                title: Some("lead updated".into()),
                body: None,
                labels: None,
                priority: None,
                clear_priority: false,
                assignee: None,
                clear_assignee: false,
            },
        )
        .unwrap();
    store
        .agent_update_issue_status(
            lead,
            &AgentUpdateIssueStatusRequestV1 {
                issue_id: issue.id,
                status: IssueStatus::InProgress,
                expected_row_version: updated.issue.row_version,
                idempotency_key: "lead-start".into(),
            },
        )
        .unwrap()
        .issue
}

/// A pre-migration store (released V97 `issue_events` at the exact source
/// version) upgrades on open: every row is copied verbatim, the rebuilt
/// catalog is the pinned one, and reopening is a stable no-op.
#[test]
#[allow(clippy::unwrap_used)]
fn issue_events_manager_actor_migration_copies_rows_verbatim_and_reopens_idempotently() {
    use super::issues::manager_actor_migration::{
        MANAGER_ACTOR_SOURCE_VERSION, issue_events_admit_manager_actor,
        rewind_manager_actor_fixture_to_source,
    };
    let directory = tempfile::tempdir().unwrap();
    let database = directory.path().join("issue-events-manager-actor.sqlite");
    let rows = {
        let store = Store::open(&database).unwrap();
        let (lead, project) = seed_issue_v97_authority_topology(&store);
        seed_pre_manager_issue_history(&store, lead, project.id);
        let rows = issue_event_rows(&store.conn);
        let kinds = rows.iter().map(|row| row[5].clone()).collect::<Vec<_>>();
        for kind in ["operator", "session"] {
            assert!(kinds.contains(&rusqlite::types::Value::Text(kind.into())));
        }
        assert!(
            rows.iter()
                .any(|row| row[7] != rusqlite::types::Value::Null),
            "the fixture must carry a lead event with an owning Epic"
        );
        // V126 (Bedrock) and V127 (#634) sit above V125; rewind the tail first.
        rewind_post_v121_tail_to(&store.conn, 125);
        rewind_manager_actor_fixture_to_source(&store.conn);
        assert_eq!(schema_version(&store.conn), MANAGER_ACTOR_SOURCE_VERSION);
        assert!(!issue_events_admit_manager_actor(&store.conn));
        assert_eq!(issue_event_rows(&store.conn), rows);
        rows
    };

    let store = Store::open(&database).unwrap();
    assert_eq!(schema_version(&store.conn), LATEST_SCHEMA_VERSION);
    assert!(issue_events_admit_manager_actor(&store.conn));
    validate_manager_actor_catalog_on(&store.conn).unwrap();
    assert_eq!(issue_event_rows(&store.conn), rows);
    let catalog = query_fingerprint(
        &store.conn,
        "SELECT type,name,tbl_name,COALESCE(sql,'') FROM sqlite_master ORDER BY type,name",
    )
    .unwrap();
    drop(store);

    let store = Store::open(&database).unwrap();
    assert_eq!(schema_version(&store.conn), LATEST_SCHEMA_VERSION);
    validate_manager_actor_catalog_on(&store.conn).unwrap();
    assert_eq!(issue_event_rows(&store.conn), rows);
    assert_eq!(
        query_fingerprint(
            &store.conn,
            "SELECT type,name,tbl_name,COALESCE(sql,'') FROM sqlite_master ORDER BY type,name",
        )
        .unwrap(),
        catalog
    );
    // The immutability triggers survive the rebuild.
    for statement in [
        "UPDATE issue_events SET actor_label=NULL",
        "DELETE FROM issue_events",
    ] {
        let error = store.conn.execute(statement, []).unwrap_err().to_string();
        assert!(error.contains("issue_events_are_immutable"), "{error}");
    }
}

/// The migration refuses any source other than the exact preceding head and
/// leaves the released V97 catalog untouched.
#[test]
#[allow(clippy::unwrap_used)]
fn issue_events_manager_actor_migration_refuses_wrong_source_version_without_ddl() {
    use super::issues::manager_actor_migration::{
        MANAGER_ACTOR_SOURCE_VERSION, apply_manager_actor_migration,
        issue_events_admit_manager_actor, rewind_manager_actor_fixture_to_source,
    };
    let store = Store::open_in_memory().unwrap();
    // V126 (Bedrock) and V127 (#634) sit above V125; rewind the tail first.
    rewind_post_v121_tail_to(&store.conn, 125);
    rewind_manager_actor_fixture_to_source(&store.conn);
    store
        .conn
        .pragma_update(None, "user_version", MANAGER_ACTOR_SOURCE_VERSION - 1)
        .unwrap();
    let error = apply_manager_actor_migration(&store)
        .unwrap_err()
        .to_string();
    assert!(error.contains("requires exact"), "{error}");
    assert_eq!(
        schema_version(&store.conn),
        MANAGER_ACTOR_SOURCE_VERSION - 1
    );
    assert!(!issue_events_admit_manager_actor(&store.conn));

    store
        .conn
        .pragma_update(None, "user_version", MANAGER_ACTOR_SOURCE_VERSION)
        .unwrap();
    apply_manager_actor_migration(&store).unwrap();
    assert!(issue_events_admit_manager_actor(&store.conn));
    validate_manager_actor_catalog_on(&store.conn).unwrap();
}

/// Insert a copy of `template` (a `content_updated` lead event) at a fresh
/// sequence with the given provenance columns.
#[allow(clippy::too_many_arguments)]
fn insert_provenance_variant(
    connection: &Connection,
    template: &str,
    sequence: i64,
    actor_kind: &str,
    actor_session_id: Option<&str>,
    owning_epic_id: Option<&str>,
    actor_label: Option<&str>,
    idempotency_key: Option<&str>,
) -> rusqlite::Result<usize> {
    connection.execute(
        "INSERT INTO issue_events (id,project_id,issue_id,sequence,operation,actor_kind,
             actor_session_id,owning_epic_id,actor_label,expected_row_version,
             resulting_row_version,idempotency_key,request_fingerprint,request_json,
             result_json,occurred_at)
         SELECT ?1,project_id,issue_id,?2,operation,?3,?4,?5,?6,?2-1,?2,?7,
                request_fingerprint,request_json,json_set(result_json,'$.row_version',?2),
                occurred_at
         FROM issue_events WHERE id=?8",
        rusqlite::params![
            Uuid::new_v4().to_string(),
            sequence,
            actor_kind,
            actor_session_id,
            owning_epic_id,
            actor_label,
            idempotency_key,
            template,
        ],
    )
}

/// The rebuilt CHECKs accept a manager row only with its session id and key,
/// no label and no owning Epic; session and operator rules are unchanged.
#[test]
#[allow(clippy::unwrap_used)]
fn issue_events_manager_actor_check_admits_manager_without_owning_epic_only() {
    let (store, lead, project) = issue_v97_authority_fixture();
    let epic = store
        .get_session(lead)
        .unwrap()
        .unwrap()
        .parent_id
        .unwrap()
        .to_string();
    seed_pre_manager_issue_history(&store, lead, project.id);
    let template: String = store
        .conn
        .query_row(
            "SELECT id FROM issue_events WHERE operation='content_updated'",
            [],
            |row| row.get(0),
        )
        .unwrap();
    let manager = Uuid::new_v4().to_string();
    let lead = lead.to_string();
    let conn = &store.conn;

    // Accepted: the manager disjunct, and the unchanged lead-session shape.
    insert_provenance_variant(
        conn,
        &template,
        40,
        "manager",
        Some(&manager),
        None,
        None,
        Some("m-ok"),
    )
    .unwrap();
    insert_provenance_variant(
        conn,
        &template,
        41,
        "session",
        Some(&lead),
        Some(&epic),
        None,
        Some("s-ok"),
    )
    .unwrap();
    let stored: (String, String, Option<String>, Option<String>) = conn
        .query_row(
            "SELECT actor_kind,actor_session_id,owning_epic_id,actor_label FROM issue_events
             WHERE idempotency_key='m-ok'",
            [],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
        )
        .unwrap();
    assert_eq!(stored, ("manager".to_string(), manager.clone(), None, None));

    // Rejected by CHECK: manager with an owning Epic, label, or missing
    // session/key; lead mutation without an owning Epic; operator with a
    // session id.
    let rejected = [
        (
            "manager",
            Some(manager.as_str()),
            Some(epic.as_str()),
            None,
            Some("m-epic"),
        ),
        (
            "manager",
            Some(manager.as_str()),
            None,
            Some("label"),
            Some("m-label"),
        ),
        ("manager", None, None, None, Some("m-nosession")),
        ("manager", Some(manager.as_str()), None, None, None),
        ("session", Some(lead.as_str()), None, None, Some("s-noepic")),
        (
            "operator",
            Some(lead.as_str()),
            None,
            Some("operator"),
            None,
        ),
        (
            "steward",
            Some(manager.as_str()),
            None,
            None,
            Some("unknown-kind"),
        ),
    ];
    for (offset, (kind, session, owning_epic, label, key)) in rejected.into_iter().enumerate() {
        let error = insert_provenance_variant(
            conn,
            &template,
            50 + i64::try_from(offset).unwrap(),
            kind,
            session,
            owning_epic,
            label,
            key,
        )
        .unwrap_err()
        .to_string();
        assert!(error.contains("CHECK constraint failed"), "{kind}: {error}");
    }
}

/// Drive one manager mutation through its whole contract: first CAS writes one
/// manager-actor receipt, an identical retry returns it deduplicated, a stale
/// row version is refused, and a revoked grant is refused. No refusal writes.
#[allow(clippy::unwrap_used)]
fn assert_manager_issue_mutation_contract(
    verb: &str,
    prepare: impl Fn(&Store, Uuid, Issue) -> Issue,
    mutate: impl Fn(&Store, Uuid, &Issue, &str) -> Result<rsi_common::rpc::AgentIssueMutationResultV1>,
    check: impl Fn(&Issue, &Issue),
) {
    use rsi_common::harness_manager_v2::{ConfigureHarnessManagerPolicyRequestV2, ManagerPolicyV2};
    let (store, lead, project) = issue_v97_authority_fixture();
    let manager = insert_manager_session(&store, project.id);
    appoint_issue_coordinator(&store, project.id, manager.id, 0, "manager-mutation-grant");
    let issue = store
        .create_issue(&NewIssue {
            project_id: project.id,
            ..make_new_issue("manager mutation target")
        })
        .unwrap();
    let prior = prepare(&store, lead, issue);
    let event_count = || -> i64 {
        store
            .conn
            .query_row("SELECT count(*) FROM issue_events", [], |row| row.get(0))
            .unwrap()
    };
    let before = event_count();

    let first = mutate(&store, manager.id, &prior, "manager-key").unwrap();
    assert!(!first.deduplicated, "{verb}");
    assert_eq!(first.issue.row_version, prior.row_version + 1, "{verb}");
    check(&prior, &first.issue);
    assert_eq!(store.get_issue(prior.id).unwrap().unwrap(), first.issue);
    assert_eq!(event_count(), before + 1, "{verb}");
    assert_eq!(
        first.event.actor_kind,
        rsi_common::types::IssueActorKindV1::Manager
    );
    assert_eq!(first.event.actor_session_id, Some(manager.id));
    assert_eq!(first.event.owning_epic_id, None);
    assert_eq!(first.event.actor_label, None);
    assert_eq!(first.event.idempotency_key.as_deref(), Some("manager-key"));
    assert_eq!(first.event.expected_row_version, prior.row_version);
    let stored: (String, String, Option<String>) = store
        .conn
        .query_row(
            "SELECT actor_kind,actor_session_id,owning_epic_id FROM issue_events WHERE id=?1",
            [first.event.id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .unwrap();
    assert_eq!(
        stored,
        ("manager".to_string(), manager.id.to_string(), None)
    );
    let history = store
        .agent_list_issue_events(
            manager.id,
            &rsi_common::types::IssueEventPageRequestV1 {
                issue_id: prior.id,
                after_sequence: 0,
                limit: None,
            },
        )
        .unwrap();
    assert_eq!(history.events.last(), Some(&first.event), "{verb}");

    let replay = mutate(&store, manager.id, &prior, "manager-key").unwrap();
    assert!(replay.deduplicated, "{verb}");
    assert_eq!(replay.event, first.event);
    assert_eq!(replay.issue, first.issue);
    assert_eq!(event_count(), before + 1, "{verb}");

    let stale = mutate(&store, manager.id, &prior, "manager-stale-key")
        .unwrap_err()
        .to_string();
    assert!(stale.contains("stale_version"), "{verb}: {stale}");
    assert_eq!(event_count(), before + 1, "{verb}");

    let policy_version = store
        .get_harness_manager_policy(project.id)
        .unwrap()
        .unwrap()
        .row_version;
    let scope_version: i64 = store
        .conn
        .query_row(
            "SELECT row_version FROM harness_manager_scopes WHERE project_id=?1",
            [project.id.to_string()],
            |row| row.get(0),
        )
        .unwrap();
    store
        .configure_harness_manager_policy(&ConfigureHarnessManagerPolicyRequestV2 {
            project_id: project.id,
            expected_scope_version: scope_version,
            expected_policy_version: policy_version,
            idempotency_key: "manager-mutation-revoke".into(),
            policy: ManagerPolicyV2::default(),
        })
        .unwrap();
    let revoked = mutate(&store, manager.id, &first.issue, "manager-revoked-key")
        .unwrap_err()
        .to_string();
    assert!(revoked.contains("authority_denied"), "{verb}: {revoked}");
    assert_eq!(event_count(), before + 1, "{verb}");
    assert_eq!(store.get_issue(prior.id).unwrap().unwrap(), first.issue);
}

#[allow(clippy::unwrap_used)]
fn lead_set_status(store: &Store, lead: Uuid, issue: &Issue, status: IssueStatus) -> Issue {
    store
        .agent_update_issue_status(
            lead,
            &rsi_common::rpc::AgentUpdateIssueStatusRequestV1 {
                issue_id: issue.id,
                status,
                expected_row_version: issue.row_version,
                idempotency_key: format!("lead-status-{}", issue.row_version),
            },
        )
        .unwrap()
        .issue
}

#[test]
fn manager_issue_update_content_records_manager_actor_replays_and_refuses_stale_or_revoked() {
    assert_manager_issue_mutation_contract(
        "AgentUpdateIssue",
        |_, _, issue| issue,
        |store, caller, issue, key| {
            store.agent_update_issue(
                caller,
                &rsi_common::rpc::AgentUpdateIssueRequestV1 {
                    issue_id: issue.id,
                    expected_row_version: issue.row_version,
                    idempotency_key: key.into(),
                    title: Some(format!("manager retitled {}", issue.row_version)),
                    body: None,
                    labels: None,
                    priority: None,
                    clear_priority: false,
                    assignee: None,
                    clear_assignee: false,
                },
            )
        },
        |prior, next| {
            assert_eq!(
                next.title,
                format!("manager retitled {}", prior.row_version)
            );
        },
    );
}

