#[test]
fn issue_workspace_strict_mutations_retry_across_reopen_and_preserve_operator_provenance() {
    let directory = tempfile::tempdir().unwrap();
    let database = directory.path().join("issue-workspace-strict.sqlite");
    let project = make_test_project("Issue workspace strict project");
    let create = CreateIssueV2RequestV1 {
        project_id: project.id,
        title: "Durable operator issue".into(),
        body: "original body".into(),
        priority: Some(2),
        labels: vec!["workspace".into()],
        assignee: Some("operator".into()),
        idempotency_key: "workspace-create-17".into(),
    };
    let created = {
        let store = Store::open(&database).unwrap();
        store.insert_project(&project).unwrap();
        let created = store.create_issue_workspace(&create).unwrap();
        assert!(!created.deduplicated);
        assert_eq!(created.issue.title, "Durable operator issue");
        assert_eq!(created.issue.row_version, 1);
        assert_eq!(created.event.actor_kind, IssueActorKindV1::Operator);
        assert!(created.event.idempotency_key.is_none());

        let updated = store
            .update_issue_workspace(&UpdateIssueRequestV1 {
                project_id: project.id,
                issue_id: created.issue.id,
                expected_row_version: 1,
                idempotency_key: "workspace-update-17".into(),
                patch: IssueContentPatchV2 {
                    title: Some("Durable operator issue revised".into()),
                    body: None,
                    labels: Some(vec!["workspace".into(), "visible".into()]),
                    priority: NullablePatchV1::Clear,
                    assignee: NullablePatchV1::Set("current-owner".into()),
                },
            })
            .unwrap();
        assert_eq!(updated.issue.row_version, 2);
        assert_eq!(updated.issue.title, "Durable operator issue revised");
        assert_eq!(updated.issue.labels, vec!["workspace", "visible"]);
        assert_eq!(updated.issue.priority, None);
        assert_eq!(updated.issue.assignee.as_deref(), Some("current-owner"));
        assert!(updated.event.idempotency_key.is_none());
        created
    };

    let store = Store::open(&database).unwrap();
    let create_replay = store.create_issue_workspace(&create).unwrap();
    assert!(create_replay.deduplicated);
    assert_eq!(create_replay.issue, created.issue);
    assert_eq!(create_replay.issue.title, "Durable operator issue");

    let update_request = UpdateIssueRequestV1 {
        project_id: project.id,
        issue_id: created.issue.id,
        expected_row_version: 1,
        idempotency_key: "workspace-update-17".into(),
        patch: IssueContentPatchV2 {
            title: Some("Durable operator issue revised".into()),
            body: None,
            labels: Some(vec!["workspace".into(), "visible".into()]),
            priority: NullablePatchV1::Clear,
            assignee: NullablePatchV1::Set("current-owner".into()),
        },
    };
    let update_replay = store.update_issue_workspace(&update_request).unwrap();
    assert!(update_replay.deduplicated);
    assert_eq!(update_replay.issue.row_version, 2);
    assert_eq!(update_replay.issue.title, "Durable operator issue revised");

    let conflict = store
        .update_issue_workspace(&UpdateIssueRequestV1 {
            patch: IssueContentPatchV2 {
                title: Some("different content with reused key".into()),
                ..update_request.patch.clone()
            },
            ..update_request.clone()
        })
        .unwrap_err();
    assert_eq!(
        issue_workspace_error_code(conflict).code,
        IssueWorkspaceErrorCodeV1::IdempotencyConflict
    );

    let stale = store
        .update_issue_workspace(&UpdateIssueRequestV1 {
            expected_row_version: 1,
            idempotency_key: "workspace-stale-17".into(),
            patch: IssueContentPatchV2 {
                body: Some("stale body".into()),
                ..IssueContentPatchV2::default()
            },
            ..update_request.clone()
        })
        .unwrap_err();
    let stale = issue_workspace_error_code(stale);
    assert_eq!(stale.code, IssueWorkspaceErrorCodeV1::StaleVersion);
    assert_eq!(stale.expected_row_version, Some(1));
    assert_eq!(stale.actual_row_version, Some(2));

    let cancelled = store
        .update_issue_status_workspace(&UpdateIssueStatusV2RequestV1 {
            project_id: project.id,
            issue_id: created.issue.id,
            expected_row_version: 2,
            idempotency_key: "workspace-cancel-17".into(),
            status: IssueStatus::Cancelled,
        })
        .unwrap();
    assert_eq!(cancelled.issue.status, IssueStatus::Cancelled);
    assert!(cancelled.issue.closed_at.is_some());
    let reopened = store
        .update_issue_status_workspace(&UpdateIssueStatusV2RequestV1 {
            project_id: project.id,
            issue_id: created.issue.id,
            expected_row_version: 3,
            idempotency_key: "workspace-reopen-17".into(),
            status: IssueStatus::Open,
        })
        .unwrap();
    assert_eq!(reopened.issue.status, IssueStatus::Open);
    assert!(reopened.issue.closed_at.is_none());

    let nonterminal = store
        .archive_issue_workspace(&ArchiveIssueRequestV1 {
            project_id: project.id,
            issue_id: created.issue.id,
            expected_row_version: 4,
            idempotency_key: "workspace-archive-too-early".into(),
        })
        .unwrap_err();
    assert_eq!(
        issue_workspace_error_code(nonterminal).code,
        IssueWorkspaceErrorCodeV1::NotTerminal
    );
    let cancelled_again = store
        .update_issue_status_workspace(&UpdateIssueStatusV2RequestV1 {
            project_id: project.id,
            issue_id: created.issue.id,
            expected_row_version: 4,
            idempotency_key: "workspace-cancel-again-17".into(),
            status: IssueStatus::Cancelled,
        })
        .unwrap();
    let archived = store
        .archive_issue_workspace(&ArchiveIssueRequestV1 {
            project_id: project.id,
            issue_id: created.issue.id,
            expected_row_version: cancelled_again.issue.row_version,
            idempotency_key: "workspace-archive-17".into(),
        })
        .unwrap();
    assert_eq!(archived.issue.status, IssueStatus::Cancelled);
    assert!(archived.issue.archived_at.is_some());
    let restored = store
        .restore_issue_workspace(&RestoreIssueRequestV1 {
            project_id: project.id,
            issue_id: created.issue.id,
            expected_row_version: archived.issue.row_version,
            idempotency_key: "workspace-restore-17".into(),
        })
        .unwrap();
    assert_eq!(restored.issue.status, IssueStatus::Cancelled);
    assert!(restored.issue.archived_at.is_none());
    assert_eq!(restored.issue.row_version, 7);

    let event_rows: (i64, i64) = store
        .conn
        .query_row(
            "SELECT COUNT(*), SUM(CASE WHEN idempotency_key IS NULL THEN 1 ELSE 0 END)
             FROM issue_events WHERE issue_id=?1",
            params![created.issue.id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .unwrap();
    assert_eq!(event_rows, (7, 7));
}

#[test]
fn issue_workspace_dependency_mutations_converge_and_keep_store_authority() {
    let store = Store::open_in_memory().unwrap();
    let project_id = d04_test_project_id();
    let dependent = store
        .create_issue(&NewIssue {
            title: "Convergent dependent".into(),
            ..make_new_issue("unused")
        })
        .unwrap();
    let blocker = store
        .create_issue(&NewIssue {
            title: "Convergent blocker".into(),
            ..make_new_issue("unused")
        })
        .unwrap();
    let request = IssueDependencyMutationRequestV1 {
        project_id,
        issue_id: dependent.id,
        depends_on_id: blocker.id,
    };
    assert!(
        store
            .add_issue_dependency_workspace(&request)
            .unwrap()
            .changed
    );
    assert!(
        !store
            .add_issue_dependency_workspace(&request)
            .unwrap()
            .changed
    );
    assert_eq!(store.list_issue_deps(dependent.id).unwrap().len(), 1);

    let cycle = store
        .add_issue_dependency_workspace(&IssueDependencyMutationRequestV1 {
            project_id,
            issue_id: blocker.id,
            depends_on_id: dependent.id,
        })
        .unwrap_err();
    assert_eq!(
        issue_workspace_error_code(cycle).code,
        IssueWorkspaceErrorCodeV1::DependencyCycle
    );

    let other_project = make_test_project("Dependency endpoint project");
    store.insert_project(&other_project).unwrap();
    let foreign = store
        .create_issue(&NewIssue {
            project_id: other_project.id,
            title: "Foreign dependency endpoint".into(),
            ..make_new_issue("unused")
        })
        .unwrap();
    let endpoint = store
        .add_issue_dependency_workspace(&IssueDependencyMutationRequestV1 {
            project_id,
            issue_id: dependent.id,
            depends_on_id: foreign.id,
        })
        .unwrap_err();
    assert_eq!(
        issue_workspace_error_code(endpoint).code,
        IssueWorkspaceErrorCodeV1::DependencyEndpoint
    );

    assert!(
        store
            .remove_issue_dependency_workspace(&request)
            .unwrap()
            .changed
    );
    assert!(
        !store
            .remove_issue_dependency_workspace(&request)
            .unwrap()
            .changed
    );
    assert!(store.list_issue_deps(dependent.id).unwrap().is_empty());
}

#[test]
fn update_issue_status_closed_at() {
    let store = Store::open_in_memory().unwrap();
    let issue = store.create_issue(&make_new_issue("lifecycle")).unwrap();
    assert!(issue.closed_at.is_none());

    let closed = store
        .update_issue_status(issue.id, IssueStatus::Closed)
        .unwrap();
    assert_eq!(closed.status, IssueStatus::Closed);
    assert!(
        closed.closed_at.is_some(),
        "entering Closed must set closed_at"
    );
    assert!(
        closed.updated_at > issue.updated_at,
        "status transition must bump updated_at"
    );

    let reopened = store
        .update_issue_status(issue.id, IssueStatus::Open)
        .unwrap();
    assert_eq!(reopened.status, IssueStatus::Open);
    assert!(reopened.closed_at.is_none(), "reopen must clear closed_at");
    assert!(reopened.updated_at > closed.updated_at);

    // Entering Cancelled (the other terminal status) also sets closed_at,
    // on a second issue entering it straight from Open.
    let other = store.create_issue(&make_new_issue("cancel-entry")).unwrap();
    let cancelled = store
        .update_issue_status(other.id, IssueStatus::Cancelled)
        .unwrap();
    assert_eq!(cancelled.status, IssueStatus::Cancelled);
    assert!(
        cancelled.closed_at.is_some(),
        "entering Cancelled must set closed_at"
    );

    // Terminal→terminal Closed→Cancelled preserves the original closed_at —
    // the documented behavior.
    let reclosed = store
        .update_issue_status(issue.id, IssueStatus::Closed)
        .unwrap();
    assert!(reclosed.closed_at.is_some());
    let recancelled = store
        .update_issue_status(issue.id, IssueStatus::Cancelled)
        .unwrap();
    assert_eq!(recancelled.status, IssueStatus::Cancelled);
    assert_eq!(
        recancelled.closed_at, reclosed.closed_at,
        "Closed -> Cancelled must preserve closed_at"
    );
    assert!(recancelled.updated_at > reclosed.updated_at);
}

#[test]
