fn add_dep_rejects_cycle() {
    let store = Store::open_in_memory().unwrap();
    let a = store.create_issue(&make_new_issue("a")).unwrap();
    let b = store.create_issue(&make_new_issue("b")).unwrap();
    let c = store.create_issue(&make_new_issue("c")).unwrap();

    // Direct 2-cycle: A→B then B→A.
    store.add_issue_dep(a.id, b.id).unwrap();
    let err = store.add_issue_dep(b.id, a.id).unwrap_err();
    assert!(
        err.to_string().contains("cycle"),
        "expected cycle error, got: {err}"
    );

    // Transitive 3-cycle: A→B→C then C→A.
    store.add_issue_dep(b.id, c.id).unwrap();
    let err = store.add_issue_dep(c.id, a.id).unwrap_err();
    assert!(
        err.to_string().contains("cycle"),
        "expected cycle error, got: {err}"
    );

    // No phantom edges from the rejected inserts.
    let count: i64 = store
        .conn
        .query_row("SELECT COUNT(*) FROM issue_deps", [], |row| row.get(0))
        .unwrap();
    assert_eq!(count, 2);
}

/// C3 item 5: `remove_issue_dep` lacked a direct store-level unit test
/// (only exercised indirectly via the RPC-fixture test). Pins the
/// `Result<bool>` contract: `true` when an edge existed and was deleted,
/// `false` when there was nothing to remove — including on a second call
/// for the same edge, and for an edge that never existed at all.
#[test]
fn remove_issue_dep_returns_true_then_false() {
    let store = Store::open_in_memory().unwrap();
    let a = store.create_issue(&make_new_issue("a")).unwrap();
    let b = store.create_issue(&make_new_issue("b")).unwrap();
    let c = store.create_issue(&make_new_issue("c")).unwrap();

    // Never existed: false, not an error.
    assert!(!store.remove_issue_dep(a.id, c.id).unwrap());

    store.add_issue_dep(a.id, b.id).unwrap();
    assert!(
        store.remove_issue_dep(a.id, b.id).unwrap(),
        "an existing edge must report true"
    );

    let count: i64 = store
        .conn
        .query_row("SELECT COUNT(*) FROM issue_deps", [], |row| row.get(0))
        .unwrap();
    assert_eq!(count, 0, "the edge must actually be gone");

    assert!(
        !store.remove_issue_dep(a.id, b.id).unwrap(),
        "removing an already-removed edge must report false, not error"
    );
}

/// V97 rejects hard deletion even through raw SQL and retains dependency rows.
/// The historical `ON DELETE CASCADE` remains defensive referential truth but
/// can no longer become a user-visible destructive path.
#[test]
fn v97_issue_delete_is_rejected_and_retains_edges() {
    let store = Store::open_in_memory().unwrap();
    let a = store.create_issue(&make_new_issue("a")).unwrap();
    let b = store.create_issue(&make_new_issue("b")).unwrap();
    store.add_issue_dep(a.id, b.id).unwrap();

    assert!(
        store
            .conn
            .execute(
                "DELETE FROM issues WHERE id = ?1",
                params![b.id.to_string()],
            )
            .is_err()
    );

    let count: i64 = store
        .conn
        .query_row("SELECT COUNT(*) FROM issue_deps", [], |row| row.get(0))
        .unwrap();
    assert_eq!(count, 1, "rejected delete must retain dependency edges");
    assert!(store.get_issue(b.id).unwrap().is_some());
}

#[test]
fn ready_work_semantics() {
    let store = Store::open_in_memory().unwrap();

    let ready_ids = |store: &Store| -> Vec<Uuid> {
        store
            .list_ready_issues(None, None)
            .unwrap()
            .into_iter()
            .map(|i| i.id)
            .collect()
    };

    // Open with no deps is ready.
    let i1 = store.create_issue(&make_new_issue("i1")).unwrap();
    assert!(ready_ids(&store).contains(&i1.id));

    // Open blocker makes the dependent not ready (blocker itself is ready).
    let i2 = store.create_issue(&make_new_issue("i2")).unwrap();
    let i3 = store.create_issue(&make_new_issue("i3")).unwrap();
    store.add_issue_dep(i2.id, i3.id).unwrap();
    let ready = ready_ids(&store);
    assert!(!ready.contains(&i2.id), "open blocker => not ready");
    assert!(ready.contains(&i3.id));

    // InProgress blocker still blocks.
    store
        .update_issue_status(i3.id, IssueStatus::InProgress)
        .unwrap();
    let ready = ready_ids(&store);
    assert!(
        !ready.contains(&i2.id),
        "InProgress blocker => still blocked"
    );
    assert!(!ready.contains(&i3.id), "InProgress issue is never ready");

    // Closed blocker unblocks.
    store
        .update_issue_status(i3.id, IssueStatus::Closed)
        .unwrap();
    assert!(
        ready_ids(&store).contains(&i2.id),
        "Closed blocker => ready"
    );

    // Cancelled blocker unblocks.
    let i4 = store.create_issue(&make_new_issue("i4")).unwrap();
    let i5 = store.create_issue(&make_new_issue("i5")).unwrap();
    store.add_issue_dep(i4.id, i5.id).unwrap();
    assert!(!ready_ids(&store).contains(&i4.id));
    store
        .update_issue_status(i5.id, IssueStatus::Cancelled)
        .unwrap();
    assert!(
        ready_ids(&store).contains(&i4.id),
        "Cancelled blocker => ready"
    );

    // Ordering: priority ASC then created_at ASC, NULL priority last.
    let store = Store::open_in_memory().unwrap();
    let p3 = store
        .create_issue(&NewIssue {
            priority: Some(3),
            ..make_new_issue("p3")
        })
        .unwrap();
    let p1 = store
        .create_issue(&NewIssue {
            priority: Some(1),
            ..make_new_issue("p1")
        })
        .unwrap();
    let p_none = store.create_issue(&make_new_issue("p-none")).unwrap();
    let p1_later = store
        .create_issue(&NewIssue {
            priority: Some(1),
            ..make_new_issue("p1-later")
        })
        .unwrap();

    assert_eq!(
        ready_ids(&store),
        vec![p1.id, p1_later.id, p3.id, p_none.id],
        "priority-then-age with NULL priority last"
    );

    // Limit applies after ordering.
    let limited = store.list_ready_issues(None, Some(2)).unwrap();
    assert_eq!(
        limited.into_iter().map(|i| i.id).collect::<Vec<_>>(),
        vec![p1.id, p1_later.id]
    );
}

/// SF-1: `update_issue` apply path — set, skip (None), and clear
/// (`Some(None)`) semantics of the double-Option patch encoding.
#[test]
fn update_issue_apply_set_skip_clear() {
    let store = Store::open_in_memory().unwrap();
    let issue = store
        .create_issue(&NewIssue {
            project_id: d04_test_project_id(),
            title: "orig title".to_string(),
            body: "orig body".to_string(),
            priority: Some(2),
            labels: vec!["a".to_string()],
            created_by_session_id: None,
            assignee: Some("jake".to_string()),
            idea_id: None,
            source_event_id: None,
            source_finding_ref: None,
        })
        .unwrap();

    // Set title/body/labels; skip priority/assignee (None = leave unchanged).
    let patched = store
        .update_issue(
            issue.id,
            &IssueUpdate {
                title: Some("new title".to_string()),
                body: Some("new body".to_string()),
                labels: Some(vec!["b".to_string(), "c".to_string()]),
                priority: None,
                assignee: None,
            },
        )
        .unwrap();
    assert_eq!(patched.title, "new title");
    assert_eq!(patched.body, "new body");
    assert_eq!(patched.labels, vec!["b", "c"]);
    assert_eq!(patched.priority, Some(2), "None must skip priority");
    assert_eq!(
        patched.assignee.as_deref(),
        Some("jake"),
        "None must skip assignee"
    );
    assert!(
        patched.updated_at > issue.updated_at,
        "patch must bump updated_at"
    );
    assert_eq!(patched.created_at, issue.created_at);
    assert_eq!(
        patched.status,
        IssueStatus::Open,
        "patch never touches status"
    );

    // Clear: Some(None) nulls the nullable fields; unpatched fields survive.
    let cleared = store
        .update_issue(
            issue.id,
            &IssueUpdate {
                priority: Some(None),
                assignee: Some(None),
                ..Default::default()
            },
        )
        .unwrap();
    assert_eq!(cleared.priority, None, "Some(None) must clear priority");
    assert_eq!(cleared.assignee, None, "Some(None) must clear assignee");
    assert_eq!(cleared.title, "new title", "unpatched fields unchanged");
    assert_eq!(cleared.labels, vec!["b", "c"]);
    assert!(cleared.updated_at > patched.updated_at);

    // Set nullable fields back via Some(Some(v)).
    let set_back = store
        .update_issue(
            issue.id,
            &IssueUpdate {
                priority: Some(Some(1)),
                assignee: Some(Some("agent".to_string())),
                ..Default::default()
            },
        )
        .unwrap();
    assert_eq!(set_back.priority, Some(1));
    assert_eq!(set_back.assignee.as_deref(), Some("agent"));
}

/// N-2 / plan D3: a hand-inserted (raw SQL) dependency cycle never hangs the
/// non-recursive ready-work query — its members are simply mutually blocked.
#[test]
fn ready_query_tolerates_raw_cycle() {
    let store = Store::open_in_memory().unwrap();
    let a = store.create_issue(&make_new_issue("cyc-a")).unwrap();
    let b = store.create_issue(&make_new_issue("cyc-b")).unwrap();
    let free = store.create_issue(&make_new_issue("free")).unwrap();

    // Bypass add_issue_dep's write-time cycle rejection with raw SQL: A<->B.
    for (x, y) in [(a.id, b.id), (b.id, a.id)] {
        store
            .conn
            .execute(
                "INSERT INTO issue_deps (project_id, issue_id, depends_on_id, created_at)
                 VALUES (?1, ?2, ?3, ?4)",
                params![
                    d04_test_project_id().to_string(),
                    x.to_string(),
                    y.to_string(),
                    "2026-07-08T00:00:00.000000000Z"
                ],
            )
            .unwrap();
    }

    let ready: Vec<Uuid> = store
        .list_ready_issues(None, None)
        .unwrap()
        .into_iter()
        .map(|i| i.id)
        .collect();
    assert!(!ready.contains(&a.id), "cycle member A must not be ready");
    assert!(!ready.contains(&b.id), "cycle member B must not be ready");
    assert_eq!(ready, vec![free.id], "unrelated open issue stays ready");
}

#[test]
fn issue_writer_c5_automatic_insert_and_pending_resolution_are_one_replay_safe_transaction() {
    let store = Store::open_in_memory().unwrap();
    let mut source = make_test_session();
    source.status = SessionStatus::Running;
    store.insert_session(&source).unwrap();
    store
        .update_failed_and_stage_c5_autofile(
            source.id,
            crate::store::daemon_settings::AutofileCause::ProcessDied,
        )
        .unwrap();
    assert_eq!(
        store
            .get_session(source.id)
            .unwrap()
            .unwrap()
            .stop_reason
            .as_deref(),
        Some("terminal_failure:process-died"),
        "failed status and typed stop reason are persisted together"
    );
    let pending_key = super::daemon_settings::c5_autofile_pending_key(source.id);
    assert!(
        store
            .get_c5_autofile_pending(&pending_key)
            .unwrap()
            .is_some()
    );
    let id = Uuid::new_v5(&Uuid::NAMESPACE_URL, b"c5-atomic-test");
    let new = NewIssue {
        project_id: d04_test_project_id(),
        title: "automatic".into(),
        body: "bounded".into(),
        priority: None,
        labels: vec!["pipeline-failure".into()],
        created_by_session_id: Some(source.id),
        assignee: None,
        idea_id: None,
        source_event_id: None,
        source_finding_ref: None,
    };
    let first = store
        .settle_c5_autofile_pending(source.id, id, &new, &pending_key)
        .unwrap();
    assert!(matches!(
        first,
        super::C5SettlementOutcome::Committed {
            deduplicated: false
        }
    ));
    assert!(
        store
            .get_c5_autofile_pending(&pending_key)
            .unwrap()
            .is_none()
    );
    let history = store
        .list_issue_events_v1(&rsi_common::types::IssueEventPageRequestV1 {
            issue_id: id,
            after_sequence: 0,
            limit: None,
        })
        .unwrap();
    assert_eq!(history.events.len(), 1);
    let event = &history.events[0];
    assert_eq!(
        event.actor_kind,
        rsi_common::types::IssueActorKindV1::System
    );
    assert_eq!(event.actor_label.as_deref(), Some("rsi:c5-autofile"));
    assert_eq!(event.actor_session_id, None);
    assert_eq!(event.owning_epic_id, None);
    assert_issue_event_semantics_are_complete(event);
    // A later marker for the same lineage reuses the deterministic id without
    // changing the first row or allocating another display number.
    store
        .update_failed_and_stage_c5_autofile(
            source.id,
            crate::store::daemon_settings::AutofileCause::ProcessDied,
        )
        .unwrap();
    let replay = store
        .settle_c5_autofile_pending(source.id, id, &new, &pending_key)
        .unwrap();
    assert!(matches!(
        replay,
        super::C5SettlementOutcome::Committed { deduplicated: true }
    ));
    assert_eq!(store.list_issues(&Default::default()).unwrap().len(), 1);
    assert_eq!(
        store
            .list_issue_events_v1(&rsi_common::types::IssueEventPageRequestV1 {
                issue_id: id,
                after_sequence: 0,
                limit: None,
            })
            .unwrap()
            .events
            .len(),
        1,
        "C5 replay duplicated its Issue event"
    );
}

#[test]
fn c5_settlement_never_admits_a_stale_marker_and_rejects_unknown_journal_versions() {
    let store = Store::open_in_memory().unwrap();
    let source = make_test_session();
    let pending_key = super::daemon_settings::c5_autofile_pending_key(source.id);
    let issue_id = Uuid::new_v5(&Uuid::NAMESPACE_URL, b"c5-stale-marker-test");
    let new = NewIssue {
        project_id: d04_test_project_id(),
        title: "must not be created".into(),
        body: String::new(),
        priority: None,
        labels: vec![],
        created_by_session_id: Some(source.id),
        assignee: None,
        idea_id: None,
        source_event_id: None,
        source_finding_ref: None,
    };

    // A marker whose source row was deleted is stale: it must not allocate an
    // issue even though the caller presents a deterministic issue id.
    store
        .set_daemon_setting(
            &pending_key,
            &format!(
                r#"{{"version":1,"source_session_id":"{}","cause":"process-died","staged_at":"2026-07-14T00:00:00.000000000Z"}}"#,
                source.id
            ),
        )
        .unwrap();
    let outcome = store.settle_c5_autofile_pending(source.id, issue_id, &new, &pending_key);
    assert!(matches!(
        outcome,
        Err(super::daemon_settings::C5TransitionError::MissingSource { session_id }) if session_id == source.id
    ));
    assert!(store.get_issue(issue_id).unwrap().is_none());
    assert!(
        store
            .get_c5_autofile_pending(&pending_key)
            .unwrap()
            .is_some()
    );

    store
        .set_daemon_setting(
            &pending_key,
            &format!(
                r#"{{"version":3,"source_session_id":"{}","cause":"process-died","staged_at":"2026-07-14T00:00:00.000000000Z"}}"#,
                source.id
            ),
        )
        .unwrap();
    let raw = store.get_daemon_setting(&pending_key).unwrap().unwrap();
    assert!(matches!(
        super::daemon_settings::C5AutofilePending::parse(&raw),
        Err(super::daemon_settings::C5JournalError::UnknownVersion(3))
    ));
}

