#[test]
fn c5_retry_successor_admission_is_atomic_and_preserves_parent_marker_on_fault() {
    let store = Store::open_in_memory().unwrap();
    let mut parent = make_test_session();
    parent.status = SessionStatus::Failed;
    parent.retry_attempt = Some(1);
    parent.max_retries = Some(2);
    let mut child = make_test_session();
    child.continued_from = Some(parent.id);
    child.retry_attempt = Some(0);
    child.max_retries = Some(2);
    child.context_window = Some(258_400);
    child.resolved_context_budget = Some(context_budget_fixture(
        258_400,
        CapabilitySource::RuntimeTelemetry,
    ));
    let child_invocation_id = Uuid::new_v4();
    store.insert_session(&parent).unwrap();
    store
        .update_failed_and_stage_c5_autofile(
            parent.id,
            crate::store::daemon_settings::AutofileCause::ProcessDied,
        )
        .unwrap();
    let key = super::daemon_settings::c5_autofile_pending_key(parent.id);

    super::daemon_settings::c5_test_fail_next_commit("retry_admission_commit");
    assert!(matches!(
        store.admit_c5_retry_successor(
            parent.id,
            &child,
            1,
            2,
            child_invocation_id,
            &store.get_c5_autofile_pending(&key).unwrap().unwrap(),
        ),
        Err(super::daemon_settings::C5TransitionError::Retryable { .. })
    ));
    assert_eq!(
        store.get_session(parent.id).unwrap().unwrap().retry_attempt,
        Some(1),
        "failed admission must leave the parent retryable"
    );
    assert!(
        store.get_session(child.id).unwrap().is_none(),
        "failed admission must leave no child row"
    );
    assert!(store.get_c5_autofile_pending(&key).unwrap().is_some());

    store
        .admit_c5_retry_successor(
            parent.id,
            &child,
            1,
            2,
            child_invocation_id,
            &store.get_c5_autofile_pending(&key).unwrap().unwrap(),
        )
        .unwrap();
    assert_eq!(
        store.get_session(parent.id).unwrap().unwrap().retry_attempt,
        Some(2)
    );
    assert_eq!(
        store.get_session(child.id).unwrap().unwrap().retry_attempt,
        Some(1)
    );
    assert_eq!(
        store
            .get_session(child.id)
            .unwrap()
            .unwrap()
            .resolved_context_budget,
        child.resolved_context_budget
    );
    assert_eq!(
        store.session_model_invocation_id(child.id).unwrap(),
        Some(child_invocation_id),
        "retry admission must atomically bind the child's model invocation"
    );
    assert!(store.get_c5_autofile_pending(&key).unwrap().is_none());
}

#[test]
fn c5_retry_admission_child_insert_failure_leaves_parent_owned_retry_for_restart() {
    let store = Store::open_in_memory().unwrap();
    let mut parent = make_test_session();
    parent.status = SessionStatus::Failed;
    parent.retry_attempt = Some(1);
    parent.max_retries = Some(2);
    let mut child = make_test_session();
    child.continued_from = Some(parent.id);
    store.insert_session(&parent).unwrap();
    store
        .update_failed_and_stage_c5_autofile(
            parent.id,
            crate::store::daemon_settings::AutofileCause::ProcessDied,
        )
        .unwrap();
    let key = super::daemon_settings::c5_autofile_pending_key(parent.id);
    store.conn.execute_batch(
        "CREATE TRIGGER c5_fail_retry_child_insert BEFORE INSERT ON sessions
         WHEN NEW.continued_from IS NOT NULL BEGIN SELECT RAISE(ABORT, 'injected-child-insert'); END;",
    ).unwrap();

    assert!(
        store
            .admit_c5_retry_successor(
                parent.id,
                &child,
                1,
                2,
                Uuid::new_v4(),
                &store.get_c5_autofile_pending(&key).unwrap().unwrap(),
            )
            .is_err()
    );
    assert!(store.get_session(child.id).unwrap().is_none());
    let restored_parent = store.get_session(parent.id).unwrap().unwrap();
    assert_eq!(restored_parent.retry_attempt, Some(1));
    assert_eq!(restored_parent.max_retries, Some(2));
    assert!(store.get_c5_autofile_pending(&key).unwrap().is_some());
}

