#[test]
fn c5_retry_admission_user_intent_matrix_has_exactly_one_durable_winner() {
    // Each row executes both legal serializations of the same durable race.
    // This intentionally exercises the exact Store admission predicate rather
    // than relying on scheduler timing: user intent first must reject the
    // child, while a committed successor keeps its child when later intent
    // settles the old parent.
    for intent in [
        "cancel_retry",
        "interrupt_session",
        "agent_halt",
        "continue_session",
        "archive_session",
        "delete_session",
        "purge_session",
    ] {
        let (store, parent, child, marker, key) = c5_retry_admission_fixture();
        match intent {
            "cancel_retry" | "interrupt_session" | "agent_halt" | "continue_session" => {
                assert!(matches!(
                    store
                        .acknowledge_c5_autofile_suppression_and_exhaust_retry(parent.id, 2)
                        .unwrap(),
                    super::daemon_settings::C5SuppressionOutcome::Committed
                ));
            }
            "archive_session" => {
                store
                    .archive_and_resolve_c5_autofile_pending(parent.id)
                    .unwrap();
            }
            "delete_session" => {
                store.resolve_c5_autofile_pending(&key).unwrap();
                store.soft_delete_session(parent.id).unwrap();
            }
            "purge_session" => {
                store.resolve_c5_autofile_pending(&key).unwrap();
                store.purge_session(parent.id).unwrap();
            }
            _ => unreachable!(),
        }
        let rejection = store
            .admit_c5_retry_successor(parent.id, &child, 1, 2, Uuid::new_v4(), &marker)
            .unwrap_err();
        assert!(matches!(
            rejection,
            super::daemon_settings::C5TransitionError::Conflict { .. }
        ));
        assert!(store.get_session(child.id).unwrap().is_none(), "{intent}");
        assert!(
            store.get_c5_autofile_pending(&key).unwrap().is_none(),
            "{intent}"
        );

        let (store, parent, child, marker, key) = c5_retry_admission_fixture();
        store
            .admit_c5_retry_successor(parent.id, &child, 1, 2, Uuid::new_v4(), &marker)
            .unwrap();
        match intent {
            "cancel_retry" | "interrupt_session" | "agent_halt" | "continue_session" => {
                assert!(matches!(
                    store
                        .acknowledge_c5_autofile_suppression_and_exhaust_retry(parent.id, 2)
                        .unwrap(),
                    super::daemon_settings::C5SuppressionOutcome::AlreadyResolved
                ));
            }
            "archive_session" => {
                store
                    .archive_and_resolve_c5_autofile_pending(parent.id)
                    .unwrap();
            }
            "delete_session" => {
                store.resolve_c5_autofile_pending(&key).unwrap();
                store.soft_delete_session(parent.id).unwrap();
            }
            "purge_session" => {
                store.resolve_c5_autofile_pending(&key).unwrap();
                store.purge_session(parent.id).unwrap();
            }
            _ => unreachable!(),
        }
        assert!(store.get_session(child.id).unwrap().is_some(), "{intent}");
        assert!(
            store.get_c5_autofile_pending(&key).unwrap().is_none(),
            "{intent}"
        );
    }
}

#[test]
fn issue_writer_c5_transaction_failures_rollback_stage_event_and_settlement_without_orphans() {
    let store = Store::open_in_memory().unwrap();
    let source = make_test_session();
    store.insert_session(&source).unwrap();
    let key = super::daemon_settings::c5_autofile_pending_key(source.id);

    store
        .conn
        .execute_batch(
            "CREATE TRIGGER c5_fail_stage_marker BEFORE INSERT ON daemon_settings
             WHEN NEW.key LIKE 'c5.autofile.pending.v1/%'
             BEGIN SELECT RAISE(ABORT, 'injected-stage-marker'); END;",
        )
        .unwrap();
    let error = store
        .update_failed_and_stage_c5_autofile(
            source.id,
            crate::store::daemon_settings::AutofileCause::ProcessDied,
        )
        .unwrap_err();
    assert!(matches!(
        error,
        super::daemon_settings::C5TransitionError::Retryable { .. }
    ));
    assert_eq!(
        store.get_session(source.id).unwrap().unwrap().status,
        SessionStatus::Starting
    );
    assert!(store.get_c5_autofile_pending(&key).unwrap().is_none());
    store
        .conn
        .execute_batch("DROP TRIGGER c5_fail_stage_marker")
        .unwrap();

    store
        .update_failed_and_stage_c5_autofile(
            source.id,
            crate::store::daemon_settings::AutofileCause::ProcessDied,
        )
        .unwrap();
    let issue_id = Uuid::new_v5(&Uuid::NAMESPACE_URL, b"c5-delete-rollback");
    let issue = NewIssue {
        project_id: d04_test_project_id(),
        title: "automatic".into(),
        body: "rollback".into(),
        priority: None,
        labels: vec![],
        created_by_session_id: Some(source.id),
        assignee: None,
        idea_id: None,
        source_event_id: None,
        source_finding_ref: None,
    };
    store
        .conn
        .execute_batch(
            "CREATE TRIGGER c5_fail_marker_delete BEFORE DELETE ON daemon_settings
             WHEN OLD.key LIKE 'c5.autofile.pending.v1/%'
             BEGIN SELECT RAISE(ABORT, 'injected-marker-delete'); END;",
        )
        .unwrap();
    let error = store
        .settle_c5_autofile_pending(source.id, issue_id, &issue, &key)
        .unwrap_err();
    assert!(matches!(
        error,
        super::daemon_settings::C5TransitionError::Retryable { .. }
    ));
    assert!(store.get_issue(issue_id).unwrap().is_none());
    assert_eq!(
        store
            .conn
            .query_row("SELECT count(*) FROM issue_events", [], |row| row
                .get::<_, i64>(0))
            .unwrap(),
        0,
        "C5 outer rollback retained an Issue event"
    );
    assert!(store.get_c5_autofile_pending(&key).unwrap().is_some());
}

#[test]
fn c5_transition_faults_rollback_every_durable_boundary() {
    fn assert_retryable(error: super::daemon_settings::C5TransitionError, operation: &str) {
        match error {
            super::daemon_settings::C5TransitionError::Retryable {
                operation: actual, ..
            } => assert_eq!(actual, operation),
            other => panic!("expected retryable {operation}, got {other:?}"),
        }
    }

    let store = Store::open_in_memory().unwrap();
    let source = make_test_session();
    let key = super::daemon_settings::c5_autofile_pending_key(source.id);
    store.insert_session(&source).unwrap();

    // A failed status UPDATE cannot leave a marker behind.
    store
        .conn
        .execute_batch(
            "CREATE TRIGGER c5_fail_status BEFORE UPDATE OF status ON sessions
         WHEN NEW.status = 'Failed' BEGIN SELECT RAISE(ABORT, 'injected-status'); END;",
        )
        .unwrap();
    assert_retryable(
        store
            .update_failed_and_stage_c5_autofile(
                source.id,
                super::daemon_settings::AutofileCause::ProcessDied,
            )
            .unwrap_err(),
        "stage_failed_status",
    );
    assert_eq!(
        store.get_session(source.id).unwrap().unwrap().status,
        SessionStatus::Starting
    );
    assert!(store.get_c5_autofile_pending(&key).unwrap().is_none());
    store
        .conn
        .execute_batch("DROP TRIGGER c5_fail_status")
        .unwrap();

    // A marker INSERT rolls back the preceding Failed transition.
    store
        .conn
        .execute_batch(
            "CREATE TRIGGER c5_fail_marker_insert BEFORE INSERT ON daemon_settings
         WHEN NEW.key LIKE 'c5.autofile.pending.v1/%'
         BEGIN SELECT RAISE(ABORT, 'injected-marker-insert'); END;",
        )
        .unwrap();
    assert_retryable(
        store
            .update_failed_and_stage_c5_autofile(
                source.id,
                super::daemon_settings::AutofileCause::ProcessDied,
            )
            .unwrap_err(),
        "stage_pending_insert",
    );
    assert_eq!(
        store.get_session(source.id).unwrap().unwrap().status,
        SessionStatus::Starting
    );
    assert!(store.get_c5_autofile_pending(&key).unwrap().is_none());
    store
        .conn
        .execute_batch("DROP TRIGGER c5_fail_marker_insert")
        .unwrap();

    store
        .update_failed_and_stage_c5_autofile(
            source.id,
            super::daemon_settings::AutofileCause::ProcessDied,
        )
        .unwrap();
    let issue_id = Uuid::new_v5(&Uuid::NAMESPACE_URL, b"c5-all-fault-boundaries");
    let issue = NewIssue {
        project_id: d04_test_project_id(),
        title: "automatic".into(),
        body: "rollback".into(),
        priority: None,
        labels: vec![],
        created_by_session_id: Some(source.id),
        assignee: None,
        idea_id: None,
        source_event_id: None,
        source_finding_ref: None,
    };

    // The issue select/insert leg rolls its work back with the marker.
    store
        .conn
        .execute_batch(
            "CREATE TRIGGER c5_fail_issue_insert BEFORE INSERT ON issues
         BEGIN SELECT RAISE(ABORT, 'injected-issue-insert'); END;",
        )
        .unwrap();
    assert_retryable(
        store
            .settle_c5_autofile_pending(source.id, issue_id, &issue, &key)
            .unwrap_err(),
        "settlement_issue_insert_or_select",
    );
    assert!(store.get_issue(issue_id).unwrap().is_none());
    assert!(store.get_c5_autofile_pending(&key).unwrap().is_some());
    store
        .conn
        .execute_batch("DROP TRIGGER c5_fail_issue_insert")
        .unwrap();

    // A marker DELETE cannot commit the freshly allocated issue alone.
    store
        .conn
        .execute_batch(
            "CREATE TRIGGER c5_fail_marker_delete BEFORE DELETE ON daemon_settings
         WHEN OLD.key LIKE 'c5.autofile.pending.v1/%'
         BEGIN SELECT RAISE(ABORT, 'injected-marker-delete'); END;",
        )
        .unwrap();
    assert_retryable(
        store
            .settle_c5_autofile_pending(source.id, issue_id, &issue, &key)
            .unwrap_err(),
        "settlement_marker_delete",
    );
    assert!(store.get_issue(issue_id).unwrap().is_none());
    assert!(store.get_c5_autofile_pending(&key).unwrap().is_some());
    store
        .conn
        .execute_batch("DROP TRIGGER c5_fail_marker_delete")
        .unwrap();

    // The narrow test-only seam models `Transaction::commit` failing after
    // the issue and marker statements completed; dropping the transaction
    // must still roll every one of them back.
    super::daemon_settings::c5_test_fail_next_commit("settlement_commit");
    assert_retryable(
        store
            .settle_c5_autofile_pending(source.id, issue_id, &issue, &key)
            .unwrap_err(),
        "settlement_commit",
    );
    assert!(store.get_issue(issue_id).unwrap().is_none());
    assert!(store.get_c5_autofile_pending(&key).unwrap().is_some());
}

#[test]
fn c5_journal_parser_is_strict_and_retains_bad_rows() {
    use super::daemon_settings::{C5AutofilePending, C5JournalError};

    let id = Uuid::new_v4();
    let valid = format!(
        r#"{{"version":1,"source_session_id":"{id}","cause":"process-died","staged_at":"2026-07-14T00:00:00.000000000Z"}}"#
    );
    let cases = vec![
        ("{".to_string(), C5JournalError::MalformedJson),
        (r#"{"version":3,"source_session_id":"00000000-0000-0000-0000-000000000000","cause":"process-died","staged_at":"2026-07-14T00:00:00.000000000Z"}"#.to_string(), C5JournalError::UnknownVersion(3)),
        (r#"{"version":2,"source_session_id":"00000000-0000-0000-0000-000000000000","cause":"process-died","staged_at":"2026-07-14T00:00:00.000000000Z"}"#.to_string(), C5JournalError::InvalidShape),
        (valid.replace("}", ",\"disposition\":\"policy-declined\"}"), C5JournalError::UnknownField("disposition".into())),
        (valid.replace("}", ",\"unexpected\":true}"), C5JournalError::UnknownField("unexpected".into())),
        (valid.replace("process-died", "made-up"), C5JournalError::UnknownCause("made-up".into())),
        (valid.replace(&id.to_string(), "not-a-uuid"), C5JournalError::InvalidSourceSessionId),
        (valid.replace("2026-07-14T00:00:00.000000000Z", "not-a-timestamp"), C5JournalError::InvalidStagedAt),
    ];
    for (raw, expected) in cases {
        assert!(matches!(C5AutofilePending::parse(&raw), Err(actual) if actual == expected));
    }

    let store = Store::open_in_memory().unwrap();
    let key = super::daemon_settings::c5_autofile_pending_key(id);
    store.set_daemon_setting(&key, "{").unwrap();
    assert!(store.get_c5_autofile_pending(&key).is_err());
    assert_eq!(
        store.get_daemon_setting(&key).unwrap().as_deref(),
        Some("{")
    );

    let source = make_test_session();
    store.insert_session(&source).unwrap();
    let mismatch_key = super::daemon_settings::c5_autofile_pending_key(source.id);
    let other_source = Uuid::new_v4();
    let mismatch = format!(
        r#"{{"version":1,"source_session_id":"{other_source}","cause":"process-died","staged_at":"2026-07-14T00:00:00.000000000Z"}}"#
    );
    store.set_daemon_setting(&mismatch_key, &mismatch).unwrap();
    let issue = NewIssue {
        project_id: d04_test_project_id(),
        title: "must not settle".into(),
        body: String::new(),
        priority: None,
        labels: vec![],
        created_by_session_id: Some(source.id),
        assignee: None,
        idea_id: None,
        source_event_id: None,
        source_finding_ref: None,
    };
    assert!(matches!(
        store.settle_c5_autofile_pending(source.id, Uuid::new_v4(), &issue, &mismatch_key),
        Err(super::daemon_settings::C5TransitionError::Conflict { operation: "settlement_pending_source", session_id }) if session_id == source.id
    ));
    assert_eq!(
        store.get_daemon_setting(&mismatch_key).unwrap().as_deref(),
        Some(mismatch.as_str())
    );
}

#[test]
fn c5_pending_list_is_key_ordered_and_bounded_to_64() {
    let store = Store::open_in_memory().unwrap();
    for value in 0..65_u128 {
        let id = Uuid::from_u128(value + 1);
        let key = super::daemon_settings::c5_autofile_pending_key(id);
        store.set_daemon_setting(&key, "{}").unwrap();
    }
    let batch = store.list_c5_autofile_pending(None, 999).unwrap();
    assert_eq!(
        batch.len(),
        super::daemon_settings::C5_AUTOFILE_PENDING_BATCH_SIZE
    );
    assert!(batch.windows(2).all(|pair| pair[0].0 < pair[1].0));
    assert!(
        batch
            .iter()
            .all(|(key, _)| key.starts_with(super::daemon_settings::C5_AUTOFILE_PENDING_PREFIX))
    );
}

#[test]
fn c5_concurrent_suppression_and_settlement_have_one_legal_winner() {
    use std::sync::{Arc, Barrier};

    let directory = tempfile::TempDir::new().unwrap();
    let db_path = directory.path().join("c5-concurrent.sqlite");
    let store = Store::open(&db_path).unwrap();
    let mut project = make_test_project("D04 concurrent project");
    project.id = d04_test_project_id();
    store.insert_project(&project).unwrap();
    let source = make_test_session();
    let key = super::daemon_settings::c5_autofile_pending_key(source.id);
    store.insert_session(&source).unwrap();
    store
        .update_failed_and_stage_c5_autofile(
            source.id,
            super::daemon_settings::AutofileCause::ProcessDied,
        )
        .unwrap();
    store
        .conn
        .execute_batch("PRAGMA wal_checkpoint(TRUNCATE);")
        .unwrap();
    drop(store);

    // Both stores are opened on the main thread, BEFORE either worker is
    // spawned. Nothing fallible may sit between `thread::spawn` and
    // `barrier.wait()`: a panic there leaves the partner blocked on a barrier
    // that can never be released, which turns any failure into an infinite
    // hang instead of a test failure. The contention under test is
    // settlement-vs-suppression after the barrier, which is untouched by this.
    let settle_store = Store::open(&db_path).unwrap();
    let suppress_store = Store::open(&db_path).unwrap();

    let barrier = Arc::new(Barrier::new(2));
    let settle_barrier = Arc::clone(&barrier);
    let settle_source = source.id;
    let settle_key = key.clone();
    let settle = std::thread::spawn(move || {
        let issue_id = Uuid::new_v5(&Uuid::NAMESPACE_URL, b"c5-concurrent-settlement");
        let issue = NewIssue {
            project_id: d04_test_project_id(),
            title: "automatic".into(),
            body: "concurrent".into(),
            priority: None,
            labels: vec![],
            created_by_session_id: Some(settle_source),
            assignee: None,
            idea_id: None,
            source_event_id: None,
            source_finding_ref: None,
        };
        let store = settle_store;
        settle_barrier.wait();
        for _ in 0..20 {
            match store.settle_c5_autofile_pending(settle_source, issue_id, &issue, &settle_key) {
                Err(super::daemon_settings::C5TransitionError::Retryable { .. }) => {
                    std::thread::yield_now()
                }
                outcome => return outcome,
            }
        }
        panic!("settlement did not escape SQLite contention")
    });
    let suppress_barrier = Arc::clone(&barrier);
    let suppress_source = source.id;
    let suppress = std::thread::spawn(move || {
        let store = suppress_store;
        suppress_barrier.wait();
        for _ in 0..20 {
            match store.acknowledge_c5_autofile_suppression_and_exhaust_retry(suppress_source, 2) {
                Err(super::daemon_settings::C5TransitionError::Retryable { .. }) => {
                    std::thread::yield_now()
                }
                outcome => return outcome,
            }
        }
        panic!("suppression did not escape SQLite contention")
    });

    let settlement = settle.join().unwrap().unwrap();
    let suppression = suppress.join().unwrap().unwrap();
    let store = Store::open(&db_path).unwrap();
    let issue_count = store.list_issues(&Default::default()).unwrap().len();
    assert!(store.get_c5_autofile_pending(&key).unwrap().is_none());
    match (settlement, suppression, issue_count) {
        (
            super::C5SettlementOutcome::Committed { .. },
            super::daemon_settings::C5SuppressionOutcome::AlreadyResolved,
            1,
        )
        | (
            super::C5SettlementOutcome::StaleMarker,
            super::daemon_settings::C5SuppressionOutcome::Committed,
            0,
        ) => {}
        other => panic!("illegal C5 race outcome: {other:?}"),
    }

    // A later replay sees the resolved marker and cannot manufacture an issue.
    let issue_id = Uuid::new_v5(&Uuid::NAMESPACE_URL, b"c5-concurrent-settlement");
    let issue = NewIssue {
        project_id: d04_test_project_id(),
        title: "automatic".into(),
        body: "concurrent".into(),
        priority: None,
        labels: vec![],
        created_by_session_id: Some(source.id),
        assignee: None,
        idea_id: None,
        source_event_id: None,
        source_finding_ref: None,
    };
    assert!(matches!(
        store
            .settle_c5_autofile_pending(source.id, issue_id, &issue, &key)
            .unwrap(),
        super::C5SettlementOutcome::StaleMarker
    ));
    assert_eq!(
        store.list_issues(&Default::default()).unwrap().len(),
        issue_count
    );
}

/// Regression for the `DatabaseBusy` flake that made the C5 concurrency test
/// above nondeterministic. `Store::open()` runs `repair_v73_model_control_schema`
/// unconditionally — outside every `if version < N` gate — and its first
/// statement is a read (`pragma_table_info`) followed by DDL writes. Under a
/// DEFERRED transaction that read -> write upgrade raises SQLITE_BUSY_SNAPSHOT
/// (extended code 517), for which SQLite deliberately does NOT invoke the busy
/// handler, so `PRAGMA busy_timeout=10000` was inert and two concurrent opens
/// of the same database failed instantly. The repair now begins IMMEDIATE,
/// which takes the write lock up front and does honor busy_timeout.
#[test]
fn concurrent_store_open_never_returns_database_busy() {
    use std::sync::{Arc, Barrier};

    let directory = tempfile::TempDir::new().unwrap();
    let db_path = directory.path().join("concurrent-open.sqlite");
    // Materialize the schema once so every racing opener takes the
    // already-migrated path — the one that still runs the V73 repair.
    drop(Store::open(&db_path).unwrap());

    const OPENERS: usize = 8;
    let barrier = Arc::new(Barrier::new(OPENERS));
    let handles: Vec<_> = (0..OPENERS)
        .map(|_| {
            let path = db_path.clone();
            let gate = Arc::clone(&barrier);
            std::thread::spawn(move || {
                // The barrier is released before the fallible work, so a
                // failing opener can never strand its partners on the gate.
                gate.wait();
                Store::open(&path).map(|_| ()).map_err(|e| e.to_string())
            })
        })
        .collect();

    let failures: Vec<String> = handles
        .into_iter()
        .map(|handle| handle.join().expect("opener thread panicked"))
        .filter_map(|opened| opened.err())
        .collect();
    assert!(
        failures.is_empty(),
        "concurrent Store::open must not fail: {failures:?}"
    );
}

struct D01PriorVersionFixture {
    directory: tempfile::TempDir,
    prior_path: PathBuf,
    upgrade_path: PathBuf,
    rollback_path: PathBuf,
    legacy_fingerprints: Vec<(String, String)>,
    prior_schema_fingerprint: String,
}

fn query_fingerprint(connection: &Connection, sql: &str) -> anyhow::Result<String> {
    use rusqlite::types::ValueRef;
    use sha2::{Digest, Sha256};

    let mut statement = connection.prepare(sql).context("D01 test operation")?;
    let column_count = statement.column_count();
    let mut rows = statement.query([]).context("D01 test operation")?;
    let mut hasher = Sha256::new();
    while let Some(row) = rows.next().context("D01 test operation")? {
        for index in 0..column_count {
            match row.get_ref(index).context("D01 test operation")? {
                ValueRef::Null => hasher.update(b"N"),
                ValueRef::Integer(value) => {
                    hasher.update(b"I");
                    hasher.update(value.to_be_bytes());
                }
                ValueRef::Real(value) => {
                    hasher.update(b"R");
                    hasher.update(value.to_bits().to_be_bytes());
                }
                ValueRef::Text(value) => {
                    hasher.update(b"T");
                    hasher.update((value.len() as u64).to_be_bytes());
                    hasher.update(value);
                }
                ValueRef::Blob(value) => {
                    hasher.update(b"B");
                    hasher.update((value.len() as u64).to_be_bytes());
                    hasher.update(value);
                }
            }
        }
        hasher.update(b"\n");
    }
    Ok(format!("{:x}", hasher.finalize()))
}

#[derive(Debug, PartialEq, Eq)]
struct V89DatabaseSnapshot {
    user_version: i32,
    catalog: String,
    tables: Vec<(String, String)>,
}

fn v89_database_snapshot(connection: &Connection) -> anyhow::Result<V89DatabaseSnapshot> {
    let user_version = connection.query_row("PRAGMA user_version", [], |row| row.get(0))?;
    let catalog = query_fingerprint(
        connection,
        "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master
         ORDER BY type,name,tbl_name,coalesce(sql,'')",
    )?;
    let table_names = connection
        .prepare("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")?
        .query_map([], |row| row.get::<_, String>(0))?
        .collect::<rusqlite::Result<Vec<_>>>()?;
    let mut tables = Vec::with_capacity(table_names.len());
    for table in table_names {
        let columns = connection
            .prepare("SELECT name FROM pragma_table_info(?1) ORDER BY cid")?
            .query_map([&table], |row| row.get::<_, String>(0))?
            .collect::<rusqlite::Result<Vec<_>>>()?;
        let quoted_table = format!("\"{}\"", table.replace('"', "\"\""));
        let fingerprint = if columns.is_empty() {
            query_fingerprint(connection, &format!("SELECT count(*) FROM {quoted_table}"))?
        } else {
            let projection = columns
                .iter()
                .map(|column| format!("\"{}\"", column.replace('"', "\"\"")))
                .collect::<Vec<_>>()
                .join(",");
            query_fingerprint(
                connection,
                &format!("SELECT {projection} FROM {quoted_table} ORDER BY {projection}"),
            )?
        };
        tables.push((table, fingerprint));
    }
    Ok(V89DatabaseSnapshot {
        user_version,
        catalog,
        tables,
    })
}

fn assert_no_v89_capacity_objects(connection: &Connection) {
    for name in V89_TABLES
        .iter()
        .chain(V89_INDEXES.iter())
        .chain(V89_TRIGGERS.iter())
    {
        assert_eq!(
            connection
                .query_row(
                    "SELECT count(*) FROM sqlite_master WHERE name=?1",
                    [*name],
                    |row| row.get::<_, i64>(0),
                )
                .unwrap(),
            0,
            "refused V89 source must not create {name}"
        );
    }
}

fn table_fingerprint(connection: &Connection, table: &str) -> anyhow::Result<String> {
    let columns: Vec<String> = connection
        .prepare(&format!("PRAGMA table_info(\"{table}\")"))
        .context("D01 test operation")?
        .query_map([], |row| row.get(1))
        .context("D01 test operation")?
        .collect::<rusqlite::Result<_>>()
        .context("D01 test operation")?;
    let projection = columns
        .iter()
        .map(|column| format!("\"{}\"", column.replace('"', "\"\"")))
        .collect::<Vec<_>>()
        .join(", ");
    query_fingerprint(
        connection,
        &format!("SELECT {projection} FROM \"{table}\" ORDER BY 1"),
    )
}

#[derive(Debug, PartialEq, Eq)]
struct D04DatabaseSnapshot {
    version: i32,
    catalog: String,
    issues: String,
    issue_deps: String,
}

fn d04_all_column_table_fingerprint(
    connection: &Connection,
    table: &str,
) -> anyhow::Result<String> {
    let columns: Vec<String> = connection
        .prepare(&format!("PRAGMA table_info(\"{table}\")"))
        .context("D04 read table columns")?
        .query_map([], |row| row.get(1))
        .context("D04 read table columns")?
        .collect::<rusqlite::Result<_>>()
        .context("D04 read table columns")?;
    assert!(
        !columns.is_empty(),
        "D04 snapshot requires an existing {table} table"
    );
    let quoted_columns = columns
        .iter()
        .map(|column| format!("\"{}\"", column.replace('\"', "\"\"")))
        .collect::<Vec<_>>()
        .join(", ");
    // Project every legacy column and order by every projected column. The
    // type/null-aware query_fingerprint encoding then makes same-count field
    // corruption observable, including values whose textual display matches.
    query_fingerprint(
        connection,
        &format!("SELECT {quoted_columns} FROM \"{table}\" ORDER BY {quoted_columns}"),
    )
}

fn d04_database_snapshot(connection: &Connection) -> anyhow::Result<D04DatabaseSnapshot> {
    assert_d01_foreign_key_check(connection)?;
    assert_eq!(
        connection.query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0))?,
        "ok",
        "D04 snapshot requires PRAGMA integrity_check to return exactly ok"
    );
    Ok(D04DatabaseSnapshot {
        version: connection.query_row("PRAGMA user_version", [], |row| row.get(0))?,
        catalog: d01_schema_fingerprint(connection)?,
        issues: d04_all_column_table_fingerprint(connection, "issues")?,
        issue_deps: d04_all_column_table_fingerprint(connection, "issue_deps")?,
    })
}

fn d01_schema_fingerprint(connection: &Connection) -> anyhow::Result<String> {
    query_fingerprint(
        connection,
        "SELECT type, name, tbl_name, COALESCE(sql, '')
         FROM sqlite_master
         ORDER BY type, name, tbl_name",
    )
}

fn d01_legacy_fingerprints(connection: &Connection) -> anyhow::Result<Vec<(String, String)>> {
    [
        "projects",
        "sessions",
        "workflows",
        "session_groups",
        "session_tags",
    ]
    .into_iter()
    .map(|table| {
        let fingerprint = if table == "sessions" {
            let columns: Vec<String> = connection
                .prepare("SELECT name FROM pragma_table_info('sessions') ORDER BY cid")?
                .query_map([], |row| row.get(0))?
                .collect::<rusqlite::Result<_>>()?;
            let projection = columns
                .iter()
                // These are post-D01 SQL-only links or provenance columns. A
                // copied V74 source cannot carry them, while forward migrations
                // must add them. Hash the durable legacy payload, not the
                // deliberately different schema envelopes.
                .filter(|column| {
                    !matches!(
                        column.as_str(),
                        "sandbox_custody_id"
                            | "execution_origin_claim_id"
                            | "execution_origin_write_seq"
                            | "agent_role"
                            | "epic_spawn_ordinal"
                            | "context_window_source"
                            | "context_window_source_version"
                            | "context_window_source_digest"
                            | "context_window_observed_at"
                            | "context_window_configured_tokens"
                            // V99 provider telemetry: same class as the links
                            // above. A copied legacy source cannot carry these
                            // and the forward migration must add them, so they
                            // are schema envelope rather than seeded payload.
                            | "provider_cli_version"
                            | "provider_capabilities"
                            | "thinking_tokens"
                            | "service_tier"
                            | "cache_creation_1h_tokens"
                            | "cache_creation_5m_tokens"
                            | "permission_denial_count"
                            | "subagent_stats_json"
                            | "queued_turn_count"
                            | "terminal_reason"
                    )
                })
                .map(|column| format!("\"{}\"", column.replace('"', "\"\"")))
                .collect::<Vec<_>>()
                .join(", ");
            query_fingerprint(
                connection,
                &format!("SELECT {projection} FROM sessions ORDER BY id"),
            )?
        } else {
            table_fingerprint(connection, table)?
        };
        Ok((table.to_string(), fingerprint))
    })
    .collect()
}

fn populate_d01_prior_version_store(store: &Store) -> anyhow::Result<()> {
    let project = make_test_project("D01 copied prior-version fixture");
    store
        .insert_project(&project)
        .context("D01 test operation")?;

    let now = chrono::Utc::now();
    let workflow = Workflow {
        id: Uuid::new_v4(),
        title: "Legacy topology workflow".to_string(),
        stage: WorkflowStage::Research,
        artifact_path: Some("thoughts/legacy.md".to_string()),
        project_id: Some(project.id),
        created_at: now,
        updated_at: now,
    };
    store
        .insert_workflow(&workflow)
        .context("D01 test operation")?;
    let label = SessionLabel {
        id: Uuid::new_v4(),
        name: "legacy-label".to_string(),
        description: Some("D01 must not reinterpret this label".to_string()),
        project_id: Some(project.id),
        color: SessionLabel::DEFAULT_COLOR.to_string(),
        created_at: now,
        updated_at: now,
    };
    store.insert_label(&label).context("D01 test operation")?;

    let mut standard = make_test_session();
    standard.project_id = Some(project.id);
    standard.group_id = Some(label.id);
    standard.workflow_id = Some(workflow.id);
    standard.topology_node_id = Some("legacy-root".to_string());
    store
        .insert_session(&standard)
        .context("D01 test operation")?;

    let mut group = make_test_session();
    group.id = Uuid::new_v4();
    group.project_id = Some(project.id);
    group.group_id = Some(label.id);
    group.session_kind = SessionKind::Group;
    group.title = Some("Legacy Group".to_string());
    store.insert_session(&group).context("D01 test operation")?;

    let mut epic = make_test_session();
    epic.id = Uuid::new_v4();
    epic.project_id = Some(project.id);
    epic.group_id = Some(label.id);
    epic.session_kind = SessionKind::Epic;
    epic.parent_id = Some(group.id);
    epic.workflow_id = Some(workflow.id);
    epic.topology_node_id = Some("legacy-epic".to_string());
    store.insert_session(&epic).context("D01 test operation")?;

    // V99 validates rotation ancestry within one owning Epic. Keep this
    // copied legacy pointer meaningful by making its predecessor a sibling
    // direct child rather than an impossible root-level predecessor.
    store
        .update_session_parent(standard.id, Some(epic.id))
        .context("D01 test operation")?;

    let mut child = make_test_session();
    child.id = Uuid::new_v4();
    child.project_id = Some(project.id);
    child.group_id = Some(label.id);
    child.parent_id = Some(epic.id);
    child.continued_from = Some(standard.id);
    child.workflow_id = Some(workflow.id);
    child.topology_node_id = Some("legacy-child".to_string());
    store.insert_session(&child).context("D01 test operation")?;

    store
        .conn
        .execute(
            "UPDATE sessions
             SET lead_session_id = ?1
             WHERE id = ?2",
            rusqlite::params![child.id.to_string(), epic.id.to_string()],
        )
        .context("D01 test operation")?;
    assert!(
        store
            .get_session(epic.id)
            .context("D01 test operation")?
            .context("D01 test operation")?
            .workflow_id_override
            .is_none(),
        "workflow_id_override is runtime-only on this exact base"
    );
    store
        .conn
        .execute(
            "UPDATE sessions SET tag = 'd01-legacy' WHERE id = ?1",
            [child.id.to_string()],
        )
        .context("D01 test operation")?;
    store
        .conn
        .execute(
            "INSERT INTO session_tags(session_id, tag) VALUES (?1, 'd01-legacy')",
            [child.id.to_string()],
        )
        .context("D01 test operation")?;
    Ok(())
}

fn d01_prior_version_fixture() -> anyhow::Result<D01PriorVersionFixture> {
    let directory = tempfile::TempDir::new().context("D01 test operation")?;
    let prior_path = directory.path().join("prior-v74.db");
    let upgrade_path = directory.path().join("upgrade.db");
    let rollback_path = directory.path().join("rollback.db");
    let store = Store::open(&prior_path).context("D01 test operation")?;
    populate_d01_prior_version_store(&store)?;

    // Settle the exact-base V73 repair path before taking the prior-version
    // fingerprint so this fixture measures only the V75 candidate migration.
    store
        .conn
        .execute_batch("PRAGMA wal_checkpoint(TRUNCATE);")
        .context("D01 test operation")?;
    drop(store);
    let store = Store::open(&prior_path).context("D01 test operation")?;
    // Rewind every non-idempotent schema tail through the one maintained
    // fixture path before claiming this database is a V74 source.  Hand-
    // removing only the D01/D05 relations left V85/V86's SQL-only Session
    // columns behind and produced an impossible hybrid fixture.
    rewind_store_to_schema_version(&store.conn, 76);

    store
        .conn
        .execute_batch(
            "
            DROP TABLE idea_compatibility_mappings;
            DROP TABLE idea_collection_memberships;
            DROP TABLE idea_collections;
            DROP TABLE idea_relationships;
            DROP TABLE idea_events;
            DROP TABLE ideas;
            DROP TABLE captures;
            PRAGMA user_version = 74;
            ",
        )
        .context("D01 test operation")?;
    let legacy_fingerprints = d01_legacy_fingerprints(&store.conn)?;
    let prior_schema_fingerprint = d01_schema_fingerprint(&store.conn)?;
    store
        .conn
        .execute_batch("PRAGMA wal_checkpoint(TRUNCATE);")
        .context("D01 test operation")?;
    drop(store);

    std::fs::copy(&prior_path, &upgrade_path).context("D01 test operation")?;
    std::fs::copy(&prior_path, &rollback_path).context("D01 test operation")?;
    assert_eq!(
        std::fs::read(&prior_path).context("D01 test operation")?,
        std::fs::read(&rollback_path).context("D01 test operation")?,
        "rollback copy must begin byte-for-byte identical to the prior-version fixture"
    );

    Ok(D01PriorVersionFixture {
        directory,
        prior_path,
        upgrade_path,
        rollback_path,
        legacy_fingerprints,
        prior_schema_fingerprint,
    })
}

