fn assert_d01_partial_spans_rejected(fixture: &D01KernelFixture) {
    let digest = format!("sha256:{}", "9".repeat(64));
    let partial_spans = [
        (Some(0), None, None),
        (None, Some(8), None),
        (None, None, Some(digest.as_str())),
        (Some(0), Some(8), None),
        (Some(0), None, Some(digest.as_str())),
        (None, Some(8), Some(digest.as_str())),
    ];
    for (index, (start, end, span_digest)) in partial_spans.into_iter().enumerate() {
        assert!(
            insert_d01_span_variant(fixture, index, start, end, span_digest).is_err(),
            "database admitted partial genesis span combination {index}"
        );
    }
}

fn assert_d01_idea_text_byte_bounds(fixture: &D01KernelFixture) -> anyhow::Result<()> {
    let mut idea = fixture.idea_a1.clone();
    idea.slug = "é".repeat(64);
    idea.sigil = Some("é".repeat(32));
    idea.title = "é".repeat(256);
    idea.description = "é".repeat(32_768);
    idea.portfolio_summary = "é".repeat(1_024);
    idea.validate().map_err(anyhow::Error::msg)?;
    fixture.store.conn.execute(
        "UPDATE ideas
         SET slug = ?1, sigil = ?2, title = ?3, description = ?4, portfolio_summary = ?5
         WHERE id = ?6",
        rusqlite::params![
            idea.slug,
            idea.sigil,
            idea.title,
            idea.description,
            idea.portfolio_summary,
            idea.id.to_string(),
        ],
    )?;
    for (column, value) in [
        ("slug", "é".repeat(65)),
        ("sigil", "é".repeat(33)),
        ("title", "é".repeat(257)),
        ("description", "é".repeat(32_769)),
        ("portfolio_summary", "é".repeat(1_025)),
    ] {
        assert!(
            fixture
                .store
                .conn
                .execute(
                    &format!("UPDATE ideas SET {column} = ?1 WHERE id = ?2"),
                    rusqlite::params![value, fixture.idea_a1.id.to_string()],
                )
                .is_err(),
            "database measured {column} in characters instead of UTF-8 bytes"
        );
    }
    assert!(
        fixture
            .store
            .conn
            .execute(
                "UPDATE ideas SET sigil = ' ' WHERE id = ?1",
                [fixture.idea_a1.id.to_string()],
            )
            .is_err()
    );
    Ok(())
}

fn d01_kernel_fixture() -> anyhow::Result<D01KernelFixture> {
    let store = Store::open_in_memory()?;
    let project_a = make_test_project("D01 project A");
    let project_b = make_test_project("D01 project B");
    let project_without_idea = make_test_project("D01 legacy project behavior");
    store.insert_project(&project_a)?;
    store.insert_project(&project_b)?;
    store.insert_project(&project_without_idea)?;

    let mut protected_session = make_test_session();
    protected_session.project_id = Some(project_a.id);
    store.insert_session(&protected_session)?;
    let mut ordinary_session = make_test_session();
    ordinary_session.id = Uuid::new_v4();
    ordinary_session.project_id = Some(project_without_idea.id);
    store.insert_session(&ordinary_session)?;

    let (capture_a1, idea_a1) = d01_capture_and_idea(project_a.id, "a-one", '1')?;
    let (capture_a2, idea_a2) = d01_capture_and_idea(project_a.id, "a-two", '2')?;
    let (capture_b, idea_b) = d01_capture_and_idea(project_b.id, "b-one", '3')?;
    store.insert_d01_idea_fixture(&capture_a1, &idea_a1)?;
    store.insert_d01_idea_fixture(&capture_a2, &idea_a2)?;
    store.insert_d01_idea_fixture(&capture_b, &idea_b)?;
    let snapshot = store
        .get_idea_with_genesis(idea_a1.id)?
        .context("D01 fixture Idea missing")?;
    assert_eq!(snapshot.idea, idea_a1);
    assert_eq!(snapshot.genesis, capture_a1);

    let (extra_capture_b, mut cross_project_idea) =
        d01_capture_and_idea(project_b.id, "cross-project-genesis", '8')?;
    cross_project_idea.project_id = project_a.id;
    assert!(
        store
            .insert_d01_idea_fixture(&extra_capture_b, &cross_project_idea)
            .is_err(),
        "composite Capture ownership FK must reject cross-project genesis"
    );

    let fixture = D01KernelFixture {
        store,
        project_a,
        project_b,
        project_without_idea,
        protected_session,
        ordinary_session,
        capture_a1,
        capture_a2,
        idea_a1,
        idea_a2,
        idea_b,
    };
    assert_d01_partial_spans_rejected(&fixture);
    assert_d01_idea_text_byte_bounds(&fixture)?;
    Ok(fixture)
}

fn d01_event(fixture: &D01KernelFixture, sequence: i64) -> anyhow::Result<IdeaEvent> {
    let digest = Sha256Digest::parse(format!("sha256:{}", sequence.to_string().repeat(64)))
        .map_err(anyhow::Error::msg)?;
    Ok(IdeaEvent {
        id: Uuid::new_v4(),
        project_id: fixture.project_a.id,
        idea_id: fixture.idea_a1.id,
        sequence,
        event_type: if sequence == 1 {
            IdeaEventType::Created
        } else {
            IdeaEventType::RelationshipChanged
        },
        actor_kind: IdeaActorKind::System,
        actor_id: "d01-test".to_string(),
        controller_session_id: None,
        controller_epoch: None,
        expected_row_version: 0,
        resulting_row_version: 0,
        idempotency_key: format!("a-one:event:{sequence}"),
        occurred_at: chrono::Utc::now(),
        payload: serde_json::json!({"kind": "fixture"}),
        artifact_digests: vec![digest.clone()],
        evidence_digests: vec![digest],
    })
}

fn insert_and_verify_d01_events(fixture: &D01KernelFixture) -> anyhow::Result<[IdeaEvent; 3]> {
    let created = d01_event(fixture, 1)?;
    fixture.store.insert_d01_event_fixture(&created)?;
    let mapped = fixture
        .store
        .conn
        .query_row(
            &format!("SELECT {IDEA_EVENT_COLUMNS} FROM idea_events WHERE id = ?1"),
            [created.id.to_string()],
            map_idea_event_row,
        )?
        .into_idea_event()?;
    assert_eq!(mapped, created);

    let mut cross_project = d01_event(fixture, 2)?;
    cross_project.project_id = fixture.project_b.id;
    assert!(
        fixture
            .store
            .insert_d01_event_fixture(&cross_project)
            .is_err()
    );
    let removal = d01_event(fixture, 2)?;
    let replacement = d01_event(fixture, 3)?;
    fixture.store.insert_d01_event_fixture(&removal)?;
    fixture.store.insert_d01_event_fixture(&replacement)?;
    Ok([created, removal, replacement])
}

fn insert_and_verify_d01_relationships(
    fixture: &D01KernelFixture,
    events: &[IdeaEvent; 3],
) -> anyhow::Result<IdeaRelationship> {
    let relationship = IdeaRelationship {
        id: Uuid::new_v4(),
        project_id: fixture.project_a.id,
        source_idea_id: fixture.idea_a1.id,
        target_idea_id: fixture.idea_a2.id,
        kind: IdeaRelationshipKind::DependsOn,
        created_event_id: events[0].id,
        created_at: chrono::Utc::now(),
        removed_event_id: None,
        removed_at: None,
    };
    fixture
        .store
        .insert_d01_relationship_fixture(&relationship)?;
    let mapped = fixture
        .store
        .conn
        .query_row(
            &format!(
                "SELECT {IDEA_RELATIONSHIP_COLUMNS}
                 FROM idea_relationships WHERE id = ?1"
            ),
            [relationship.id.to_string()],
            map_idea_relationship_row,
        )?
        .into_idea_relationship()?;
    assert_eq!(mapped, relationship);

    let mut cross_project = relationship.clone();
    cross_project.id = Uuid::new_v4();
    cross_project.target_idea_id = fixture.idea_b.id;
    assert!(
        fixture
            .store
            .insert_d01_relationship_fixture(&cross_project)
            .is_err()
    );

    let removed_at = chrono::Utc::now();
    let removed_at_text = removed_at.to_rfc3339_opts(chrono::SecondsFormat::Nanos, true);
    fixture.store.conn.execute(
        "UPDATE idea_relationships
         SET removed_event_id = ?1, removed_at = ?2 WHERE id = ?3",
        rusqlite::params![
            events[1].id.to_string(),
            removed_at_text,
            relationship.id.to_string(),
        ],
    )?;
    assert!(
        fixture
            .store
            .conn
            .execute(
                "UPDATE idea_relationships
                 SET removed_event_id = NULL, removed_at = NULL WHERE id = ?1",
                [relationship.id.to_string()],
            )
            .is_err(),
        "relationship tombstone was reactivated"
    );
    assert!(
        fixture
            .store
            .conn
            .execute(
                "UPDATE idea_relationships SET removed_event_id = ?1, removed_at = ?2
                 WHERE id = ?3",
                rusqlite::params![
                    events[2].id.to_string(),
                    (removed_at + chrono::Duration::seconds(1))
                        .to_rfc3339_opts(chrono::SecondsFormat::Nanos, true),
                    relationship.id.to_string(),
                ],
            )
            .is_err(),
        "relationship removal evidence was rewritten"
    );
    let readded = IdeaRelationship {
        id: Uuid::new_v4(),
        created_event_id: events[2].id,
        created_at: chrono::Utc::now(),
        ..relationship
    };
    fixture.store.insert_d01_relationship_fixture(&readded)?;
    assert_eq!(
        fixture.store.conn.query_row(
            "SELECT COUNT(*) FROM idea_relationships
             WHERE source_idea_id = ?1 AND target_idea_id = ?2 AND kind = ?3",
            rusqlite::params![
                readded.source_idea_id.to_string(),
                readded.target_idea_id.to_string(),
                readded.kind.as_str(),
            ],
            |row| row.get::<_, i64>(0),
        )?,
        2,
        "relationship remove/re-add must preserve history"
    );
    Ok(readded)
}

