fn context_budget_fixture(active_tokens: u64, source: CapabilitySource) -> ResolvedContextBudget {
    let confidence = match source {
        CapabilitySource::RuntimeTelemetry | CapabilitySource::Configured => {
            CapabilityConfidence::Authoritative
        }
        CapabilitySource::OfficialDocumentation | CapabilitySource::ProviderCatalog => {
            CapabilityConfidence::Verified
        }
        CapabilitySource::RepositoryFallback | CapabilitySource::LegacyUnverified => {
            CapabilityConfidence::Degraded
        }
    };
    let has_attributed_source = source != CapabilitySource::LegacyUnverified;
    ResolvedContextBudget {
        active_tokens,
        capacity: ContextCapacity::default(),
        evidence: CapabilityEvidence {
            source,
            source_version: has_attributed_source.then(|| "codex-cli 0.155.1".to_string()),
            source_digest: has_attributed_source.then(|| format!("sha256:{}", "c".repeat(64))),
            observed_at: has_attributed_source.then(|| {
                "2026-09-02T12:34:56.123456789Z"
                    .parse()
                    .expect("fixed provenance timestamp")
            }),
            confidence,
        },
    }
}

#[test]
fn v100_forward_migration_preserves_windows_backfills_legacy_and_reopens() {
    let directory = tempfile::tempdir().expect("create V100 migration fixture directory");
    let database = directory.path().join("v100-context-provenance.sqlite");
    let store = Store::open(&database).expect("create V100 migration fixture");
    rewind_store_to_schema_version(&store.conn, 98);

    let mut legacy = make_test_session();
    legacy.context_window = Some(258_400);
    let mut empty = make_test_session();
    empty.id = Uuid::new_v4();
    empty.context_window = None;
    assert!(
        store.insert_session(&legacy).is_err(),
        "production insert must refuse an exact V98 catalog"
    );
    super::sessions::insert_pre_v99_session_on(&store.conn, &legacy)
        .expect("insert deployed V98 row with a context window");
    super::sessions::insert_pre_v99_session_on(&store.conn, &empty)
        .expect("insert deployed V98 row without a context window");

    let stored_window = |connection: &Connection, id: Uuid| {
        connection
            .query_row(
                "SELECT typeof(context_window), quote(context_window) FROM sessions WHERE id=?1",
                [id.to_string()],
                |row| Ok((row.get::<_, String>(0)?, row.get::<_, String>(1)?)),
            )
            .expect("fingerprint stored context window")
    };
    let legacy_before = stored_window(&store.conn, legacy.id);
    let empty_before = stored_window(&store.conn, empty.id);

    store
        .init_schema()
        .expect("migrate exact V98 fixture through the current schema head");
    assert_eq!(
        store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        LATEST_SCHEMA_VERSION
    );
    assert_eq!(stored_window(&store.conn, legacy.id), legacy_before);
    assert_eq!(stored_window(&store.conn, empty.id), empty_before);
    assert_eq!(
        store
            .conn
            .query_row(
                "SELECT context_window_source, context_window_source_version,
                        context_window_source_digest, context_window_observed_at
                   FROM sessions WHERE id=?1",
                [legacy.id.to_string()],
                |row| {
                    Ok((
                        row.get::<_, Option<String>>(0)?,
                        row.get::<_, Option<String>>(1)?,
                        row.get::<_, Option<String>>(2)?,
                        row.get::<_, Option<String>>(3)?,
                    ))
                },
            )
            .unwrap(),
        (Some("legacy_unverified".to_string()), None, None, None)
    );
    assert_eq!(
        store
            .conn
            .query_row(
                "SELECT context_window_source, context_window_source_version,
                        context_window_source_digest, context_window_observed_at
                   FROM sessions WHERE id=?1",
                [empty.id.to_string()],
                |row| {
                    Ok((
                        row.get::<_, Option<String>>(0)?,
                        row.get::<_, Option<String>>(1)?,
                        row.get::<_, Option<String>>(2)?,
                        row.get::<_, Option<String>>(3)?,
                    ))
                },
            )
            .unwrap(),
        (None, None, None, None)
    );
    let loaded_legacy = store.get_session(legacy.id).unwrap().unwrap();
    assert_eq!(loaded_legacy.context_window, Some(258_400));
    let loaded_budget = loaded_legacy
        .resolved_context_budget
        .expect("legacy window receives explicit degraded evidence");
    assert_eq!(
        loaded_budget.evidence.source,
        CapabilitySource::LegacyUnverified
    );
    assert!(!loaded_budget.authorizes_threshold_rotation());
    assert!(
        store
            .get_session(empty.id)
            .unwrap()
            .unwrap()
            .resolved_context_budget
            .is_none()
    );
    assert!(
        store
            .conn
            .execute(
                "UPDATE sessions SET context_window_source='guessed' WHERE id=?1",
                [legacy.id.to_string()],
            )
            .is_err(),
        "V100 source CHECK must reject values outside the closed enum"
    );

    store
        .init_schema()
        .expect("V100 reopen in place is idempotent");
    drop(store);
    let reopened = Store::open(&database).expect("reopen migrated V100 database");
    assert_eq!(stored_window(&reopened.conn, legacy.id), legacy_before);
    assert_eq!(
        reopened
            .get_session(legacy.id)
            .unwrap()
            .unwrap()
            .resolved_context_budget
            .unwrap()
            .evidence
            .source,
        CapabilitySource::LegacyUnverified
    );
}

#[test]
fn v101_forward_migration_preserves_v100_tuple_and_new_writes_reopen_raw_configuration() {
    let directory = tempfile::tempdir().expect("create V101 migration fixture directory");
    let database = directory.path().join("v101-configured-context.sqlite");
    let store = Store::open(&database).expect("create V101 migration fixture");

    let mut configured = make_test_session();
    configured.context_window = Some(380_000);
    let mut budget = context_budget_fixture(380_000, CapabilitySource::Configured);
    budget.capacity.configured_tokens = Some(400_000);
    configured.resolved_context_budget = Some(budget);
    store
        .insert_session(&configured)
        .expect("seed configured V101 row");

    rewind_store_to_schema_version(&store.conn, 100);
    let v100_tuple = store
        .conn
        .query_row(
            "SELECT context_window, context_window_source,
                    context_window_source_version, context_window_source_digest,
                    context_window_observed_at
               FROM sessions WHERE id=?1",
            [configured.id.to_string()],
            |row| {
                Ok((
                    row.get::<_, Option<i64>>(0)?,
                    row.get::<_, Option<String>>(1)?,
                    row.get::<_, Option<String>>(2)?,
                    row.get::<_, Option<String>>(3)?,
                    row.get::<_, Option<String>>(4)?,
                ))
            },
        )
        .expect("capture exact V100 evidence tuple");

    store
        .init_schema()
        .expect("migrate exact V100 fixture through the current schema head");
    assert_eq!(
        store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        LATEST_SCHEMA_VERSION
    );
    let migrated = store
        .conn
        .query_row(
            "SELECT context_window, context_window_source,
                    context_window_source_version, context_window_source_digest,
                    context_window_observed_at, context_window_configured_tokens
               FROM sessions WHERE id=?1",
            [configured.id.to_string()],
            |row| {
                Ok((
                    row.get::<_, Option<i64>>(0)?,
                    row.get::<_, Option<String>>(1)?,
                    row.get::<_, Option<String>>(2)?,
                    row.get::<_, Option<String>>(3)?,
                    row.get::<_, Option<String>>(4)?,
                    row.get::<_, Option<i64>>(5)?,
                ))
            },
        )
        .expect("read migrated V101 evidence tuple");
    assert_eq!(
        (migrated.0, migrated.1, migrated.2, migrated.3, migrated.4),
        v100_tuple
    );
    assert_eq!(migrated.5, None, "V101 must not invent missing raw intent");

    let mut loaded = store.get_session(configured.id).unwrap().unwrap();
    loaded
        .resolved_context_budget
        .as_mut()
        .expect("configured V100 evidence remains readable")
        .capacity
        .configured_tokens = Some(400_000);
    store
        .update_session_metadata(&loaded)
        .expect("persist raw configured context intent");
    drop(store);

    let reopened = Store::open(&database).expect("reopen V101 configured row");
    let reopened_budget = reopened
        .get_session(configured.id)
        .unwrap()
        .unwrap()
        .resolved_context_budget
        .expect("reopen configured context evidence");
    assert_eq!(reopened_budget.active_tokens, 380_000);
    assert_eq!(reopened_budget.capacity.configured_tokens, Some(400_000));
    assert_eq!(
        reopened_budget.evidence.source,
        CapabilitySource::Configured
    );
}

#[test]
fn context_budget_session_rows_roundtrip_runtime_catalog_configured_and_legacy_sources() {
    let store = Store::open_in_memory().expect("open context-budget row-roundtrip store");
    for (index, source) in [
        CapabilitySource::RuntimeTelemetry,
        CapabilitySource::ProviderCatalog,
        CapabilitySource::Configured,
        CapabilitySource::LegacyUnverified,
    ]
    .into_iter()
    .enumerate()
    {
        let mut session = make_test_session();
        session.id = Uuid::from_u128(0x9900 + index as u128);
        let active_tokens = 258_400 + index as u64;
        session.context_window = Some(active_tokens);
        session.resolved_context_budget = Some(context_budget_fixture(active_tokens, source));
        store
            .insert_session(&session)
            .expect("insert context-budget source row");
        let raw_observed_at = store
            .conn
            .query_row(
                "SELECT context_window_observed_at FROM sessions WHERE id=?1",
                [session.id.to_string()],
                |row| row.get::<_, Option<String>>(0),
            )
            .expect("read raw context-budget observation timestamp");
        assert_eq!(
            raw_observed_at,
            (source != CapabilitySource::LegacyUnverified)
                .then(|| "2026-09-02T12:34:56.123456789Z".to_string())
        );
        let loaded = store.get_session(session.id).unwrap().unwrap();
        assert_eq!(loaded.context_window, session.context_window);
        assert_eq!(
            loaded.resolved_context_budget, session.resolved_context_budget,
            "source roundtrip failed for {source:?}"
        );
    }

    let mut implicit_legacy = make_test_session();
    implicit_legacy.id = Uuid::from_u128(0x99fe);
    implicit_legacy.context_window = Some(400_000);
    store
        .insert_session(&implicit_legacy)
        .expect("insert scalar-only context-budget Session");
    let implicit_budget = store
        .get_session(implicit_legacy.id)
        .unwrap()
        .unwrap()
        .resolved_context_budget
        .expect("scalar-only Session receives legacy evidence");
    assert_eq!(implicit_budget.active_tokens, 400_000);
    assert_eq!(
        implicit_budget.evidence,
        CapabilityEvidence::legacy_unverified()
    );

    let mut metadata = make_test_session();
    metadata.id = Uuid::from_u128(0x99ff);
    store.insert_session(&metadata).unwrap();
    metadata.context_window = Some(300_000);
    metadata.resolved_context_budget = Some(context_budget_fixture(
        300_000,
        CapabilitySource::Configured,
    ));
    store.update_session_metadata(&metadata).unwrap();
    assert_eq!(
        store
            .get_session(metadata.id)
            .unwrap()
            .unwrap()
            .resolved_context_budget,
        metadata.resolved_context_budget
    );
}

#[test]
fn discovery_only_catalog_identity_survives_store_reopen() {
    let directory = tempfile::tempdir().expect("create discovery-only catalog fixture");
    let database = directory.path().join("discovery-only-catalog.sqlite");
    let store = Store::open(&database).expect("open discovery-only catalog store");
    let mut session = make_test_session();
    session.provider = SessionProvider::Codex;
    session.model = Some("gpt-6-astra".to_string());
    let registry = ProviderCapabilityRegistry::default();
    registry
        .refresh_codex_catalog(
            "codex-cli 0.153.0",
            include_bytes!("../../tests/fixtures/codex-models-0.155.1.json"),
            "2026-09-03T12:34:56.123456789Z"
                .parse()
                .expect("fixed discovery observation"),
        )
        .expect("parse discovery-only future catalog");
    let mut request = ContextBudgetRequest::new(SessionProvider::Codex, "gpt-6-astra");
    request.configured_tokens = Some(400_000);
    let budget = registry.resolve_context_budget(request);
    assert_eq!(budget.active_tokens, 258_400);
    assert_eq!(budget.capacity.configured_tokens, Some(400_000));
    assert_eq!(budget.capacity.effective_percent, None);
    assert_eq!(budget.evidence.source, CapabilitySource::LegacyUnverified);
    assert_eq!(budget.evidence.confidence, CapabilityConfidence::Degraded);
    assert_eq!(
        budget.evidence.source_version.as_deref(),
        Some("codex-cli 0.153.0")
    );
    assert!(budget.evidence.source_digest.is_some());
    assert!(!budget.authorizes_threshold_rotation());
    session.context_window = Some(budget.active_tokens);
    session.resolved_context_budget = Some(budget);
    store
        .insert_session(&session)
        .expect("persist discovery-only catalog identity");
    drop(store);

    let reopened = Store::open(&database).expect("reopen discovery-only catalog store");
    let loaded = reopened
        .get_session(session.id)
        .unwrap()
        .expect("discovery-only session survives reopen");
    assert_eq!(loaded.context_window, session.context_window);
    let loaded_budget = loaded
        .resolved_context_budget
        .expect("discovery-only evidence survives reopen");
    let expected_budget = session
        .resolved_context_budget
        .expect("fixture has discovery-only evidence");
    assert_eq!(loaded_budget.active_tokens, expected_budget.active_tokens);
    assert_eq!(
        loaded_budget.evidence, expected_budget.evidence,
        "the exact untrusted catalog identity must survive restart"
    );
    assert_eq!(loaded_budget.capacity.configured_tokens, Some(400_000));
    assert_eq!(loaded_budget.capacity.provider_default_tokens, None);
    assert_eq!(loaded_budget.capacity.provider_max_tokens, None);
    assert_eq!(loaded_budget.capacity.effective_percent, None);
    assert!(!loaded_budget.authorizes_threshold_rotation());
}

