#[test]
fn manager_notice_v118_preserves_v117_catalog_and_rolls_back_failed_install() {
    let store = Store::open_in_memory().unwrap();
    rewind_store_to_schema_version(&store.conn, 117);
    let catalog = |connection: &Connection| {
        connection
            .prepare("SELECT type,name,sql FROM sqlite_master ORDER BY type,name")
            .unwrap()
            .query_map([], |row| {
                Ok((
                    row.get::<_, String>(0)?,
                    row.get::<_, String>(1)?,
                    row.get::<_, Option<String>>(2)?,
                ))
            })
            .unwrap()
            .collect::<rusqlite::Result<Vec<_>>>()
            .unwrap()
    };
    let before = catalog(&store.conn);
    store
        .apply_manager_notice_retirement_v118_migration()
        .unwrap();
    let after = catalog(&store.conn);
    assert_eq!(after.len(), before.len() + 1);
    assert_eq!(
        after
            .into_iter()
            .filter(|(_, name, _)| name != "harness_manager_notices_pending_job_route_sequence")
            .collect::<Vec<_>>(),
        before
    );
    assert_post_v77_chain_replayed(&store.conn);
    assert!(
        store
            .apply_manager_notice_retirement_v118_migration()
            .is_err()
    );
    assert_post_v77_chain_replayed(&store.conn);

    rewind_store_to_schema_version(&store.conn, 117);
    store
        .conn
        .execute_batch(
            "CREATE INDEX harness_manager_notices_pending_job_route_sequence
         ON harness_manager_notices(id);",
        )
        .unwrap();
    let conflicting_catalog = catalog(&store.conn);
    assert!(
        store
            .apply_manager_notice_retirement_v118_migration()
            .is_err()
    );
    assert_eq!(catalog(&store.conn), conflicting_catalog);
    assert_eq!(
        store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        117
    );
}

