#[test]
fn manager_notice_v117_migrates_exact_v116_and_reopens_idempotently() {
    let directory = tempfile::tempdir().expect("create V117 migration fixture directory");
    let database = directory.path().join("v117-manager-notices.sqlite");
    let store = Store::open(&database).expect("create current manager notice schema");
    let project = make_test_project("V117 mixed-kind manager notice backfill");
    store.insert_project(&project).unwrap();
    let mut manager = make_test_session();
    manager.project_id = Some(project.id);
    manager.session_kind = SessionKind::Standard;
    manager.parent_id = None;
    store.insert_session(&manager).unwrap();
    let config = store
        .configure_harness_manager(
            &rsi_common::harness_manager::ConfigureHarnessManagerRequestV1 {
                project_id: project.id,
                session_id: manager.id,
                epic_ids: None,
                group_ids: Vec::new(),
                expected_row_version: 0,
            },
        )
        .unwrap();
    for index in 0..256 {
        store
            .manager_v2_save_receipt(
                &config,
                None,
                0,
                "configure_policy",
                &format!("historical-non-action-{index}"),
                &serde_json::json!({"index":index}),
                &serde_json::json!({"row_version":index + 1}),
            )
            .unwrap();
    }
    let action_id = store
        .manager_v2_save_receipt(
            &config,
            None,
            0,
            "lifecycle_action",
            "historical-lifecycle-action",
            &serde_json::json!({"action":"pause_lead"}),
            &serde_json::json!({"state":"succeeded"}),
        )
        .unwrap();
    rewind_manager_notices_fixture_to_v116(&store.conn);
    assert_fixture_matches_claimed_version(&store.conn, 116);
    drop(store);

    let migrated = Store::open(&database).expect("migrate exact V116 fixture to V117");
    assert_post_v77_chain_replayed(&migrated.conn);
    let historical_rows: (i64, i64, String) = migrated
        .conn
        .query_row(
            "SELECT
               (SELECT count(*) FROM harness_manager_v2_operations
                 WHERE project_id=?1 AND kind='configure_policy'),
               (SELECT count(*) FROM harness_manager_action_notice_queue),
               (SELECT operation_id FROM harness_manager_action_notice_queue)",
            [project.id.to_string()],
            |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
        )
        .unwrap();
    assert_eq!(historical_rows, (256, 1, action_id.to_string()));
    drop(migrated);

    let reopened = Store::open(&database).expect("reopen migrated V117 schema");
    assert_post_v77_chain_replayed(&reopened.conn);
}

