#[allow(clippy::expect_used)]
fn assert_harness_manager_fixture_version(connection: &Connection, target_version: i32) {
    for (version, objects) in [
        (102, V102_HARNESS_MANAGER_OBJECTS.as_slice()),
        (103, V103_HARNESS_MANAGER_OBJECTS.as_slice()),
        (104, V104_HARNESS_MANAGER_OBJECTS.as_slice()),
        (105, V105_PENDING_QUESTION_OBJECTS.as_slice()),
        (106, V106_PENDING_APPROVAL_OBJECTS.as_slice()),
        (107, V107_APPROVAL_PUBLICATION_OBJECTS.as_slice()),
        (108, V108_DECISION_HISTORY_OBJECTS.as_slice()),
        (109, V109_APPROVAL_SCAN_OBJECTS.as_slice()),
        (110, V110_MANAGER_SCOPE_OBJECTS.as_slice()),
        (111, V111_MANAGER_SUCCESSION_OBJECTS.as_slice()),
    ] {
        for (kind, name) in objects {
            let present: bool = connection
                .query_row(
                    "SELECT EXISTS(SELECT 1 FROM sqlite_master WHERE type=?1 AND name=?2)",
                    rusqlite::params![kind, name],
                    |row| row.get(0),
                )
                .expect("probe manager fixture catalog object");
            assert_eq!(
                present,
                target_version >= version,
                "claimed V{target_version} has incorrect V{version} manager {kind} `{name}` presence"
            );
        }
    }
    for column in ["scope_mode", "group_ids_json"] {
        assert_eq!(
            table_columns(connection, "harness_manager_scopes")
                .iter()
                .any(|name| name == column),
            target_version >= 110,
            "claimed V{target_version} has incorrect V110 {column} presence"
        );
    }
    assert_eq!(
        table_columns(connection, "harness_manager_watches")
            .iter()
            .any(|name| name == "notice_generation"),
        target_version >= 103,
        "claimed V{target_version} has incorrect V103 manager notice_generation column presence"
    );
}

/// Rewind only the exact V111 tail, leaving all released predecessor objects.
#[allow(clippy::expect_used)]
fn restore_v110_manager_succession_fixture(connection: &Connection) {
    let version: i32 = connection
        .query_row("PRAGMA user_version", [], |r| r.get(0))
        .expect("read V111 source");
    if version == 110 {
        assert_harness_manager_fixture_version(connection, 110);
        return;
    }
    assert_eq!(
        version, 111,
        "V111-to-V110 rewind requires exact V111 source"
    );
    let tx = Transaction::new_unchecked(connection, TransactionBehavior::Immediate)
        .expect("begin V111 rewind");
    assert_harness_manager_fixture_version(&tx, 111);
    for (kind, name) in V111_MANAGER_SUCCESSION_OBJECTS.iter().rev() {
        tx.execute_batch(&format!("DROP {} {};", kind.to_uppercase(), name))
            .expect("drop exact V111 object");
    }
    tx.execute_batch("PRAGMA user_version=110;")
        .expect("rewind V111 version");
    assert_harness_manager_fixture_version(&tx, 110);
    tx.commit().expect("commit V111 rewind");
}

