#[allow(clippy::expect_used)]
fn table_exists(connection: &Connection, table: &str) -> bool {
    let count: i64 = connection
        .query_row(
            "SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = ?1",
            [table],
            |row| row.get(0),
        )
        .expect("probe sqlite_master for table");
    count == 1
}

#[allow(clippy::expect_used)]
fn index_exists(connection: &Connection, index: &str) -> bool {
    let count: i64 = connection
        .query_row(
            "SELECT COUNT(*) FROM sqlite_master WHERE type = 'index' AND name = ?1",
            [index],
            |row| row.get(0),
        )
        .expect("probe sqlite_master for index");
    count == 1
}

/// Column names of `table`, in `cid` order — the same shape V77's preflight
/// reads, so fixture assertions and the production gate cannot drift.
#[allow(clippy::expect_used)]
fn table_columns(connection: &Connection, table: &str) -> Vec<String> {
    connection
        .prepare("SELECT name FROM pragma_table_info(?1) ORDER BY cid")
        .expect("prepare pragma_table_info")
        .query_map([table], |row| row.get::<_, String>(0))
        .expect("query pragma_table_info")
        .collect::<rusqlite::Result<Vec<_>>>()
        .expect("collect pragma_table_info")
}

#[allow(clippy::expect_used)]
fn restore_v92_pioneer_fixture(connection: &Connection) {
    let active_version: i32 = connection
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .expect("read V93 rewind source version");
    if active_version == 92 {
        return;
    }
    assert_eq!(
        active_version, 93,
        "V93-to-V92 rewind requires exact V93 source"
    );
    let source = Store::open_in_memory_v92_for_test().expect("build exact V92 catalog source");
    let catalog_sql = source
        .conn
        .prepare(
            "SELECT sql FROM sqlite_master
             WHERE tbl_name='recursive_live_attempts' AND sql IS NOT NULL
             ORDER BY CASE type WHEN 'table' THEN 0 ELSE 1 END, name",
        )
        .expect("prepare exact V92 recursive-live catalog query")
        .query_map([], |row| row.get::<_, String>(0))
        .expect("read exact V92 recursive-live catalog")
        .collect::<rusqlite::Result<Vec<_>>>()
        .expect("collect exact V92 recursive-live catalog");
    connection
        .execute_batch(
            "PRAGMA foreign_keys=OFF;
             BEGIN;
             CREATE TEMP TABLE recursive_live_attempts_v93_backup AS
                 SELECT * FROM recursive_live_attempts;
             DROP TABLE recursive_live_attempts;",
        )
        .expect("open exact V92 recursive-live catalog restoration");
    for statement in catalog_sql {
        connection
            .execute_batch(&statement)
            .expect("restore exact V92 recursive-live catalog object");
    }
    connection
        .execute_batch(
            "INSERT INTO recursive_live_attempts
                 SELECT * FROM recursive_live_attempts_v93_backup;
             DROP TABLE recursive_live_attempts_v93_backup;
             PRAGMA user_version=92;
             COMMIT;
             PRAGMA foreign_keys=ON;",
        )
        .expect("commit exact V92 recursive-live catalog restoration");
    let restored_version: i32 = connection
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .expect("read restored V92 version");
    assert_eq!(restored_version, 92, "V93 rewind must restore V92 version");
    let tx = connection
        .unchecked_transaction()
        .expect("open restored V92 catalog assertion");
    super::h1_v92_validate_catalog(&tx).expect("V93 rewind restored exact V92 catalog");
    tx.commit().expect("close restored V92 catalog assertion");
    assert_eq!(
        connection
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .expect("re-read restored V92 version"),
        92,
        "V92 catalog validation must preserve the restored version"
    );
}

