/// Compute the shipped V82 mailbox fingerprint without confusing a later
/// schema head with mailbox drift. The fingerprint intentionally absorbs
/// `user_version`, so later migrations must project only that value to V82 and
/// restore the exact live head immediately afterward.
#[allow(clippy::expect_used)]
fn accepted_v82_mailbox_fingerprint(connection: &Connection) -> String {
    let live_version: i64 = connection
        .query_row("PRAGMA user_version", [], |row| row.get(0))
        .expect("read live schema head before V82 mailbox projection");
    connection
        .pragma_update(None, "user_version", 82_i64)
        .expect("temporarily project the accepted mailbox catalog to V82");
    let fingerprint = super::agent_coordination::v81_schema_fingerprint(connection);
    connection
        .pragma_update(None, "user_version", live_version)
        .expect("restore live schema head after the V82 mailbox projection");
    fingerprint.expect("compute the accepted V82 mailbox catalog fingerprint")
}

/// Issue #26 encoded as a test: a fixture that rewinds `user_version` without
/// rewinding the schema must be rejected loudly, at fixture-construction time,
/// instead of surfacing several migrations later as an opaque V77 preflight
/// abort that reads like inherited background noise.
#[test]
#[should_panic(expected = "fixture claims V39 but the V112 archive journal is present")]
fn fixture_guard_rejects_a_version_only_rewind() {
    let store = Store::open_in_memory().unwrap();
    // Exactly what the broken fixtures used to do.
    store
        .conn
        .pragma_update(None, "user_version", 39_i64)
        .unwrap();
    assert_fixture_matches_claimed_version(&store.conn, 39);
}

