#[test]
fn harness_manager_fixture_helpers_refuse_skipped_predecessor_versions_without_mutation() {
    let store = Store::open_in_memory().unwrap();
    let snapshot = v89_database_snapshot(&store.conn).unwrap();
    let refused = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        restore_v101_harness_manager_fixture(&store.conn);
    }));
    assert!(
        refused.is_err(),
        "V102 teardown requires the V103 tail to be removed first"
    );
    assert_eq!(v89_database_snapshot(&store.conn).unwrap(), snapshot);

    // Drive the tail-to-V108 rewind through the single generic dispatcher
    // (already taught every step through LATEST_SCHEMA_VERSION, and hard-
    // asserted to stay current with it) instead of a fixed, ad hoc list of
    // per-version `if` checks. A hardcoded list silently no-ops for any
    // version it wasn't updated for, which is exactly how this test went
    // rolling-red across V112..V125 (issue #604). The explicit walk below
    // continues to exercise the individual V108..V101 fixture helpers
    // (idempotency, refusal-without-mutation) one call at a time; landing
    // exactly on V108 first makes the initial `restore_v108_...` call below
    // take its already-idempotent early-return path.
    rewind_store_to_schema_version(&store.conn, 108);
    assert_eq!(
        store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .unwrap(),
        108,
        "rewind_store_to_schema_version must land exactly on V108 before the \
         explicit V108..V101 fixture-helper walk below"
    );
    restore_v108_approval_scan_fixture(&store.conn);
    restore_v107_decision_history_fixture(&store.conn);
    restore_v106_approval_publication_fixture(&store.conn);
    restore_v105_pending_approval_fixture(&store.conn);
    restore_v104_pending_question_fixture(&store.conn);
    restore_v103_harness_manager_v2_fixture(&store.conn);
    restore_v102_harness_manager_fixture(&store.conn);
    assert_fixture_matches_claimed_version(&store.conn, 102);
    restore_v102_harness_manager_fixture(&store.conn);
    restore_v101_harness_manager_fixture(&store.conn);
    restore_v101_harness_manager_fixture(&store.conn);
    assert_fixture_matches_claimed_version(&store.conn, 101);
    let snapshot = v89_database_snapshot(&store.conn).unwrap();
    let refused = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        restore_v102_harness_manager_fixture(&store.conn);
    }));
    assert!(
        refused.is_err(),
        "V103 teardown cannot claim an older source"
    );
    assert_eq!(v89_database_snapshot(&store.conn).unwrap(), snapshot);
}

#[test]
fn harness_manager_fixture_rewinds_v102_v103_v104_v105_v106_v107_v108_v109_v110_v111_and_replays_the_exact_head_catalog()
 {
    use rsi_common::harness_manager::ConfigureHarnessManagerRequestV1;

    for target in [101, 102, 103, 104, 105, 106, 107, 108, 109, 110] {
        let store = Store::open_in_memory().unwrap();
        let project = make_test_project("Manager rewind fixture");
        store.insert_project(&project).unwrap();
        let mut manager = make_test_session();
        manager.project_id = Some(project.id);
        store.insert_session(&manager).unwrap();
        store
            .configure_harness_manager(&ConfigureHarnessManagerRequestV1 {
                group_ids: Vec::new(),
                project_id: project.id,
                session_id: manager.id,
                epic_ids: Some(Vec::new()),
                expected_row_version: 0,
            })
            .unwrap();
        let catalog_query = "SELECT type,name,coalesce(tbl_name,''),coalesce(sql,'') FROM sqlite_master ORDER BY type,name";
        let head_catalog = query_fingerprint(&store.conn, catalog_query).unwrap();
        let stable_sessions = "SELECT id,query,status,working_dir FROM sessions ORDER BY id";
        let session_rows = query_fingerprint(&store.conn, stable_sessions).unwrap();
        let scopes = "SELECT project_id,manager_session_id,epic_ids_json,row_version,updated_at FROM harness_manager_scopes ORDER BY project_id";
        let scope_rows = query_fingerprint(&store.conn, scopes).unwrap();

        rewind_store_to_schema_version(&store.conn, target);
        assert_fixture_matches_claimed_version(&store.conn, target);
        // V102 scope data survives removal of V103 alone. V101 has none of
        // the manager tables, indexes, cross-table triggers, or notice column.
        if target >= 102 {
            assert_eq!(query_fingerprint(&store.conn, scopes).unwrap(), scope_rows);
        }
        assert_eq!(
            query_fingerprint(&store.conn, stable_sessions).unwrap(),
            session_rows
        );
        rewind_store_to_schema_version(&store.conn, target);

        store
            .init_schema()
            .expect("replay exact manager predecessor to schema head");
        assert_post_v77_chain_replayed(&store.conn);
        assert_eq!(
            query_fingerprint(&store.conn, catalog_query).unwrap(),
            head_catalog
        );
        assert_eq!(
            query_fingerprint(&store.conn, stable_sessions).unwrap(),
            session_rows
        );
        if target >= 102 {
            assert_eq!(query_fingerprint(&store.conn, scopes).unwrap(), scope_rows);
        } else {
            assert_eq!(
                store
                    .conn
                    .query_row("SELECT count(*) FROM harness_manager_scopes", [], |row| row
                        .get::<_, i64>(0))
                    .unwrap(),
                0
            );
        }
        store
            .init_schema()
            .expect("replayed manager catalog reopens idempotently");
        assert_eq!(
            query_fingerprint(&store.conn, catalog_query).unwrap(),
            head_catalog
        );
    }
}

/// The teardown half of the issue #26 evidence.
///
/// [`assert_post_v77_chain_replayed`] is only proof that V77..V82 executed if
/// their relations were genuinely absent beforehand. This test states that
/// premise directly: rewind, assert every relation is gone, replay, assert every
/// relation is back and correctly fingerprinted.
#[test]
fn rewind_tears_down_the_non_idempotent_migration_tail() {
    let store = Store::open_in_memory().unwrap();
    rewind_store_to_schema_version(&store.conn, 39);

    for table in D05_V78_TABLES
        .iter()
        .chain(V80_TABLES.iter())
        .chain(V81_TABLES.iter())
    {
        assert!(
            !table_exists(&store.conn, table),
            "`{table}` survived the rewind, so its migration would not re-execute"
        );
    }
    assert_eq!(
        table_columns(&store.conn, "issues"),
        V76_ISSUE_COLUMNS,
        "the rewind left `issues` in a post-V76 shape"
    );

    store.init_schema().unwrap();
    assert_post_v77_chain_replayed(&store.conn);
}

fn populate_v90_projection_fixture(store: &mut Store) -> (Uuid, Uuid) {
    use super::sandbox_custody::{CustodyCause, NewCustodyRoot, SessionCustodyBinding};
    use rsi_common::types::{SandboxCleanupState, SandboxKind};

    let mut ordinary = make_test_session();
    ordinary.id = Uuid::new_v4();
    ordinary.working_dir = PathBuf::from("/tmp/v90-ordinary-repo");
    store
        .insert_session(&ordinary)
        .expect("insert ordinary V90 fixture Session");

    let mut sandboxed = make_test_session();
    sandboxed.id = Uuid::new_v4();
    sandboxed.working_dir = PathBuf::from("/tmp/v90-sandbox-repo");
    sandboxed.sandbox_kind = Some(SandboxKind::GitWorktree);
    sandboxed.sandbox_root = Some(PathBuf::from(format!("/tmp/v90-sandbox-{}", sandboxed.id)));
    sandboxed.sandbox_branch = Some(format!("rsi/v90-{}", &sandboxed.id.to_string()[..8]));
    sandboxed.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
    let custody_id = Uuid::new_v4();
    store
        .insert_session_with_custody(
            &sandboxed,
            SessionCustodyBinding::New(NewCustodyRoot {
                custody_id,
                canonical_repo_dir: sandboxed.working_dir.to_string_lossy().into_owned(),
                sandbox_root: sandboxed
                    .sandbox_root
                    .as_ref()
                    .unwrap()
                    .to_string_lossy()
                    .into_owned(),
                sandbox_branch: sandboxed.sandbox_branch.clone().unwrap(),
                repository_identity: format!("repo:v90:{custody_id}"),
                source_commit: "a".repeat(40),
                cause: CustodyCause::FreshLaunch,
            }),
        )
        .expect("insert custody-bearing V90 fixture Session");
    (ordinary.id, sandboxed.id)
}

fn v90_projection_fingerprint(connection: &Connection) -> String {
    query_fingerprint(
        connection,
        "SELECT session_id,schema_version,projection_version,execution_state,freshness,
                canonical_repo_dir,effective_cwd,custody_id,custody_generation,
                validated_at,error_code,updated_at
         FROM session_execution_projections ORDER BY session_id",
    )
    .expect("fingerprint execution projections")
}

#[test]
fn session_execution_projection_retention_migration_rebuilds_prior_head_data_and_catalog() {
    let directory = tempfile::tempdir().expect("V90 migration directory");
    let database = directory.path().join("v90-data-bearing.sqlite");
    let before;
    {
        let mut store = Store::open(&database).expect("open V90 fixture store");
        populate_v90_projection_fixture(&mut store);
        store
            .init_schema()
            .expect("stabilize unversioned repairs before V89 rewind");
        rewind_store_to_schema_version(&store.conn, 89);
        before = v90_projection_fingerprint(&store.conn);
        assert_fixture_matches_claimed_version(&store.conn, 89);
    }

    {
        let migrated = Store::open(&database).expect("migrate exact V89 projection catalog");
        assert_eq!(
            migrated
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            LATEST_SCHEMA_VERSION
        );
        assert_eq!(v90_projection_fingerprint(&migrated.conn), before);
        let tx = migrated.conn.unchecked_transaction().unwrap();
        assert!(super::session_execution_projection_catalog_matches(&tx, true).unwrap());
        assert!(super::session_execution_projection_foreign_keys_match(&tx, true).unwrap());
        drop(tx);
        assert_eq!(
            migrated
                .conn
                .query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0))
                .unwrap(),
            "ok"
        );
        assert_eq!(
            migrated
                .conn
                .query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |row| {
                    row.get::<_, i64>(0)
                })
                .unwrap(),
            0
        );
    }

    let reopened = Store::open(&database).expect("V90 projection migration reopens idempotently");
    assert_eq!(v90_projection_fingerprint(&reopened.conn), before);
    assert_post_v77_chain_replayed(&reopened.conn);
}

#[test]
fn session_execution_projection_retention_migration_failpoints_rollback_exact_prior_head() {
    assert_eq!(super::V90MigrationFault::ALL.len(), 10);
    for fault in super::V90MigrationFault::ALL {
        let mut store = Store::open_in_memory().expect("open V90 failpoint fixture");
        populate_v90_projection_fixture(&mut store);
        store
            .init_schema()
            .expect("stabilize unversioned repairs before V89 rewind");
        rewind_store_to_schema_version(&store.conn, 89);
        let before = v89_database_snapshot(&store.conn).expect("snapshot exact V89 source");

        super::v90_test_fail_next_migration(fault);
        let error = store
            .init_schema()
            .expect_err("V90 fault must abort migration");
        assert!(
            error
                .to_string()
                .contains(&format!("injected V90 migration fault: {fault:?}")),
            "V90 {fault:?} failed before its seam: {error}"
        );
        assert_eq!(
            v89_database_snapshot(&store.conn).unwrap(),
            before,
            "V90 {fault:?} must restore exact prior catalog, data, and version"
        );
        assert_fixture_matches_claimed_version(&store.conn, 89);
    }
}

#[test]
fn session_execution_projection_retention_migration_copy_parity_and_except_fail_closed() {
    for corruption in [
        super::V90CopyCorruption::Count,
        super::V90CopyCorruption::Bytes,
    ] {
        let mut store = Store::open_in_memory().expect("open V90 copy-corruption fixture");
        populate_v90_projection_fixture(&mut store);
        store
            .init_schema()
            .expect("stabilize unversioned repairs before V89 rewind");
        rewind_store_to_schema_version(&store.conn, 89);
        let before = v89_database_snapshot(&store.conn).expect("snapshot exact V89 source");

        super::v90_test_corrupt_next_copy(corruption);
        let error = store
            .init_schema()
            .expect_err("V90 copy corruption must abort migration");
        let rendered = error.to_string();
        assert!(rendered.contains("V90 execution-projection copy mismatch"));
        match corruption {
            super::V90CopyCorruption::Count => {
                assert!(rendered.contains("source=2, destination=1"));
            }
            super::V90CopyCorruption::Bytes => {
                assert!(rendered.contains("source=2, destination=2"));
                assert!(rendered.contains("source-minus-destination=1"));
                assert!(rendered.contains("destination-minus-source=1"));
            }
        }
        assert_eq!(v89_database_snapshot(&store.conn).unwrap(), before);
        assert_fixture_matches_claimed_version(&store.conn, 89);
    }
}

#[test]
fn session_execution_projection_retention_migration_refuses_bad_preflight_without_mutation() {
    for case in ["catalog", "missing projection", "integrity", "foreign key"] {
        let mut store = Store::open_in_memory().expect("open V90 refusal fixture");
        let (ordinary_id, _) = populate_v90_projection_fixture(&mut store);
        store
            .init_schema()
            .expect("stabilize unversioned repairs before V89 rewind");
        rewind_store_to_schema_version(&store.conn, 89);
        match case {
            "catalog" => store
                .conn
                .execute_batch(
                    "DROP INDEX idx_session_execution_projections_custody;
                     CREATE INDEX idx_session_execution_projections_custody
                         ON session_execution_projections(session_id,custody_id);",
                )
                .unwrap(),
            "missing projection" => {
                store
                    .conn
                    .execute_batch("DROP TRIGGER session_execution_projections_no_delete;")
                    .unwrap();
                store
                    .conn
                    .execute(
                        "DELETE FROM session_execution_projections WHERE session_id=?1",
                        [ordinary_id.to_string()],
                    )
                    .unwrap();
                store
                    .conn
                    .execute_batch(super::SESSION_EXECUTION_PROJECTION_NO_DELETE_SQL)
                    .unwrap();
            }
            "integrity" => store
                .conn
                .execute_batch(&format!(
                    "PRAGMA ignore_check_constraints=ON;
                     UPDATE session_execution_projections SET schema_version=2
                         WHERE session_id='{ordinary_id}';
                     PRAGMA ignore_check_constraints=OFF;"
                ))
                .unwrap(),
            "foreign key" => store
                .conn
                .execute_batch(&format!(
                    "PRAGMA foreign_keys=OFF;
                     UPDATE session_execution_projections
                         SET custody_id='00000000-0000-4000-8000-000000000090'
                         WHERE session_id='{ordinary_id}';
                     PRAGMA foreign_keys=ON;"
                ))
                .unwrap(),
            _ => unreachable!(),
        }
        let before = v89_database_snapshot(&store.conn).expect("snapshot refused V89 source");
        let error = store.init_schema().expect_err(case);
        let rendered = error.to_string();
        match case {
            "catalog" => assert!(rendered.contains("exact V89 execution-projection catalog")),
            "missing projection" => assert!(rendered.contains("found 1 missing")),
            "integrity" => assert!(rendered.contains("integrity_check=ok")),
            "foreign key" => assert!(rendered.contains("clean V89 foreign keys")),
            _ => unreachable!(),
        }
        assert_eq!(
            v89_database_snapshot(&store.conn).unwrap(),
            before,
            "{case} refusal mutated V89 catalog, data, or version"
        );
        assert_eq!(
            store
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            89
        );
    }
}

#[test]
fn v89_data_bearing_v88_migration_reopen_and_direct_rewind_replay() {
    let store = Store::open_in_memory().expect("open V89 reference store");
    let mut session = make_test_session();
    session.id = Uuid::from_u128(0x8900_0001);
    store
        .insert_session(&session)
        .expect("insert data-bearing V88 Session");
    rewind_store_to_schema_version(&store.conn, 88);

    let before_sessions = query_fingerprint(
        &store.conn,
        "SELECT id,status,provider,working_dir,created_at,updated_at FROM sessions ORDER BY id",
    )
    .expect("fingerprint V88 Session bytes");
    let before_projects = query_fingerprint(
        &store.conn,
        "SELECT id,name,created_at,updated_at FROM projects ORDER BY id",
    )
    .expect("fingerprint V88 project bytes");

    store.init_schema().expect("migrate exact V88 to V89");
    assert_post_v77_chain_replayed(&store.conn);
    assert_eq!(
        query_fingerprint(
            &store.conn,
            "SELECT id,status,provider,working_dir,created_at,updated_at FROM sessions ORDER BY id",
        )
        .unwrap(),
        before_sessions
    );
    assert_eq!(
        query_fingerprint(
            &store.conn,
            "SELECT id,name,created_at,updated_at FROM projects ORDER BY id",
        )
        .unwrap(),
        before_projects
    );
    for table in V89_TABLES {
        assert_eq!(
            store
                .conn
                .query_row(&format!("SELECT count(*) FROM {table}"), [], |row| {
                    row.get::<_, i64>(0)
                })
                .unwrap(),
            0,
            "V89 migration must not synthesize `{table}` rows"
        );
    }
    assert_eq!(
        store
            .conn
            .query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0))
            .unwrap(),
        "ok"
    );
    assert_eq!(
        store
            .conn
            .query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |row| {
                row.get::<_, i64>(0)
            })
            .unwrap(),
        0
    );
    store.init_schema().expect("V89 reopen is idempotent");
}

