#[test]
fn v89_rejects_unpinned_pre_antigravity_catalog_variant() {
    let directory = tempfile::tempdir().expect("create hostile pre-Antigravity V88 fixture dir");
    let path = directory.path().join("hostile-pre-antigravity-v88.sqlite");
    let connection = create_v88_pre_antigravity_fixture(&path);
    let table_sql: String = connection
        .query_row(
            "SELECT sql FROM sqlite_master
             WHERE type='table' AND name='recursive_live_attempts'",
            [],
            |row| row.get(0),
        )
        .expect("read hostile recursive-live table SQL");
    let indexes = connection
        .prepare(
            "SELECT sql FROM sqlite_master
             WHERE type='index' AND tbl_name='recursive_live_attempts' AND sql IS NOT NULL
             ORDER BY name",
        )
        .expect("prepare hostile recursive-live index SQL")
        .query_map([], |row| row.get::<_, String>(0))
        .expect("query hostile recursive-live index SQL")
        .collect::<rusqlite::Result<Vec<_>>>()
        .expect("collect hostile recursive-live index SQL");
    assert_eq!(
        connection
            .query_row("SELECT count(*) FROM recursive_live_attempts", [], |row| {
                row.get::<_, i64>(0)
            })
            .expect("count hostile recursive-live fixture table"),
        0
    );
    let gemini_fragment = "'Gemini', ";
    assert_eq!(table_sql.matches(gemini_fragment).count(), 1);
    let hostile_table_sql = table_sql.replace(gemini_fragment, "");
    connection
        .execute_batch("PRAGMA foreign_keys=OFF; DROP TABLE recursive_live_attempts;")
        .expect("drop hostile recursive-live table");
    connection
        .execute_batch(&hostile_table_sql)
        .expect("replay unpinned recursive-live table variant");
    for sql in indexes {
        connection
            .execute_batch(&sql)
            .expect("restore hostile recursive-live index");
    }
    connection
        .execute_batch("PRAGMA foreign_keys=ON;")
        .expect("restore hostile foreign keys");
    assert_eq!(
        connection
            .query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0))
            .expect("check hostile V88 fixture integrity"),
        "ok"
    );
    assert_eq!(
        connection
            .query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |row| {
                row.get::<_, i64>(0)
            })
            .expect("check hostile V88 fixture foreign keys"),
        0
    );
    let tx = connection
        .unchecked_transaction()
        .expect("open hostile V88 catalog transaction");
    assert_ne!(
        super::capacity_recovery::v88_full_catalog_fingerprint(&tx)
            .expect("fingerprint hostile V88 fixture"),
        super::capacity_recovery::V88_ACCEPTED_PRE_ANTIGRAVITY_FULL_CATALOG_FINGERPRINT
    );
    drop(tx);
    drop(connection);

    let error = match Store::open(&path) {
        Ok(_) => panic!("unpinned recursive-live variant must not pass V89 admission"),
        Err(error) => error,
    };
    assert!(
        error
            .to_string()
            .contains("requires exact V88 source catalog"),
        "V89 accepted unpinned recursive-live variant: {error}"
    );
}

#[test]
fn h1_v92_migration_seeds_epics_and_lead_generation_closes_aba() {
    let store = Store::open_in_memory().expect("open V92 lead-generation fixture");
    let mut epic = make_test_session();
    epic.id = Uuid::new_v4();
    epic.session_kind = SessionKind::Epic;
    store.insert_session(&epic).expect("insert Epic");
    let mut lead_a = make_test_session();
    lead_a.id = Uuid::new_v4();
    lead_a.session_kind = SessionKind::Task;
    lead_a.parent_id = Some(epic.id);
    store.insert_session(&lead_a).expect("insert lead A");
    let mut lead_b = make_test_session();
    lead_b.id = Uuid::new_v4();
    lead_b.session_kind = SessionKind::Task;
    lead_b.parent_id = Some(epic.id);
    store.insert_session(&lead_b).expect("insert lead B");

    store
        .set_lead_session(epic.id, Some(lead_a.id))
        .expect("set initial lead");
    let initial: i64 = store
        .conn
        .query_row(
            "SELECT generation FROM epic_lead_generations WHERE epic_id=?1",
            [epic.id.to_string()],
            |row| row.get(0),
        )
        .unwrap();
    store
        .set_lead_session(epic.id, Some(lead_b.id))
        .expect("move lead A to B");
    store
        .set_lead_session(epic.id, Some(lead_a.id))
        .expect("move lead B to A");
    let after_aba: i64 = store
        .conn
        .query_row(
            "SELECT generation FROM epic_lead_generations WHERE epic_id=?1",
            [epic.id.to_string()],
            |row| row.get(0),
        )
        .unwrap();
    assert_eq!(after_aba, initial + 2, "A→B→A must advance the fence twice");
}

#[test]
fn h1_v92_migration_failpoints_restore_exact_v91_state() {
    assert_eq!(super::H1V92MigrationFault::ALL.len(), 6);
    for fault in super::H1V92MigrationFault::ALL {
        let store = Store::open_in_memory().expect("open V92 fault fixture");
        let mut epic = make_test_session();
        epic.id = Uuid::new_v4();
        epic.session_kind = SessionKind::Epic;
        store.insert_session(&epic).expect("insert Epic source row");
        rewind_store_to_schema_version(&store.conn, 91);
        let before = query_fingerprint(
            &store.conn,
            "SELECT type,name,coalesce(sql,'') FROM sqlite_master ORDER BY type,name",
        )
        .expect("snapshot exact V91 source");

        super::h1_v92_test_fail_next_migration(fault);
        let error = store
            .init_schema()
            .expect_err("V92 fault must abort migration");
        assert!(
            error
                .to_string()
                .contains(&format!("injected V92 migration fault: {fault:?}")),
            "V92 {fault:?} failed before its seam: {error}"
        );
        assert_eq!(
            store
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            91
        );
        assert_eq!(
            query_fingerprint(
                &store.conn,
                "SELECT type,name,coalesce(sql,'') FROM sqlite_master ORDER BY type,name",
            )
            .unwrap(),
            before,
            "V92 {fault:?} must roll back exact catalog bytes"
        );
        for table in V92_TABLES {
            assert!(!table_exists(&store.conn, table));
        }
        for trigger in V92_TRIGGERS {
            let count: i64 = store
                .conn
                .query_row(
                    "SELECT count(*) FROM sqlite_master WHERE type='trigger' AND name=?1",
                    [trigger],
                    |row| row.get(0),
                )
                .unwrap();
            assert!(count == 0, "V92 {fault:?} left trigger `{trigger}` behind");
        }
        assert_fixture_matches_claimed_version(&store.conn, 91);
    }
}

