#[test]
fn v94_authenticates_each_normalized_v93_history_before_ddl() {
    fn migrate_to_v93(path: &std::path::Path) -> String {
        super::cohort_settlement::fail_next_v94_migration(
            super::cohort_settlement::SourceWorktreeSettlementV94MigrationFault::AfterPreflight,
        );
        let error = match Store::open(path) {
            Ok(_) => panic!("fault must stop exact V93 descendant"),
            Err(error) => error,
        };
        assert!(error.to_string().contains("injected V94"), "{error}");
        let connection = Connection::open(path).expect("open exact V93 descendant");
        Store::register_sql_functions(&connection).expect("register SQL functions");
        let tx = connection
            .unchecked_transaction()
            .expect("V93 fingerprint tx");
        super::h1_v94_validate_v93_catalog(&tx).expect("authentic V93 descendant");
        assert_eq!(
            tx.query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .expect("read V93 version"),
            93
        );
        assert_eq!(
            tx.query_row("PRAGMA integrity_check", [], |row| row.get::<_, String>(0))
                .expect("V93 integrity"),
            "ok"
        );
        assert_eq!(
            tx.query_row("SELECT count(*) FROM pragma_foreign_key_check", [], |row| {
                row.get::<_, i64>(0)
            })
            .expect("V93 foreign keys"),
            0
        );
        super::capacity_recovery::v88_full_catalog_fingerprint(&tx).expect("V93 fingerprint")
    }

    let directory = tempfile::tempdir().expect("V93 fingerprint fixtures");
    let fresh = directory.path().join("fresh.sqlite");
    let fresh_fingerprint = migrate_to_v93(&fresh);

    let legacy = directory.path().join("legacy.sqlite");
    let connection = create_legacy_v0_fixture(&legacy);
    seed_legacy_v0_session(&connection);
    drop(connection);
    let legacy_fingerprint = migrate_to_v93(&legacy);

    let deployed = directory.path().join("deployed.sqlite");
    drop(create_deployed_additive_v88_fixture(&deployed));
    let deployed_fingerprint = migrate_to_v93(&deployed);

    let antigravity = directory.path().join("pre-antigravity.sqlite");
    drop(create_v88_pre_antigravity_fixture(&antigravity));
    let antigravity_fingerprint = migrate_to_v93(&antigravity);
    assert_eq!(
        fresh_fingerprint,
        H1_V94_ACCEPTED_FRESH_V93_FULL_CATALOG_FINGERPRINT
    );
    assert_eq!(
        legacy_fingerprint,
        H1_V94_ACCEPTED_LEGACY_V0_V93_FULL_CATALOG_FINGERPRINT
    );
    assert_eq!(
        deployed_fingerprint,
        H1_V94_ACCEPTED_DEPLOYED_ADDITIVE_V93_FULL_CATALOG_FINGERPRINT
    );
    assert_eq!(
        antigravity_fingerprint,
        H1_V94_ACCEPTED_PRE_ANTIGRAVITY_V93_FULL_CATALOG_FINGERPRINT
    );
    for path in [&fresh, &legacy, &deployed, &antigravity] {
        let store = Store::open(path).expect("authenticated V93 history reaches V94");
        assert_eq!(
            store
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .expect("read V94 version"),
            LATEST_SCHEMA_VERSION
        );
    }
}

#[test]
fn v95_authenticates_each_original_v94_history_before_hardening() {
    fn migrate_to_v94(path: &std::path::Path) -> String {
        super::cohort_settlement::fail_next_v94_migration(
            super::cohort_settlement::SourceWorktreeSettlementV94MigrationFault::AfterPreflight,
        );
        assert!(Store::open(path).is_err());
        let connection = Connection::open(path).expect("open V93 lineage");
        Store::register_sql_functions(&connection).expect("register functions");
        let tx = connection.unchecked_transaction().expect("open V94 tx");
        super::h1_v94_validate_v93_catalog(&tx).expect("accepted V93 lineage");
        super::cohort_settlement::install_v94_schema(&tx).expect("install original V94");
        super::cohort_settlement::validate_v94_catalog(&tx).expect("validate original V94");
        tx.execute("PRAGMA user_version=94", []).expect("pin V94");
        let fingerprint = super::capacity_recovery::v88_full_catalog_fingerprint(&tx)
            .expect("fingerprint V94 lineage");
        tx.commit().expect("commit V94 lineage");
        fingerprint
    }

    let directory = tempfile::tempdir().expect("V94 lineage fingerprints");
    let fresh = directory.path().join("fresh.sqlite");
    let legacy = directory.path().join("legacy.sqlite");
    let deployed = directory.path().join("deployed.sqlite");
    let antigravity = directory.path().join("antigravity.sqlite");
    let connection = create_legacy_v0_fixture(&legacy);
    seed_legacy_v0_session(&connection);
    drop(connection);
    drop(create_deployed_additive_v88_fixture(&deployed));
    drop(create_v88_pre_antigravity_fixture(&antigravity));
    let expected = [
        super::H1_V95_ACCEPTED_FRESH_V94_FULL_CATALOG_FINGERPRINT,
        super::H1_V95_ACCEPTED_LEGACY_V0_V94_FULL_CATALOG_FINGERPRINT,
        super::H1_V95_ACCEPTED_DEPLOYED_ADDITIVE_V94_FULL_CATALOG_FINGERPRINT,
        super::H1_V95_ACCEPTED_PRE_ANTIGRAVITY_V94_FULL_CATALOG_FINGERPRINT,
    ];
    for (path, expected) in [&fresh, &legacy, &deployed, &antigravity]
        .into_iter()
        .zip(expected)
    {
        assert_eq!(migrate_to_v94(path), expected);
        let connection = Connection::open(path).expect("reopen exact V94 lineage");
        Store::register_sql_functions(&connection).expect("register SQL functions");
        let tx = connection
            .unchecked_transaction()
            .expect("open V94 auth tx");
        super::h1_v95_validate_v94_catalog(&tx).expect("authenticate exact V94 lineage");
        tx.commit().expect("close V94 auth tx");
        restore_deployed_v94_settlement_fixture(&connection);
        let tx = connection
            .unchecked_transaction()
            .expect("open deployed V94 auth transaction");
        assert_eq!(
            super::h1_v95_validate_v94_catalog(&tx)
                .expect("authenticate exact deployed V94 lineage"),
            super::cohort_settlement::V94SettlementCatalog::Deployed
        );
        tx.commit().expect("close deployed V94 auth transaction");
        drop(connection);
        Store::open(path).expect("migrate authenticated V94 lineage through V95");
    }
}

#[test]
fn v95_migration_failpoints_restore_exact_v94_state_then_converge() {
    assert_eq!(
        super::cohort_settlement::SourceWorktreeSettlementV95MigrationFault::ALL.len(),
        10
    );
    for fault in super::cohort_settlement::SourceWorktreeSettlementV95MigrationFault::ALL {
        use rsi_common::cohort_settlement::SourceWorktreeSettlementPhaseV1 as P;
        let mut store = Store::open_in_memory().expect("open V95 fault fixture");
        rewind_store_to_schema_version(&store.conn, 94);
        let run_id = seed_v94_settlement_projection_fixture(
            &mut store,
            &format!("fault-{fault:?}"),
            &[
                (P::RecoveryRequired, Some("recovery_proof_failed")),
                (P::IntentCommitted, None),
            ],
        );
        let before_catalog = query_fingerprint(
            &store.conn,
            "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master ORDER BY type,name,tbl_name,coalesce(sql,'')",
        )
        .expect("fingerprint exact V94 catalog");
        let before_runs = query_fingerprint(
            &store.conn,
            "SELECT * FROM source_worktree_settlement_runs ORDER BY run_id",
        )
        .expect("fingerprint split V94 run rows");
        let before_items = query_fingerprint(
            &store.conn,
            "SELECT * FROM source_worktree_settlement_items ORDER BY run_id,sequence",
        )
        .expect("fingerprint split V94 item rows");

        super::cohort_settlement::fail_next_v95_migration(fault);
        let error = store
            .init_schema()
            .expect_err("V95 fault must abort its immediate transaction");
        assert!(
            error.to_string().contains(&format!(
                "injected V95 settlement migration fault: {fault:?}"
            )),
            "V95 {fault:?} failed before its seam: {error}"
        );
        assert_eq!(
            store
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .expect("read rolled-back V94 version"),
            94
        );
        assert_eq!(
            query_fingerprint(
                &store.conn,
                "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master ORDER BY type,name,tbl_name,coalesce(sql,'')",
            )
            .expect("fingerprint rolled-back V94 catalog"),
            before_catalog,
            "V95 {fault:?} changed exact V94 catalog bytes"
        );
        assert_eq!(
            query_fingerprint(
                &store.conn,
                "SELECT * FROM source_worktree_settlement_runs ORDER BY run_id",
            )
            .expect("fingerprint rolled-back split V94 run rows"),
            before_runs,
            "V95 {fault:?} changed split run rows"
        );
        assert_eq!(
            query_fingerprint(
                &store.conn,
                "SELECT * FROM source_worktree_settlement_items ORDER BY run_id,sequence",
            )
            .expect("fingerprint rolled-back split V94 item rows"),
            before_items,
            "V95 {fault:?} changed split item rows"
        );
        let tx = store
            .conn
            .unchecked_transaction()
            .expect("open rolled-back V94 auth tx");
        super::h1_v95_validate_v94_catalog(&tx).expect("rollback retained exact V94 source");
        tx.commit().expect("close rolled-back V94 auth tx");

        store.init_schema().expect("retry V95 migration");
        let tx = store
            .conn
            .unchecked_transaction()
            .expect("open converged V95 tx");
        super::cohort_settlement::validate_v95_catalog(&tx)
            .expect("retry converged to exact V95 catalog");
        tx.commit().expect("close converged V95 tx");
        let run = store
            .get_source_worktree_settlement_run(run_id)
            .expect("load normalized split run")
            .expect("normalized split run");
        assert_eq!(
            run.state,
            rsi_common::cohort_settlement::SourceWorktreeSettlementRunStateV1::Partial
        );
        run.validate_wire()
            .expect("normalized split run is wire-valid");
    }
}

fn seed_v94_settlement_projection_fixture(
    store: &mut Store,
    key: &str,
    phases: &[(
        rsi_common::cohort_settlement::SourceWorktreeSettlementPhaseV1,
        Option<&str>,
    )],
) -> Uuid {
    use super::cohort_settlement::{NewSettlementItem, NewSettlementRun};
    use super::sandbox_custody::{CustodyCause, NewCustodyRoot, SessionCustodyBinding};
    use rsi_common::types::{SandboxCleanupState, SandboxKind};

    let repository_identity = format!("repo:v95-normalize:{key}");
    let canonical_repo_dir = format!("/tmp/v95-normalize-repo-{key}");
    let mut items = Vec::new();
    for (index, _) in phases.iter().enumerate() {
        let mut session = make_test_session();
        session.id = Uuid::new_v4();
        session.status = SessionStatus::Completed;
        session.working_dir = PathBuf::from(&canonical_repo_dir);
        session.sandbox_kind = Some(SandboxKind::GitWorktree);
        session.sandbox_root = Some(PathBuf::from(format!(
            "/tmp/v95-normalize-sandbox-{}",
            session.id
        )));
        session.sandbox_branch = Some(format!("rsi/v95-{key}-{index}"));
        session.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
        let custody_id = Uuid::new_v4();
        let root = NewCustodyRoot {
            custody_id,
            canonical_repo_dir: canonical_repo_dir.clone(),
            sandbox_root: session
                .sandbox_root
                .as_ref()
                .expect("sandbox root")
                .to_string_lossy()
                .into_owned(),
            sandbox_branch: session.sandbox_branch.clone().expect("sandbox branch"),
            repository_identity: repository_identity.clone(),
            source_commit: "a".repeat(40),
            cause: CustodyCause::FreshLaunch,
        };
        // Most callers hand this fixture a store rewound below V99, where the
        // current Session identity suffix does not exist yet. Below V98 the
        // custody allocation identity is absent as well. The
        // production insert names the current catalog and must keep failing
        // closed there, so seed the frozen pre-V98 row shape instead; the
        // remaining current-schema callers keep the production path.
        let fixture_schema_version: i32 = store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get(0))
            .expect("read settlement fixture schema version");
        if fixture_schema_version < 99 {
            store
                .insert_session_with_pre_v99_custody(&session, root)
                .expect("insert pre-V99 settlement fixture custody");
        } else {
            store
                .insert_session_with_custody(&session, SessionCustodyBinding::New(root))
                .expect("insert V94 settlement fixture custody");
        }
        items.push(NewSettlementItem {
            session_id: session.id,
            original_status: "Completed".into(),
            original_updated_at: session
                .updated_at
                .to_rfc3339_opts(chrono::SecondsFormat::Nanos, true),
            custody_id,
            custody_generation: 1,
            canonical_repo_dir: canonical_repo_dir.clone(),
            sandbox_root: session
                .sandbox_root
                .expect("sandbox root")
                .to_string_lossy()
                .into_owned(),
            sandbox_branch: session.sandbox_branch.expect("sandbox branch"),
            repository_identity: repository_identity.clone(),
            source_ref: format!("refs/heads/rsi/v95-{key}-{index}"),
            source_oid: "a".repeat(40),
            target_oid: "b".repeat(40),
            evidence_digest: format!("sha256:{}", "c".repeat(64)),
            clean_state_digest: format!("sha256:{}", "d".repeat(64)),
            reserved_effects: 0,
            active_effects: 0,
            participant_count: 1,
        });
    }
    let run_id = Uuid::new_v4();
    store
        .insert_source_worktree_settlement_run(&NewSettlementRun {
            run_id,
            repository_identity,
            canonical_repo_dir,
            target_ref: "refs/heads/main".into(),
            target_oid: "b".repeat(40),
            plan_digest: format!("sha256:{}", "e".repeat(64)),
            idempotency_key: key.into(),
            authorization_digest: format!("sha256:{}", "f".repeat(64)),
            request_fingerprint: format!("sha256:{}", "1".repeat(64)),
            observed_count: phases.len() as u32,
            retained_count: 0,
            items,
        })
        .expect("insert V94 settlement projection fixture");

    for (sequence, (phase, refusal)) in phases.iter().enumerate() {
        use rsi_common::cohort_settlement::SourceWorktreeSettlementPhaseV1 as P;
        let transitions: &[P] = match phase {
            P::IntentCommitted => &[],
            P::WorktreeRemoved => &[P::WorktreeRemoved],
            P::BranchRemoved | P::Settled => &[P::WorktreeRemoved, P::BranchRemoved],
            P::Refused => &[P::Refused],
            P::RecoveryRequired => &[P::RecoveryRequired],
            P::Unattempted => &[P::Unattempted],
            P::Planned => panic!("fixture cannot regress to planned"),
        };
        for (step, transition) in transitions.iter().enumerate() {
            let final_transition =
                *transition == *phase || (*phase == P::Settled && *transition == P::BranchRemoved);
            store
                .conn
                .execute(
                    "UPDATE source_worktree_settlement_items
                     SET phase=?1,refusal_code=?2,updated_at=?3
                     WHERE run_id=?4 AND sequence=?5",
                    rusqlite::params![
                        transition.as_str(),
                        final_transition.then_some(*refusal).flatten(),
                        format!("2099-01-01T00:00:{:02}.000000000Z", sequence * 3 + step),
                        run_id.to_string(),
                        sequence as i64,
                    ],
                )
                .expect("advance split V94 item without refreshing run");
        }
        if *phase == P::Settled {
            store
                .conn
                .execute(
                    "UPDATE source_worktree_settlement_items
                     SET phase='settled',refusal_code=NULL,updated_at=?1
                     WHERE run_id=?2 AND sequence=?3",
                    rusqlite::params![
                        format!("2099-01-01T00:00:{:02}.000000000Z", sequence * 3 + 2),
                        run_id.to_string(),
                        sequence as i64,
                    ],
                )
                .expect("advance split V94 item to Settled");
        }
    }
    run_id
}

/// The pre-V98 fixture insert must be a faithful twin of the production row
/// write, not a loophole. A root seeded through it carries no allocation
/// identity — exactly like a genuinely pre-V98 deployed row — and the V98
/// migration must backfill it to the sequence-one allocation owner when the
/// fixture migrates forward. The helper must also refuse a store that already
/// carries the V98 column, so nothing routes around the production insert.
#[test]
fn pre_v98_custody_fixture_insert_backfills_to_the_allocation_owner() {
    use super::sandbox_custody::{CustodyCause, NewCustodyRoot};
    use rsi_common::types::{SandboxCleanupState, SandboxKind};

    let canonical_repo_dir = "/tmp/v98-fixture-parity-repo";
    let mut session = make_test_session();
    session.status = SessionStatus::Completed;
    session.working_dir = PathBuf::from(canonical_repo_dir);
    session.sandbox_kind = Some(SandboxKind::GitWorktree);
    session.sandbox_root = Some(PathBuf::from(format!(
        "/tmp/v98-fixture-parity-sandbox-{}",
        session.id
    )));
    session.sandbox_branch = Some("rsi/v98-fixture-parity".to_string());
    session.sandbox_cleanup_state = Some(SandboxCleanupState::Live);
    let custody_id = Uuid::new_v4();
    let root = NewCustodyRoot {
        custody_id,
        canonical_repo_dir: canonical_repo_dir.to_string(),
        sandbox_root: session
            .sandbox_root
            .as_ref()
            .expect("sandbox root")
            .to_string_lossy()
            .into_owned(),
        sandbox_branch: session.sandbox_branch.clone().expect("sandbox branch"),
        repository_identity: "repo:v98-fixture-parity".to_string(),
        source_commit: "a".repeat(40),
        cause: CustodyCause::FreshLaunch,
    };

    let mut store = Store::open_in_memory().expect("open V98 fixture parity store");
    assert!(
        store
            .insert_session_with_pre_v99_custody(&session, root.clone())
            .is_err(),
        "pre-V98 fixture insert must refuse a current-schema store"
    );

    rewind_store_to_schema_version(&store.conn, 97);
    store
        .insert_session_with_pre_v99_custody(&session, root)
        .expect("seed a pre-V98 custody root");
    store
        .init_schema()
        .expect("migrate the pre-V98 fixture root to the schema head");
    assert_eq!(
        store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .expect("read migrated fixture schema version"),
        LATEST_SCHEMA_VERSION
    );
    assert_eq!(
        store
            .conn
            .query_row(
                "SELECT allocation_id FROM sandbox_custody_roots WHERE custody_id=?1",
                [custody_id.to_string()],
                |row| row.get::<_, String>(0)
            )
            .expect("read backfilled allocation identity"),
        session.id.to_string()
    );
}

fn restore_deployed_v94_settlement_fixture(connection: &Connection) {
    let tx = connection
        .unchecked_transaction()
        .expect("open current-to-deployed V94 fixture transaction");
    tx.execute_batch(
        "DROP TRIGGER source_worktree_settlement_items_terminal;
         DROP TRIGGER source_worktree_settlement_items_forward_phase;
         DROP TRIGGER source_worktree_settlement_items_identity_immutable;
         DROP TRIGGER source_worktree_settlement_items_no_delete;
         DROP TRIGGER source_worktree_settlement_runs_terminal;
         DROP TRIGGER source_worktree_settlement_runs_forward_state;
         DROP TRIGGER source_worktree_settlement_runs_identity_immutable;
         DROP TRIGGER source_worktree_settlement_runs_no_delete;
         DROP INDEX idx_source_worktree_settlement_items_phase;
         DROP INDEX idx_source_worktree_settlement_runs_state;
         DROP TABLE source_worktree_settlement_items;
         DROP TABLE source_worktree_settlement_runs;",
    )
    .expect("remove current V94 settlement projection");
    super::cohort_settlement::install_deployed_v94_schema(&tx)
        .expect("install frozen deployed V94 settlement projection");
    tx.execute("PRAGMA user_version=94", [])
        .expect("pin deployed V94 fixture");
    tx.commit()
        .expect("commit current-to-deployed V94 fixture transaction");
    let tx = connection
        .unchecked_transaction()
        .expect("open deployed V94 catalog transaction");
    assert_eq!(
        super::cohort_settlement::classify_v94_settlement_catalog(&tx)
            .expect("authenticate deployed V94 catalog"),
        super::cohort_settlement::V94SettlementCatalog::Deployed
    );
    tx.commit().expect("close deployed V94 catalog transaction");
}

fn deployed_v94_settlement_store() -> Store {
    let store = Store::open_in_memory().expect("open deployed V94 fixture store");
    rewind_store_to_schema_version(&store.conn, 94);
    restore_deployed_v94_settlement_fixture(&store.conn);
    store
}

fn deployed_v94_fingerprint(store: &Store) -> (String, String, String) {
    (
        query_fingerprint(
            &store.conn,
            "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master
             ORDER BY type,name,tbl_name,coalesce(sql,'')",
        )
        .expect("fingerprint deployed V94 catalog"),
        query_fingerprint(
            &store.conn,
            "SELECT rowid,* FROM source_worktree_settlement_runs ORDER BY rowid",
        )
        .expect("fingerprint deployed V94 run rows"),
        query_fingerprint(
            &store.conn,
            "SELECT * FROM source_worktree_settlement_items ORDER BY run_id,sequence",
        )
        .expect("fingerprint deployed V94 item rows"),
    )
}

#[test]
fn v95_deployed_v94_bridge_reaches_schema_head_for_empty_and_data_bearing_journals() {
    let empty = deployed_v94_settlement_store();
    empty
        .init_schema()
        .expect("bridge empty deployed V94 journal to schema head");
    assert_eq!(
        empty
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .expect("read empty bridge schema version"),
        LATEST_SCHEMA_VERSION
    );

    let mut store = deployed_v94_settlement_store();
    let first_run_id = seed_v94_settlement_projection_fixture(
        &mut store,
        "deployed-bridge-first",
        &[(
            rsi_common::cohort_settlement::SourceWorktreeSettlementPhaseV1::IntentCommitted,
            None,
        )],
    );
    let second_run_id = Uuid::new_v4();
    store
        .conn
        .execute(
            "INSERT INTO source_worktree_settlement_runs (
                rowid,run_id,schema_version,policy_version,repository_identity,canonical_repo_dir,
                target_ref,target_oid,plan_digest,idempotency_key,authorization_digest,
                request_fingerprint,state,observed_count,eligible_count,retained_count,
                settled_count,refused_count,recovery_required_count,unattempted_count,
                created_at,updated_at,finished_at,terminal_error
             )
             SELECT 100,?1,schema_version,policy_version,repository_identity,canonical_repo_dir,
                    target_ref,target_oid,plan_digest,'deployed-bridge-second',authorization_digest,
                    request_fingerprint,state,observed_count,eligible_count,retained_count,
                    settled_count,refused_count,recovery_required_count,unattempted_count,
                    created_at,updated_at,finished_at,terminal_error
               FROM source_worktree_settlement_runs WHERE run_id=?2",
            params![second_run_id.to_string(), first_run_id.to_string()],
        )
        .expect("append ordered deployed V94 run row");
    store
        .conn
        .execute(
            "INSERT INTO source_worktree_settlement_items
             SELECT ?1,sequence,session_id,original_status,original_updated_at,custody_id,
                    custody_generation,canonical_repo_dir,sandbox_root,sandbox_branch,
                    repository_identity,source_ref,source_oid,target_oid,evidence_digest,
                    clean_state_digest,reserved_effects,active_effects,participant_count,
                    phase,before_observation,after_observation,refusal_code,created_at,updated_at
               FROM source_worktree_settlement_items WHERE run_id=?2",
            params![second_run_id.to_string(), first_run_id.to_string()],
        )
        .expect("copy deployed V94 item row");
    store
        .init_schema()
        .expect("bridge data-bearing deployed V94 journal to schema head");
    let run_rows = store
        .conn
        .prepare(
            "SELECT run_id,rowid FROM source_worktree_settlement_runs
             WHERE run_id IN (?1,?2) ORDER BY rowid",
        )
        .expect("prepare bridged rowid read")
        .query_map(
            params![first_run_id.to_string(), second_run_id.to_string()],
            |row| Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?)),
        )
        .expect("read bridged rowids")
        .collect::<std::result::Result<Vec<_>, _>>()
        .expect("collect bridged rowids");
    assert_eq!(
        run_rows,
        vec![
            (first_run_id.to_string(), 1),
            (second_run_id.to_string(), 100)
        ]
    );
    assert_eq!(
        store
            .conn
            .prepare(
                "SELECT run_id,generation FROM source_worktree_settlement_run_order
                 WHERE run_id IN (?1,?2) ORDER BY generation",
            )
            .expect("prepare bridged generation read")
            .query_map(
                params![first_run_id.to_string(), second_run_id.to_string()],
                |row| Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?)),
            )
            .expect("read bridged generations")
            .collect::<std::result::Result<Vec<_>, _>>()
            .expect("collect bridged generations"),
        vec![
            (first_run_id.to_string(), 1),
            (second_run_id.to_string(), 2)
        ]
    );
    let tx = store
        .conn
        .unchecked_transaction()
        .expect("open bridged V95 catalog transaction");
    super::cohort_settlement::validate_v95_catalog(&tx)
        .expect("bridge reaches exact current V95 catalog");
    tx.commit().expect("close bridged V95 catalog transaction");
}

#[test]
fn v95_deployed_v94_bridge_faults_roll_back_exactly_then_retry() {
    assert_eq!(
        super::cohort_settlement::SourceWorktreeSettlementV94BridgeFault::ALL.len(),
        5
    );
    for fault in super::cohort_settlement::SourceWorktreeSettlementV94BridgeFault::ALL {
        let mut store = deployed_v94_settlement_store();
        let run_id = seed_v94_settlement_projection_fixture(
            &mut store,
            &format!("deployed-bridge-fault-{fault:?}"),
            &[(
                rsi_common::cohort_settlement::SourceWorktreeSettlementPhaseV1::IntentCommitted,
                None,
            )],
        );
        let before = deployed_v94_fingerprint(&store);
        super::cohort_settlement::fail_next_v94_bridge(fault);
        let error = store
            .init_schema()
            .expect_err("V94 bridge fault must abort the V95 immediate transaction");
        assert!(
            error
                .to_string()
                .contains(&format!("injected V94-to-V95 bridge fault: {fault:?}")),
            "unexpected V94 bridge error: {error}"
        );
        assert_eq!(
            store
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .expect("read rolled-back deployed V94 version"),
            94
        );
        assert_eq!(deployed_v94_fingerprint(&store), before);
        let tx = store
            .conn
            .unchecked_transaction()
            .expect("open rolled-back deployed V94 catalog transaction");
        assert_eq!(
            super::cohort_settlement::classify_v94_settlement_catalog(&tx)
                .expect("authenticate rolled-back deployed V94 catalog"),
            super::cohort_settlement::V94SettlementCatalog::Deployed
        );
        tx.commit()
            .expect("close rolled-back deployed V94 catalog transaction");
        store
            .init_schema()
            .expect("retry deployed V94 bridge after injected fault");
        assert!(
            store
                .get_source_worktree_settlement_run(run_id)
                .expect("load bridged run")
                .is_some(),
            "retry retained deployed V94 run"
        );
    }
}

#[test]
fn v95_deployed_v94_v95_failpoints_roll_back_exactly_then_retry() {
    assert_eq!(
        super::cohort_settlement::SourceWorktreeSettlementV95MigrationFault::ALL.len(),
        10
    );
    for fault in super::cohort_settlement::SourceWorktreeSettlementV95MigrationFault::ALL {
        use rsi_common::cohort_settlement::SourceWorktreeSettlementPhaseV1 as P;

        let mut store = deployed_v94_settlement_store();
        let run_id = seed_v94_settlement_projection_fixture(
            &mut store,
            &format!("deployed-v95-fault-{fault:?}"),
            &[
                (P::RecoveryRequired, Some("recovery_proof_failed")),
                (P::IntentCommitted, None),
            ],
        );
        let before = deployed_v94_fingerprint(&store);

        super::cohort_settlement::fail_next_v95_migration(fault);
        let error = store
            .init_schema()
            .expect_err("V95 fault must roll back the deployed-V94 bridge transaction");
        assert!(
            error.to_string().contains(&format!(
                "injected V95 settlement migration fault: {fault:?}"
            )),
            "V95 {fault:?} failed before its seam: {error}"
        );
        assert_eq!(
            store
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .expect("read rolled-back deployed V94 version"),
            94
        );
        assert_eq!(
            deployed_v94_fingerprint(&store),
            before,
            "V95 {fault:?} changed exact deployed V94 catalog or rows"
        );
        let tx = store
            .conn
            .unchecked_transaction()
            .expect("open rolled-back deployed V94 auth transaction");
        assert_eq!(
            super::h1_v95_validate_v94_catalog(&tx)
                .expect("rollback retained exact deployed V94 source"),
            super::cohort_settlement::V94SettlementCatalog::Deployed
        );
        tx.commit()
            .expect("close rolled-back deployed V94 auth transaction");

        store
            .init_schema()
            .expect("retry deployed V94 bridge after V95 fault");
        let tx = store
            .conn
            .unchecked_transaction()
            .expect("open converged deployed V95 transaction");
        super::cohort_settlement::validate_v95_catalog(&tx)
            .expect("retry converged to exact V95 catalog");
        tx.commit()
            .expect("close converged deployed V95 transaction");
        let run = store
            .get_source_worktree_settlement_run(run_id)
            .expect("load normalized deployed run")
            .expect("normalized deployed run");
        assert_eq!(
            run.state,
            rsi_common::cohort_settlement::SourceWorktreeSettlementRunStateV1::Partial
        );
        run.validate_wire()
            .expect("normalized deployed run is wire-valid");
    }
}

#[test]
fn v95_deployed_v94_bridge_rejects_hostile_catalog_and_row_before_writing() {
    let store = deployed_v94_settlement_store();
    store
        .conn
        .execute_batch("CREATE TABLE hostile_unrelated_v94_catalog_drift(value TEXT)")
        .expect("inject unrelated deployed V94 catalog drift");
    let before = deployed_v94_fingerprint(&store);
    super::cohort_settlement::fail_next_v94_bridge(
        super::cohort_settlement::SourceWorktreeSettlementV94BridgeFault::AfterSourceObjectDrop,
    );
    let error = store
        .init_schema()
        .expect_err("unrelated deployed V94 drift must fail before bridge DDL");
    assert!(
        error
            .to_string()
            .contains("exact accepted deployed V94 source catalog"),
        "unexpected unrelated deployed catalog error: {error}"
    );
    assert_eq!(deployed_v94_fingerprint(&store), before);
    assert_eq!(
        store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .expect("read retained unrelated-drift V94 version"),
        94
    );
    let clean_store = deployed_v94_settlement_store();
    let error = clean_store
        .init_schema()
        .expect_err("unrelated drift must not consume the bridge seam");
    assert!(
        error
            .to_string()
            .contains("injected V94-to-V95 bridge fault: AfterSourceObjectDrop"),
        "unrelated drift reached a bridge seam: {error}"
    );

    let store = deployed_v94_settlement_store();
    store
        .conn
        .execute_batch("DROP TRIGGER source_worktree_settlement_runs_no_delete")
        .expect("inject hostile deployed V94 catalog");
    let before = deployed_v94_fingerprint(&store);
    let error = store
        .init_schema()
        .expect_err("hostile deployed V94 catalog must fail before bridge DDL");
    assert!(
        error
            .to_string()
            .contains("exact accepted V94 settlement catalog"),
        "unexpected hostile deployed catalog error: {error}"
    );
    assert_eq!(deployed_v94_fingerprint(&store), before);

    let mut store = deployed_v94_settlement_store();
    let run_id = seed_v94_settlement_projection_fixture(
        &mut store,
        "deployed-bridge-hostile-row",
        &[(
            rsi_common::cohort_settlement::SourceWorktreeSettlementPhaseV1::IntentCommitted,
            None,
        )],
    );
    store
        .conn
        .execute(
            "UPDATE source_worktree_settlement_items
             SET refusal_code='unknown_deployed_refusal'
             WHERE run_id=?1 AND sequence=0",
            [run_id.to_string()],
        )
        .expect("inject hostile deployed V94 row");
    let before = deployed_v94_fingerprint(&store);
    let error = store
        .init_schema()
        .expect_err("unsupported deployed V94 refusal code must fail before bridge DDL");
    assert!(
        error
            .to_string()
            .contains("outside the current target catalog"),
        "unexpected hostile deployed row error: {error}"
    );
    assert_eq!(deployed_v94_fingerprint(&store), before);
    assert_eq!(
        store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .expect("read retained hostile deployed V94 version"),
        94
    );
}

fn restore_exact_v94_trigger(connection: &Connection, trigger_name: &str, sql: &str) {
    connection
        .execute_batch(&format!("{sql};"))
        .unwrap_or_else(|error| panic!("restore exact V94 trigger {trigger_name}: {error}"));
    let restored: String = connection
        .query_row(
            "SELECT sql FROM sqlite_master WHERE type='trigger' AND name=?1",
            [trigger_name],
            |row| row.get(0),
        )
        .expect("read restored V94 trigger");
    assert_eq!(restored, sql, "V94 trigger SQL bytes changed on restore");
}

fn embedded_nul_uuid_text() -> String {
    let value = "01234567-89ab-4def-8abc-\0bcdef012345".to_string();
    debug_assert_eq!(value.len(), 36);
    value
}

fn assert_v95_row_preflight_rejects_without_mutation(store: &Store, expected: &str) {
    let before_catalog = query_fingerprint(
        &store.conn,
        "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master
         ORDER BY type,name,tbl_name,coalesce(sql,'')",
    )
    .expect("fingerprint exact V94 source catalog");
    let before_runs = query_fingerprint(
        &store.conn,
        "SELECT * FROM source_worktree_settlement_runs ORDER BY run_id",
    )
    .expect("fingerprint exact V94 source runs");
    let before_items = query_fingerprint(
        &store.conn,
        "SELECT * FROM source_worktree_settlement_items ORDER BY run_id,sequence",
    )
    .expect("fingerprint exact V94 source items");
    let tx = store
        .conn
        .unchecked_transaction()
        .expect("authenticate hostile-row V94 catalog");
    super::h1_v95_validate_v94_catalog(&tx).expect("V94 catalog remains exact");
    tx.commit().expect("close V94 catalog authentication");

    let error = store
        .init_schema()
        .expect_err("out-of-bounds authentic V94 rows must fail before hardening");
    assert!(error.to_string().contains(expected), "{error}");
    assert_eq!(
        store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .expect("read retained V94 version"),
        94
    );
    for object in V95_INDEXES.iter().chain(V95_BOUNDS_TRIGGERS.iter()) {
        assert_eq!(
            store
                .conn
                .query_row(
                    "SELECT count(*) FROM sqlite_master WHERE name=?1",
                    [*object],
                    |row| row.get::<_, i64>(0),
                )
                .expect("probe absent V95 object"),
            0,
            "V95 object `{object}` leaked before row authentication"
        );
    }
    assert_eq!(
        query_fingerprint(
            &store.conn,
            "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master
             ORDER BY type,name,tbl_name,coalesce(sql,'')",
        )
        .expect("fingerprint rejected V94 catalog"),
        before_catalog
    );
    assert_eq!(
        query_fingerprint(
            &store.conn,
            "SELECT * FROM source_worktree_settlement_runs ORDER BY run_id",
        )
        .expect("fingerprint rejected V94 runs"),
        before_runs
    );
    assert_eq!(
        query_fingerprint(
            &store.conn,
            "SELECT * FROM source_worktree_settlement_items ORDER BY run_id,sequence",
        )
        .expect("fingerprint rejected V94 items"),
        before_items
    );
}

#[test]
fn v95_rejects_authentic_v94_oversized_text_before_any_hardening() {
    use rsi_common::cohort_settlement::SourceWorktreeSettlementPhaseV1 as P;

    let mut store = Store::open_in_memory().expect("open oversized V94 fixture");
    rewind_store_to_schema_version(&store.conn, 94);
    let run_id = seed_v94_settlement_projection_fixture(
        &mut store,
        "oversized-text",
        &[(P::IntentCommitted, None)],
    );
    let trigger_name = "source_worktree_settlement_items_identity_immutable";
    let trigger_sql: String = store
        .conn
        .query_row(
            "SELECT sql FROM sqlite_master WHERE type='trigger' AND name=?1",
            [trigger_name],
            |row| row.get(0),
        )
        .expect("read V94 item identity trigger");
    store
        .conn
        .execute(&format!("DROP TRIGGER {trigger_name}"), [])
        .expect("drop V94 item identity trigger temporarily");
    store
        .conn
        .execute(
            "UPDATE source_worktree_settlement_items SET sandbox_root=?1
             WHERE run_id=?2 AND sequence=0",
            rusqlite::params![format!("/tmp/{}", "x".repeat(4096)), run_id.to_string()],
        )
        .expect("install oversized V94 item text");
    restore_exact_v94_trigger(&store.conn, trigger_name, &trigger_sql);

    let load = store
        .list_source_worktree_settlement_journal_items(run_id)
        .expect_err("bounded journal loader must reject oversized V94 text");
    assert!(load.to_string().contains("exceeds byte bound"), "{load}");
    assert_v95_row_preflight_rejects_without_mutation(&store, "out-of-bounds V94 item row");
}

