#[test]
fn v95_backfill_generation_survives_vacuum_and_reopen() {
    use rsi_common::cohort_settlement::SourceWorktreeSettlementPhaseV1 as P;

    let directory = tempfile::tempdir().expect("latest-run VACUUM fixture directory");
    let path = directory.path().join("latest-run-vacuum.sqlite");
    let mut store = Store::open(&path).expect("open V95 pointer backfill fixture");
    rewind_store_to_schema_version(&store.conn, 94);
    let first_run_id = seed_v94_settlement_projection_fixture(
        &mut store,
        "pointer-backfill",
        &[(P::IntentCommitted, None)],
    );
    let second_run_id = Uuid::new_v4();
    store
        .conn
        .execute(
            "INSERT INTO source_worktree_settlement_runs (
                rowid,run_id,schema_version,policy_version,repository_identity,canonical_repo_dir,
                target_ref,target_oid,plan_digest,idempotency_key,authorization_digest,
                request_fingerprint,state,observed_count,eligible_count,retained_count,
                settled_count,refused_count,recovery_required_count,unattempted_count,
                created_at,updated_at,finished_at,terminal_error
             )
             SELECT 100,?1,schema_version,policy_version,repository_identity,canonical_repo_dir,
                    target_ref,target_oid,plan_digest,'pointer-backfill-later',authorization_digest,
                    request_fingerprint,state,observed_count,eligible_count,retained_count,
                    settled_count,refused_count,recovery_required_count,unattempted_count,
                    created_at,updated_at,finished_at,terminal_error
               FROM source_worktree_settlement_runs WHERE run_id=?2",
            params![second_run_id.to_string(), first_run_id.to_string()],
        )
        .expect("append later V94 run row");
    store
        .conn
        .execute(
            "INSERT INTO source_worktree_settlement_items
             SELECT ?1,sequence,session_id,original_status,original_updated_at,custody_id,
                    custody_generation,canonical_repo_dir,sandbox_root,sandbox_branch,
                    repository_identity,source_ref,source_oid,target_oid,evidence_digest,
                    clean_state_digest,reserved_effects,active_effects,participant_count,
                    phase,before_observation,after_observation,refusal_code,created_at,updated_at
               FROM source_worktree_settlement_items WHERE run_id=?2",
            params![second_run_id.to_string(), first_run_id.to_string()],
        )
        .expect("append later V94 item row");

    store.init_schema().expect("migrate V94 pointer history");
    let (pointer_run_id, generation): (String, i64) = store
        .conn
        .query_row(
            "SELECT run_id,generation FROM source_worktree_settlement_latest_runs",
            [],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .expect("read backfilled latest-run pointer");
    assert_eq!(pointer_run_id, second_run_id.to_string());
    assert_eq!(generation, 2);
    assert_eq!(
        store
            .conn
            .prepare(
                "SELECT run_id,generation FROM source_worktree_settlement_run_order
                 ORDER BY generation",
            )
            .expect("prepare immutable run order read")
            .query_map([], |row| Ok((
                row.get::<_, String>(0)?,
                row.get::<_, i64>(1)?
            )))
            .expect("read immutable run order")
            .collect::<std::result::Result<Vec<_>, _>>()
            .expect("collect immutable run order"),
        vec![
            (first_run_id.to_string(), 1),
            (second_run_id.to_string(), 2)
        ]
    );
    assert_eq!(
        store
            .latest_source_worktree_settlement_run("repo:v95-normalize:pointer-backfill")
            .expect("load pointer-backed receipt")
            .expect("latest receipt")
            .run_id,
        second_run_id
    );
    store
        .conn
        .execute_batch("VACUUM")
        .expect("VACUUM pointer database");
    drop(store);
    let reopened = Store::open(&path).expect("reopen VACUUMed pointer database");
    assert_eq!(
        reopened
            .latest_source_worktree_settlement_run("repo:v95-normalize:pointer-backfill")
            .expect("load receipt after VACUUM")
            .expect("latest receipt after VACUUM")
            .run_id,
        second_run_id
    );
    assert_eq!(
        reopened
            .conn
            .query_row(
                "SELECT generation FROM source_worktree_settlement_latest_runs",
                [],
                |row| row.get::<_, i64>(0),
            )
            .expect("read generation after VACUUM"),
        2
    );
    assert_eq!(
        reopened
            .conn
            .prepare(
                "SELECT run_id,generation FROM source_worktree_settlement_run_order
                 ORDER BY generation",
            )
            .expect("prepare immutable run order after VACUUM")
            .query_map([], |row| Ok((
                row.get::<_, String>(0)?,
                row.get::<_, i64>(1)?
            )))
            .expect("read immutable run order after VACUUM")
            .collect::<std::result::Result<Vec<_>, _>>()
            .expect("collect immutable run order after VACUUM"),
        vec![
            (first_run_id.to_string(), 1),
            (second_run_id.to_string(), 2)
        ]
    );
}

#[test]
fn v95_empty_journal_rewinds_exactly_and_rejects_hostile_source_drift() {
    let store = Store::open_in_memory().expect("open V95 rewind fixture");
    rewind_store_to_schema_version(&store.conn, 94);
    let tx = store
        .conn
        .unchecked_transaction()
        .expect("open exact restored V94 transaction");
    super::h1_v95_validate_v94_catalog(&tx).expect("rewind restored exact accepted V94 catalog");
    tx.commit().expect("close restored V94 transaction");
    store.init_schema().expect("replay exact V94 to V95");
    rewind_store_to_schema_version(&store.conn, 95);

    store
        .conn
        .execute_batch(
            "DROP TRIGGER source_worktree_settlement_runs_terminal;
             CREATE TRIGGER source_worktree_settlement_runs_terminal
             BEFORE UPDATE ON source_worktree_settlement_runs BEGIN SELECT 1; END;",
        )
        .expect("mutate V95 source before rewind");
    let before = query_fingerprint(
        &store.conn,
        "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master
         ORDER BY type,name,tbl_name,coalesce(sql,'')",
    )
    .expect("fingerprint hostile V95 catalog");
    let rewind = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        rewind_store_to_schema_version(&store.conn, 94);
    }));
    assert!(
        rewind.is_err(),
        "hostile V95 source must not be blessed by rewind"
    );
    assert_eq!(
        store
            .conn
            .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
            .expect("read retained hostile V95 version"),
        95
    );
    assert_eq!(
        query_fingerprint(
            &store.conn,
            "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master
             ORDER BY type,name,tbl_name,coalesce(sql,'')",
        )
        .expect("fingerprint retained hostile V95 catalog"),
        before
    );
}

