#[test]
fn v94_migration_failpoints_restore_exact_v93_state_then_converge() {
    assert_eq!(
        super::cohort_settlement::SourceWorktreeSettlementV94MigrationFault::ALL.len(),
        5
    );
    for fault in super::cohort_settlement::SourceWorktreeSettlementV94MigrationFault::ALL {
        let store = Store::open_in_memory().expect("open V94 fault fixture");
        let mut session = make_test_session();
        session.id = Uuid::new_v4();
        store
            .insert_session(&session)
            .expect("insert V93 preservation row");
        store
            .init_schema()
            .expect("stabilize idempotent compatibility backfills before V93 rewind");
        rewind_store_to_schema_version(&store.conn, 93);
        let before_catalog = query_fingerprint(
            &store.conn,
            "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master ORDER BY type,name,tbl_name,coalesce(sql,'')",
        )
        .expect("fingerprint exact V93 source catalog");
        let before_sessions = query_fingerprint(&store.conn, "SELECT * FROM sessions ORDER BY id")
            .expect("fingerprint exact V93 source rows");

        super::cohort_settlement::fail_next_v94_migration(fault);
        let error = store
            .init_schema()
            .expect_err("V94 fault must abort the immediate transaction");
        assert!(
            error.to_string().contains(&format!(
                "injected V94 settlement migration fault: {fault:?}"
            )),
            "V94 {fault:?} failed before its seam: {error}"
        );
        assert_eq!(
            store
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .expect("read rolled-back V93 version"),
            93
        );
        assert_eq!(
            query_fingerprint(
                &store.conn,
                "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master ORDER BY type,name,tbl_name,coalesce(sql,'')",
            )
            .expect("fingerprint rolled-back V93 catalog"),
            before_catalog,
            "V94 {fault:?} changed exact V93 catalog bytes"
        );
        assert_eq!(
            query_fingerprint(&store.conn, "SELECT * FROM sessions ORDER BY id")
                .expect("fingerprint rolled-back V93 rows"),
            before_sessions,
            "V94 {fault:?} changed source rows"
        );
        assert_fixture_matches_claimed_version(&store.conn, 93);

        store
            .init_schema()
            .expect("retry after V94 fault must converge");
        let tx = store
            .conn
            .unchecked_transaction()
            .expect("open converged V94 catalog transaction");
        super::cohort_settlement::validate_v95_catalog(&tx)
            .expect("retry converged to exact V95 catalog");
        tx.commit().expect("close V94 catalog transaction");
    }
}

#[test]
fn v94_migrated_database_reopens_without_catalog_or_row_drift() {
    let directory = tempfile::tempdir().expect("create V94 reopen fixture directory");
    let path = directory.path().join("v94-reopen.sqlite");
    let store = Store::open(&path).expect("create V94 database");
    let mut session = make_test_session();
    session.id = Uuid::new_v4();
    store
        .insert_session(&session)
        .expect("insert V94 reopen preservation row");
    rewind_store_to_schema_version(&store.conn, 93);
    drop(store);

    let migrated = Store::open(&path).expect("migrate exact V93 database to V94");
    let catalog = query_fingerprint(
        &migrated.conn,
        "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master ORDER BY type,name,tbl_name,coalesce(sql,'')",
    )
    .expect("fingerprint migrated V94 catalog");
    let rows = query_fingerprint(&migrated.conn, "SELECT * FROM sessions ORDER BY id")
        .expect("fingerprint migrated V94 rows");
    drop(migrated);

    let reopened = Store::open(&path).expect("reopen migrated V94 database");
    assert_eq!(
        query_fingerprint(
            &reopened.conn,
            "SELECT type,name,tbl_name,coalesce(sql,'') FROM sqlite_master ORDER BY type,name,tbl_name,coalesce(sql,'')",
        )
        .expect("fingerprint reopened V94 catalog"),
        catalog
    );
    assert_eq!(
        query_fingerprint(&reopened.conn, "SELECT * FROM sessions ORDER BY id")
            .expect("fingerprint reopened V94 rows"),
        rows
    );
    assert_post_v77_chain_replayed(&reopened.conn);
}

