#[test]
fn v89_migration_failpoints_restore_exact_v88_catalog_data_and_version() {
    assert_eq!(super::V89MigrationFault::ALL.len(), 7);
    for fault in super::V89MigrationFault::ALL {
        let store = Store::open_in_memory().expect("open V89 fault fixture");
        let mut session = make_test_session();
        session.id = Uuid::new_v4();
        store
            .insert_session(&session)
            .expect("insert V88 fixture row");
        store
            .init_schema()
            .expect("stabilize legacy model-control backfill before V88 rewind");
        rewind_store_to_schema_version(&store.conn, 88);
        let before =
            v89_database_snapshot(&store.conn).expect("snapshot exact data-bearing V88 source");

        super::v89_test_fail_next_migration(fault);
        let error = store
            .init_schema()
            .expect_err("V89 fault must abort migration");
        assert!(
            error
                .to_string()
                .contains(&format!("injected V89 migration fault: {fault:?}")),
            "V89 {fault:?} failed before its seam: {error}"
        );
        assert_eq!(
            v89_database_snapshot(&store.conn).unwrap(),
            before,
            "V89 {fault:?} must roll back exact catalog and data bytes"
        );
        assert_no_v89_capacity_objects(&store.conn);
        assert_fixture_matches_claimed_version(&store.conn, 88);
    }
}

#[test]
fn v89_rejects_drifted_or_non_v88_sources_before_ddl() {
    for (label, mutate) in [
        (
            "dropped unlisted trigger",
            "DROP TRIGGER sessions_execution_origin_write_guard;",
        ),
        (
            "altered same-name trigger SQL",
            "DROP TRIGGER sessions_execution_origin_write_guard;
             CREATE TRIGGER sessions_execution_origin_write_guard
             BEFORE UPDATE ON sessions BEGIN SELECT 1; END;",
        ),
        (
            "extra table",
            "CREATE TABLE issue82_extra_table(value TEXT);",
        ),
        (
            "extra index",
            "CREATE INDEX issue82_extra_index ON sessions(status);",
        ),
        (
            "extra trigger",
            "CREATE TRIGGER issue82_extra_trigger
             AFTER UPDATE ON sessions BEGIN SELECT 1; END;",
        ),
    ] {
        let store = Store::open_in_memory().expect("open V89 catalog-refusal fixture");
        rewind_store_to_schema_version(&store.conn, 88);
        store.conn.execute_batch(mutate).expect(label);
        let before = v89_database_snapshot(&store.conn).expect("snapshot drifted V88 source");
        let error = store.init_schema().expect_err(label);
        assert!(
            error
                .to_string()
                .contains("requires exact V88 source catalog"),
            "{label}: {error}"
        );
        assert_eq!(
            v89_database_snapshot(&store.conn).unwrap(),
            before,
            "{label}"
        );
        assert_no_v89_capacity_objects(&store.conn);
    }

    let store = Store::open_in_memory().expect("open altered-table-constraint fixture");
    rewind_store_to_schema_version(&store.conn, 88);
    store
        .conn
        .pragma_update(None, "writable_schema", true)
        .unwrap();
    assert_eq!(
        store
            .conn
            .execute(
                "UPDATE sqlite_master
                 SET sql=replace(sql,'expected_owner_generation>0','expected_owner_generation>=0')
                 WHERE type='table' AND name='execution_origin_claims'",
                [],
            )
            .unwrap(),
        1
    );
    store
        .conn
        .pragma_update(None, "writable_schema", false)
        .unwrap();
    let before = v89_database_snapshot(&store.conn).expect("snapshot altered table constraint");
    let error = store
        .init_schema()
        .expect_err("altered table constraint SQL must be rejected");
    assert!(
        error
            .to_string()
            .contains("requires exact V88 source catalog")
    );
    assert_eq!(v89_database_snapshot(&store.conn).unwrap(), before);
    assert_no_v89_capacity_objects(&store.conn);
}

#[test]
fn h1_v87_data_bearing_direct_deep_rewind_families_replay_cleanly() {
    let fresh = Store::open_in_memory().expect("open fresh V87 catalog reference");
    let head_catalog = query_fingerprint(
        &fresh.conn,
        "SELECT type,name,coalesce(tbl_name,''),coalesce(sql,'') FROM sqlite_master ORDER BY type,name",
    )
    .expect("fingerprint fresh V87 catalog");

    for (index, target) in [79_i32, 78, 77, 76].into_iter().enumerate() {
        let directory = tempfile::tempdir().expect("direct deep-rewind directory");
        let path = directory.path().join(format!("direct-v{target}.sqlite"));
        let store = Store::open(&path).expect("open exact V87 deep-rewind source");
        let session = h1_v85_test_session(0x87f0_0000 + index as u128, index as i64 + 1);
        store
            .insert_session(&session)
            .expect("insert data-bearing deep-rewind Session");
        let stable_session_query = format!(
            "SELECT id,status,coalesce(stop_reason,''),pending_archive,working_dir,created_at,updated_at FROM sessions WHERE id='{}'",
            session.id
        );
        let before_session = query_fingerprint(&store.conn, &stable_session_query)
            .expect("fingerprint pre-rewind stable Session bytes");

        match target {
            79 => agent_coordination_restore_v79_fixture(&store.conn),
            78 => d05_restore_v78_fixture(&store.conn),
            77 => d05_restore_v77_fixture(&store.conn),
            76 => {
                d05_restore_v77_fixture(&store.conn);
                d05_restore_v76_issue_fixture(&store.conn);
            }
            _ => unreachable!(),
        }
        assert_fixture_matches_claimed_version(&store.conn, target);
        drop(store);

        let replayed = Store::open(&path).expect("reopen and replay direct deep rewind");
        assert_eq!(
            replayed
                .conn
                .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
                .unwrap(),
            LATEST_SCHEMA_VERSION,
            "direct V{target} replay reaches current head"
        );
        assert_eq!(
            query_fingerprint(&replayed.conn, &stable_session_query).unwrap(),
            before_session,
            "direct V{target} replay preserves stable Session row bytes"
        );
        assert_eq!(
            query_fingerprint(
                &replayed.conn,
                "SELECT type,name,coalesce(tbl_name,''),coalesce(sql,'') FROM sqlite_master ORDER BY type,name",
            )
            .unwrap(),
            head_catalog,
            "direct V{target} replay restores the exact head catalog"
        );
        h1_v87_assert_catalog_clean(&replayed.conn, &format!("direct V{target} replay"));
    }
}

/// Arm one migration's own failpoint, replay a rewound chain, and require the
/// replay to abort at exactly that step.
///
/// A migration that does not run cannot consume its failpoint, so this is a
/// positive execution probe rather than an inference from the final schema.
#[allow(clippy::expect_used)]
fn assert_migration_step_executes(step: &str, arm: impl FnOnce()) {
    let store = Store::open_in_memory().expect("open a fresh store");
    rewind_store_to_schema_version(&store.conn, 39);

    arm();
    let replayed = store.init_schema();

    // The failpoint slot is thread-local and one-shot. If the armed step never
    // ran, the fault is still armed; a fresh store replays the whole chain and
    // consumes it, so a failure here cannot poison later tests. This must run
    // before the assertions below, which panic.
    let _ = Store::open_in_memory_via_migrations_for_test();

    match replayed {
        Ok(()) => panic!(
            "{step} did not execute during the replay: the chain completed without ever \
             reaching {step}'s failpoint. Migration-chain coverage for {step} is suppressed."
        ),
        Err(error) => {
            let rendered = error.to_string();
            assert!(
                rendered.contains(&format!("injected {step} migration fault")),
                "{step} aborted the replay for the wrong reason: {rendered}"
            );
        }
    }
}

/// Direct evidence that **every** migration step recovered by the issue #26
/// repair actually executes during a replayed chain.
///
/// Before this repair the chain aborted inside V77's preflight, so V77 itself
/// only half-ran and V78..V82 never ran at all. Asserting the final schema shape
/// would not distinguish "the migration rebuilt this" from "the fixture never
/// tore it down"; arming each step's own failpoint does, because an unexecuted
/// step cannot consume one.
#[test]
fn every_recovered_migration_step_actually_executes() {
    assert_migration_step_executes("V77", || {
        super::d04_test_fail_next_migration(super::D04MigrationFault::AfterPreflight);
    });
    assert_migration_step_executes("V78", || {
        super::d05_test_fail_next_migration(super::D05MigrationFault::AfterExactSource);
    });
    assert_migration_step_executes("V79", || {
        super::d05_v79_test_fail_next_migration(super::D05V79MigrationFault::AfterExactSource);
    });
    assert_migration_step_executes("V80", || {
        super::agent_coordination_v80_test_fail_next_migration(
            super::AgentCoordinationV80MigrationFault::AfterExactSource,
        );
    });
    assert_migration_step_executes("V81", || {
        super::agent_message_v81_test_fail_next_migration(
            super::AgentMessageV81MigrationFault::AfterExactSource,
        );
    });
    assert_migration_step_executes("V82", || {
        super::agent_message_v82_test_fail_next_migration(
            super::AgentMessageV82MigrationFault::AfterExactSource,
        );
    });
}

