#[test]
fn pending_question_v105_fixture_requires_exact_predecessor_and_preserves_legacy_display() {
    let store = Store::open_in_memory().unwrap();
    let session = make_test_session();
    store.insert_session(&session).unwrap();
    let raw = r#"{"questions":[{"question":"Legacy question remains readable","header":"Migration","options":[],"multiSelect":false}]}"#;
    store
        .update_session_pending_question_json(session.id, Some(raw))
        .unwrap();
    store
        .insert_event(&ConversationEvent {
            id: 0,
            session_id: session.id,
            sequence: 1,
            event_type: EventType::ToolUse,
            role: Some(Role::Assistant),
            created_at: chrono::Utc::now(),
            content: String::new(),
            tool_name: Some("AskUserQuestion".into()),
            tool_input: Some(Box::new(serde_json::from_str(raw).unwrap())),
            offload_id: None,
            tool_use_id: Some("legacy-tool-without-publication".into()),
            metadata: None,
        })
        .unwrap();
    let head_catalog = query_fingerprint(&store.conn,
        "SELECT type,name,coalesce(tbl_name,''),coalesce(sql,'') FROM sqlite_master ORDER BY type,name").unwrap();
    let snapshot = v89_database_snapshot(&store.conn).unwrap();
    let refused = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        restore_v103_harness_manager_v2_fixture(&store.conn);
    }));
    assert!(
        refused.is_err(),
        "V104 helper must reject an intact V105 tail"
    );
    assert_eq!(v89_database_snapshot(&store.conn).unwrap(), snapshot);
    if store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
        .unwrap()
        == 111
    {
        restore_v110_manager_succession_fixture(&store.conn);
    }
    if store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
        .unwrap()
        == 110
    {
        restore_v109_manager_scope_fixture(&store.conn);
    }
    restore_v108_approval_scan_fixture(&store.conn);
    restore_v107_decision_history_fixture(&store.conn);
    restore_v106_approval_publication_fixture(&store.conn);
    restore_v105_pending_approval_fixture(&store.conn);
    restore_v104_pending_question_fixture(&store.conn);
    restore_v104_pending_question_fixture(&store.conn);
    assert_fixture_matches_claimed_version(&store.conn, 104);
    let pending: String = store
        .conn
        .query_row(
            "SELECT pending_question_json FROM sessions WHERE id=?1",
            [session.id.to_string()],
            |r| r.get(0),
        )
        .unwrap();
    assert_eq!(pending, raw);
    store.init_schema().unwrap();
    assert_eq!(
        store
            .conn
            .query_row(
                "SELECT count(*) FROM pending_question_publications",
                [],
                |r| r.get::<_, i64>(0)
            )
            .unwrap(),
        0
    );
    assert_eq!(query_fingerprint(&store.conn,
        "SELECT type,name,coalesce(tbl_name,''),coalesce(sql,'') FROM sqlite_master ORDER BY type,name").unwrap(), head_catalog);
    assert!(
        store
            .manager_v2_question_target(session.id)
            .unwrap_err()
            .to_string()
            .contains("question_identity_unavailable")
    );
    store.init_schema().unwrap();
    assert_post_v77_chain_replayed(&store.conn);
}

