#[test]
fn pending_approval_v106_fixture_requires_exact_predecessor_preserves_legacy_and_reopens() {
    let store = Store::open_in_memory().unwrap();
    let session = make_test_session();
    store.insert_session(&session).unwrap();
    let approval = rsi_common::types::Approval {
        id: Uuid::new_v4(),
        session_id: session.id,
        tool_name: "Legacy approval".into(),
        tool_input: serde_json::json!({"command":"inspect"}),
        status: rsi_common::types::ApprovalStatus::Pending,
        created_at: chrono::Utc::now(),
        resolved_at: None,
    };
    store.insert_approval(&approval).unwrap();
    let catalog = "SELECT type,name,coalesce(tbl_name,''),coalesce(sql,'') FROM sqlite_master ORDER BY type,name";
    let head = query_fingerprint(&store.conn, catalog).unwrap();
    let before = v89_database_snapshot(&store.conn).unwrap();
    assert!(
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            restore_v104_pending_question_fixture(&store.conn);
        }))
        .is_err(),
        "cannot skip intact V106 tail"
    );
    assert_eq!(v89_database_snapshot(&store.conn).unwrap(), before);
    if store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
        .unwrap()
        == 111
    {
        restore_v110_manager_succession_fixture(&store.conn);
    }
    if store
        .conn
        .query_row("PRAGMA user_version", [], |row| row.get::<_, i32>(0))
        .unwrap()
        == 110
    {
        restore_v109_manager_scope_fixture(&store.conn);
    }
    restore_v108_approval_scan_fixture(&store.conn);
    restore_v107_decision_history_fixture(&store.conn);
    restore_v106_approval_publication_fixture(&store.conn);
    restore_v105_pending_approval_fixture(&store.conn);
    restore_v105_pending_approval_fixture(&store.conn);
    assert_fixture_matches_claimed_version(&store.conn, 105);
    let rows = query_fingerprint(&store.conn, "SELECT * FROM approvals ORDER BY id").unwrap();
    store.init_schema().unwrap();
    assert_eq!(query_fingerprint(&store.conn, catalog).unwrap(), head);
    assert_eq!(
        query_fingerprint(&store.conn, "SELECT * FROM approvals ORDER BY id").unwrap(),
        rows
    );
    assert_eq!(
        store.pending_appserver_approval_target(session.id).unwrap(),
        None
    );
    store.init_schema().unwrap();
    assert_post_v77_chain_replayed(&store.conn);
    assert_eq!(query_fingerprint(&store.conn, catalog).unwrap(), head);
}

